ClinicalChunks.register("data/templates-039.js",[{"id":"templates-cc8a4dd288231cb516d4","key":"v1-c9ccc21dfe2a3058|templates-cc8a4dd288231cb516d4","module":"templates","moduleKey":"v1-c9ccc21dfe2a3058|templates","version":"v1-c9ccc21dfe2a3058","title":"植物神经功能紊乱","category":"门诊病历模板","raw":{"name":"植物神经功能紊乱","category":"门诊病历模板","case":{"case_name":"门诊病历221","templates":{"主诉":"反复头晕伴恶心1周。","现病史":"患者1周前饮食不当后出现植物神经功能紊乱相关症状，呈搏动性，劳累后加重，休息后稍缓解，伴恶心，无呕吐，无肢体活动障碍。自服「布洛芬」可暂时缓解，今日再次发作，来诊。发病以来精神可，饮食睡眠尚可，大小便正常，体重无明显变化。","既往史":"既往体健，否认高血压、糖尿病、冠心病等慢性病史。否认肝炎、结核等传染病史。否认手术外伤史。否认食物药物过敏史。预防接种史随社会。","个人史及过敏史":"生于原籍，久居本地，无疫区疫水接触史，无特殊粉尘毒物放射性物质接触史。不吸烟，不饮酒。生活规律。否认食物药物过敏史。","体格检查":"T 36.8℃，P 80次/分，R 18次/分，BP 125/80mmHg。神志清楚，精神可，自主体位，查体合作。皮肤黏膜无黄染，浅表淋巴结未触及肿大。颈软，无抵抗。双肺呼吸音清。心率80次/分，律齐。腹平软，无压痛。神经系统检查：生理反射存在，病理反射未引出。生理反射存在，病理反射未引出。","辅助检查":"检查计划：患者反复头晕伴恶心1周，症状呈搏动性、劳累后加重，休息后稍缓解，需先排除器质性疾病，完善血常规检查排除感染、贫血所致头晕乏力；查生化全项检查了解肝肾功能、血糖及电解质水平，排除低血糖、电解质紊乱等所致头晕恶心；患者头晕反复发作需排除脑血管病变，完善凝血功能检查评估凝血状态，查血糖及血脂检查明确代谢性危险因素，查同型半胱氨酸检查了解有无高同型半胱氨酸血症；完善头颅CT/MRI检查排除颅内出血及占位性病变并明确有无缺血性病灶及脑萎缩，完善颈动脉超声检查了解颈部血管有无斑块狭窄，查经颅多普勒检查评估颅内血流情况；为排除心源性因素所致头晕，完善心电图检查排除心律失常及心肌缺血，查心脏超声（排查栓子来源）了解心脏结构及功能、排查心腔内栓子来源；若出现头痛加剧、发热或脑膜刺激征，必要时完善腰椎穿刺（必要时）检查排除颅内感染，病情稳定后复查心电图及头颅影像学观察动态变化。\n\n（检查清单）\n【必做检查】\n血常规、生化全项、凝血功能、血糖、血脂、同型半胱氨酸\n\n【影像学检查】\n头颅CT/MRI、颈动脉超声、经颅多普勒\n\n【其他检查】\n心电图、心脏超声（排查栓子来源）、腰椎穿刺（必要时）","初步诊断":"1. 植物神经功能紊乱\n（注：根据患者病史、体征及辅助检查综合判断，必要时请相关科室会诊。）","处理方案":"【药物治疗】\n1. 谷维素片 10mg tid×4周（调节植物神经功能，改善心悸、失眠等症状）。\n2. 维生素B1片 10mg tid×4周（营养神经，与谷维素联合改善神经功能紊乱）。\n3. 伴明显焦虑、情绪低落者：氟哌噻吨美利曲辛片（黛力新）1片 bid（早、午各1片）×2周，症状缓解后遵医嘱逐渐减量停用。\n4. 伴明显失眠者：佐匹克隆片 7.5mg qn×1周（短期助眠，连续使用不超过2周，避免依赖）。\n【一般治疗及生活指导】\n1. 保持规律作息，每晚保证7-8小时睡眠，避免熬夜、劳累及长时间用眼，午后避免补觉过长。\n2. 适当有氧运动（如快走、太极拳、八段锦），每周3-5次、每次30分钟，循序渐进，以不感疲劳为度。\n3. 合理饮食，均衡营养，减少咖啡、浓茶、酒精及辛辣刺激性食物摄入，睡前避免饱食。\n4. 学会情绪管理，适当减压，避免精神紧张与过度思虑；戒烟限酒。\n【随诊要求】\n1. 用药2周后复诊，评估症状改善情况及药物耐受性，必要时调整用药方案。\n2. 若症状加重、出现新发胸痛、明显呼吸困难、晕厥等，需及时就诊，完善心电图、心脏彩超等检查排除器质性疾病。\n3. 症状缓解后建议每1-3个月门诊随访1次，评估停药时机及复发风险。"},"icd10_diagnosis":"","icd10_secondary":[],"icd9cm3_procedure":[]}},"locator":{"file":"门诊住院病历模板/病历模板包_全部_20261111.json","arrayRow":356,"caseRow":1},"sourceHash":"10e4fdb435986b7b85f847c3951d0cb0eafdce0f372c5617949c05b337149194","contentHash":"712a7c1ed1969bc305979b6e1065f992140fbabcb4b490304526883eef5e0a58","pinyin":"zhiwushenjinggongnengwenluan","initials":"zwsjgnwl","setting":"out","caseName":"门诊病历221","templateNames":["主诉","现病史","既往史","个人史及过敏史","体格检查","辅助检查","初步诊断","处理方案"],"emptyTemplates":[],"escapedNewlines":[],"quickFields":[["病例名称","门诊病历221",60],["模板名称","主诉 现病史 既往史 个人史及过敏史 体格检查 辅助检查 初步诊断 处理方案",30],["主要诊断编码","",30]]},{"id":"templates-90353d9bf614b5565e90","key":"v1-c9ccc21dfe2a3058|templates-90353d9bf614b5565e90","module":"templates","moduleKey":"v1-c9ccc21dfe2a3058|templates","version":"v1-c9ccc21dfe2a3058","title":"白血病","category":"门诊病历模板","raw":{"name":"白血病","category":"门诊病历模板","case":{"case_name":"门诊病历222","templates":{"主诉":"发热、乏力、面色苍白伴皮肤出血点3周。","现病史":"患者于3周前无明显诱因出现发热（体温最高39.2℃，多为持续，抗生素效果不佳），进行性乏力、面色苍白、活动后心慌气短，伴皮肤瘀点瘀斑、牙龈出血、鼻出血，有骨痛（胸骨压痛）、淋巴结肿大、肝脾肿大，为白血病浸润表现，食欲减退，体重下降约4kg。有无化学毒物或放射线接触史及血液病家族史：无。今日来我院门诊就诊。","既往史":"既往体健，否认高血压、糖尿病、冠心病等慢性病史。否认肝炎、结核等传染病史。否认手术外伤史。否认食物药物过敏史。预防接种史随社会。","个人史及过敏史":"生于原籍，久居本地，无疫区疫水接触史，无特殊粉尘毒物放射性物质接触史。不吸烟，不饮酒。生活规律。否认食物药物过敏史。","体格检查":"T38.2℃，P104次/分（可增快），R22次/分，BP110/70mmHg。神志清楚，贫血貌，皮肤可见瘀点瘀斑，巩膜无黄染。浅表淋巴结未触及肿大，胸骨压痛（+）。心肺听诊未闻及明显异常。腹平软，肝肋下未触及，脾肋下未触及，双下肢无水肿。","辅助检查":"【必做】血常规（白细胞升高、贫血、血小板减少，三系异常）、外周血涂片（原始或幼稚细胞，提示急性白血病）、凝血功能、肝肾功能、电解质、尿酸；【确诊】骨髓穿刺和活检（原始细胞≥20%，为急性白血病确诊依据）、流式细胞术免疫分型（明确系列，AML或ALL）、染色体核型及融合基因（预后分层）。","初步诊断":"1. 急性白血病？（AML或ALL，待骨髓确诊）\n（注：疑白血病应立即转血液科住院：尽快骨髓穿刺明确诊断分型；急性白血病病情凶险（感染、出血，尤其颅内出血、DIC），确诊后尽早化疗（AML：蒽环类+阿糖胞苷（3+7方案）；ALL：VDLP等方案），支持治疗（成分输血、抗感染、尿酸控制）；年轻高危者缓解后行异基因造血干细胞移植评估；中枢神经系统白血病预防（鞘内注射）。）","处理方案":"【药物治疗】\n1. 急性髓系白血病诱导缓解（DA\"3+7\"方案）：柔红霉素60mg/m²静脉滴注d1-3+阿糖胞苷100mg/m²静脉滴注d1-7，联合治疗28天为1周期；缓解后按计划行巩固化疗。门诊化疗期间应每周监测血常规及骨髓象调整剂量。\n2. 急性淋巴细胞白血病诱导缓解（VDLP方案）：长春新碱1.4mg/m²（单次最大2mg）静脉推注d1、8、15、22；柔红霉素40mg/m²静脉滴注d1-3、15-17；左旋门冬酰胺酶6000U/m²肌肉注射d19-28；泼尼松40-60mg/m²口服d1-28，后逐渐减量。\n3. 慢性粒细胞白血病慢性期（首选TKI）：伊马替尼片400mg口服qd，持续长期服用；服药期间每1-2周复查血常规，达血液学缓解后定期监测BCR-ABL融合基因定量调整用药。\n4. 对症支持用药：别嘌醇片0.1g口服tid（化疗前后防治高尿酸血症及肿瘤溶解综合征），并予碳酸氢钠片1.0g口服tid碱化尿液；粒细胞缺乏伴发热时尽早启用广谱抗感染（如头孢哌酮舒巴坦3.0g静脉滴注q12h，发热持续48小时以上联合万古霉素1.0g静脉滴注q12h）。\n\n【一般治疗及生活指导】\n1. 充分休息：贫血或化疗期间卧床或半卧床休息，避免剧烈活动与劳累，血红蛋白低于60g/L时减少下床活动防止跌倒。\n2. 饮食管理：给予高蛋白、高热量、高维生素、易消化软食（如鱼虾、蛋、瘦肉、新鲜蔬果汁），食物充分煮熟，禁食生冷、坚硬、辛辣及带骨刺食物，预防消化道出血与感染。\n3. 预防感染：勤洗手、勤更换衣物床单，外出佩戴口罩，避免去人群密集及空气污浊场所；保持口腔清洁，使用软毛牙刷，饭前饭后漱口。\n4. 出血防护：避免磕碰及皮肤损伤，不用牙签剔牙，不挖鼻孔，剪短指甲；密切观察皮肤、黏膜有无出血点、瘀斑，以及血尿、黑便、牙龈出血等情况，出现异常及时就医。\n\n【随诊要求】\n1. 化疗期间每周至少复查1次血常规，并监测肝肾功能、电解质及凝血功能；骨髓抑制期（WBC<1.0×10⁹/L或PLT<20×10⁹/L）应增加监测频次并警惕感染、出血。\n2. 按疗程规定时间返院行骨髓穿刺及微小残留病（MRD）检测，评估缓解深度并决定后续巩固或维持治疗；CML患者每3个月复查血常规及BCR-ABL融合基因定量。\n3. 出现发热（尤其体温≥38℃）、寒战、皮肤黏膜或内脏出血、骨关节疼痛、淋巴结肿大、腹痛腹胀等任何新发症状时，应立即返院就诊，切勿自行使用退热药或止血药。\n4. 规律随访门诊，由血液科专科医师制定个体化后续方案；长期服用TKI者需定期监测心脏功能（心电图、超声心动图）及肝肾功能。"},"icd10_diagnosis":"","icd10_secondary":[],"icd9cm3_procedure":[]}},"locator":{"file":"门诊住院病历模板/病历模板包_全部_20261111.json","arrayRow":357,"caseRow":1},"sourceHash":"10e4fdb435986b7b85f847c3951d0cb0eafdce0f372c5617949c05b337149194","contentHash":"f8b52433009b768eecfeb5c4c7f7c4a8c2b8b6025ea70995f63a57bae7b6b236","pinyin":"baixuebing","initials":"bxb","setting":"out","caseName":"门诊病历222","templateNames":["主诉","现病史","既往史","个人史及过敏史","体格检查","辅助检查","初步诊断","处理方案"],"emptyTemplates":[],"escapedNewlines":[],"quickFields":[["病例名称","门诊病历222",60],["模板名称","主诉 现病史 既往史 个人史及过敏史 体格检查 辅助检查 初步诊断 处理方案",30],["主要诊断编码","",30]]},{"id":"templates-fce550766cf43ecda39b","key":"v1-c9ccc21dfe2a3058|templates-fce550766cf43ecda39b","module":"templates","moduleKey":"v1-c9ccc21dfe2a3058|templates","version":"v1-c9ccc21dfe2a3058","title":"多发性骨髓瘤","category":"门诊病历模板","raw":{"name":"多发性骨髓瘤","category":"门诊病历模板","case":{"case_name":"门诊病历223","templates":{"主诉":"骨痛、乏力伴贫血、反复感染6月。","现病史":"患者于6月前渐出现腰背部或肋骨骨痛（活动后加重、休息减轻，夜间明显），乏力、面色苍白，反复肺部或泌尿系感染，有泡沫尿、水肿（肾损害），无头晕、视物模糊（高黏滞综合征），无病理性骨折，体重下降约5kg，无发热。有无血液病家族史：无。今日来我院门诊就诊。","既往史":"既往体健，否认高血压、糖尿病、冠心病等慢性病史。否认肝炎、结核等传染病史。否认手术外伤史。否认食物药物过敏史。预防接种史随社会。","个人史及过敏史":"生于原籍，久居本地，无疫区疫水接触史，无特殊粉尘毒物放射性物质接触史。不吸烟，不饮酒。生活规律。否认食物药物过敏史。","体格检查":"T36.5℃，P88次/分，R18次/分，BP120/75mmHg。神志清楚，贫血貌。胸骨、肋骨、脊柱压痛，无骨骼变形及肿物，浅表淋巴结未触及肿大。心肺听诊未见明显异常。腹平软，肝脾肋下未触及。双下肢无水肿。","辅助检查":"检查计划：患者6月来渐起腰背部及肋骨骨痛，活动后加重、休息减轻而夜间明显，伴乏力、面色苍白，反复肺部及泌尿系感染，并有泡沫尿、水肿等肾损害表现，体重下降约5kg，门诊需优先筛查血液系统疾病、排查继发因素：查血常规了解贫血程度及有无白细胞、血小板减少，本病贫血多呈正细胞正色素性；查血沉以了解炎症及球蛋白升高情况，本病常见显著增快；完善血清蛋白电泳及免疫固定电泳以明确有无M蛋白即单克隆免疫球蛋白，为诊断核心依据；完善血清游离轻链及κ或λ比值以了解轻链型骨髓瘤及克隆性，查血或尿轻链辅助明确轻链分泌情况；患者长期骨痛并有肾损害表现，需完善肝肾功能检查明确有无肾功能不全，为后续化疗及双膦酸盐用药评估脏器储备；查血钙排除高钙血症所致乏力、肾功能损害，查白蛋白及β2-微球蛋白评估营养状态与肿瘤负荷（分期）；患者骨痛以腰背、肋骨为著，完善全身骨骼X线或低剂量CT检查明确有无溶骨性破坏及病理性骨折；因腰背痛突出，完善脊柱MRI明确有无椎体压缩性骨折及骨髓浸润范围；为确诊本病，完善骨髓穿刺和活检（骨髓瘤细胞≥10%，即浆细胞克隆性增殖），必要时加做免疫分型与细胞遗传学。\n\n（检查清单）\n【必做】血常规（贫血，呈正细胞正色素性）、血沉（显著增快）、血清蛋白电泳及免疫固定电泳（M蛋白，即单克隆免疫球蛋白）、血清游离轻链及κ或λ比值、血或尿轻链、肝肾功能、血钙、β2-微球蛋白、白蛋白；【影像学】全身骨骼X线或低剂量CT（溶骨性破坏、病理性骨折）、脊柱MRI（疑椎体压缩或骨髓浸润）；【确诊】骨髓穿刺和活检（骨髓瘤细胞≥10%，即浆细胞克隆性增殖）。","初步诊断":"1. 多发性骨髓瘤（IgG或IgA或轻链型，Ⅱ期，待确诊）\n（注：确诊后转血液科：治疗原则为症状性骨髓瘤启动治疗：诱导（硼替佐米+来那度胺+地塞米松（VRd）方案，年龄<65岁且体能好者可自体干细胞移植巩固）、维持治疗（来那度胺）；支持治疗：骨病用双膦酸盐（唑来膦酸4mg每月静滴，注意肾功能及颌骨坏死）、放疗（局部剧痛或病理性骨折风险），纠正贫血（促红素）、抗感染、处理高钙血症及肾衰竭（水化、补液、避免肾毒性药物）；定期监测M蛋白评估疗效。）","处理方案":"【药物治疗】\n1. 诱导化疗（VRd方案，首选）：硼替佐米（万珂）1.3mg/m²皮下注射，d1、4、8、11；来那度胺25mg口服qd，d1-21；地塞米松20-40mg口服，d1-2、8-9、15-16、22-23（老年或体弱者20mg），28天为1疗程，诱导治疗4-6疗程后复查血清蛋白电泳（M蛋白）、血清游离轻链评估疗效；缓解后以来那度胺10mg口服qd、d1-21维持治疗。肾功能不全者来那度胺需按肌酐清除率减量。\n2. 骨病防治：唑来膦酸4mg静脉滴注（滴注时间≥15分钟），每月1次，同时口服碳酸钙D3片600mg qd＋骨化三醇0.25μg bid；治疗满2年或病情稳定者重新评估是否继续用药。\n3. 预防感染：阿昔洛韦400mg口服bid，硼替佐米治疗期间常规预防带状疱疹；含大剂量地塞米松疗程中加用复方磺胺甲噁唑1片口服bid，预防肺孢子菌肺炎。\n4. 降尿酸及水化：别嘌醇100mg口服tid，化疗初期常规预防高尿酸血症；每日饮水2000-3000ml保证尿量，促进异常免疫球蛋白及尿酸排泄，减轻肾小管损害，高钙血症时加强水化并监测血钙。\n\n【一般治疗及生活指导】\n1. 活动与防跌倒：有溶骨性破坏或骨痛者睡硬板床、轴式翻身，避免弯腰负重、剧烈运动、久站久坐及按摩推拿，防止病理性骨折及脊髓压迫。\n2. 饮食：高蛋白、高维生素、易消化饮食（瘦肉、蛋、奶、豆制品等）；高尿酸者低嘌呤饮食，避免动物内脏、浓肉汤、海鲜及啤酒；肾功能不全者低盐、优质低蛋白饮食；每日饮水2000-3000ml。\n3. 预防感染：注意保暖、勤洗手、佩戴口罩，避免去人群密集场所及接触呼吸道感染者；保持口腔及皮肤清洁，出现牙龈出血、鼻衄时及时处理。\n4. 观察药物不良反应：出现手足麻木、刺痛等周围神经症状，单侧下肢肿胀疼痛（警惕深静脉血栓），以及发热、乏力、出血倾向时及时就诊，勿自行停药或增减剂量。\n\n【随诊要求】\n1. 化疗期间每2周或每疗程前后门诊复查血常规、肝肾功能、电解质（尤其血钙）、尿酸、β2-微球蛋白、血清蛋白电泳（M蛋白）、血清游离轻链及24小时尿轻链、尿本周蛋白，评估疗效及骨髓抑制程度。\n2. 每2-3个月复查骨骼影像（全身X线、MRI或PET-CT）评估骨病进展；出现骨痛加重、新发骨折或下肢麻木无力（警惕脊髓压迫）时立即就诊。\n3. 使用唑来膦酸者每疗程用药前复查肾功能、血钙，每3-6个月行口腔检查，预防颌骨坏死；长期服用来那度胺者注意血栓风险，定期评估。\n4. 完成诱导治疗（4-6疗程）后按医嘱进入维持治疗或巩固/自体移植评估，维持治疗期间每1-3个月门诊复诊；发热＞38℃、感染征象、出血、骨痛加重等随时就诊。"},"icd10_diagnosis":"","icd10_secondary":[],"icd9cm3_procedure":[]}},"locator":{"file":"门诊住院病历模板/病历模板包_全部_20261111.json","arrayRow":358,"caseRow":1},"sourceHash":"10e4fdb435986b7b85f847c3951d0cb0eafdce0f372c5617949c05b337149194","contentHash":"a7701892be5e4b4c2abb20f0f4d7dd970a3f940c91e6b9dbbc78992c2032d1b7","pinyin":"duofaxinggusuiliu","initials":"dfxgsl","setting":"out","caseName":"门诊病历223","templateNames":["主诉","现病史","既往史","个人史及过敏史","体格检查","辅助检查","初步诊断","处理方案"],"emptyTemplates":[],"escapedNewlines":[],"quickFields":[["病例名称","门诊病历223",60],["模板名称","主诉 现病史 既往史 个人史及过敏史 体格检查 辅助检查 初步诊断 处理方案",30],["主要诊断编码","",30]]},{"id":"templates-e11e1009df304aaca142","key":"v1-c9ccc21dfe2a3058|templates-e11e1009df304aaca142","module":"templates","moduleKey":"v1-c9ccc21dfe2a3058|templates","version":"v1-c9ccc21dfe2a3058","title":"骨髓增生异常综合征","category":"门诊病历模板","raw":{"name":"骨髓增生异常综合征","category":"门诊病历模板","case":{"case_name":"门诊病历224","templates":{"主诉":"乏力、面色苍白伴皮肤出血点、反复感染6月。","现病史":"患者于6月前渐出现乏力、面色苍白、活动后心慌气短，伴皮肤瘀点瘀斑、牙龈出血、鼻出血，反复呼吸道感染，无发热，食欲减退，体重下降约4kg。有无化学毒物（苯）、放射线接触史、化疗史及血液病家族史：无。今日来我院门诊就诊。","既往史":"既往体健，否认高血压、糖尿病、冠心病等慢性病史。否认肝炎、结核等传染病史。否认手术外伤史。否认食物药物过敏史。预防接种史随社会。","个人史及过敏史":"生于原籍，久居本地，无疫区疫水接触史，无特殊粉尘毒物放射性物质接触史。不吸烟，不饮酒。生活规律。否认食物药物过敏史。","体格检查":"T36.8℃，P92次/分，R20次/分，BP115/70mmHg。神志清楚，贫血貌，皮肤可见瘀点瘀斑。浅表淋巴结未触及肿大。胸骨无压痛。心肺听诊未见明显异常。腹平软，肝肋下未触及，脾肋下2cm，可触及肿大。","辅助检查":"【必做】血常规（一系或多系血细胞减少，即贫血或白细胞减少或血小板减少，可伴大红细胞）、外周血涂片（病态造血：粒细胞分叶不良、血小板形态异常）、网织红细胞（不高）、铁蛋白、叶酸维生素B12（排除营养性贫血）、肝肾功能；【确诊】骨髓穿刺和活检（病态造血、原始细胞比例、铁染色，即环形铁粒幼细胞）及染色体核型分析（预后分层，即IPSS-R评分）。","初步诊断":"1. 骨髓增生异常综合征（MDS-U型，待骨髓确诊）\n（注：确诊后转血液科按危险分层治疗：低危，予以支持治疗（输血、促红素、粒细胞集落刺激因子）+免疫调节（来那度胺，del(5q)型）+去甲基化（阿扎胞苷或地西他滨）；高危，以去甲基化治疗为主，年轻适合者行异基因造血干细胞移植（唯一根治手段）；防治感染、出血；MDS有向急性白血病转化风险（高危组），需规律随访血常规及骨髓。）","处理方案":"【药物治疗】\n1. 重组人促红细胞生成素注射液10000IU皮下注射，每周3次，连用8~12周评估疗效（Hb<100g/L、内源性EPO<500mIU/ml的贫血患者）；有效者长期维持，Hb≥120g/L或Hb上升过快（每月增幅>20g/L）时减量或暂停。\n2. 来那度胺胶囊10mg口服，每日1次，连用21天，28天为1周期，至少4~6周期评估（适用于伴del(5q)的较低危患者）；用药期间须严格避孕，每周期复查血常规、肝肾功能，必要时按血小板计数调整剂量。\n3. 重组人粒细胞集落刺激因子注射液150~300μg皮下注射，每日1次（当中性粒细胞绝对值<1.0×10⁹/L或合并感染时启用），至中性粒细胞恢复后停用。\n4. 地西他滨20mg/m²静脉滴注，每日1次，连用5天，每4周1周期（适用于较高危/高危患者，建议日间病房或住院给药），持续至疾病进展或不能耐受。\n【一般治疗及生活指导】\n1. 注意休息，避免劳累、熬夜及剧烈运动；明显乏力或Hb<60g/L者以卧床休息为主，减少耗氧，保证充足睡眠。\n2. 高蛋白、高维生素、易消化软食（如鱼、蛋、瘦肉、新鲜蔬果），食物充分煮熟，忌生冷、坚硬及带刺食物；血小板<30×10⁹/L时避免粗糙饮食以防消化道出血。\n3. 血小板减少者避免磕碰、剧烈咳嗽、用力擤鼻及用力排便，刷牙用软毛牙刷、动作轻柔，出现皮肤瘀斑、牙龈出血、黑便及时就医。\n4. 中性粒细胞<1.0×10⁹/L时避免去人群密集场所，注意手卫生及口腔护理；禁烟酒，勿自行服用不明\"偏方\"及可能影响造血功能或抗凝的药物，未经医师评估不接种活疫苗。\n【随诊要求】\n1. 每2~4周门诊复查血常规及网织红细胞，评估疗效与输血需求；贫血或血小板明显减少者每1~2周复查1次。\n2. 每3~6个月复查骨髓穿刺+活检及细胞遗传学检查（染色体核型/FISH）评估疾病演变；出现原始细胞比例升高或血细胞减少进行性加重时随时复查。\n3. 使用来那度胺者每月监测血常规、肝肾功能、甲状腺功能并严格避孕；使用促红细胞生成素者定期监测血压及血红蛋白上升速率；使用地西他滨者每周期前后复查血常规、肝肾功能。\n4. 累计输注红细胞≥20单位或血清铁蛋白持续>1000μg/L者，予去铁治疗（地拉罗司20mg/kg口服每日1次，餐前30分钟服用）并定期监测铁蛋白、肝肾功能及听力。\n5. 若出现发热、畏寒、感染征象、出血加重、骨痛或乏力进行性加重等，立即就诊，不可延误。"},"icd10_diagnosis":"","icd10_secondary":[],"icd9cm3_procedure":[]}},"locator":{"file":"门诊住院病历模板/病历模板包_全部_20261111.json","arrayRow":359,"caseRow":1},"sourceHash":"10e4fdb435986b7b85f847c3951d0cb0eafdce0f372c5617949c05b337149194","contentHash":"b1ea85e29b0b830358efced44ca5bad659de503cf629b44023840f207c66ed24","pinyin":"gusuizengshengyichangzonghezheng","initials":"gszsyczhz","setting":"out","caseName":"门诊病历224","templateNames":["主诉","现病史","既往史","个人史及过敏史","体格检查","辅助检查","初步诊断","处理方案"],"emptyTemplates":[],"escapedNewlines":[],"quickFields":[["病例名称","门诊病历224",60],["模板名称","主诉 现病史 既往史 个人史及过敏史 体格检查 辅助检查 初步诊断 处理方案",30],["主要诊断编码","",30]]},{"id":"templates-5f1dac4a1349b4d5ac2c","key":"v1-c9ccc21dfe2a3058|templates-5f1dac4a1349b4d5ac2c","module":"templates","moduleKey":"v1-c9ccc21dfe2a3058|templates","version":"v1-c9ccc21dfe2a3058","title":"血友病","category":"门诊病历模板","raw":{"name":"血友病","category":"门诊病历模板","case":{"case_name":"门诊病历225","templates":{"主诉":"反复关节、肌肉出血肿痛10年，再发右膝关节肿痛3天。","现病史":"患者为血友病A（因子Ⅷ缺乏）患者，自幼反复出现关节（膝、肘、踝）、肌肉自发性或轻微外伤后出血、肿胀疼痛。本次于3天前轻微扭伤后出现右膝关节肿胀、疼痛、活动受限，无皮肤破口，无发热。无血尿、黑便、颅内出血等严重出血史，家族史：母系男性发病。今日来我院门诊就诊。","既往史":"既往体健，否认高血压、糖尿病、冠心病等慢性病史。否认肝炎、结核等传染病史。否认手术外伤史。否认食物药物过敏史。预防接种史随社会。","个人史及过敏史":"生于原籍，久居本地，无疫区疫水接触史，无特殊粉尘毒物放射性物质接触史。不吸烟，不饮酒。生活规律。否认食物药物过敏史。","体格检查":"T36.6℃，P84次/分，R18次/分，BP115/70mmHg。神志清楚，查体合作。右膝关节明显肿胀、皮温升高，浮髌试验（+），关节活动受限（屈曲约90°），局部压痛（+），皮肤无破口。全身皮肤可见瘀斑。口腔黏膜、鼻腔无活动性出血。","辅助检查":"【必做】血常规、活化部分凝血活酶时间（APTT延长，用于筛选）、凝血因子Ⅷ或Ⅸ活性（降低，用于确诊及分型：重型<1%、中型1%~5%、轻型>5%~40%）、血管性血友病因子（vWF:Ag，排除vWD）；【影像学】关节X线或超声或MRI（靶关节评估：慢性滑膜炎、关节破坏）。","初步诊断":"1. 血友病A，重型，右膝关节出血\n（注：急性关节或肌肉出血处理：立即补充凝血因子，血友病A：重组人凝血因子Ⅷ（轻型25~40IU/kg，重型大出血50IU/kg，q8~12h至出血停止）、血友病B：凝血因子Ⅸ；无因子制剂时冷沉淀或新鲜冰冻血浆（A型）；制动（RICE）、禁用阿司匹林或NSAIDs及肌注；抗纤溶药（氨甲环酸，用于黏膜出血）；严重出血（颅内、消化道、腹膜后）为急症需足量因子替代并住院；预防治疗（规律因子替代，用于重型儿童）防关节病变；转血液科并建立血友病登记随访，避免创伤及有创操作（需因子保护下进行）。）","处理方案":"【药物治疗】\n1. 替代治疗（首选）：凝血因子Ⅷ（如重组人凝血因子Ⅷ，拜科奇）20～40 IU/kg，静脉注射，q12h，按出血部位及严重程度调整剂量与疗程，即轻度出血20 IU/kg×1～2天；中度出血30 IU/kg q12h×3～5天；重度或危险部位（颅内、消化道、咽喉）出血40～50 IU/kg q8～12h×7～14天，使FⅧ:C维持于止血水平以上；血友病B改用凝血因子Ⅸ（如重组人凝血因子Ⅸ，贝赋）同法给药。\n2. 轻中型血友病A（FⅧ:C≥5%）：去氨加压素（DDAVP，弥凝）0.3 μg/kg 皮下注射或鼻喷雾剂喷鼻，每12～24小时1次，用药前及用药后监测FⅧ:C，确保止血有效。\n3. 抗纤溶治疗：氨甲环酸片（妥塞敏）1.0 g po tid，与替代治疗联用，疗程3～5天；禁忌：血尿、DIC及合并血栓性疾病者禁用。\n4. 预防治疗（重型或年出血≥2次的关节出血者）：低剂量方案重组人凝血因子Ⅷ 10～15 IU/kg 静脉注射，每周2～3次；或艾美赛珠单抗（Hemlibra）首剂3 mg/kg 皮下注射，每周1次×4周后改为1.5 mg/kg 每周1次维持。\n【一般治疗及生活指导】\n1. 避免一切外伤及剧烈活动（对抗性体育、骑车、爬高、提重物等），以游泳、散步等非对抗性运动为宜；拔牙、手术及侵入性操作前须预防性补充凝血因子并告知血友病史。\n2. 禁用阿司匹林、布洛芬等非甾体抗炎药及影响血小板功能的中西药物，忌肌肉注射；出血急性期局部冷敷15～20分钟、加压包扎并抬高患肢制动。\n3. 保持口腔卫生，进温软易消化食物，避免过硬、带骨刺食物损伤黏膜；每日观察有无血尿、黑便、血便及关节肿胀、皮损瘀斑。\n4. 家中常备凝血因子制剂与冰袋，学习关节出血自我识别（局部灼热、胀痛、活动受限），出现可疑出血及时联系专科。\n【随诊要求】\n1. 每3～6个月专科复诊1次，复查血常规、FⅧ:C或FⅨ:C活性、抑制物（Bethesda法）检测及病毒学筛查（HBV、HCV、HIV）。\n2. 关节出血后2周内骨科或康复科随诊评估关节功能，防止血友病性关节病；出现新发出血、常规剂量止血无效或疑有抑制物者及时就诊。\n3. 规律替代或预防治疗者监测输注反应、过敏及血栓风险；拟行手术、拔牙或妊娠者提前至专科门诊评估并制定围术期替代方案。","手术记录":"手术记录\n\n手术日期：（门诊病历未记载，请术者据实际填写）\n术前诊断：血友病A型；右膝关节出血（血友病性关节出血）\n术后诊断：同术前诊断\n手术名称：右膝关节腔穿刺抽吸、关节腔积血清除术，在凝血因子替代保护下实施（门诊病历未记载具体术式，仅记载\"手术、拔牙或妊娠者提前至专科门诊评估并制定围术期替代方案\"；若实际行关节镜下滑膜切除术等其他术式，请术者据实修改）\n术者：（病历未记载，请术者补充）　　助手：（病历未记载，请补充）\n麻醉方法：（病历未记载，请补充）【住址】；因本病存在出血倾向，椎管内麻醉及肌肉注射应避免，麻醉方式须经麻醉科与血液科共同评估\n体位：仰卧位，右膝伸直位或轻度屈曲位（常规，请据实际填写）\n手术经过（要点，具体步骤请术者据实际操作补充）：本例为血友病患者右膝关节自发性或轻微外伤后出血，任何有创操作均患者凝血因子替代保护下进行。\n1. 围手术期凝血因子替代方案（核心安全措施，依据门诊处理方案）：术前30分钟至1小时输注凝血因子，血友病A予重组人凝血因子Ⅷ 40～50IU/kg（按出血严重程度与术式调整），血友病B予凝血因子Ⅸ同法给药，使FⅧ:C或FⅨ:C提升至80%～100%并维持至手术结束；轻中型血友病A（FⅧ:C≥5%）可选用去氨加压素0.3μg/kg静脉或皮下注射，用药前后监测FⅧ:C确保止血有效；术前备足凝血因子制剂、冷沉淀及新鲜冰冻血浆。\n2. 常规消毒铺巾后，于右膝髌骨外上缘以穿刺针穿刺进入关节腔，抽吸关节腔内积血（抽吸量请据实记录），以生理盐水反复冲洗至回流液清亮，必要时关节腔内注入氨甲环酸或糖皮质激素（病历未记载，请术者据实际填写）。\n3. 拔针后穿刺点压迫5～10分钟，以弹力绷带加压包扎，局部冷敷，患肢支具制动于功能位。\n4. 术中严格避免切断或钳夹组织，如为开放或关节镜手术，患者凝血因子保护下精细操作、彻底止血，创面以明胶海绵等局部止血材料覆盖。\n5. 术后继续因子替代：术后第1～3天FⅧ 30～40IU/kg每12小时1次，维持FⅧ:C＞50%；此后20～30IU/kg每日1次，维持3～5天（血友病B改用凝血因子Ⅸ），并每日监测APTT、FⅧ:C或FⅨ:C及抑制物（Bethesda法）。\n术中出血量：（病历未记载，请据实际填写；建议记录关节腔内抽吸积血量及术中失血量）　　输血量：（病历未记载，请据实际填写；出血量大或血红蛋白明显下降时需输注红细胞及凝血因子制剂）\n切除标本：无组织标本切除（如关节镜下切除滑膜组织，须送病理检查，病历未记载，请据实填写）\n术中意外及处理：无（病历未记载；如发生创面渗血不止、替代治疗无效提示凝血因子抑制物产生、关节腔再出血等，应立即追加凝血因子剂量并请血液科会诊，请据实记录）\n术后情况：穿刺或术后继续凝血因子替代及抗纤溶治疗（氨甲环酸1.0g口服每日3次，疗程3～5天；血尿、DIC及血栓性疾病者禁用），患肢制动、冷敷、抬高，2周内骨科或康复科随诊评估关节功能；禁用阿司匹林、布洛芬等非甾体抗炎药及一切肌肉注射；出现新发出血、常规剂量止血无效或关节肿痛加重，及时就诊血液科及骨科。\n签名：术者________　　记录者________","手术知情同意书":"手术知情同意书\n\n患者姓名：（病历未记载，请补充）　　性别：（病历未记载）　　年龄：（病历未记载）\n科别：血液科/骨科　　住院号（门诊号）：门诊病历225　　就诊日期：（病历未记载，请补充）\n术前诊断：血友病（A/B型，分型及凝血因子活性分级病历未记载）；右膝关节出血\n拟定手术名称：右膝关节腔穿刺抽吸、关节腔积血清除术（在凝血因子替代保护下实施；若行关节镜下滑膜切除等其他术式，以实际术式为准）\n拟定手术日期：（病历未记载，请补充）\n麻醉方式：（病历未记载，请补充；因出血倾向应避免椎管内麻醉及肌肉注射，需麻醉科与血液科共同评估）\n\n一、手术目的：清除右膝关节腔内积血，减轻关节肿胀、疼痛及活动受限，防止反复出血导致血友病性关节病（慢性滑膜炎、关节软骨破坏、关节畸形），并在凝血因子保护下安全完成操作。\n\n二、替代治疗方案（各有适应证与利弊）：\n1. 单纯凝血因子替代治疗+制动、冷敷、加压（RICE）：轻中度关节出血可先行替代治疗后观察，多数可吸收，但大量积血吸收慢、疼痛重，可能残留关节功能障碍。\n2. 抗纤溶治疗（氨甲环酸）联合替代治疗：辅助止血，适用于黏膜出血，关节腔大量积血时不能替代穿刺引流。\n3. 关节镜下滑膜切除术或放射性滑膜切除术：适用于反复关节出血、慢性滑膜炎及靶关节者，可减少出血次数，但需更充分的因子替代与更长的围术期支持。\n4. 不做有创操作：关节腔积血可机化，导致关节僵硬、畸形及永久性功能障碍；但单纯观察亦不会立即危及生命。\n\n三、手术及围术期风险与并发症：\n1. 出血风险显著高于常人：穿刺点渗血、关节腔再出血、皮下及肌肉血肿，严重者可致失血性贫血、休克；如替代剂量不足或产生凝血因子抑制物，止血可能失败。\n2. 凝血因子输注相关风险：过敏反应、发热、寒战；反复输注可产生凝血因子抑制物（Bethesda法阳性），使后续替代治疗失效，为本病最需警惕的并发症。\n3. 血源性感染风险：输注凝血因子制剂、冷沉淀、新鲜冰冻血浆等血制品可能传播乙型肝炎、丙型肝炎、艾滋病等疾病。\n4. 关节腔感染（化脓性关节炎）、穿刺针道感染。\n5. 关节软骨及周围软组织损伤、关节功能障碍、关节畸形残留。\n6. 麻醉意外及心脑血管意外；血管迷走反射、晕厥。\n7. 血栓形成风险（替代治疗、抗纤溶药物与制动共同作用）。\n8. 禁用阿司匹林、布洛芬等非甾体抗炎药及肌肉注射，如违反可加重出血；用药期间需监测APTT及FⅧ:C/FⅨ:C。\n9. 其他不可预知的并发症。\n\n四、麻醉风险：麻醉药物过敏、呼吸循环抑制、心律失常、误吸等；因凝血功能异常，椎管内麻醉有椎管内血肿及截瘫风险，肌肉注射可致局部血肿，应由麻醉医师与血液科医师共同评估并另行签署麻醉知情同意书。\n\n五、输血及血制品：术中、术后出血需输注红细胞、血浆，并必须使用凝血因子制剂及可能使用冷沉淀、新鲜冰冻血浆；输血及血制品可能传播肝炎、艾滋病等血源性疾病并可能发生输血反应。已另行签署输血知情同意书。\n\n六、术中改变术式的可能：若术中发现关节腔积血量大、血肿机化、滑膜增生明显或合并关节内其他病变，可能扩大手术范围（如改行关节镜下滑膜切除术）；若替代治疗后仍渗血不止，可能终止手术、加压包扎并继续替代治疗，术者将与家属沟通后决定。\n\n七、术后注意事项：严格遵医嘱按时、足量输注凝血因子，不得自行减量或停药；监测FⅧ:C/FⅨ:C、APTT及抑制物；患肢制动、冷敷、抬高，避免负重及剧烈活动；禁用阿司匹林、布洛芬等非甾体抗炎药及一切肌肉注射；注意口腔卫生，进温软饮食；如出现关节肿胀加重、新发出血、尿血、黑便、剧烈头痛呕吐（警惕颅内出血），立即急诊就诊。建议尽早建立血友病登记并规律随访。\n\n八、其他：诊疗费用按医保政策结算，具体以实际发生为准；患者及家属有权了解病情并可随时提出疑问。\n\n医师签名：____________　　日期：____年__月__日\n患者（或家属）签名：____________与患者关系：______　　日期：____年__月__日"},"icd10_diagnosis":"","icd10_secondary":[],"icd9cm3_procedure":[]}},"locator":{"file":"门诊住院病历模板/病历模板包_全部_20261111.json","arrayRow":360,"caseRow":1},"sourceHash":"10e4fdb435986b7b85f847c3951d0cb0eafdce0f372c5617949c05b337149194","contentHash":"2acd21dfc87da277df8575b861c7bf297a8d40c736746a55bef3ab5f51bf65e9","pinyin":"xueyoubing","initials":"xyb","setting":"mixed","caseName":"门诊病历225","templateNames":["主诉","现病史","既往史","个人史及过敏史","体格检查","辅助检查","初步诊断","处理方案","手术记录","手术知情同意书"],"emptyTemplates":[],"escapedNewlines":[],"quickFields":[["病例名称","门诊病历225",60],["模板名称","主诉 现病史 既往史 个人史及过敏史 体格检查 辅助检查 初步诊断 处理方案 手术记录 手术知情同意书",30],["主要诊断编码","",30]]},{"id":"templates-2d6e51088e0fafdc5fba","key":"v1-c9ccc21dfe2a3058|templates-2d6e51088e0fafdc5fba","module":"templates","moduleKey":"v1-c9ccc21dfe2a3058|templates","version":"v1-c9ccc21dfe2a3058","title":"地中海贫血","category":"门诊病历模板","raw":{"name":"地中海贫血","category":"门诊病历模板","case":{"case_name":"门诊病历226","templates":{"主诉":"自幼贫血、面色苍白、发育落后10年，加重伴黄疸2周。","现病史":"患儿自幼（3岁起）出现面色苍白、乏力、生长发育较同龄落后，间歇性皮肤巩膜黄染，反复输血史（如重型β地中海贫血，开始输血年龄3岁，频率每3～4周1次）。有脾大，无胆石症（溶血所致），有骨骼改变（地贫面容：颅骨板障增宽、颧骨隆起）。家族史：父母均为携带者。今日来我院门诊就诊。","既往史":"既往体健，否认高血压、糖尿病、冠心病等慢性病史。否认肝炎、结核等传染病史。否认手术外伤史。否认食物药物过敏史。预防接种史随社会。","个人史及过敏史":"生于原籍，久居本地，无疫区疫水接触史，无特殊粉尘毒物放射性物质接触史。不吸烟，不饮酒。生活规律。否认食物药物过敏史。","体格检查":"T36.7℃，P96次/分，R22次/分，BP95/60mmHg。神志清楚，生长发育落后，贫血貌，巩膜轻度黄染（+）。地贫特殊面容（+）（颧骨隆起、眼距增宽、鼻梁塌陷）。心界扩大，为长期贫血高输出状态所致，双肺呼吸音清。腹膨隆，脾肋下4cm，为巨脾（重型常见）、肝肋下2cm，可触及肿大。","辅助检查":"【必做】血常规（小细胞低色素性贫血：MCV、MCH降低）、网织红细胞（升高）、外周血涂片（靶形红细胞，为特征性改变）、血清铁蛋白（升高，提示输血性铁过载）、血红蛋白电泳（HbA2升高、HbF升高，为诊断依据）；【基因诊断】地中海贫血基因检测（确诊及分型，即α或β地贫基因型）；【其他】肝肾功能、血糖（铁过载并发症筛查）、心脏MRI（心肌铁沉积，T2*评估）。","初步诊断":"1. 地中海贫血（β型，重型）\n（注：轻型无需特殊治疗（注意遗传咨询）；中间型或重型：规律输血维持Hb>90~105g/L+去铁治疗（去铁胺皮下泵注或去铁酮口服，铁过载为致死主因，需监测铁蛋白及脏器铁）；脾大脾亢者脾切除（权衡感染风险）；重型根治为异基因造血干细胞移植（儿童期最佳时机）；避免补铁剂（非缺铁）；预防感染及疫苗接种；转血液科或儿科专科长期管理。）","处理方案":"【药物治疗】\n1. 补充叶酸：叶酸片 5mg po qd，长期口服，用于轻、中型患者纠正慢性溶血所致叶酸缺乏。\n2. 祛铁治疗（输血依赖型）：地拉罗司分散片 20mg/kg/d po qd（餐前30分钟以水或果汁溶解后服用），每3个月依据血清铁蛋白调整剂量；或去铁酮片 25mg/kg po tid，铁蛋白<500μg/L时暂缓，治疗期间监测血常规及肝肾功能。\n3. 诱导HbF（β-地中海贫血中间型）：羟基脲片 15～20mg/kg/d 分2次口服，3个月为一疗程，据Hb及HbF水平调整剂量。\n4. 脾切除术后感染预防：青霉素V钾片 250mg po bid；青霉素过敏者改阿奇霉素片 250mg po qd，长期口服或遵医嘱。\n\n【一般治疗及生活指导】\n1. 饮食：均衡营养，适当增加富含叶酸、优质蛋白食物；输血依赖者减少动物肝脏、动物血等高铁食物摄入，餐后饮浓茶可减少铁吸收，禁止服用铁剂及含铁复合维生素。\n2. 休息与活动：轻、中型者可正常生活学习，避免剧烈运动及重体力劳动；重度贫血及输血依赖者注意休息、保证睡眠，避免劳累、熬夜及受凉。\n3. 预防感染：注意个人卫生，流感季节避免去人群密集场所，可接种流感及肺炎球菌疫苗（灭活/非活疫苗）；出现感染发热及时就医，防止诱发溶血危象。\n4. 禁忌与生育：避免使用磺胺类、伯氨喹等可能诱发溶血的药物；有生育计划者行地中海贫血遗传咨询及产前筛查/产前诊断。\n\n【随诊要求】\n1. 轻、中型患者每3～6个月门诊复查血常规、血清铁蛋白及叶酸水平。\n2. 输血依赖者每月复查血常规，每3个月复查血清铁蛋白、肝肾功能，每6～12个月行心脏/肝脏MRI T2*评估铁沉积。\n3. 服用羟基脲者每2～4周复查血常规，每3个月复查HbF及肝肾功能。\n4. 出现发热、黄疸加深、浓茶样尿、腹痛或贫血加重时立即就诊；脾切除者发热应警惕暴发性感染，及时急诊处理。"},"icd10_diagnosis":"","icd10_secondary":[],"icd9cm3_procedure":[]}},"locator":{"file":"门诊住院病历模板/病历模板包_全部_20261111.json","arrayRow":361,"caseRow":1},"sourceHash":"10e4fdb435986b7b85f847c3951d0cb0eafdce0f372c5617949c05b337149194","contentHash":"0120f586cd71dd1950038e70d0a852490c14df22e961f98277b4fdecd19da385","pinyin":"dizhonghaipinxue","initials":"dzhpx","setting":"out","caseName":"门诊病历226","templateNames":["主诉","现病史","既往史","个人史及过敏史","体格检查","辅助检查","初步诊断","处理方案"],"emptyTemplates":[],"escapedNewlines":[],"quickFields":[["病例名称","门诊病历226",60],["模板名称","主诉 现病史 既往史 个人史及过敏史 体格检查 辅助检查 初步诊断 处理方案",30],["主要诊断编码","",30]]},{"id":"templates-36985a7af312e9602e31","key":"v1-c9ccc21dfe2a3058|templates-36985a7af312e9602e31","module":"templates","moduleKey":"v1-c9ccc21dfe2a3058|templates","version":"v1-c9ccc21dfe2a3058","title":"痛风性关节炎","category":"门诊病历模板","raw":{"name":"痛风性关节炎","category":"门诊病历模板","case":{"case_name":"门诊病历227","templates":{"主诉":"反复关节红肿热痛5年，急性发作3天。","现病史":"患者5年来反复出现第一跖趾关节急性关节炎发作，多于夜间、饮酒或高嘌呤饮食或受凉或劳累后突发，红肿灼痛剧烈（刀割样），数小时至1天内达高峰，活动受限，7~10天自行缓解。本次于3天前再次发作，无痛风石（耳廓、关节周围），无肾结石，血尿酸水平最高520μmol/L，用药史（降尿酸药使用情况）：未规律服用降尿酸药。今日来我院门诊就诊。","既往史":"既往体健，否认高血压、糖尿病、冠心病等慢性病史。否认肝炎、结核等传染病史。否认手术外伤史。否认食物药物过敏史。预防接种史随社会。","个人史及过敏史":"生于原籍，久居本地，无疫区疫水接触史，无特殊粉尘毒物放射性物质接触史。不吸烟；饮酒10年，约4两/日。生活规律。否认食物药物过敏史。","体格检查":"T37.2℃，P88次/分，R18次/分，BP128/78mmHg。神志清楚，痛苦面容，跛行。第一跖趾关节红肿明显、皮温升高、触痛剧烈（+++），活动受限，局部皮肤绷紧发亮。耳廓可触及痛风石。余关节无红肿。","辅助检查":"【必做】血尿酸（急性期可正常，不可因正常排除痛风）、血常规（白细胞可升高）、血沉、CRP、肾功能、尿常规（尿酸盐结晶，可提示肾结石）；【确诊】关节液穿刺偏振光显微镜检查（负性双折光针状尿酸盐结晶，为金标准）；【影像学】关节超声（双轨征、痛风石）、X线（慢性期穿凿样骨缺损）。","初步诊断":"1. 痛风（急性关节炎期）\n（注：急性期尽早（24小时内）抗炎镇痛：NSAIDs（依托考昔120mg qd或塞来昔布200mg bid，5~7天）或秋水仙碱（首剂1.0mg、1h后0.5mg、此后0.5mg bid，腹泻即停）或糖皮质激素（NSAIDs或秋水仙碱禁忌时泼尼松30mg/d×5天）；急性期暂不启动或调整降尿酸药（正在规律用者不停）；缓解≥2周后启动降尿酸：非布司他20~40mg qd 或 别嘌醇（HLA-B*5801筛查，汉族人群尤需）、苯溴马隆（肾功能好者），起始小剂量并联合小剂量秋水仙碱预防发作3~6个月；目标血尿酸<360μmol/L（痛风石者<300）；低嘌呤饮食、戒酒、多饮水（>2000ml/d）、减重。）","处理方案":"【药物治疗】\n1. 急性发作期抗炎镇痛：首选非甾体抗炎药（NSAIDs），如依托考昔片120mg qd（或塞来昔布胶囊200mg bid），餐后口服，症状缓解后48小时停药，疗程一般5～7天；肾功能不全者禁用NSAIDs。\n2. 秋水仙碱：NSAIDs禁忌或疗效不佳时选用，急性期首剂1.0mg，1小时后加服0.5mg，12小时后改为0.5mg bid，症状缓解或出现恶心、腹泻等胃肠道反应时立即停药，疗程一般3～5天。\n3. 降尿酸治疗：急性症状缓解2周后（约2～4周）启动，非布司他片20mg qd起始（最大40mg qd）或别嘌醇片100mg qd起始（每2～4周递增100mg，最大300mg qd），根据血尿酸水平调整，目标血尿酸＜360μmol/L，有痛风石者＜300μmol/L；起始降尿酸同时联用小剂量秋水仙碱0.5mg qd预防发作，持续3～6个月。\n4. 碱化尿液：碳酸氢钠片1.0g tid，监测尿pH维持在6.2～6.9，避免尿路结石形成。\n【一般治疗及生活指导】\n1. 急性期患肢关节制动、抬高、休息，避免负重行走及局部按摩、热敷，疼痛缓解后逐渐恢复关节活动。\n2. 严格低嘌呤饮食：避免动物内脏、海鲜（贝类、沙丁鱼等）、浓肉汤、火锅及含糖饮料，限制红肉摄入；戒烟戒酒，尤其禁饮啤酒和白酒。\n3. 大量饮水，每日饮水量2000ml以上，保证尿量充足以促进尿酸排泄；控制体重、规律作息，避免劳累、受凉、外伤及精神紧张等诱发因素。\n4. 避免使用升高血尿酸的药物（如噻嗪类利尿剂、袢利尿剂、小剂量阿司匹林等），确需使用者应权衡利弊并加强血尿酸监测。\n【随诊要求】\n建议2～4周后复诊，复查血尿酸、肝肾功能及血常规，评估疗效和药物不良反应；血尿酸未达标者每2～4周复诊调整降尿酸药物剂量，达标后每3～6个月复查血尿酸、肝肾功能1次；如出现关节红肿热痛复发、皮疹、发热或药物不良反应，应及时就诊。"},"icd10_diagnosis":"","icd10_secondary":[],"icd9cm3_procedure":[]}},"locator":{"file":"门诊住院病历模板/病历模板包_全部_20261111.json","arrayRow":362,"caseRow":1},"sourceHash":"10e4fdb435986b7b85f847c3951d0cb0eafdce0f372c5617949c05b337149194","contentHash":"27dcb0fe65389263aa31228e3ddc1be8d9ea15e17d1339f964c803611888859c","pinyin":"tongfengxingguanjieyan","initials":"tfxgjy","setting":"out","caseName":"门诊病历227","templateNames":["主诉","现病史","既往史","个人史及过敏史","体格检查","辅助检查","初步诊断","处理方案"],"emptyTemplates":[],"escapedNewlines":[],"quickFields":[["病例名称","门诊病历227",60],["模板名称","主诉 现病史 既往史 个人史及过敏史 体格检查 辅助检查 初步诊断 处理方案",30],["主要诊断编码","",30]]},{"id":"templates-d1116a5750e0808cc861","key":"v1-c9ccc21dfe2a3058|templates-d1116a5750e0808cc861","module":"templates","moduleKey":"v1-c9ccc21dfe2a3058|templates","version":"v1-c9ccc21dfe2a3058","title":"反应性关节炎","category":"门诊病历模板","raw":{"name":"反应性关节炎","category":"门诊病历模板","case":{"case_name":"门诊病历228","templates":{"主诉":"腹泻后关节肿痛6周，双膝、踝关节为著。","现病史":"患者于6周前出现腹泻（肠道感染：沙门菌或志贺菌或弯曲菌），2周后出现膝、踝等非对称性大关节肿胀疼痛、活动受限，晨僵、晨起明显，有足跟痛、跟腱附着点炎，无腰痛，无眼红痛、畏光，无尿道炎，无皮疹。无发热，无活动后气短。今日来我院门诊就诊。","既往史":"既往体健，否认高血压、糖尿病、冠心病等慢性病史。否认肝炎、结核等传染病史。否认手术外伤史。否认食物药物过敏史。预防接种史随社会。","个人史及过敏史":"生于原籍，久居本地，无疫区疫水接触史，无特殊粉尘毒物放射性物质接触史。不吸烟，不饮酒。生活规律。否认食物药物过敏史。","体格检查":"T37.0℃，P84次/分，R18次/分，BP120/76mmHg。神志清楚，查体合作。右膝关节肿胀、压痛（+）、皮温升高、活动受限（非对称性、少关节），跟腱止点压痛（+），骶髂关节压痛、叩击痛（+）。眼部检查结膜无充血。皮肤无环状龟头炎、无角皮病。","辅助检查":"【必做】血常规、血沉、CRP（升高）、类风湿因子（阴性）、HLA-B27（阳性率高，支持诊断非必须）、肝肾功能；【感染相关】大便培养（肠道感染后）、尿道或宫颈分泌物衣原体核酸检测、抗链球菌溶血素O（鉴别风湿热）；【影像学】受累关节及骶髂关节X线或CT（骶髂关节炎，晚期可见）、MRI（早期骶髂关节炎及附着点炎）；【其他】眼压及裂隙灯检查（虹膜炎）。","初步诊断":"1. 反应性关节炎（肠道感染后）\n（注：对症为主：NSAIDs（塞来昔布200mg qd~bid或萘普生）为一线，用以缓解关节症状；持续活动或NSAIDs不佳：柳氮磺吡啶（0.25g tid起始渐增至1g bid）或甲氨蝶呤（难治性）；明确感染（衣原体）者用多西环素100mg bid×2~4周；眼虹膜炎请眼科处理（糖皮质激素滴眼）；关节腔内激素注射（单关节）；多数呈自限性（3~12个月），部分转为慢性或反复，HLA-B27阳性者注意脊柱关节病进展，随访；急性期休息、避免负重。）","处理方案":"【药物治疗】\n1.非甾体抗炎药（一线首选）：塞来昔布胶囊0.2g bid×2周，餐后服用，或美洛昔康片7.5mg qd；症状缓解后逐渐减量，注意胃肠道及心肾不良反应。\n2.糖皮质激素（NSAIDs疗效不佳或关节肿痛明显时短期使用）：泼尼松片10-15mg qd×1-2周，症状控制后每1-2周减2.5-5mg缓慢撤停，避免长期使用。\n3.改善病情抗风湿药（病程≥3个月、反复发作或NSAIDs不能控制者）：柳氮磺吡啶肠溶片0.25g tid起始，每周递增0.25g/次，维持量0.5g tid，或甲氨蝶呤片7.5-15mg每周1次，次日服叶酸片5mg qd；用药期间每月监测血常规、肝肾功能。\n4.抗生素（衣原体感染相关、尿道炎症状明显者）：多西环素片0.1g bid×14天；或阿奇霉素片0.5g qd×7天；肠道感染诱发者不建议常规使用抗生素。\n\n【一般治疗及生活指导】\n1.急性期适当卧床休息，减少受累关节负重活动，抬高患肢缓解肿胀；症状缓解后循序渐进进行关节功能锻炼（如游泳、关节屈伸活动），防止关节强直及肌肉萎缩。\n2.注意个人卫生，避免不洁性接触；合并尿道炎、结膜炎者及时规范治疗，避免反复感染诱发复发。\n3.饮食清淡均衡，戒烟限酒，避免高嘌呤饮食；适量补充钙及维生素D（牛奶、豆制品），减少激素相关骨质疏松风险。\n4.足跟痛、跟腱附着点炎者穿软底鞋或使用足跟垫，减少局部刺激；避免剧烈运动及长时间行走。\n\n【随诊要求】\n1.用药2周后复诊，评估关节症状缓解程度及药物耐受性，复查血常规、肝肾功能、ESR、CRP；NSAIDs疗效不佳或症状加重者及时复诊调整方案。\n2.慢性病程（≥3个月）或反复发作者每1-3个月随访1次，监测疾病活动性及柳氮磺吡啶/甲氨蝶呤不良反应（血常规、肝肾功能每月1次），必要时行关节超声或影像学检查。\n3.合并尿道炎、结膜炎或HLA-B27阳性者，治疗后4-6周复查相关感染指标，评估是否需巩固抗感染治疗。\n4.出现持续高热、虹膜炎（眼红、畏光、视力下降）、明显关节破坏或髋关节受累时立即就诊，必要时转风湿免疫科住院治疗。"},"icd10_diagnosis":"","icd10_secondary":[],"icd9cm3_procedure":[]}},"locator":{"file":"门诊住院病历模板/病历模板包_全部_20261111.json","arrayRow":363,"caseRow":1},"sourceHash":"10e4fdb435986b7b85f847c3951d0cb0eafdce0f372c5617949c05b337149194","contentHash":"069c0e91bf25ab29a74ccda23b4fd68996f8269ddb69a895d859c96630ed3ab7","pinyin":"fanyingxingguanjieyan","initials":"fyxgjy","setting":"out","caseName":"门诊病历228","templateNames":["主诉","现病史","既往史","个人史及过敏史","体格检查","辅助检查","初步诊断","处理方案"],"emptyTemplates":[],"escapedNewlines":[],"quickFields":[["病例名称","门诊病历228",60],["模板名称","主诉 现病史 既往史 个人史及过敏史 体格检查 辅助检查 初步诊断 处理方案",30],["主要诊断编码","",30]]},{"id":"templates-45df11bdd03179561e2a","key":"v1-c9ccc21dfe2a3058|templates-45df11bdd03179561e2a","module":"templates","moduleKey":"v1-c9ccc21dfe2a3058|templates","version":"v1-c9ccc21dfe2a3058","title":"皮肌炎","category":"门诊病历模板","raw":{"name":"皮肌炎","category":"门诊病历模板","case":{"case_name":"门诊病历229","templates":{"主诉":"对称性四肢近端肌无力伴皮疹6月，加重1周。","现病史":"患者于6月前渐出现双上肢及双下肢近端（肩带肌、骨盆带肌）无力，表现为上举手臂困难、梳头费力、下蹲起立及上楼困难，伴肌肉酸痛，有特征性皮疹：上眼睑紫红色斑（向阳疹）、指关节伸面紫红色丘疹（Gottron征）、颈胸V字区及肩背（披肩征）红斑，有吞咽困难、饮水呛咳（咽肌受累），有心悸，无胸痛。无发热。有无肿瘤（40岁以上，需警惕副肿瘤性）、药物及结缔组织病相关因素：无。今日来我院门诊就诊。","既往史":"既往体健，否认高血压、糖尿病、冠心病等慢性病史。否认肝炎、结核等传染病史。否认手术外伤史。否认食物药物过敏史。预防接种史随社会。","个人史及过敏史":"生于原籍，久居本地，无疫区疫水接触史，无特殊粉尘毒物放射性物质接触史。不吸烟，不饮酒。生活规律。否认食物药物过敏史。","体格检查":"T36.8℃，P84次/分，R18次/分，BP118/74mmHg。神志清楚。双上眼睑可见紫红色水肿性斑（向阳疹），双手掌指及近端指间关节伸面紫红色鳞屑性丘疹（Gottron征），颈前及上胸部（V字区）、肩背部可见红斑。双肺呼吸音清，未闻及干湿性啰音。心脏听诊心律齐、未闻及病理性杂音。双上肢近端肌力3级，双下肢近端肌力4级（远端正常），肌肉压痛（+），腱反射减弱，感觉正常。","辅助检查":"【必做】血清肌酶（CK、CK-MB、LDH、AST/ALT，肌酸激酶显著升高为活动指标）、血沉、CRP、自身抗体（抗Jo-1抗体，与抗合成酶综合征相关；抗MDA5、抗TIF1-γ等，为肌炎特异性抗体）、肌电图（肌源性损害）、肌肉MRI（肌肉水肿，用于受累评估）；【确诊】肌肉活检（肌纤维变性坏死、炎性细胞浸润，为诊断金标准）；【其他】胸部CT（间质性肺病，抗Jo-1相关）、肿瘤筛查（40岁以上全面筛查：肿瘤标志物、胸腹盆CT、胃肠镜等）。","初步诊断":"1. 皮肌炎\n（注：治疗：糖皮质激素为一线（泼尼松1~1.5mg/kg/d，肌酶下降后渐减，疗程常1年以上）+免疫抑制剂（甲氨蝶呤或硫唑嘌呤或吗替麦考酚酯，用于激素减量或难治者，可联合）；注意防治激素不良反应；合并间质性肺病者（急进型抗MDA5相关可危及生命）需强化免疫治疗；40岁以上新发皮肌炎必须全面肿瘤筛查（肌炎可为副肿瘤表现）；吞咽困难、呼吸肌无力为重症需住院；皮肤症状对症（防晒、羟氯喹）；转风湿免疫科长期随访。）","处理方案":"【药物治疗】\n1. 糖皮质激素（首选一线治疗）：泼尼松片 1.0～1.5mg/kg·d（成人常用40～60mg/d），晨起顿服，连用4～8周；待肌力改善、肌酶（CK、LDH等）下降后每2～4周减量5mg，逐步减至维持量（10～15mg/d）长期维持，总疗程1～2年，切忌快速减量或骤停。\n2. 免疫抑制剂（激素效果不佳或需激素减量时联合）：甲氨蝶呤片 15～25mg，每周1次口服（次日加用叶酸片5mg预防口腔溃疡及骨髓抑制）；或硫唑嘌呤片 50mg，每日2次（用药前查TPMT，注意监测血常规及肝功能）；或吗替麦考酚酯胶囊 0.5g，每日2次，逐渐加量。\n3. 皮疹治疗（伴皮肤损害者）：羟氯喹片 0.2g，每日2次，连用3～6个月，用药期间每6个月行眼底及视野检查，监测视网膜毒性。\n4. 预防激素副作用：碳酸钙D3片 0.6g，每日1次＋骨化三醇胶丸 0.25μg，每日1次，长期口服；同时予质子泵抑制剂（如奥美拉唑肠溶胶囊20mg，每日1次）保护胃黏膜。\n\n【一般治疗及生活指导】\n1. 休息与活动：急性期绝对卧床休息，减少肌肉负荷；肌力恢复期在康复治疗师指导下循序渐进进行被动及主动关节活动、抗阻训练，防止肌萎缩及关节挛缩，避免过度劳累及剧烈运动诱发肌酶升高。\n2. 避光防晒：皮肌炎皮疹对日光敏感，外出穿长袖长裤、戴宽檐帽、撑遮阳伞，暴露部位涂SPF≥50广谱防晒霜，避免正午外出，防止皮疹加重及皮肤癌变。\n3. 饮食营养：给予高蛋白、高维生素、易消化饮食（瘦肉、蛋、奶、新鲜蔬果）；有吞咽困难、饮水呛咳者改为软食或半流质，进食时坐直、细嚼慢咽，防止误吸；吞咽困难明显者及时就医评估鼻饲或静脉营养。\n4. 禁忌：避免使用可能诱发或加重肌病的药物（他汀类降脂药、青霉胺、氯喹、糖皮质激素诱导性肌病药物）及肌松剂；育龄期女性治疗期间严格避孕，妊娠需在病情缓解稳定后由风湿科与产科联合评估。\n\n【随诊要求】\n1. 治疗初期每2～4周门诊复诊1次，评估肌力、皮疹、肌痛及吞咽、呼吸情况；病情稳定后延长至每1～3个月1次。\n2. 每次复诊复查血常规、尿常规、肝肾功能及肌酶谱（CK、LDH、AST、ALT）；用药期间定期监测血药浓度相关指标（MTX注意血象及肝功，硫唑嘌呤注意血象）。\n3. 每3～6个月复查自身抗体谱（ANA、抗Jo-1抗体等）及胸部高分辨率CT，筛查间质性肺病；长期激素治疗者每3～6个月监测血糖、血压、血脂，每6～12个月行骨密度检查。\n4. 出现以下情况需立即就诊：进行性呼吸困难、呼吸肌受累、吞咽困难加重、饮水呛咳、发热、咯血、黑便，或出现肌无力迅速加重。"},"icd10_diagnosis":"","icd10_secondary":[],"icd9cm3_procedure":[]}},"locator":{"file":"门诊住院病历模板/病历模板包_全部_20261111.json","arrayRow":364,"caseRow":1},"sourceHash":"10e4fdb435986b7b85f847c3951d0cb0eafdce0f372c5617949c05b337149194","contentHash":"7e4d2229d2abad1f89e6e221ebbe54e293ae29fb5c71f7ca669a10857f3cdc51","pinyin":"pijiyan","initials":"pjy","setting":"out","caseName":"门诊病历229","templateNames":["主诉","现病史","既往史","个人史及过敏史","体格检查","辅助检查","初步诊断","处理方案"],"emptyTemplates":[],"escapedNewlines":[],"quickFields":[["病例名称","门诊病历229",60],["模板名称","主诉 现病史 既往史 个人史及过敏史 体格检查 辅助检查 初步诊断 处理方案",30],["主要诊断编码","",30]]},{"id":"templates-f3b299e1ee38e50e7eab","key":"v1-c9ccc21dfe2a3058|templates-f3b299e1ee38e50e7eab","module":"templates","moduleKey":"v1-c9ccc21dfe2a3058|templates","version":"v1-c9ccc21dfe2a3058","title":"硬皮病","category":"门诊病历模板","raw":{"name":"硬皮病","category":"门诊病历模板","case":{"case_name":"门诊病历230","templates":{"主诉":"双手及面部皮肤硬化4年，吞咽困难3月","现病史":"患者于4年前渐出现双手雷诺现象（遇冷手指苍白-青紫-潮红），随后手指、手背皮肤肿胀、硬化，皮肤紧绷、发亮，不易捏起，渐累及面部（面具脸，口周放射纹、张口受限）、前臂及躯干，有手指溃疡、关节痛、吞咽困难及反酸烧心（食管受累，为系统性硬化症常见表现），无活动后气短，无血压升高及蛋白尿。有无职业粉尘接触（矽尘）及自身免疫病史：无。今日来我院门诊就诊。","既往史":"既往体健，否认高血压、糖尿病、冠心病等慢性病史。否认肝炎、结核等传染病史。否认手术外伤史。否认食物药物过敏史。预防接种史随社会。","个人史及过敏史":"生于原籍，久居本地，无疫区疫水接触史，无特殊粉尘毒物放射性物质接触史。不吸烟，不饮酒。生活规律。否认食物药物过敏史。","体格检查":"T36.6℃，P80次/分，R18次/分，BP116/72mmHg。神志清楚。面部皮肤紧绷、缺乏表情（面具脸），口周放射状沟纹，张口度2.5cm（减小），手指皮肤硬化呈腊肠样，皮纹消失、不易捏起（指端硬化），可见指端溃疡及凹陷性瘢痕，甲周毛细血管扩张。双肺呼吸音清，未闻及Velcro啰音（暂无肺纤维化体征），心界不大。腹部检查无异常。","辅助检查":"检查计划：患者4年前起双手遇冷出现雷诺现象（苍白—青紫—潮红），随后手指、手背皮肤肿胀硬化、紧绷发亮、不易捏起，渐累及面部（面具脸、口周放射纹、张口受限）、前臂及躯干，伴手指溃疡、关节痛及吞咽困难、反酸烧心，本次门诊需系统评估皮肤与各脏器受累：查抗核抗体筛查自身免疫病，本病多呈阳性；完善特异性抗体检查，抗Scl-70与弥漫型及间质性肺病相关，抗着丝点抗体与局限型及肺动脉高压相关，用以明确临床亚型；查血常规、血沉了解有无贫血、感染及炎症活动度；查肝肾功能为后续免疫抑制治疗评估脏器储备；查尿常规筛查蛋白尿、血尿，警惕硬皮病肾危象等肾损害；患者虽无活动后气短，但弥漫型皮肤硬化者肺间质纤维化发生率高，完善胸部HRCT明确有无肺间质纤维化；完善肺功能（含弥散功能）评估肺通气与弥散受损程度并作为随访基线；患者有吞咽困难及反酸烧心，完善食管钡餐或食管测压了解食管动力障碍及下段括约肌功能；完善超声心动图评估肺动脉压力、右心大小及心包积液，明确有无肺动脉高压，必要时行右心导管确诊；若皮肤及内脏受累证据不典型，必要时完善皮肤活检明确病理改变。\n\n（检查清单）\n【必做】抗核抗体（阳性）、特异性抗体（抗Scl-70，与弥漫型相关；抗着丝点抗体，与局限型相关）、血常规、血沉、肝肾功能、尿常规；【影像学】胸部HRCT（肺间质纤维化）、食管钡餐或食管测压（食管动力障碍）、超声心动图（肺动脉高压，可由右心导管确诊）；【其他】肺功能、皮肤活检（必要时）。","初步诊断":"1. 系统性硬化症（弥漫型）\n（注：无特效根治药，以脏器受累防治为核心：雷诺现象采用保暖、硝苯地平、伊洛前列素（指端溃疡）；皮肤及关节受累用甲氨蝶呤；间质性肺病用环磷酰胺或吗替麦考酚酯+抗纤维化（尼达尼布，具SSc-ILD适应证）；肺动脉高压用波生坦或西地那非+右心导管监测；胃食管反流用质子泵抑制剂；最关键：警惕硬皮病肾危象（突发恶性高血压+急性肾衰，属急诊，用ACEI（卡托普利）治疗可挽救）；戒烟、保暖、避免寒冷应激，转风湿免疫科多学科长期管理。）","处理方案":"【药物治疗】\n1. 糖皮质激素：泼尼松片30mg qd晨起顿服（按0.5-1mg/kg·d），适用于炎症活动期或间质性肺病等内脏受累者，病情稳定后每2-4周减量5mg，减至维持量5-10mg qd，总疗程3-6个月，注意监测血糖、血压及骨密度。\n2. 血管活性药物（改善雷诺现象）：硝苯地平控释片30mg qd，或氨氯地平片5mg qd，疗程3-6个月，症状缓解后以小剂量维持；疗效不佳者可加用前列腺素类（伊洛前列素）静脉给药。\n3. 免疫抑制剂：甲氨蝶呤片10-15mg每周一次口服（同服叶酸片5mg qd预防骨髓抑制），用于皮肤硬化进展快或关节受累者；合并肺间质纤维化者改用环磷酰胺（按0.5-1g/m²每月静脉冲击，需血常规、肝功能监测）。\n4. 对症治疗：反流性食管炎予奥美拉唑肠溶片20mg qd，餐前30分钟口服；每日自测血压，血压升高或尿蛋白阳性（警惕肾危象）时加用卡托普利片12.5mg tid起始，并立即就诊。\n【一般治疗及生活指导】\n1. 保暖防寒：避免寒冷刺激、冷水接触及情绪激动，冬季戴手套、穿厚袜、温水洗漱，减少雷诺现象发作频率及程度。\n2. 皮肤护理：保持皮肤清洁湿润，外用保湿剂（凡士林、尿素软膏）每日2-3次，避免皮肤外伤、烫伤、抓挠及过度日晒，防止溃疡与感染。\n3. 戒烟限酒，避免饮用咖啡、浓茶等缩血管饮品，规律作息、避免劳累及精神紧张。\n4. 功能锻炼：每日主动活动手指、腕、肘及四肢关节并配合按摩理疗，防止关节挛缩、皮肤紧绷与肌肉萎缩；进食细软易消化食物，细嚼慢咽，饭后保持立位30分钟以减轻反流。\n【随诊要求】\n1. 每1-3个月门诊复诊1次，评估皮肤硬化范围与厚度、雷诺现象发作情况及关节功能。\n2. 每3-6个月复查血常规、肝肾功能、尿常规及自身抗体（抗Scl-70、抗着丝点抗体）；每年行胸部高分辨CT、肺功能及超声心动图，动态监测肺间质纤维化与肺动脉高压。\n3. 每日自测血压并记录，血压急剧升高、少尿或水肿提示肾危象，须立即急诊就诊；出现新发或加重的呼吸困难、干咳、胸痛、吞咽困难、腹痛黑便时及时复诊。"},"icd10_diagnosis":"","icd10_secondary":[],"icd9cm3_procedure":[]}},"locator":{"file":"门诊住院病历模板/病历模板包_全部_20261111.json","arrayRow":365,"caseRow":1},"sourceHash":"10e4fdb435986b7b85f847c3951d0cb0eafdce0f372c5617949c05b337149194","contentHash":"afdd317c5c4d48f356a0c04d82b52d33307c5f5cc9feff9ff4170698ea02ffce","pinyin":"yingpibing","initials":"ypb","setting":"out","caseName":"门诊病历230","templateNames":["主诉","现病史","既往史","个人史及过敏史","体格检查","辅助检查","初步诊断","处理方案"],"emptyTemplates":[],"escapedNewlines":[],"quickFields":[["病例名称","门诊病历230",60],["模板名称","主诉 现病史 既往史 个人史及过敏史 体格检查 辅助检查 初步诊断 处理方案",30],["主要诊断编码","",30]]},{"id":"templates-958d9834774ba17b9009","key":"v1-c9ccc21dfe2a3058|templates-958d9834774ba17b9009","module":"templates","moduleKey":"v1-c9ccc21dfe2a3058|templates","version":"v1-c9ccc21dfe2a3058","title":"结节性红斑","category":"门诊病历模板","raw":{"name":"结节性红斑","category":"门诊病历模板","case":{"case_name":"门诊病历231","templates":{"主诉":"双小腿伸侧红色疼痛性结节4周，伴发热、关节痛。","现病史":"患者于4周前（上呼吸道感染后）出现双小腿伸侧对称性皮下结节，红色、隆起、灼热、触痛明显，渐增多，无破溃，伴发热（体温最高38.4℃）、乏力、膝关节及踝关节疼痛、肿胀。有无咳嗽、胸闷（结节病筛查）、腹痛腹泻（炎症性肠病）、结核接触史：均无。今日来我院门诊就诊。","既往史":"既往体健，否认高血压、糖尿病、冠心病等慢性病史。否认肝炎、结核等传染病史。否认手术外伤史。否认食物药物过敏史。预防接种史随社会。","个人史及过敏史":"生于原籍，久居本地，无疫区疫水接触史，无特殊粉尘毒物放射性物质接触史。不吸烟，不饮酒。生活规律。否认食物药物过敏史。","体格检查":"T38.2℃，P96次/分，R20次/分，BP118/74mmHg。神志清楚，查体合作。双小腿伸侧可见对称分布多个红色皮下结节，直径约2cm，隆起于皮面，皮温升高，压痛（+），无破溃无化脓，膝关节肿胀、压痛。","辅助检查":"检查计划：患者4周前上呼吸道感染后于双小腿伸侧出现对称性红色疼痛性结节，灼热、触痛明显、无破溃，伴发热（最高38.4℃）、乏力及膝踝关节疼痛肿胀，本病多为潜在疾病的反应性表现，需系统寻找病因：查血常规、CRP及血沉评估炎症反应程度，本病血沉常显著增快；因起病前有上呼吸道感染，完善抗链球菌溶血素O检查筛查链球菌感染，阳性者提示链球菌诱因，需一并抗感染治疗；我国为结核高发地区，患者虽无结核接触史及咳嗽胸闷，仍完善结核菌素试验或IGRA筛查结核感染，并查胸部X线片明确有无肺门淋巴结增大等结节病征象，因结核患者使用糖皮质激素需格外谨慎；查肝肾功能评估用药安全并除外肝肾功能受损所致皮损；查尿常规筛查肾脏受累；完善自身抗体谱（抗核抗体、抗中性粒细胞胞质抗体等）排除结缔组织病、血管炎等系统性疾病；患者无腹痛腹泻但仍需除外炎症性肠病，查大便潜血筛查肠道病变；若结节形态不典型或持续不消退，完善皮肤活检明确间隔性脂膜炎改变。\n\n（检查清单）\n【必做】血常规、血沉（显著增快）、CRP、抗链球菌溶血素O（链球菌感染筛查）、结核菌素试验或IGRA（结核筛查，我国为重点）、胸部X线片（肺门淋巴结，提示结节病）、肝肾功能、尿常规；【其他】自身抗体谱（结缔组织病）、大便潜血（炎症性肠病）、皮肤活检（间隔性脂膜炎，为诊断金标准，不典型时采用）。","初步诊断":"1. 结节性红斑\n（注：结节性红斑多为对潜在疾病的反应性表现，需积极寻找病因（链球菌感染、结核、结节病、药物、炎症性肠病、白塞病、妊娠等，我国尤其注意结核）；对症：卧床抬高患肢、NSAIDs（塞来昔布200mg bid）镇痛抗炎、10%碘化钾溶液（5~10ml tid，疗效好）、皮损广泛严重者可短期糖皮质激素（泼尼松20~30mg/d，但结核患者慎用，需同时抗结核）；治疗原发病后结节多可消退（病程3~6周），一般不留瘢痕。）","处理方案":"【药物治疗】\n1. 布洛芬缓释胶囊 0.3g po bid×7～14天（或双氯芬酸钠缓释片 75mg po qd×7～14天）：抗炎止痛，为结节性红斑一线对症治疗，缓解结节疼痛及关节症状。\n2. 10%碘化钾溶液 5～10ml po tid×2～4周：具有抗炎及抑制迟发型超敏反应作用，为结节性红斑有效辅助治疗，可促进结节消退；甲状腺疾病及妊娠期患者慎用。\n3. 醋酸泼尼松片 30mg po qd，结节消退后每1～2周递减5mg至停用（总疗程约4～6周）：适用于皮损广泛、疼痛剧烈或伴明显全身症状的重症患者；用药前排除结核、糖尿病、严重感染等禁忌。\n4. 青霉素V钾片 0.5g po tid×10天（青霉素过敏者改用患者霉素片 0.15g po bid×10天）：合并上呼吸道链球菌感染等明确感染灶者，同时针对病因抗感染治疗。\n\n【一般治疗及生活指导】\n1. 急性期适当卧床休息，抬高患肢（休息时垫高双下肢），减轻下肢静脉淤血及结节炎症。\n2. 避免久站、久行及剧烈运动，穿宽松软底鞋袜，减少对小腿皮损的摩擦与压迫。\n3. 饮食清淡，多饮水，忌辛辣刺激、油腻及酒精类食物；适当补充维生素C及优质蛋白促进恢复。\n4. 注意保暖，避免受凉；如反复发作，应戒烟并积极筛查并治疗原发病（链球菌感染、结核、结节病、药物等）。\n\n【随诊要求】\n1. 治疗1～2周复诊，评估结节消退情况及疼痛缓解程度，必要时调整用药。\n2. 疗程结束后复查血常规、血沉及C反应蛋白评估炎症控制情况；用药期间监测肝肾功能。\n3. 如皮损反复发作、持续不愈，或伴发热、咳嗽、关节肿痛、腹痛等系统症状，及时复诊并完善胸部X线/CT、结核菌素试验、自身抗体等检查，排查结核、结节病、白塞病等系统性疾病。"},"icd10_diagnosis":"","icd10_secondary":[],"icd9cm3_procedure":[]}},"locator":{"file":"门诊住院病历模板/病历模板包_全部_20261111.json","arrayRow":366,"caseRow":1},"sourceHash":"10e4fdb435986b7b85f847c3951d0cb0eafdce0f372c5617949c05b337149194","contentHash":"89613c03fe5ee24501ed2d8ac991d1c38531365a239d81f112147c752b3e1271","pinyin":"jiejiexinghongban","initials":"jjxhb","setting":"out","caseName":"门诊病历231","templateNames":["主诉","现病史","既往史","个人史及过敏史","体格检查","辅助检查","初步诊断","处理方案"],"emptyTemplates":[],"escapedNewlines":[],"quickFields":[["病例名称","门诊病历231",60],["模板名称","主诉 现病史 既往史 个人史及过敏史 体格检查 辅助检查 初步诊断 处理方案",30],["主要诊断编码","",30]]},{"id":"templates-4aed7537a52b6ba7fef4","key":"v1-c9ccc21dfe2a3058|templates-4aed7537a52b6ba7fef4","module":"templates","moduleKey":"v1-c9ccc21dfe2a3058|templates","version":"v1-c9ccc21dfe2a3058","title":"股癣","category":"门诊病历模板","raw":{"name":"股癣","category":"门诊病历模板","case":{"case_name":"门诊病历232","templates":{"主诉":"腹股沟及大腿内侧红斑、丘疹伴瘙痒3周。","现病史":"患者于3周前出现腹股沟及双侧大腿内侧近端皮肤红斑，渐扩大呈环状，边界清楚，边缘可见丘疹、小水疱及脱屑，中央趋于消退，伴明显瘙痒，搔抓后加重，夏季或出汗后明显，无蔓延至臀部、会阴，无发热。有无足癣、糖尿病及长期使用糖皮质激素（外涂或口服）史：无足癣，无糖尿病，无长期使用糖皮质激素史。今日来我院门诊就诊。","既往史":"既往体健，否认高血压、糖尿病、冠心病等慢性病史。否认肝炎、结核等传染病史。否认手术外伤史。否认食物药物过敏史。预防接种史随社会。","个人史及过敏史":"生于原籍，久居本地，无疫区疫水接触史，无特殊粉尘毒物放射性物质接触史。不吸烟，不饮酒。生活规律。否认食物药物过敏史。","体格检查":"T36.5℃，P78次/分，R18次/分，BP115/72mmHg。神志清楚，查体合作。腹股沟及双大腿内侧可见对称性环状红斑，边界清楚略隆起，边缘有丘疹、脱屑，中央色暗，无渗出，真菌直接镜检部位取皮损边缘鳞屑。","辅助检查":"检查计划：患者3周前起腹股沟及双侧大腿内侧近端出现红斑，渐扩大呈环状、边界清楚，边缘可见丘疹、小水疱及脱屑而中央趋于消退，瘙痒明显、出汗后加重，无足癣、糖尿病及长期外用或口服糖皮质激素史，临床高度提示浅部真菌感染：取皮损边缘鳞屑行10%KOH真菌镜检，见菌丝或孢子即可确诊，为确诊依据，且可与其他红斑鳞屑性皮肤病、红癣、湿疹等相鉴别；若真菌镜检阴性而临床仍高度疑诊（如近期曾自行外用抗真菌药致菌量减少），完善真菌培养明确致病菌种，以指导外用或口服抗真菌药的选择并与其他皮肤感染鉴别；同时需仔细检查趾间、足底及指（趾）甲有无合并手足癣、甲癣，明确有无自身接种来源，以便同治、减少复发；因患者既往体健、无糖尿病及免疫抑制病史，暂不需常规加做血糖及免疫相关筛查；但若皮损反复不愈、面积扩大或规范抗真菌治疗无效，应加查空腹血糖及糖化血红蛋白排除糖尿病所致易感，必要时行皮损组织病理检查排除其他难辨认皮肤病。\n\n（检查清单）\n【必做】真菌镜检（皮损边缘鳞屑10%KOH涂片，见菌丝或孢子，为确诊依据）；【其他】真菌培养（镜检阴性而高度疑诊时）。","初步诊断":"1. 股癣\n（注：外用抗真菌药（特比萘芬乳膏bid或联苯苄唑乳膏qd，连续2~4周，皮损消退后继续1~2周防复发），皮损面积大或反复发作者口服特比萘芬250mg qd×2~4周或伊曲康唑；保持局部干燥（穿透气内裤、勤换）、避免搔抓；勿用糖皮质激素类药膏（可致皮损扩大呈难辨认癣）；伴足癣者同治（自身接种来源）；糖尿病患者控制血糖。）","处理方案":"【药物治疗】\n1. 1%盐酸特比萘芬乳膏 外用，涂于患处及周边皮肤，每日2次，疗程2-4周（症状消退后继续用药1-2周防复发）。\n2. 1%联苯苄唑乳膏 外用，每日1次，疗程2-4周。\n3. 炎症红肿明显者，可联用复方酮康唑乳膏（含抗真菌药+激素）短期外用，每日1-2次，不超过1-2周；或单用0.1%丁酸氢化可的松乳膏控制炎症后单用抗真菌药。\n4. 皮损广泛、反复发作或外用药疗效不佳者：伊曲康唑胶囊0.2g bid，餐后口服，连用7天（或盐酸特比萘芬片0.25g qd，口服，疗程2周）。\n\n【一般治疗及生活指导】\n1. 保持腹股沟、会阴部皮肤清洁干燥，每日温水清洗后彻底擦干，避免潮湿闷热环境；出汗多者及时更换衣物。\n2. 穿宽松透气的纯棉内裤并勤更换，内裤、毛巾、浴巾用开水烫洗或阳光暴晒消毒；个人洗浴用品与家人分开使用，避免交叉感染。\n3. 避免搔抓患处，防止继发细菌感染及自体接种扩散至臀部、股部其他区域；同时治疗足癣（\"两足一手\"）以防互相传染。\n4. 忌辛辣刺激性食物及饮酒以减少瘙痒；合并糖尿病者应积极控制血糖，避免长期患者广谱抗生素或糖皮质激素。\n\n【随诊要求】\n1. 治疗2周后复诊，评估皮损消退情况及药物耐受性。\n2. 外用药治疗2周无效、皮损扩大或反复发作者，复诊行真菌镜检/培养以明确诊断并调整治疗方案。\n3. 症状消退后仍建议继续用药1-2周，停药2周后复查真菌镜检阴性视为痊愈。\n4. 反复发作或久治不愈者，建议检查空腹血糖及糖化血红蛋白排除糖尿病，并筛查家庭成员及密切接触者是否患有足癣或股癣，同步治疗以防再感染。"},"icd10_diagnosis":"","icd10_secondary":[],"icd9cm3_procedure":[]}},"locator":{"file":"门诊住院病历模板/病历模板包_全部_20261111.json","arrayRow":367,"caseRow":1},"sourceHash":"10e4fdb435986b7b85f847c3951d0cb0eafdce0f372c5617949c05b337149194","contentHash":"53985d88fe955eebcddfd6e37f9525a890b142d5d7b11a86a921e2ace5a823e4","pinyin":"guxuan","initials":"gx","setting":"out","caseName":"门诊病历232","templateNames":["主诉","现病史","既往史","个人史及过敏史","体格检查","辅助检查","初步诊断","处理方案"],"emptyTemplates":[],"escapedNewlines":[],"quickFields":[["病例名称","门诊病历232",60],["模板名称","主诉 现病史 既往史 个人史及过敏史 体格检查 辅助检查 初步诊断 处理方案",30],["主要诊断编码","",30]]},{"id":"templates-d078e04642647726bdb9","key":"v1-c9ccc21dfe2a3058|templates-d078e04642647726bdb9","module":"templates","moduleKey":"v1-c9ccc21dfe2a3058|templates","version":"v1-c9ccc21dfe2a3058","title":"手足癣","category":"门诊病历模板","raw":{"name":"手足癣","category":"门诊病历模板","case":{"case_name":"门诊病历233","templates":{"主诉":"手足部皮肤脱屑、水疱伴瘙痒6月。","现病史":"患者于6月前出现足趾间（第3~4、4~5趾间常见）浸渍发白、脱屑、水疱，渐蔓延至足底、足侧缘，伴瘙痒，搔抓后可见糜烂渗液（浸渍糜烂型）或角化增厚脱屑（鳞屑角化型），有手部受累（单侧手癣），无发热。有无糖尿病、多汗及公共场所赤足史：无糖尿病，有多汗及公共场所赤足史。今日来我院门诊就诊。","既往史":"既往体健，否认高血压、糖尿病、冠心病等慢性病史。否认肝炎、结核等传染病史。否认手术外伤史。否认食物药物过敏史。预防接种史随社会。","个人史及过敏史":"生于原籍，久居本地，无疫区疫水接触史，无特殊粉尘毒物放射性物质接触史。不吸烟，不饮酒。生活规律。否认食物药物过敏史。","体格检查":"T36.5℃，P76次/分，R18次/分，BP116/72mmHg。神志清楚，查体合作。双足趾间浸渍发白、足底角化增厚脱屑，单侧手掌角化脱屑，边界清楚，局部无红肿（如有红肿热痛需考虑继发细菌感染）。","辅助检查":"检查计划：患者6月前起足趾间（第3~4、4~5趾间）出现浸渍发白、脱屑、水疱，渐蔓延至足底及足侧缘，伴明显瘙痒，搔抓后糜烂渗液，部分呈角化增厚脱屑，并有单侧手部受累，追问有多汗及公共场所赤足史，临床考虑浅部真菌感染：刮取足趾间及手部皮屑行真菌镜检，KOH涂片见菌丝即可确诊，为本病确诊依据，并可与湿疹、接触性皮炎、掌跖脓疱病等鉴别；若镜检阴性而症状典型，或需明确致病菌种以指导口服抗真菌治疗（鳞屑角化型疗程长、易复发），完善真菌培养；因患者有多汗及公共场所赤足史，且为单侧手癣，需同时检查指（趾）甲有无甲癣并存，明确自身接种来源以便同治、防止反复；若皮损反复发作、迁延不愈或规范抗真菌治疗无效，建议加查空腹血糖及糖化血红蛋白排除糖尿病所致易感；对糜烂渗液明显者，还需排查有无继发细菌感染，必要时行分泌物细菌培养及药敏试验。\n\n（检查清单）\n【必做】真菌镜检（皮屑KOH涂片见菌丝）；【其他】真菌培养。","初步诊断":"1. 手癣、足癣（鳞屑角化型）\n（注：外用抗真菌药（特比萘芬乳膏或联苯苄唑乳膏，连续4周以上，鳞屑角化型需更长）；浸渍糜烂型先收敛干燥（硼酸溶液湿敷）再用抗真菌药；鳞屑角化型厚皮可先用尿素软膏软化；面积大、反复或甲癣（常并存）者口服特比萘芬250mg qd或伊曲康唑；保持足部干燥（棉袜、通风鞋）、不共用拖鞋毛巾、鞋袜消毒；伴甲癣需同治防复发。）","处理方案":"【药物治疗】\n1. 首选外用抗真菌药：盐酸特比萘芬乳膏（兰美抒）1% 或联苯苄唑乳膏1%，涂患处及周围1cm正常皮肤，bid，轻揉片刻，连续用药4周；角化过度型延长至6-8周，真菌镜检转阴后继续用药1-2周以防复发。\n2. 角质剥脱剂（角化增厚型）：10%水杨酸软膏 或 10%尿素软膏，每晚1次涂于增厚部位封包，白天用抗真菌乳膏，两药交替，连续2-4周至角质变薄。\n3. 口服抗真菌药（外用药疗效不佳、皮损广泛或合并甲癣者）：伊曲康唑胶囊0.2g bid，餐后立即服用，连服7天；或盐酸特比萘芬片0.25g qd，连服2-4周（口服前查肝功能）。\n\n【一般治疗及生活指导】\n1. 保持手足干燥清洁：每日洗脚后逐一擦干趾（指）缝，穿透气棉袜与宽松透气的鞋，每日更换鞋袜，避免长时间穿胶鞋、捂汗。\n2. 杜绝搔抓：搔抓可引起自体接种传染至手部、股部等，痒甚时可冷敷或轻拍；毛巾、拖鞋、浴盆、指甲剪等个人用品单独使用，定期用开水烫洗或暴晒消毒。\n3. 生活方式：避免久坐久站致足部出汗，运动或洗浴后及时更换干燥鞋袜；糖尿病等基础病患者积极控制血糖，减少复发诱因。\n4. 家庭同治：同住家人有足癣、体癣者应同时规范治疗，防止交叉再感染。\n\n【随诊要求】\n用药2周复诊评估疗效与不良反应，完成全疗程后复诊复查真菌镜检以确认痊愈；若用药4周皮损无改善、范围扩大或出现红肿渗液，应随时复诊，调整方案并排查合并细菌感染或甲癣。"},"icd10_diagnosis":"","icd10_secondary":[],"icd9cm3_procedure":[]}},"locator":{"file":"门诊住院病历模板/病历模板包_全部_20261111.json","arrayRow":368,"caseRow":1},"sourceHash":"10e4fdb435986b7b85f847c3951d0cb0eafdce0f372c5617949c05b337149194","contentHash":"fb9599ed122bdade2697a36233c91b91ac52efdab0f0fa713fa485dfb270bd09","pinyin":"shouzuxuan","initials":"szx","setting":"out","caseName":"门诊病历233","templateNames":["主诉","现病史","既往史","个人史及过敏史","体格检查","辅助检查","初步诊断","处理方案"],"emptyTemplates":[],"escapedNewlines":[],"quickFields":[["病例名称","门诊病历233",60],["模板名称","主诉 现病史 既往史 个人史及过敏史 体格检查 辅助检查 初步诊断 处理方案",30],["主要诊断编码","",30]]},{"id":"templates-e13e9b69aa362086b587","key":"v1-c9ccc21dfe2a3058|templates-e13e9b69aa362086b587","module":"templates","moduleKey":"v1-c9ccc21dfe2a3058|templates","version":"v1-c9ccc21dfe2a3058","title":"甲癣","category":"门诊病历模板","raw":{"name":"甲癣","category":"门诊病历模板","case":{"case_name":"门诊病历234","templates":{"主诉":"趾甲增厚、变色、变形6月。","现病史":"患者于6月前出现多个趾甲增厚、变浑浊呈灰黄色、失去光泽，甲下碎屑堆积，甲板与甲床分离，甲变形，无甲患者肿疼痛，无发热。有无足癣或手癣（常为传染源）、糖尿病、长期穿不透气鞋及免疫功能低下（长期激素或免疫抑制剂）：有足癣，无糖尿病，有长期穿不透气鞋史，无免疫功能低下。今日来我院门诊就诊。","既往史":"既往体健，否认高血压、糖尿病、冠心病等慢性病史。否认肝炎、结核等传染病史。否认手术外伤史。否认食物药物过敏史。预防接种史随社会。","个人史及过敏史":"生于原籍，久居本地，无疫区疫水接触史，无特殊粉尘毒物放射性物质接触史。不吸烟，不饮酒。生活规律。否认食物药物过敏史。","体格检查":"T36.6℃，P78次/分，R18次/分，BP118/74mmHg。神志清楚，查体合作。双拇趾甲板增厚、浑浊、变色（灰黄），甲下角化碎屑，甲分离，甲周皮肤无红肿，足趾间有脱屑（并存足癣）。","辅助检查":"【必做】甲屑真菌镜检（KOH涂片见菌丝或孢子）+真菌培养（确诊及排除其他甲病，如银屑病甲、甲外伤、甲营养不良）；【其他】病甲取材部位选择（甲下近端碎屑阳性率高）。","初步诊断":"1. 甲真菌病（甲癣）\n（注：仅远端浅表或<50%甲板受累可外用药（阿莫罗芬搽剂每周1次或环吡酮搽剂qd，疗程需6~12个月，成功率有限）；累及甲根、甲母质或多个甲：口服抗真菌药，如特比萘芬250mg qd（趾甲6~12周、指甲6周）或伊曲康唑冲击疗法（0.2g bid×1周/月，趾甲3~4个冲击）；注意肝功能监测；治疗期间修剪病甲、鞋袜消毒防再感染；治愈标准为新生正常甲长出（趾甲约需9~12个月），需耐心坚持。）","处理方案":"【药物治疗】\n1. 盐酸特比萘芬片250mg po qd，指甲癣连用6周，趾甲癣连用12周（可与锉甲配合提高疗效）；服药前及服药第4周复查肝功能，肝功能异常者慎用。\n2. 伊曲康唑胶囊0.2g po bid（餐后立即服用），采用冲击疗法：服药1周、停药3周为1个疗程，指甲癣连用2个疗程，趾甲癣连用3~4个疗程；禁与利福平、苯妥英钠及部分他汀类等药物合用，用药期间监测肝功能。\n3. 外用阿莫罗芬搽剂（5%）：先用指甲锉锉薄病甲，涂搽液覆盖整个甲板及甲周，每周1次，指甲癣连用6个月、趾甲癣连用9~12个月；适用于甲板受累面积＜50%的轻症或不能耐受口服药者。\n\n【一般治疗及生活指导】\n1. 保持手足皮肤及鞋袜清洁干燥，鞋袜勤换洗，袜子可用开水烫洗或阳光暴晒，不与他人共用拖鞋、浴巾、指甲剪、搓脚石等个人物品。\n2. 合并手癣、足癣、体股癣者应同步规范治疗，避免搔抓患处后接触正常皮肤引起自身交叉感染。\n3. 穿着透气、宽松的鞋袜，避免久穿不透气胶鞋、高跟鞋及美甲、长期涂甲油，防止损伤甲板、甲周皮肤诱发或加重感染。\n4. 均衡饮食，保证蛋白质及B族维生素摄入，糖尿病患者严格控制血糖。\n\n【随诊要求】\n1. 口服抗真菌药者每月复查肝功能；治疗期间每4~8周门诊复诊，观察病甲新生及恢复情况。\n2. 疗程结束时复查真菌镜检及培养，连续2~3次阴性（并见正常甲板长出）方为临床及真菌学治愈；症状未缓解或病甲继续扩大时及时复诊调整方案。\n3. 治愈后仍有再发可能，日常注意防护，一旦发现甲板增厚、变色、混浊、脱屑等异常，尽早就诊复查。"},"icd10_diagnosis":"","icd10_secondary":[],"icd9cm3_procedure":[]}},"locator":{"file":"门诊住院病历模板/病历模板包_全部_20261111.json","arrayRow":369,"caseRow":1},"sourceHash":"10e4fdb435986b7b85f847c3951d0cb0eafdce0f372c5617949c05b337149194","contentHash":"437da3cab98619cf3ae265b154b5d93cf0f58f7552061f27df059e96fb8d2782","pinyin":"jiaxuan","initials":"jx","setting":"out","caseName":"门诊病历234","templateNames":["主诉","现病史","既往史","个人史及过敏史","体格检查","辅助检查","初步诊断","处理方案"],"emptyTemplates":[],"escapedNewlines":[],"quickFields":[["病例名称","门诊病历234",60],["模板名称","主诉 现病史 既往史 个人史及过敏史 体格检查 辅助检查 初步诊断 处理方案",30],["主要诊断编码","",30]]},{"id":"templates-1d1945bfd41bafb73351","key":"v1-c9ccc21dfe2a3058|templates-1d1945bfd41bafb73351","module":"templates","moduleKey":"v1-c9ccc21dfe2a3058|templates","version":"v1-c9ccc21dfe2a3058","title":"花斑癣","category":"门诊病历模板","raw":{"name":"花斑癣","category":"门诊病历模板","case":{"case_name":"门诊病历235","templates":{"主诉":"胸背部色素沉着、减退斑伴轻微鳞屑3月。","现病史":"患者于3月前（夏季、出汗多后）出现胸背部、上臂散在圆形或类圆形斑疹，颜色为浅白色，表面覆细小糠秕状鳞屑，多无自觉症状或轻微瘙痒，出汗时瘙痒加重，日晒后白斑更明显（色素减退）。有无多汗、皮脂溢出及免疫功能低下：有多汗及皮脂溢出，无免疫功能低下。今日来我院门诊就诊。","既往史":"既往体健，否认高血压、糖尿病、冠心病等慢性病史。否认肝炎、结核等传染病史。否认手术外伤史。否认食物药物过敏史。预防接种史随社会。","个人史及过敏史":"生于原籍，久居本地，无疫区疫水接触史，无特殊粉尘毒物放射性物质接触史。不吸烟，不饮酒。生活规律。否认食物药物过敏史。","体格检查":"T36.5℃，P78次/分，R18次/分，BP116/72mmHg。神志清楚，查体合作。胸背部、上臂可见散在、融合的圆形或类圆形斑，呈浅白色，边界不清，表面覆糠秕样鳞屑，刮取鳞屑可见孢子与菌丝共存。","辅助检查":"检查计划：患者3月前夏季、出汗多后于胸背部及上臂出现散在圆形或类圆形斑疹，色浅白，表面覆细小糠秕状鳞屑，出汗时瘙痒加重、日晒后白斑更为明显，平素多汗并有皮脂溢出，无免疫功能低下，临床考虑花斑糠疹：刮取皮损鳞屑行真菌镜检，KOH涂片见成群圆形厚壁孢子及短粗菌丝、呈香蕉串样即可确诊，为本病确诊依据，并与白癜风、白色糠疹、贫血痣等色素减退性疾病鉴别；完善伍德灯检查，本病皮损多呈黄绿色荧光，可辅助诊断并了解皮损分布范围，指导外用药涂抹范围及疗效判断；因花斑糠疹为糠秕马拉色菌所致，需同时检查面颈、上臂及躯干其他部位有无类似皮损，明确受累范围，以判断仅需外用还是需口服抗真菌治疗；患者无免疫功能低下，一般不需加做免疫相关检查；但若皮损广泛、反复发作或规范抗真菌治疗疗效不佳，可加查空腹血糖及免疫功能筛查排除糖尿病、免疫抑制等易感因素，并检查有无合并其他浅部真菌感染（如手足癣、甲癣）以便同治。\n\n（检查清单）\n【必做】真菌镜检（鳞屑KOH涂片，见成群圆形厚壁孢子和短粗菌丝，呈香蕉串样，可确诊）；【其他】伍德灯检查（皮损呈黄绿色荧光，辅助诊断）。","初步诊断":"1. 花斑癣（花斑糠疹）\n（注：外用抗真菌药（2%酮康唑洗剂/乳膏或特比萘芬乳膏，涂药后保留5~10分钟洗去，每日1次×2周）；皮损广泛或反复者口服伊曲康唑（0.2g qd×7天）或氟康唑；注意色素减退斑需数月才能恢复（非疾病持续）；保持皮肤干燥、减少出汗、勤换衣物、衣物煮沸消毒；复发常见（糠秕马拉色菌为常驻菌），可每1~2周用酮康唑洗剂预防。）","处理方案":"【药物治疗】\n1. 2%酮康唑洗剂（或2.5%二硫化硒洗剂）外洗患处，涂抹后保留5～10分钟再冲洗，每日1次，连续2周。\n2. 1%特比萘芬乳膏（或2%酮康唑乳膏）外用患处，每日1～2次，连续2～4周，皮损消退后再巩固1周。\n3. 皮损泛发或外用疗效不佳者：伊曲康唑胶囊200mg口服，每日1次，餐后即服，连用7天（或氟康唑片150mg口服，每周1次，连用2～4周）。\n【一般治疗及生活指导】\n1. 保持皮肤清洁干燥，勤洗澡、勤换内衣及床单被褥，衣物、毛巾、浴巾定期煮沸消毒或在阳光下暴晒。\n2. 出汗后及时擦干，避免长期处于高温潮湿环境，减少剧烈运动后大汗浸渍。\n3. 洗澡尽量使用中性或弱酸性清洁产品，避免使用油腻护肤品及油性沐浴露，减少皮肤油脂堆积。\n4. 避免自行长期外用糖皮质激素类药膏，以免皮损扩大、病情迁延。\n【随诊要求】\n疗程结束后2～4周复诊，复查皮损消退情况；若2周后皮损无明显改善或反复发作，应及时复诊调整治疗方案。花斑癣易复发，夏季或多汗季节可每周1～2次使用2%酮康唑洗剂洗浴以预防复发。"},"icd10_diagnosis":"","icd10_secondary":[],"icd9cm3_procedure":[]}},"locator":{"file":"门诊住院病历模板/病历模板包_全部_20261111.json","arrayRow":370,"caseRow":1},"sourceHash":"10e4fdb435986b7b85f847c3951d0cb0eafdce0f372c5617949c05b337149194","contentHash":"190e7dcb4c886d512ee1840a552f6d75ec0129192ee2fc07297b5f28ce4055d4","pinyin":"huabanxuan","initials":"hbx","setting":"out","caseName":"门诊病历235","templateNames":["主诉","现病史","既往史","个人史及过敏史","体格检查","辅助检查","初步诊断","处理方案"],"emptyTemplates":[],"escapedNewlines":[],"quickFields":[["病例名称","门诊病历235",60],["模板名称","主诉 现病史 既往史 个人史及过敏史 体格检查 辅助检查 初步诊断 处理方案",30],["主要诊断编码","",30]]},{"id":"templates-871e2ea9a2fa307f60d2","key":"v1-c9ccc21dfe2a3058|templates-871e2ea9a2fa307f60d2","module":"templates","moduleKey":"v1-c9ccc21dfe2a3058|templates","version":"v1-c9ccc21dfe2a3058","title":"脓疱疮","category":"门诊病历模板","raw":{"name":"脓疱疮","category":"门诊病历模板","case":{"case_name":"门诊病历236","templates":{"主诉":"口周、面部及四肢脓疱、结痂伴瘙痒5天。","现病史":"患儿于5天前（夏秋季、皮肤外伤或搔抓后）在口周、鼻孔周围、面部及四肢出现红斑，很快形成水疱或脓疱，疱壁薄、易破溃，破后糜烂、结蜜黄色痂，伴瘙痒，皮损向周围蔓延（自身接种），有发热，无其他部位不适。有无湿疹、痱子等基础皮肤病及接触患病儿童史：无湿疹、痱子等基础皮肤病，有接触患病儿童史。今日来我院门诊就诊。","既往史":"既往体健，否认高血压、糖尿病、冠心病等慢性病史。否认肝炎、结核等传染病史。否认手术外伤史。否认食物药物过敏史。预防接种史随社会。","个人史及过敏史":"生于原籍，久居本地，无疫区疫水接触史，无特殊粉尘毒物放射性物质接触史。不吸烟，不饮酒。生活规律。否认食物药物过敏史。","体格检查":"T37.8℃，P96次/分，R22次/分，BP95/60mmHg。神志清楚，精神可。口周、鼻周、面部及四肢可见散在脓疱、糜烂面及蜜黄色厚痂，周围红晕，疱壁薄，尼氏征阴性，口腔黏膜无受累。颈部及腹股沟淋巴结肿大。","辅助检查":"检查计划：患儿5天前于夏秋季、皮肤外伤或搔抓后，在口周、鼻孔周围、面部及四肢出现红斑并迅速形成水疱、脓疱，疱壁薄易破，破后糜烂、结蜜黄色痂，瘙痒明显且有自身接种蔓延趋势，伴发热，有接触患病儿童史，本病以一般临床诊断为主，依据典型皮损及接触史即可诊断；因患儿有发热且皮损较广泛，为明确致病菌（金黄色葡萄球菌或链球菌）并指导抗生素选择，完善脓液细菌培养+药敏，反复发作或重症者尤应送检；链球菌感染后1~3周可继发急性肾小球肾炎，故于病后1~3周复查尿常规，了解有无血尿、蛋白尿以排查肾小球肾炎；若患儿出现水肿、尿量减少或血压升高，应及时加查肾功能及补体C3，必要时收住院进一步诊治；同时注意隔离、剪短指甲避免搔抓，毛巾衣物消毒，并检查有无湿疹、痱子等基础皮肤病以便同治。\n\n（检查清单）\n【必做】一般临床诊断为主；【其他】脓液细菌培养+药敏（疑金黄色葡萄球菌或链球菌感染，反复或重症时）、尿常规（链球菌感染后1~3周查，用以排查肾小球肾炎）。","初步诊断":"1. 脓疱疮（非大疱性）\n（注：局部治疗为主：脓疱或痂皮先用0.1%依沙吖啶溶液或高锰酸钾溶液湿敷清创，再涂莫匹罗星软膏（百多邦）或夫西地酸乳膏bid×5~7天；皮损广泛或伴发热、淋巴结炎：口服抗生素（一代头孢（头孢氨苄）或阿莫西林克拉维酸5~7天）；注意隔离（有传染性，接触传染）、剪短指甲避免搔抓、毛巾衣物消毒、勤洗手；伴基础皮肤病（湿疹）者同治；少数链球菌感染后可继发急性肾小球肾炎（血尿、水肿、高血压），病后1~3周复查尿常规。）","处理方案":"【药物治疗】\n1. 外用抗菌药：莫匹罗星软膏（百多邦）涂于皮损处，bid～tid，连用5～7天；泛发性皮损可选用夫西地酸乳膏，bid，连用5～7天。涂药前先用0.05%聚维酮碘溶液或生理盐水清洗、去除脓痂。\n2. 口服抗菌药（皮损广泛、伴发热或区域淋巴结肿大者）：头孢氨苄胶囊0.5g，qid，口服，连用5～7天。\n3. 青霉素过敏者：阿奇霉素片0.5g，qd，口服，首日加倍，连用3～5天。\n4. 根据患者具体情况制定个体化方案配合口服抗组胺药（如氯雷他定10mg qd）减轻瘙痒，避免搔抓加重扩散。\n\n【一般治疗及生活指导】\n1. 本病有传染性，避免与家人及他人密切接触、共用毛巾、浴巾、衣物、床单及玩具等，衣物、被褥勤换洗并煮沸消毒或日光暴晒。\n2. 保持皮肤清洁干燥，勤剪指甲，避免搔抓及强行揭除脓痂，搔抓后及时洗手，防止自体接种扩散至其他部位。\n3. 清淡饮食，多饮水，忌辛辣刺激性食物及海鲜、牛羊肉等易致敏食物。\n4. 注意休息，避免劳累及熬夜，适当活动；出汗后及时清洁皮肤，防止汗渍浸渍加重感染。\n\n【随诊要求】\n1. 用药后3～5天复诊，评估皮损消退及新发皮损情况。\n2. 若用药3天后皮损无好转、增多扩散，或出现发热、寒战、脓疱破裂后红肿扩大、腹股沟或腋窝淋巴结肿痛等，应立即返诊，必要时调整抗菌药物或查血常规、脓液细菌培养及药敏。\n3. 疗程结束后复诊确认痊愈；反复发作者建议排查鼻腔金黄色葡萄球菌定植及基础疾病（如糖尿病、贫血等），并进行相应处理。"},"icd10_diagnosis":"","icd10_secondary":[],"icd9cm3_procedure":[]}},"locator":{"file":"门诊住院病历模板/病历模板包_全部_20261111.json","arrayRow":371,"caseRow":1},"sourceHash":"10e4fdb435986b7b85f847c3951d0cb0eafdce0f372c5617949c05b337149194","contentHash":"be5b84453f2cc749269f44f4f0a7c0181f50beab0903d03bb0802a658e8e6dc0","pinyin":"nongpaochuang","initials":"npc","setting":"out","caseName":"门诊病历236","templateNames":["主诉","现病史","既往史","个人史及过敏史","体格检查","辅助检查","初步诊断","处理方案"],"emptyTemplates":[],"escapedNewlines":[],"quickFields":[["病例名称","门诊病历236",60],["模板名称","主诉 现病史 既往史 个人史及过敏史 体格检查 辅助检查 初步诊断 处理方案",30],["主要诊断编码","",30]]},{"id":"templates-10059afac421dcb3db6e","key":"v1-c9ccc21dfe2a3058|templates-10059afac421dcb3db6e","module":"templates","moduleKey":"v1-c9ccc21dfe2a3058|templates","version":"v1-c9ccc21dfe2a3058","title":"耳鸣","category":"门诊病历模板","raw":{"name":"耳鸣","category":"门诊病历模板","case":{"case_name":"门诊病历237","templates":{"主诉":"双侧耳鸣反复发作12月，伴听力下降2周。","现病史":"患者于12月前无明显诱因出现双侧耳鸣，为高调蝉鸣音，呈持续发作，安静时明显、夜间加重；伴听力下降、耳闷胀感，无眩晕，无耳流脓，不支持中耳炎、梅尼埃病等病因；无高血压、动脉硬化、颈椎病，无长期噪声暴露史，无耳毒性药物（氨基糖苷类、袢利尿剂、阿司匹林）用药史，无精神紧张及睡眠障碍；无颞下颌关节弹响，与咀嚼无关。今日来我院门诊就诊。","既往史":"既往体健，否认高血压、糖尿病、冠心病等慢性病史。否认肝炎、结核等传染病史。否认手术外伤史。否认食物药物过敏史。预防接种史随社会。","个人史及过敏史":"生于原籍，久居本地，无疫区疫水接触史，无特殊粉尘毒物放射性物质接触史。不吸烟，不饮酒。生活规律。否认食物药物过敏史。","体格检查":"T36.5℃，P76次/分，R18次/分，BP120/76mmHg。神志清楚，查体合作。外耳道通畅，无耵聍栓塞及异物；鼓膜完整、标志清，无内陷及穿孔；乳突区无压痛。音叉试验：Rinne试验气导大于骨导，Weber试验居中，提示感音性听力下降。颈部未闻及血管杂音（搏动性耳鸣时听诊）。","辅助检查":"【必做】纯音测听+声导抗（听力及中耳功能评估，为耳鸣常规检查）、耳内镜检查；【影像学】颞骨CT或MRI（疑听神经瘤时，单侧耳鸣伴听力下降者需重要排除，或疑血管性病变时）；【其他】耳鸣匹配检查、心理评估（焦虑、抑郁影响）。","初步诊断":"1. 耳鸣（双侧，主观性，病因待查）\n（注：治疗原则：明确并治疗病因（中耳炎、耵聍、听神经瘤、高血压、药物等）；特发性耳鸣处理：认知行为疗法及声治疗（耳鸣习服疗法，即掩蔽治疗）、改善睡眠、避免噪声及耳毒性药物、限烟酒咖啡；药物（疗效有限）：改善微循环（银杏叶提取物、甲钴胺）、抗焦虑抑郁（伴情绪障碍时）；单侧进行性耳鸣伴眩晕或听力下降者必须行听力学及影像学检查排除听神经瘤等器质性疾病。）","处理方案":"【药物治疗】\n1. 改善内耳微循环：银杏叶提取物片（金纳多）40mg，口服，每日3次，疗程4~8周。\n2. 营养神经：甲钴胺片0.5mg，口服，每日3次，疗程4~8周；可联合维生素B1片10mg，口服，每日3次。\n3. 改善内耳血供及组胺样作用：盐酸倍他司汀片（敏使朗）6mg，口服，每日3次，疗程4周；消化性溃疡活动期及哮喘患者慎用。\n4. 镇静安神辅助治疗：伴有睡眠障碍、焦虑者，可短期口服谷维素片10mg，每日3次，或遵医嘱加用艾司唑仑片1mg睡前口服，疗程不超过2周。\n【一般治疗及生活指导】\n1. 远离噪声环境，避免长时间、高音量使用耳机（音量≤最大60%、连续使用≤60分钟）；必要接触噪声时佩戴防噪耳塞/耳罩。\n2. 规律作息，保证充足睡眠，避免熬夜、精神紧张及过度劳累；保持情绪平稳，勿过度关注耳鸣声，必要时行耳鸣掩蔽或声治疗放松训练。\n3. 清淡低盐低脂饮食，戒烟限酒，少饮浓茶、咖啡等刺激性饮品；控制血压、血糖及血脂在正常范围。\n4. 避免使用耳毒性药物（如氨基糖苷类抗生素、袢利尿剂、阿司匹林大剂量、顺铂等）；避免用力擤鼻、挖耳及头部外伤。\n【随诊要求】\n1. 用药2~4周后复诊，评估耳鸣响度、持续时间及对生活影响的变化，必要时复查纯音测听、声导抗及耳鸣匹配检查，调整治疗方案。\n2. 如耳鸣由单侧突发、持续加重，或伴听力骤降、眩晕、耳痛、耳流脓、头痛等症状，应及时就诊耳鼻喉科，排除突发性聋、梅尼埃病、听神经瘤等器质性疾病。\n3. 慢性耳鸣患者建议每3~6个月复诊1次，动态评估病情；长期耳鸣伴明显焦虑、抑郁或失眠影响生活者，转诊心理科/睡眠门诊行认知行为治疗及心理干预。"},"icd10_diagnosis":"","icd10_secondary":[],"icd9cm3_procedure":[]}},"locator":{"file":"门诊住院病历模板/病历模板包_全部_20261111.json","arrayRow":372,"caseRow":1},"sourceHash":"10e4fdb435986b7b85f847c3951d0cb0eafdce0f372c5617949c05b337149194","contentHash":"bde1f2753043ae422c6f4be11b9b98ae48b2a9698b88605316ec9fb511300e71","pinyin":"erming","initials":"em","setting":"out","caseName":"门诊病历237","templateNames":["主诉","现病史","既往史","个人史及过敏史","体格检查","辅助检查","初步诊断","处理方案"],"emptyTemplates":[],"escapedNewlines":[],"quickFields":[["病例名称","门诊病历237",60],["模板名称","主诉 现病史 既往史 个人史及过敏史 体格检查 辅助检查 初步诊断 处理方案",30],["主要诊断编码","",30]]},{"id":"templates-bf2dbeb4da28243954f6","key":"v1-c9ccc21dfe2a3058|templates-bf2dbeb4da28243954f6","module":"templates","moduleKey":"v1-c9ccc21dfe2a3058|templates","version":"v1-c9ccc21dfe2a3058","title":"耳聋","category":"门诊病历模板","raw":{"name":"耳聋","category":"门诊病历模板","case":{"case_name":"门诊病历238","templates":{"主诉":"右耳听力下降（突发性下降）2周，伴耳鸣。","现病史":"患者于2周前出现右耳听力下降，为突发（数小时至数天内出现，突发性耳聋为耳鼻喉急症），伴耳鸣、耳闷胀感，无眩晕，无耳流脓（不支持中耳炎、胆脂瘤），无耳外伤史、爆震及噪声接触史，无耳毒性药物史（氨基糖苷类、袢利尿剂、大剂量阿司匹林），无家族耳聋史，无高血压、糖尿病、动脉硬化等老年性耳聋相关因素，无梅尼埃病史。今日来我院门诊就诊。","既往史":"既往体健，否认高血压、糖尿病、冠心病等慢性病史。否认肝炎、结核等传染病史。否认手术外伤史。否认食物药物过敏史。预防接种史随社会。","个人史及过敏史":"生于原籍，久居本地，无疫区疫水接触史，无特殊粉尘毒物放射性物质接触史。不吸烟，不饮酒。生活规律。否认食物药物过敏史。","体格检查":"T36.5℃，P76次/分，R18次/分，BP120/76mmHg。神志清楚，查体合作。外耳道通畅，鼓膜完整标志清，无内陷、穿孔及鼓室积液（不支持分泌性中耳炎），音叉试验（Rinne：气导大于骨导；Weber：偏向左侧健耳），初步鉴别传导性聋与感音神经性聋。","辅助检查":"【必做】纯音测听（听阈曲线，确定耳聋类型及程度：传导性、感音神经性或混合性）、声导抗（中耳功能）、耳内镜；【影像学】颞骨高分辨率CT（传导性聋者查中耳、乳突病变；突发性聋者排除内听道占位）、内听道MRI（感音神经性聋者排除听神经瘤）；【其他】耳声发射、听性脑干反应（客观听力评估，适用于儿童或不配合者）。","初步诊断":"1. 耳聋（感音神经性，右，中度）\n（注：突发性耳聋（72小时内突发、原因不明的感音神经性聋≥30dB）为急症，应尽早（1周内）治疗：糖皮质激素（全身用药：泼尼松1mg/kg/d渐减；或鼓室内注射地塞米松）+改善内耳微循环（银杏叶提取物、巴曲酶）+高压氧，越早治疗效果越好；传导性聋针对病因（中耳炎引流、耳硬化症手术（镫骨手术））；不可逆感音神经性聋：助听器验配，重度-极重度（双耳）考虑人工耳蜗植入；避免噪声及耳毒性药物。）","处理方案":"【药物治疗】\n1. 糖皮质激素（突发性感音神经性聋首选，发病72小时内尽早足量使用）：醋酸泼尼松片按1mg/kg/d晨起顿服，每日最大量60mg，连用5～7天，此后每3天减量5mg直至停药；伴糖尿病、高血压等不宜全身用药者，改行鼓室内注射甲泼尼龙（专科操作）。\n2. 改善内耳微循环：银杏叶提取物片（金纳多）40mg tid口服，疗程2～4周；或甲磺酸倍他司汀片6mg tid口服，连用2周。\n3. 神经营养与修复：甲钴胺片0.5mg tid口服，连用4周；维生素B1片10mg tid口服，连用4周。\n4. 若为分泌性中耳炎等传导性聋：桉柠蒎肠溶软胶囊0.3g tid口服 + 糠酸莫米松鼻喷雾剂每侧2喷 qd，连用2周，并治疗原发中耳疾病。\n【一般治疗及生活指导】\n1. 充分休息，保证充足睡眠，避免熬夜、劳累及精神紧张；急性期减少噪声暴露，避免长时间佩戴耳机（音量不超过最大音量60%，单次不超过60分钟）。\n2. 低盐低脂清淡饮食，保证足量饮水，戒烟限酒，忌浓茶、咖啡等刺激性饮品。\n3. 避免剧烈运动、用力擤鼻、憋气及乘坐飞机等气压骤变活动；伴眩晕者注意防跌倒，避免登高及单独驾驶。\n4. 禁用耳毒性药物（氨基糖苷类抗生素、袢利尿剂、顺铂等），避免强噪声环境及头部外伤。\n【随诊要求】\n1. 用药后1～2周门诊复查纯音测听、声导抗及耳内镜检查，评估听力变化；疗程结束（4周）复查听力，恢复不佳者建议鼓室内激素注射，并完善内听道MRI排除听神经瘤等占位病变。\n2. 治疗期间若出现眩晕加重、听力持续下降或新发明显耳鸣，随时复诊。\n3. 听力稳定后每3～6个月复查听力；双耳重度及以上感音神经性聋经规范治疗6个月无效者，转诊耳鼻喉科评估助听器验配或人工耳蜗植入。"},"icd10_diagnosis":"","icd10_secondary":[],"icd9cm3_procedure":[]}},"locator":{"file":"门诊住院病历模板/病历模板包_全部_20261111.json","arrayRow":373,"caseRow":1},"sourceHash":"10e4fdb435986b7b85f847c3951d0cb0eafdce0f372c5617949c05b337149194","contentHash":"0728c6da08981b679bb6bd10c7a35114f85bf6da00fff4a4ba7cc505b48bcd0c","pinyin":"erlong","initials":"el","setting":"out","caseName":"门诊病历238","templateNames":["主诉","现病史","既往史","个人史及过敏史","体格检查","辅助检查","初步诊断","处理方案"],"emptyTemplates":[],"escapedNewlines":[],"quickFields":[["病例名称","门诊病历238",60],["模板名称","主诉 现病史 既往史 个人史及过敏史 体格检查 辅助检查 初步诊断 处理方案",30],["主要诊断编码","",30]]},{"id":"templates-c8ddfd8c90ee25521045","key":"v1-c9ccc21dfe2a3058|templates-c8ddfd8c90ee25521045","module":"templates","moduleKey":"v1-c9ccc21dfe2a3058|templates","version":"v1-c9ccc21dfe2a3058","title":"鼻炎","category":"门诊病历模板","raw":{"name":"鼻炎","category":"门诊病历模板","case":{"case_name":"门诊病历239","templates":{"主诉":"鼻塞、流涕伴打喷嚏、鼻痒反复发作3年。","现病史":"患者于近3年每年春季反复出现鼻塞（交替性）、流涕（清水样）、阵发性打喷嚏（晨起或接触过敏原后连打数个至十余个）、鼻痒、眼痒，伴嗅觉减退，无头痛，无咽部异物感，受凉、接触花粉后加重。有哮喘病史，无湿疹、荨麻疹史，有过敏史，其母亲有变应性鼻炎家族史。今日来我院门诊就诊。","既往史":"既往体健，否认高血压、糖尿病、冠心病等慢性病史。否认肝炎、结核等传染病史。否认手术外伤史。否认食物药物过敏史。预防接种史随社会。","个人史及过敏史":"生于原籍，久居本地，无疫区疫水接触史，无特殊粉尘毒物放射性物质接触史。不吸烟，不饮酒。生活规律。否认食物药物过敏史。","体格检查":"T36.5℃，P76次/分，R18次/分，BP118/74mmHg。神志清楚，查体合作。双侧鼻黏膜苍白水肿，无充血；鼻甲肿大，下鼻甲明显；鼻腔可见清水样分泌物，无黏脓性分泌物；鼻道通畅度尚可。咽部淋巴滤泡增生，无充血。","辅助检查":"【必做】一般临床诊断为主；【其他】过敏原检测（皮肤点刺或血清特异性IgE，为变应性鼻炎确诊及规避依据）、鼻内镜检查（排除鼻息肉、鼻窦炎等）。","初步诊断":"1. 鼻炎（变应性）\n（注：变应性鼻炎：首选鼻用糖皮质激素（糠酸莫米松鼻喷剂为一线用药，疗程≥4周）+口服抗组胺药（氯雷他定10mg qd或西替利嗪）+鼻用抗组胺药（氮卓斯汀）；严重者可加白三烯受体拮抗剂（孟鲁司特10mg qn）；避免接触过敏原、生理盐水冲洗鼻腔；单纯慢性鼻炎可用减充血剂（羟甲唑啉，连续使用≤7天，防药物性鼻炎）；伴哮喘或哮喘控制不佳者评估特异性免疫治疗（脱敏）。）","处理方案":"【药物治疗】\n1. 糠酸莫米松鼻喷雾剂（内舒拿）每侧鼻孔各2喷，每日1次，晨起使用，疗程2~4周（过敏性鼻炎一线用药，起效慢需连续使用）。\n2. 氯雷他定片 10mg 每日1次，口服，疗程7~14天（合并打喷嚏、流清涕、鼻痒明显时加用）。\n3. 生理性海水鼻腔喷雾 每侧鼻孔2~4喷，每日3次，冲洗鼻腔清除分泌物及过敏原（各型鼻炎均可常规使用）。\n4. 鼻塞严重影响睡眠或通气时，可短期加用盐酸羟甲唑啉鼻喷雾剂，每侧1~2喷，每日不超过2次，连续使用不超过7天，避免药物性鼻炎。\n\n【一般治疗及生活指导】\n1. 明确并避免接触过敏原（尘螨、花粉、动物皮屑、霉菌等），勤换洗床单被套、使用防螨用品，花粉季外出佩戴口罩。\n2. 饮食清淡，忌辛辣刺激、烟酒及过冷过热食物；多饮水，保持室内空气流通、温度湿度适宜。\n3. 规律作息，避免熬夜及过度劳累，适度锻炼增强体质；注意保暖，预防感冒诱发或加重鼻炎。\n4. 避免用力擤鼻及挖鼻、用力吸鼻，防止鼻腔黏膜损伤及感染向鼻窦、中耳蔓延。\n\n【随诊要求】\n1. 用药2周后复诊，评估鼻塞、流涕、喷嚏等症状改善情况及药物耐受性，调整用药方案。\n2. 若连续用药1周症状无缓解，或出现持续黄脓涕、面部胀痛、发热、头痛加重等表现，提示可能合并鼻窦炎，应及时复诊。\n3. 症状控制后按医嘱逐步减量或维持治疗，不可自行突然停药，以防症状反复；过敏性鼻炎建议在花粉季前2周开始预防性用药并定期随访。"},"icd10_diagnosis":"","icd10_secondary":[],"icd9cm3_procedure":[]}},"locator":{"file":"门诊住院病历模板/病历模板包_全部_20261111.json","arrayRow":374,"caseRow":1},"sourceHash":"10e4fdb435986b7b85f847c3951d0cb0eafdce0f372c5617949c05b337149194","contentHash":"01a1475384106d88bc2e66a5ea1cc0818de9e903a30b256cd570b7807c1250d0","pinyin":"biyan","initials":"by","setting":"out","caseName":"门诊病历239","templateNames":["主诉","现病史","既往史","个人史及过敏史","体格检查","辅助检查","初步诊断","处理方案"],"emptyTemplates":[],"escapedNewlines":[],"quickFields":[["病例名称","门诊病历239",60],["模板名称","主诉 现病史 既往史 个人史及过敏史 体格检查 辅助检查 初步诊断 处理方案",30],["主要诊断编码","",30]]},{"id":"templates-f9f71e51d7f6f4325c5d","key":"v1-c9ccc21dfe2a3058|templates-f9f71e51d7f6f4325c5d","module":"templates","moduleKey":"v1-c9ccc21dfe2a3058|templates","version":"v1-c9ccc21dfe2a3058","title":"口腔溃疡","category":"门诊病历模板","raw":{"name":"口腔溃疡","category":"门诊病历模板","case":{"case_name":"门诊病历240","templates":{"主诉":"口腔黏膜反复溃疡、疼痛3年，再发5天。","现病史":"患者于3年前开始反复出现口腔黏膜溃疡，多见于唇内侧、颊黏膜及舌缘，单发或多发，呈圆形或椭圆形，中心凹陷、覆黄白色假膜、周围红晕，疼痛明显（进食说话时加重），一般7天愈合，反复发作，无发热，无眼红、眼干，无生殖器溃疡、皮疹及关节痛，不支持白塞病；精神紧张、熬夜、进食辛辣或月经期前后加重。今日来我院门诊就诊。","既往史":"既往体健，否认高血压、糖尿病、冠心病等慢性病史。否认肝炎、结核等传染病史。否认手术外伤史。否认食物药物过敏史。预防接种史随社会。","个人史及过敏史":"生于原籍，久居本地，无疫区疫水接触史，无特殊粉尘毒物放射性物质接触史。不吸烟，不饮酒。生活规律。否认食物药物过敏史。","体格检查":"T36.6℃，P78次/分，R18次/分，BP118/74mmHg。神志清楚，查体合作。唇内侧、颊黏膜及舌缘可见3个圆形溃疡，直径约4mm，表面覆黄白色假膜，周围红晕，触痛明显。口腔卫生尚可，未见牙石、龋齿及不良修复体。","辅助检查":"【必做】一般临床诊断为主；【其他】血常规（反复发作者排除贫血、粒细胞缺乏）、维生素B12、叶酸、铁蛋白（营养缺乏筛查）、自身抗体（疑白塞病、SLE时）、HIV及梅毒筛查（不典型溃疡）。","初步诊断":"1. 复发性阿弗他溃疡\n（注：局部治疗：止痛（利多卡因凝胶涂患处）、促愈合（重组人表皮生长因子凝胶、复方皮质散）、含漱液（氯己定漱口液，短期使用，防牙齿染色）；溃疡反复频繁或疼痛剧烈影响进食者可口服（秋水仙碱0.5mg bid（难治性）、沙利度胺（重症，需严格避孕）、补充维生素B族及叶酸）；避免辛辣刺激、保持口腔卫生、规律作息减压；溃疡＞2~3周不愈合、边缘不规则、基底硬结者需活检排除癌性溃疡（尤其老年单发溃疡）；伴眼、生殖器、皮肤受累者排查白塞病。）","处理方案":"【药物治疗】\n1. 局部抗炎促愈合：复方氯己定含漱液10ml含漱3-5分钟后吐出，tid，连用5-7天；或康复新液10ml含漱，tid。\n2. 促黏膜修复：重组人表皮生长因子凝胶（贝复济）适量涂布溃疡面，bid-tid，用至溃疡愈合。\n3. 镇痛（疼痛明显时）：利多卡因凝胶0.5g涂布溃疡局部，qid，进食前使用。\n4. 补充B族维生素及微量元素：复合维生素B片1片 tid，联用葡萄糖酸锌口服液10ml qd，连用2周。\n\n【一般治疗及生活指导】\n1. 保持口腔清洁：早晚刷牙、饭后淡盐水或温开水漱口，避免口腔内菌群失调加重感染。\n2. 饮食指导：进食清淡、温凉、软烂易消化食物，多饮水；忌辛辣、过烫、过硬、油炸及粗糙食物，戒烟酒。\n3. 作息活动：保证充足睡眠，避免劳累、熬夜及精神紧张，适当活动以增强免疫力。\n4. 避免刺激：减少对溃疡面的物理刺激，避免用舌舔舐或手指触碰溃疡处，保持大便通畅。\n\n【随诊要求】\n1. 常规溃疡多于1-2周内自愈，若超过2周未愈合或疼痛加重、溃疡面扩大、数目增多，应及时复诊。\n2. 反复发作（1年内发作3次以上）者建议复诊行口腔黏膜专科检查，评估是否需要系统用药（如免疫调节治疗）。\n3. 同一部位溃疡持续超过1个月不愈合者，须及时复诊行活检等检查，排除恶性病变可能。"},"icd10_diagnosis":"","icd10_secondary":[],"icd9cm3_procedure":[]}},"locator":{"file":"门诊住院病历模板/病历模板包_全部_20261111.json","arrayRow":375,"caseRow":1},"sourceHash":"10e4fdb435986b7b85f847c3951d0cb0eafdce0f372c5617949c05b337149194","contentHash":"2f75e186fb10a9e247acb390238197bb651fb861dcf1eca625cdf9f3485a713f","pinyin":"kouqiangkuiyang","initials":"kqky","setting":"out","caseName":"门诊病历240","templateNames":["主诉","现病史","既往史","个人史及过敏史","体格检查","辅助检查","初步诊断","处理方案"],"emptyTemplates":[],"escapedNewlines":[],"quickFields":[["病例名称","门诊病历240",60],["模板名称","主诉 现病史 既往史 个人史及过敏史 体格检查 辅助检查 初步诊断 处理方案",30],["主要诊断编码","",30]]},{"id":"templates-b87a9c206b302b966a74","key":"v1-c9ccc21dfe2a3058|templates-b87a9c206b302b966a74","module":"templates","moduleKey":"v1-c9ccc21dfe2a3058|templates","version":"v1-c9ccc21dfe2a3058","title":"牙龈炎","category":"门诊病历模板","raw":{"name":"牙龈炎","category":"门诊病历模板","case":{"case_name":"门诊病历241","templates":{"主诉":"刷牙时牙龈出血伴牙龈红肿3周。","现病史":"患者于3周前出现刷牙时牙龈出血、吮吸时亦有出血，牙龈红肿、胀痛，口腔异味，无自发痛，无牙齿松动，无妊娠（不支持妊娠期龈炎及龈瘤），未服用苯妥英钠、环孢素、钙通道阻滞剂等药物（不支持药物性牙龈增生），无糖尿病、血液病及维生素C缺乏，吸烟10年、10支/日。今日来我院门诊就诊。","既往史":"既往体健，否认高血压、糖尿病、冠心病等慢性病史。否认肝炎、结核等传染病史。否认手术外伤史。否认食物药物过敏史。预防接种史随社会。","个人史及过敏史":"生于原籍，久居本地，无疫区疫水接触史，无特殊粉尘毒物放射性物质接触史。不吸烟，不饮酒。生活规律。否认食物药物过敏史。","体格检查":"T36.5℃，P76次/分，R18次/分，BP118/74mmHg。神志清楚，查体合作。牙龈边缘红肿、质地松软，无增生（不支持药物性或妊娠性牙龈增生）；探诊出血（+）；龈沟探诊深度2mm（正常＜3mm，未加深，不支持牙周炎）；牙石少量；无牙齿松动。口腔卫生状况尚可。","辅助检查":"检查计划：患者3周来刷牙及吮吸时牙龈出血，牙龈红肿、胀痛，口腔异味明显，无自发痛及牙齿松动，无妊娠及苯妥英钠、环孢素、钙通道阻滞剂等药物服用史，无糖尿病、血液病及维生素C缺乏病史，但有吸烟10年、10支/日：先行一般临床检查及牙周探诊，了解牙龈红肿范围、探诊出血及牙周袋深度、附着丧失情况，以明确牙龈炎诊断并与牙周炎鉴别；完善X线片（曲面断层）检查，牙龈炎时牙槽骨无吸收，如见牙槽骨吸收则诊断为牙周炎，并了解有无牙石、邻面龋及不良修复体等局部刺激因素；因患者牙龈出血明显，且吸烟为牙周病危险因素，于洁治前完善血常规及凝血功能检查，排除血小板减少、白血病等血液系统疾病及凝血功能障碍所致出血，保障洁治安全；如血常规提示贫血或白细胞异常，进一步加查外周血涂片及铁代谢等以明确病因；洁治后1~2周复查牙龈出血及红肿情况评估疗效，若出血持续不缓解，需再次排查全身因素。\n\n（检查清单）\n【必做】一般临床检查+牙周探诊；【影像学】X线片（曲面断层，牙龈炎时牙槽骨无吸收；如见骨吸收则诊断为牙周炎）；【其他】血常规、凝血功能（牙龈出血明显或疑血液病时，于拔牙或洁治前检查）。","初步诊断":"1. 牙龈炎（慢性）\n（注：核心治疗为专业洁治（龈上洁治，去除牙石菌斑，每年1~2次）+自我口腔维护（正确刷牙（Bass法，每日2次）、牙线或牙缝刷）；局部可用氯己定含漱液（短期1~2周）；去除局部刺激因素（不良修复体）、控制糖尿病、戒烟；妊娠期龈炎加强口腔清洁，产后多自行消退；洁治后牙龈出血多在1~2周内改善，若持续出血需排查全身因素。）","处理方案":"【药物治疗】\n1. 抗菌含漱：0.02%葡萄糖酸氯己定含漱液10ml含漱，tid，每次含漱约1分钟，疗程5～7天（含漱后半小时内勿刷牙、进食，长期使用可致牙齿及舌背着色，停药后可恢复）。\n2. 局部涂布：碘甘油涂布牙龈缘及龈沟内，bid，每次0.5ml，涂布后30分钟内勿漱口饮水，用于红肿溢脓明显者，连用3～5天。\n3. 口服抗菌（牙龈肿痛、溢脓等急性炎症明显时）：阿莫西林胶囊0.5g tid×5天，首日加倍；对青霉素过敏者改用甲硝唑片0.2g tid×5天，或克林霉素胶囊0.3g bid×5天。\n4. 辅助用药：维生素C片0.2g tid，连服2周，促进牙龈组织修复；疼痛明显者可加布洛芬缓释胶囊0.3g bid×3天。\n\n【一般治疗及生活指导】\n1. 口腔清洁：采用改良巴氏刷牙法，每日早晚各1次、每次至少2分钟，刷毛与牙面呈45°角轻压龈缘上下颤动，配合牙线或牙间隙刷每日清洁邻面牙缝，清除菌斑及软垢。\n2. 饮食指导：多饮水，进食清淡、富含维生素的软食，避免过烫、辛辣、过硬及过甜黏腻食物，减少对牙龈的刺激；戒烟限酒。\n3. 作息与习惯：规律作息、避免熬夜及过度劳累，保持口腔湿润；避免用牙签粗力剔牙、自行以硬物刮擦牙龈，勿咬硬物。\n4. 禁忌：急性炎症期避免用力刷牙及使用牙线摩擦红肿牙龈，禁止自行挤压牙龈溢脓部位，防止感染扩散。\n\n【随诊要求】\n1. 治疗后1～2周复诊，评估牙龈红肿、出血、溢脓消退情况；如用药3天后症状无缓解或出现发热、牙龈出血不止、肿痛加重，应及时复诊。\n2. 急性炎症控制后，建议择期行龈上洁治术（洗牙）及必要的龈下刮治，去除牙石与菌斑等局部刺激因素。\n3. 症状反复或存在妊娠期龈炎、药物性牙龈增生、糖尿病等基础疾病者，应定期（每3～6个月）口腔科复查，并每6～12个月常规洁牙1次以维护牙周健康。"},"icd10_diagnosis":"","icd10_secondary":[],"icd9cm3_procedure":[]}},"locator":{"file":"门诊住院病历模板/病历模板包_全部_20261111.json","arrayRow":376,"caseRow":1},"sourceHash":"10e4fdb435986b7b85f847c3951d0cb0eafdce0f372c5617949c05b337149194","contentHash":"39da4d2dc0bb872077b3409f58a4f0056477c827d23d9cb0bae95bbdea4804b0","pinyin":"yayinyan","initials":"yyy","setting":"out","caseName":"门诊病历241","templateNames":["主诉","现病史","既往史","个人史及过敏史","体格检查","辅助检查","初步诊断","处理方案"],"emptyTemplates":[],"escapedNewlines":[],"quickFields":[["病例名称","门诊病历241",60],["模板名称","主诉 现病史 既往史 个人史及过敏史 体格检查 辅助检查 初步诊断 处理方案",30],["主要诊断编码","",30]]},{"id":"templates-85d9153f669d3da099dd","key":"v1-c9ccc21dfe2a3058|templates-85d9153f669d3da099dd","module":"templates","moduleKey":"v1-c9ccc21dfe2a3058|templates","version":"v1-c9ccc21dfe2a3058","title":"牙周炎","category":"门诊病历模板","raw":{"name":"牙周炎","category":"门诊病历模板","case":{"case_name":"门诊病历242","templates":{"主诉":"牙龈反复红肿出血伴牙齿松动18年，加重2周。","现病史":"患者于18年前开始反复牙龈红肿、刷牙出血、口腔异味，渐出现牙龈萎缩、牙根暴露、牙齿松动移位、咀嚼无力，2周来个别牙牙龈肿胀疼痛加重，有牙周溢脓，无发热。有糖尿病史（血糖控制尚可），吸烟20年、20支/日，无遗传易感因素及妊娠史。今日来我院门诊就诊。","既往史":"既往体健，否认高血压、糖尿病、冠心病等慢性病史。否认肝炎、结核等传染病史。否认手术外伤史。否认食物药物过敏史。预防接种史随社会。","个人史及过敏史":"生于原籍，久居本地，无疫区疫水接触史，无特殊粉尘毒物放射性物质接触史。不吸烟，不饮酒。生活规律。否认食物药物过敏史。","体格检查":"T36.6℃，P78次/分，R18次/分，BP130/80mmHg。神志清楚，查体合作。全口牙龈暗红、肿胀、萎缩，牙石菌斑量多，牙周探诊：探诊深度5mm（＞4mm提示附着丧失，符合牙周炎），探诊出血（+），有牙周溢脓，牙齿松动Ⅱ度（下颌前牙），有牙移位及食物嵌塞。","辅助检查":"检查计划：患者牙龈反复红肿出血伴牙齿松动18年、近2周个别牙肿胀疼痛并有牙周溢脓，为明确牙周组织破坏的范围与程度，门诊即刻完善牙周探诊，逐牙位记录探诊深度、临床附着丧失及出血指数，了解牙周袋深度与活动性炎症部位，为牙周检查核心并为诊断依据，指导后续龈上洁治与龈下刮治（SRP）的分象限方案；牙槽骨的吸收方式是慢性牙周炎分期分级的关键，完善X线片检查（曲面断层全景片或对可疑牙位加拍根尖片），明确牙槽骨吸收呈水平型或垂直型及其累及范围，为诊断提供影像依据（诊断依据）；患者有糖尿病史，糖尿病与牙周炎存在双向影响关系，查血糖（必要时加查糖化血红蛋白）了解血糖控制水平，评估其对牙周组织修复与疗效的影响，控制血糖有利于牙周治疗，据此指导牙周治疗时机选择及内科协同控糖；患者吸烟20年、每日20支，为牙周炎明确的危险因素，需在治疗中持续评估并建议戒烟，以改善治疗反应与长期疗效；因病程长、炎症反复且存在深袋与溢脓，属难治性牙周炎可能，必要时完善牙周微生物检查（龈下菌斑涂片或厌氧培养）了解致病菌构成，指导抗菌药物的选择，避免经验性用药；基础治疗（SRP）完成后4~6周定期复查牙周探诊与出血指数，评估疗效并明确是否需行牙周翻瓣、植骨等手术治疗；对松动明显、无法保留的患牙，必要时加拍根尖片明确根周骨支持情况后再决定拔除方案，拔牙前复查血糖以评估愈合风险。\n\n（检查清单）\n【必做】牙周探诊（探诊深度、附着丧失、出血指数，为牙周检查核心）、X线片（曲面断层或根尖片，观察牙槽骨吸收程度（水平或垂直吸收），为诊断依据）；【其他】血糖（糖尿病与牙周炎双向关系，控制血糖有利于牙周治疗）、微生物检查（难治性牙周炎）。","初步诊断":"1. 慢性牙周炎（中度）\n（注：基础治疗：龈上洁治+龈下刮治及根面平整（SRP，分象限进行）、口腔卫生指导（Bass刷牙、牙缝刷或牙线）；药物治疗：局部缓释抗菌药（盐酸米诺环素软膏）配合，急性脓肿期全身抗生素（甲硝唑+阿莫西林7天）；基础治疗后复查（4~6周），仍有深袋或骨吸收明显者行牙周手术（翻瓣、植骨）；定期维护（3~6个月复查）；控制糖尿病、戒烟；牙齿松动严重无法保留者拔除。）","处理方案":"【药物治疗】\n1. 抗感染治疗（控制牙周袋内厌氧菌为主、兼顾需氧菌）：甲硝唑片0.2g tid×7天＋阿莫西林胶囊0.5g tid×7天；青霉素过敏者改用甲硝唑片0.2g tid×7天＋患者霉素胶囊0.15g bid×7天，均为餐后服。\n2. 局部用药：龈下刮治及根面平整后牙周袋内置入盐酸米诺环素软膏（派丽奥）0.5g/支，每周1次，连用2~4次；同时0.12%氯己定含漱液10ml含漱1分钟，bid，含漱后清水漱口，用药期间避免饮用浓茶、咖啡。\n3. 对症止痛（疼痛明显时）：布洛芬缓释胶囊0.3g bid，餐后服，连用不超过3~5天，有消化性溃疡病史者禁用。\n【一般治疗及生活指导】\n1. 牙周基础治疗：行全口龈上洁治＋龈下刮治及根面平整（SRP），按象限分次完成，彻底去除菌斑、牙石及不良修复体等局部刺激因素；急性牙周脓肿形成者及时切开引流。\n2. 口腔卫生维护：采用巴氏（Bass）刷牙法每日早晚各1次、每次不少于3分钟，配合牙线及牙缝刷清洁邻面与根分叉区；戒烟，吸烟及不良口腔卫生习惯显著影响疗效与愈合。\n3. 饮食与休息：进食温软清淡饮食，避免过冷过热及辛辣刺激性食物，暂用健侧咀嚼、避免啃咬硬物；保证充足睡眠、避免劳累，糖尿病患者需将血糖控制达标。\n【随诊要求】\n1. 用药期间如出现皮疹、腹泻、恶心、味觉异常等不适，及时复诊调整用药；急性症状缓解后2~4周复诊，评估牙周袋深度及炎症控制情况。\n2. 牙周基础治疗完成后4~6周复诊，复查牙周袋深度、附着丧失及出血指数，必要时行再评估与进一步牙周治疗。\n3. 定期牙周维护：每3~6个月复查维护一次（牙周支持治疗），期间如出现牙龈反复出血、牙齿松动加重或牙周脓肿，随时就诊。"},"icd10_diagnosis":"","icd10_secondary":[],"icd9cm3_procedure":[]}},"locator":{"file":"门诊住院病历模板/病历模板包_全部_20261111.json","arrayRow":377,"caseRow":1},"sourceHash":"10e4fdb435986b7b85f847c3951d0cb0eafdce0f372c5617949c05b337149194","contentHash":"3b735d7ad263fe306e0c27e476412c77d8df73172ed8406845ef29a8449b09e0","pinyin":"yazhouyan","initials":"yzy","setting":"out","caseName":"门诊病历242","templateNames":["主诉","现病史","既往史","个人史及过敏史","体格检查","辅助检查","初步诊断","处理方案"],"emptyTemplates":[],"escapedNewlines":[],"quickFields":[["病例名称","门诊病历242",60],["模板名称","主诉 现病史 既往史 个人史及过敏史 体格检查 辅助检查 初步诊断 处理方案",30],["主要诊断编码","",30]]},{"id":"templates-65967c6b25b72a4790f3","key":"v1-c9ccc21dfe2a3058|templates-65967c6b25b72a4790f3","module":"templates","moduleKey":"v1-c9ccc21dfe2a3058|templates","version":"v1-c9ccc21dfe2a3058","title":"咽炎","category":"门诊病历模板","raw":{"name":"咽炎","category":"门诊病历模板","case":{"case_name":"门诊病历243","templates":{"主诉":"反复咽部异物感10月，咽痛3天","现病史":"患者于10月前开始反复咽部异物感、干痒、灼热、微痛、刺激性咳嗽（晨起用力清嗓），刷牙时恶心，症状在讲话多、受凉、烟酒刺激后加重，3天前急性发作咽痛，吞咽时明显，无发热，无声音嘶哑，无呼吸困难。有鼻后滴漏（鼻炎鼻窦炎），无反酸烧心等胃食管反流表现，有职业用声及烟酒史。今日来我院门诊就诊。","既往史":"既往体健，否认高血压、糖尿病、冠心病等慢性病史。否认肝炎、结核等传染病史。否认手术外伤史。否认食物药物过敏史。预防接种史随社会。","个人史及过敏史":"生于原籍，久居本地，无疫区疫水接触史，无特殊粉尘毒物放射性物质接触史。不吸烟，不饮酒。生活规律。否认食物药物过敏史。","体格检查":"T36.7℃，P78次/分，R18次/分，BP118/74mmHg。神志清楚，查体合作。咽部黏膜慢性充血肥厚，咽后壁淋巴滤泡增生呈颗粒状，腭弓充血，扁桃体不大，咽侧索肥厚。","辅助检查":"【必做】一般临床诊断为主；【其他】鼻内镜或喉镜（排除鼻窦炎、咽喉新生物，适用于咽异物感持续或伴吞咽困难者）、食管24小时pH监测（疑反流性咽炎）。","初步诊断":"1. 咽炎（急性）\n（注：急性咽炎对症为主：多饮温水、盐水漱口、含片（西地碘）、必要时解热镇痛；细菌性（脓性分泌物或发热）用抗菌药物；慢性咽炎重在去除病因（治疗鼻炎鼻窦炎鼻后滴漏、胃食管反流（PPI）、戒烟酒、避免辛辣刺激及过度用声）、咽部雾化、中成药（蓝芩口服液或甘桔冰梅片）；顽固性咽异物感需喉镜检查排除新生物（梨状窝、声门下）。）","处理方案":"【药物治疗】\n1. 抗感染：阿莫西林胶囊 0.5g 口服 每日3次 ×5天（青霉素过敏者改用阿奇霉素片 0.5g 口服 每日1次 ×3天）；考虑病毒感染或轻型病例不常规使用抗菌药物，以对症治疗为主。\n2. 中成药抗炎利咽：蓝芩口服液 10ml 口服 每日3次 ×5天；或 蒲地蓝消炎口服液 10ml 口服 每日3次 ×5天，二选一。\n3. 局部用药：西地碘含片 1片 含服 每2~3小时1次，每日不超过6片，连用不超过5天；或 复方硼砂溶液 含漱 每日3~4次。\n4. 对症止痛：布洛芬缓释胶囊 0.3g 口服 每日2次，咽痛剧烈或伴发热时服用，热退痛止即停，连续使用不超过3天。\n\n【一般治疗及生活指导】\n1. 适当休息，保证充足睡眠，避免熬夜和劳累；减少用嗓，避免长时间大声说话及清嗓子动作。\n2. 多饮温水，饮食清淡、易消化，忌辛辣、煎炸、过烫及过硬食物，戒烟戒酒。\n3. 保持室内空气湿润、通风，温盐水漱口 每日3~4次，保持口腔及咽部清洁。\n4. 注意保暖，避免冷空气、粉尘、油烟等刺激；急性期避免剧烈运动及过度发声。\n\n【随诊要求】\n1. 用药3~5天后复诊评估疗效；若症状明显缓解可完成疗程，无需特殊复诊。\n2. 若用药3天后咽痛、发热无缓解或进行性加重，或出现高热持续不退、吞咽困难、声音嘶哑加重、呼吸不畅等表现，应及时复诊或至急诊就诊，必要时行喉镜检查除外喉部病变。"},"icd10_diagnosis":"","icd10_secondary":[],"icd9cm3_procedure":[]}},"locator":{"file":"门诊住院病历模板/病历模板包_全部_20261111.json","arrayRow":378,"caseRow":1},"sourceHash":"10e4fdb435986b7b85f847c3951d0cb0eafdce0f372c5617949c05b337149194","contentHash":"c1a0e2281dc36c080bc44ef291f0bc29f5f48505489ec71014c7894be8bc2d44","pinyin":"yanyan","initials":"yy","setting":"out","caseName":"门诊病历243","templateNames":["主诉","现病史","既往史","个人史及过敏史","体格检查","辅助检查","初步诊断","处理方案"],"emptyTemplates":[],"escapedNewlines":[],"quickFields":[["病例名称","门诊病历243",60],["模板名称","主诉 现病史 既往史 个人史及过敏史 体格检查 辅助检查 初步诊断 处理方案",30],["主要诊断编码","",30]]},{"id":"templates-a03dd8e8c217fe982fe5","key":"v1-c9ccc21dfe2a3058|templates-a03dd8e8c217fe982fe5","module":"templates","moduleKey":"v1-c9ccc21dfe2a3058|templates","version":"v1-c9ccc21dfe2a3058","title":"子宫肌瘤","category":"门诊病历模板","raw":{"name":"子宫肌瘤","category":"门诊病历模板","case":{"case_name":"门诊病历244","templates":{"主诉":"月经量增多、经期延长2年，加重3月","现病史":"患者于2年前体检发现子宫肌瘤（部位：肌壁间，大小约5cm），近3月月经量明显增多、经期延长（10天）、经期腹痛，伴头晕乏力、面色苍白等贫血表现，有尿频尿急（压迫膀胱）、便秘（压迫直肠）及腰酸腹坠等压迫症状，白带增多，无异常阴道出血（绝经后出血需警惕恶变及其他病变）。生育要求：有生育要求。今日来我院门诊就诊。","既往史":"既往体健，否认高血压、糖尿病、冠心病等慢性病史。否认肝炎、结核等传染病史。否认手术外伤史。否认食物药物过敏史。预防接种史随社会。","个人史及过敏史":"生于原籍，久居本地，无疫区疫水接触史，无特殊粉尘毒物放射性物质接触史。不吸烟，不饮酒。生活规律。否认食物药物过敏史。","体格检查":"T36.5℃，P84次/分，R18次/分，BP118/74mmHg。神志清楚，贫血貌（+）。腹平软，下腹部可及质硬、活动、结节状包块（符合较大肌瘤）。妇科检查：子宫增大如孕12周大小、质硬、表面不规则，双附件未触及包块，宫颈光滑。","辅助检查":"【必做】血常规（贫血评估）、盆腔超声（肌瘤数目、部位、大小、有无变性，为首选及随访手段）；【影像学】盆腔MRI（多发性或巨大肌瘤术前定位、疑变性与肉瘤鉴别时）；【其他】宫腔镜（黏膜下肌瘤）、诊断性刮宫或内膜活检（异常出血者，排除内膜病变）。","初步诊断":"1. 子宫肌瘤（肌壁间，多发）\n（注：无症状肌瘤定期随访（每3~6个月超声）；有症状（月经过多致贫血：口服铁剂；压迫症状）：药物治疗（复方口服避孕药或左炔诺孕酮宫内缓释系统（曼月乐，减少经量）或GnRH-a（术前缩瘤或围绝经期，3~6个月））；手术指征：症状明显药物治疗无效、肌瘤增长迅速疑恶变、压迫症状重、影响生育，可行肌瘤剔除（有生育要求）或全子宫切除（无生育要求）；黏膜下肌瘤宫腔镜切除；妊娠期注意肌瘤红色变性；绝经后肌瘤不缩反长需警惕恶变（平滑肌肉瘤，迅速增大、疼痛），应手术。）","处理方案":"【药物治疗】\n1. 促性腺激素释放激素激动剂（GnRH-a）类：醋酸亮丙瑞林微球3.75mg皮下注射，每4周1次，疗程3～6个月，用于术前缩瘤或围绝经期症状明显者，注意反向添加疗法及骨密度监测。\n2. 孕激素受体调节剂：米非司酮片12.5mg口服每日1次，连用3～6个月，适用于月经量增多、有生育要求或术前准备者，用药期间需避孕并监测肝肾功能。\n3. 抗纤溶止血药：氨甲环酸片1.0g口服每日3次，仅于月经期（月经第1～5天）服用，用于月经过多控制出血，有血栓性疾病史者禁用。\n4. 补铁纠正贫血：琥珀酸亚铁片0.1g口服每日2次，餐后服用，配合维生素C片0.1g每日3次促进吸收，血红蛋白恢复正常后继续服用1～2个月，每月复查血常规。\n【一般治疗及生活指导】\n1. 定期随访观察：无症状或症状轻微者每3～6个月行妇科超声检查监测肌瘤大小及生长速度，避免不必要干预。\n2. 饮食指导：均衡营养，多食瘦肉、动物肝脏、绿叶蔬菜等富含铁及蛋白质食物，减少高脂、高糖饮食及油炸食品；避免服用含雌激素成分的保健品、补品及激素类药物（如蜂王浆、雪蛤、不明成分美容养颜产品）。\n3. 生活活动：避免长期久坐，适度进行散步、瑜伽等有氧运动；经期注意休息，避免剧烈运动、重体力劳动及寒冷刺激，保持外阴清洁，经期禁性生活、盆浴及游泳。\n4. 禁忌：避免随意服用含雌激素或活血化瘀的中成药、偏方；有生育要求者勿自行长期用药，需专科评估肌瘤位置对妊娠的影响。\n【随诊要求】\n1. 保守观察者每3～6个月复查妇科超声及妇科检查，连续2年无变化可延长至每6～12个月复查1次。\n2. 药物治疗期间每1～3个月复诊，复查血常规、肝肾功能，监测月经量及贫血改善情况，评估疗效与不良反应。\n3. 如出现月经量突然增多伴头晕乏力、经期延长、腹痛加剧、尿频尿急、便秘、腰酸下坠感等压迫症状，或触及腹部包块迅速增大，需及时就诊，必要时完善宫腔镜、MRI及血肿瘤标志物检查排除恶变。\n4. 有生育要求者经治疗后建议尽早备孕，妊娠后按高危妊娠管理，定期产检监测肌瘤变化。"},"icd10_diagnosis":"","icd10_secondary":[],"icd9cm3_procedure":[]}},"locator":{"file":"门诊住院病历模板/病历模板包_全部_20261111.json","arrayRow":379,"caseRow":1},"sourceHash":"10e4fdb435986b7b85f847c3951d0cb0eafdce0f372c5617949c05b337149194","contentHash":"289210224987947823f25e4064e2ab7f6c7636dc4f38c5e913e86996eac3a795","pinyin":"zigongjiliu","initials":"zgjl","setting":"out","caseName":"门诊病历244","templateNames":["主诉","现病史","既往史","个人史及过敏史","体格检查","辅助检查","初步诊断","处理方案"],"emptyTemplates":[],"escapedNewlines":[],"quickFields":[["病例名称","门诊病历244",60],["模板名称","主诉 现病史 既往史 个人史及过敏史 体格检查 辅助检查 初步诊断 处理方案",30],["主要诊断编码","",30]]},{"id":"templates-f99adf802e26e9932c35","key":"v1-c9ccc21dfe2a3058|templates-f99adf802e26e9932c35","module":"templates","moduleKey":"v1-c9ccc21dfe2a3058|templates","version":"v1-c9ccc21dfe2a3058","title":"卵巢囊肿","category":"门诊病历模板","raw":{"name":"卵巢囊肿","category":"门诊病历模板","case":{"case_name":"门诊病历245","templates":{"主诉":"体检发现下腹囊性包块6月，伴下腹胀痛3天","现病史":"患者于6月前体检行超声发现卵巢囊肿（右侧，大小约5cm，性质：单纯囊性），定期复查大小变化不明显。近3天出现下腹胀痛、坠胀，无突发剧痛（不支持卵巢囊肿蒂扭转或破裂），无恶心呕吐，无发热，无异常阴道出血，月经规律，末次月经为2周前。无卵巢肿瘤家族史（BRCA突变）：无。今日来我院门诊就诊。","既往史":"既往体健，否认高血压、糖尿病、冠心病等慢性病史。否认肝炎、结核等传染病史。否认手术外伤史。否认食物药物过敏史。预防接种史随社会。","个人史及过敏史":"生于原籍，久居本地，无疫区疫水接触史，无特殊粉尘毒物放射性物质接触史。不吸烟，不饮酒。生活规律。否认食物药物过敏史。","体格检查":"T36.5℃，P78次/分，R18次/分，BP118/74mmHg。神志清楚，查体合作，无痛苦面容。腹平软，下腹部轻压痛，无反跳痛及肌紧张（无破裂或扭转所致腹膜炎体征）。妇科检查：子宫正常大小，右附件区可及囊性包块，大小约5cm，活动可，轻压痛。","辅助检查":"【必做】盆腔超声（囊肿大小、形态、囊壁、分隔、囊内结构、有无实性成分，为卵巢囊肿性质评估首选）；【肿瘤标志物】CA125（升高为上皮性卵巢癌筛查指标，但良性病变、子宫内膜异位症、盆腔炎、月经期也可升高）、HE4、AFP（内胚窦瘤）、hCG（妊娠）；【影像学】盆腔MRI（复杂囊肿或疑恶性时）、CT（转移评估）；【其他】绝经后女性或囊肿持续存在者行腹腔镜探查或手术。","初步诊断":"1. 卵巢囊肿（右，病理性，性质待查）\n（注：育龄期＜5cm单纯囊肿多可随访（2~3个月后复查，生理性囊肿多自行消退）；持续存在、＞5cm、有实性成分、囊壁增厚、CA125升高或绝经后新发囊肿：建议腹腔镜手术（囊肿剥除或附件切除）送病理；突发下腹剧痛伴恶心提示蒂扭转（5~10cm囊肿易发）或破裂，为妇科急症需急诊手术；口服避孕药抑制排卵可防功能性囊肿复发；有卵巢癌家族史者遗传咨询。）","处理方案":"【药物治疗】\n1. 功能性囊肿（卵泡囊肿、黄体囊肿）：复方短效口服避孕药，如屈螺酮炔雌醇片（优思明）1片 qd po，连服21天后停药7天为1个周期，连用2～3个周期，抑制排卵、促使囊肿消退。\n2. 月经后半周期孕激素调节：地屈孕酮片10mg bid po×10天（自月经周期第14天起服），连用2～3个月经周期，纠正黄体功能不足，减少黄体囊肿形成。\n3. 合并盆腔炎性改变或囊肿内出血吸收期：头孢呋辛酯片0.25g bid po×7天，联合甲硝唑片0.4g bid po×7天（青霉素过敏者改用阿奇霉素片0.5g qd po×5天）。\n4. 中医辨证辅助治疗（血瘀证）：桂枝茯苓胶囊0.62g（3粒）tid po×4周，可连用2～3个疗程。\n\n【一般治疗及生活指导】\n1. 休息：避免剧烈运动、跑跳、提重物及重体力劳动，尤其月经后半期（黄体期），防止囊肿破裂或蒂扭转。\n2. 饮食：清淡均衡饮食，多食新鲜蔬菜水果等高纤维食物，少食辛辣刺激及油腻食物；忌食含雌激素的滋补品（如蜂王浆、雪蛤、不明成分保健品），超重者控制体重。\n3. 活动：可进行散步、瑜伽等轻中度有氧运动，避免突然改变体位、长时间憋尿及腹部受压。\n4. 禁忌：囊肿较大（≥5cm）或有腹痛者经期禁止性生活及剧烈盆浴，注意经期卫生，防止盆腔感染诱发囊肿增大。\n\n【随诊要求】\n1. 功能性囊肿：每3个月于月经干净后3～7天复查妇科超声，观察囊肿大小及形态变化；若2～3个周期内未消退或反而增大，转妇科门诊进一步评估。\n2. 囊肿持续存在、直径≥5cm或伴持续性腹痛、月经紊乱者，缩短至1个月复查，必要时查血清肿瘤标志物（CA125、HE4）及盆腔MRI平扫+增强。\n3. 绝经后新发囊肿，或超声提示囊肿内有实性成分、分隔、囊壁增厚或血流丰富者，建议尽早转上级医院妇科肿瘤专科诊治。\n4. 随访期间如突发下腹剧痛、伴恶心呕吐、肛门坠胀或晕厥，提示囊肿破裂、蒂扭转或黄体破裂可能，需立即急诊就诊，勿延误。"},"icd10_diagnosis":"","icd10_secondary":[],"icd9cm3_procedure":[]}},"locator":{"file":"门诊住院病历模板/病历模板包_全部_20261111.json","arrayRow":380,"caseRow":1},"sourceHash":"10e4fdb435986b7b85f847c3951d0cb0eafdce0f372c5617949c05b337149194","contentHash":"4c15864f2f7fe17c0d82019a2d9d1ec367c42a063481954a0651f260ea8f39ef","pinyin":"luanchaonangzhong","initials":"lcnz","setting":"out","caseName":"门诊病历245","templateNames":["主诉","现病史","既往史","个人史及过敏史","体格检查","辅助检查","初步诊断","处理方案"],"emptyTemplates":[],"escapedNewlines":[],"quickFields":[["病例名称","门诊病历245",60],["模板名称","主诉 现病史 既往史 个人史及过敏史 体格检查 辅助检查 初步诊断 处理方案",30],["主要诊断编码","",30]]},{"id":"templates-991dcd5eaaffea5640b0","key":"v1-c9ccc21dfe2a3058|templates-991dcd5eaaffea5640b0","module":"templates","moduleKey":"v1-c9ccc21dfe2a3058|templates","version":"v1-c9ccc21dfe2a3058","title":"宫颈炎","category":"门诊病历模板","raw":{"name":"宫颈炎","category":"门诊病历模板","case":{"case_name":"门诊病历246","templates":{"主诉":"白带增多伴接触性出血、外阴不适2周。","现病史":"患者于2周前出现白带增多（黏液脓性，有异味），有接触性出血（同房后出血）、外阴瘙痒灼热及腰骶部酸痛，无发热，无腹痛。无不洁性生活、多个性伴侣、阴道炎反复发作及宫颈手术史。末次月经为2周前，无宫内节育器。今日来我院门诊就诊。","既往史":"既往体健，否认高血压、糖尿病、冠心病等慢性病史。否认肝炎、结核等传染病史。否认手术外伤史。否认食物药物过敏史。预防接种史随社会。","个人史及过敏史":"生于原籍，久居本地，无疫区疫水接触史，无特殊粉尘毒物放射性物质接触史。不吸烟，不饮酒。生活规律。否认食物药物过敏史。","体格检查":"T36.5℃，P78次/分，R18次/分，BP118/74mmHg。神志清楚，查体合作。妇科检查：阴道黏膜充血，无异常；分泌物呈黏液脓性、量多，无脓性及异味加重；宫颈充血、水肿，宫颈口可见黏液脓性分泌物，宫颈外口呈糜烂样外观，无息肉；宫颈举痛（-）；双附件无压痛。","辅助检查":"【必做】宫颈分泌物涂片（白细胞，提示炎症）、淋球菌及沙眼衣原体核酸检测（宫颈炎主要病原，为性传播感染筛查）、白带常规；【筛查】宫颈细胞学检查（TCT）及HPV检测（宫颈炎与宫颈癌前病变鉴别，有接触性出血者必查）；【其他】宫颈活检（TCT或HPV异常时行阴道镜）。","初步诊断":"1. 宫颈炎（急性，病原待查）\n（注：急性宫颈炎经验性治疗覆盖淋球菌及衣原体：头孢曲松1g肌注单剂+多西环素100mg bid×7天（或阿奇霉素1g单剂），性伴侣同治，治疗期间禁性生活；病原学明确者针对性治疗；慢性宫颈炎（糜烂样外观）无症状者无需治疗（多为生理性柱状上皮异位，定期宫颈癌筛查即可）；白带多或接触性出血明显可物理治疗（激光或冷冻，排除恶变后）；无论有无症状，有性生活女性定期TCT+HPV筛查。）","处理方案":"【药物治疗】\n1. 针对沙眼衣原体感染：多西环素片100mg bid×14天；或阿奇霉素片0.5g qd×3天。\n2. 针对淋病奈瑟菌感染：头孢曲松钠1g 单次肌注；或头孢克肟胶囊400mg 单次口服。\n3. 合并滴虫或细菌性阴道病：甲硝唑片0.4g bid×7天；或甲硝唑栓0.5g qn阴道置入×7天。\n4. 局部辅助治疗：保妇康栓1粒 qn阴道置入，连用7-10天，促进宫颈炎症消退。\n\n【一般治疗及生活指导】\n1. 治疗期间禁止性生活和盆浴，避免交叉感染及上行感染；性伴侣应同时检查并治疗。\n2. 注意休息，避免劳累及剧烈运动，保证充足睡眠，增强机体抵抗力。\n3. 保持外阴清洁干燥，穿宽松棉质内裤并勤更换，避免使用刺激性洗液过度冲洗阴道。\n4. 清淡饮食，忌辛辣刺激及生冷油腻食物，戒烟限酒，多饮水。\n\n【随诊要求】\n1. 治疗后2周复诊，复查妇科检查及宫颈分泌物病原学检查，评估疗效。\n2. 治疗结束后3个月复查沙眼衣原体、淋球菌等病原体转阴情况，确认病原学治愈。\n3. 若出现发热、下腹痛加重、阴道脓性分泌物增多或接触性出血，随时就诊。\n4. 慢性宫颈炎行物理治疗后1-2个月复查宫颈创面愈合情况；治疗后宫颈细胞学检查异常者遵医嘱定期随访TCT/HPV。"},"icd10_diagnosis":"","icd10_secondary":[],"icd9cm3_procedure":[]}},"locator":{"file":"门诊住院病历模板/病历模板包_全部_20261111.json","arrayRow":381,"caseRow":1},"sourceHash":"10e4fdb435986b7b85f847c3951d0cb0eafdce0f372c5617949c05b337149194","contentHash":"9954d8df42cad817de980901f781edf8c4cff9ff1cf90440882dc1bd7acc5224","pinyin":"gongjingyan","initials":"gjy","setting":"out","caseName":"门诊病历246","templateNames":["主诉","现病史","既往史","个人史及过敏史","体格检查","辅助检查","初步诊断","处理方案"],"emptyTemplates":[],"escapedNewlines":[],"quickFields":[["病例名称","门诊病历246",60],["模板名称","主诉 现病史 既往史 个人史及过敏史 体格检查 辅助检查 初步诊断 处理方案",30],["主要诊断编码","",30]]},{"id":"templates-b11abfb954e7c30e63a4","key":"v1-c9ccc21dfe2a3058|templates-b11abfb954e7c30e63a4","module":"templates","moduleKey":"v1-c9ccc21dfe2a3058|templates","version":"v1-c9ccc21dfe2a3058","title":"乳腺增生","category":"门诊病历模板","raw":{"name":"乳腺增生","category":"门诊病历模板","case":{"case_name":"门诊病历247","templates":{"主诉":"乳房胀痛伴肿块感反复发作8月，经前加重。","现病史":"患者于8月前开始经前双乳胀痛、触痛，经后缓解，周期性明显，乳房可触及片状及结节状增厚，无乳头溢液，肿块无固定，无新发肿块，近期有情志波动、熬夜、压力大等诱因。月经规律，已婚已育，初产年龄28岁，哺乳10个月，无乳腺癌家族史。今日来我院门诊就诊。","既往史":"既往体健，否认高血压、糖尿病、冠心病等慢性病史。否认肝炎、结核等传染病史。否认手术外伤史。否认食物药物过敏史。预防接种史随社会。","个人史及过敏史":"生于原籍，久居本地，无疫区疫水接触史，无特殊粉尘毒物放射性物质接触史。不吸烟，不饮酒。生活规律。否认食物药物过敏史。","体格检查":"T36.5℃，P76次/分，R18次/分，BP118/74mmHg。神志清楚，查体合作。双乳对称，皮肤无橘皮样改变及酒窝征，乳头无内陷及溢液，双乳外上象限可触及片状增厚及结节状腺体，质韧，边界不清，轻压痛，与皮肤无粘连，腋窝淋巴结未触及肿大。","辅助检查":"【必做】乳腺超声（首选，适用于＜40岁或致密腺体者：观察乳腺结构、有无肿块及BI-RADS分级）；【影像学】乳腺X线钼靶（≥40岁或超声可疑者，用于钙化及早期癌筛查）；【其他】细针或空心针穿刺活检（BI-RADS≥4类肿块，病理确诊）、性激素（内分泌紊乱评估）。","初步诊断":"1. 乳腺增生症（乳腺囊性增生病）\n（注：多数为良性生理性改变：调整生活方式（规律作息、情绪疏导、低脂饮食、合适内衣）、定期自查（月经后1周）；症状明显（胀痛影响生活）者可口服（中成药逍遥丸或乳癖消、维生素E、他莫昔芬（短期慎用））；最重要的是与乳腺癌鉴别：新发肿块、固定不活动、质硬边界不清、腋窝淋巴结肿大、乳头溢液（血性）均需进一步检查（穿刺活检）；BI-RADS 3类6个月复查，4类及以上活检；有家族史或高危者每年钼靶+超声筛查。）","处理方案":"【药物治疗】\n1. 中成药调节内分泌：乳癖散结胶囊 4粒 tid，月经来潮后第14天开始服用，连服14天为一疗程，连用2-3个疗程；或乳癖消片 5-6片 tid，连服4周。\n2. 维生素辅助治疗：维生素E软胶囊 0.1g bid，维生素B6片 20mg tid，连用4-8周。\n3. 疼痛明显或症状较重者：枸橼酸他莫昔芬片 10mg bid，于月经第5天开始服用，连用10-15天，疼痛缓解后即停药，不宜长期服用（用药前评估血栓及子宫内膜风险，短期使用）。\n4. 疼痛剧烈影响生活者：布洛芬缓释胶囊 0.3g bid，疼痛缓解后停用，连用不超过5天。\n\n【一般治疗及生活指导】\n1. 规律作息，保证充足睡眠，避免熬夜、劳累；保持情绪稳定，避免精神紧张、焦虑及抑郁，学会自我减压。\n2. 饮食宜清淡、低脂、高纤维，多食新鲜蔬菜、水果及豆制品，忌辛辣刺激、油炸、高糖食物，避免咖啡、浓茶、酒精及含雌激素的保健品（如蜂王浆、雪蛤、胎盘制剂等）。\n3. 佩戴大小合适、支撑良好的文胸，避免过紧或过松；坚持适度有氧运动（如快走、游泳、瑜伽），控制体重于正常范围。\n4. 避免长期使用含雌激素类药物或化妆品，育龄期女性合理选用避孕方式，减少外源性雌激素摄入。\n\n【随诊要求】\n1. 服药2周后复诊，评估乳房胀痛及肿块改善情况，由医师调整治疗方案。\n2. 每月于月经干净后7-10天进行乳房自查（视诊及触诊），发现异常及时就诊。\n3. 每年行乳腺超声检查1次；年龄≥40岁者每年加做乳腺X线（钼靶）检查，必要时行乳腺MRI。\n4. 若出现乳房肿块进行性增大、质地变硬、固定不移，或出现乳头溢液（尤其血性）、乳房皮肤凹陷（\"酒窝征\"）或橘皮样改变，或药物治疗4-8周后症状无缓解，应立即复诊行进一步检查（必要时穿刺活检）。"},"icd10_diagnosis":"","icd10_secondary":[],"icd9cm3_procedure":[]}},"locator":{"file":"门诊住院病历模板/病历模板包_全部_20261111.json","arrayRow":382,"caseRow":1},"sourceHash":"10e4fdb435986b7b85f847c3951d0cb0eafdce0f372c5617949c05b337149194","contentHash":"b0fa652b61287fccd8166021858edaf1a969afcfb505bb518f2eafae5fb0d6f9","pinyin":"ruxianzengsheng","initials":"rxzs","setting":"out","caseName":"门诊病历247","templateNames":["主诉","现病史","既往史","个人史及过敏史","体格检查","辅助检查","初步诊断","处理方案"],"emptyTemplates":[],"escapedNewlines":[],"quickFields":[["病例名称","门诊病历247",60],["模板名称","主诉 现病史 既往史 个人史及过敏史 体格检查 辅助检查 初步诊断 处理方案",30],["主要诊断编码","",30]]},{"id":"templates-8bd267c4d356577d07c9","key":"v1-c9ccc21dfe2a3058|templates-8bd267c4d356577d07c9","module":"templates","moduleKey":"v1-c9ccc21dfe2a3058|templates","version":"v1-c9ccc21dfe2a3058","title":"乳腺炎","category":"门诊病历模板","raw":{"name":"乳腺炎","category":"门诊病历模板","case":{"case_name":"门诊病历248","templates":{"主诉":"乳房红肿热痛伴发热3天（哺乳期）。","现病史":"患者（哺乳期：产后4周）于3天前出现右乳房胀痛，局部红肿、皮温升高、触痛，可及硬块，伴发热（体温最高38.8℃）、畏寒、乏力，有乳汁排出不畅及乳头皲裂（哺乳期常见诱因），无乳头溢液（不支持非哺乳期浆细胞性乳腺炎等），无咳嗽。今日来我院门诊就诊。","既往史":"既往体健，否认高血压、糖尿病、冠心病等慢性病史。否认肝炎、结核等传染病史。否认手术外伤史。否认食物药物过敏史。预防接种史随社会。","个人史及过敏史":"生于原籍，久居本地，无疫区疫水接触史，无特殊粉尘毒物放射性物质接触史。不吸烟，不饮酒。生活规律。否认食物药物过敏史。","体格检查":"T38.6℃，P96次/分，R20次/分，BP118/74mmHg。神志清楚，急性热病容。右乳外上象限皮肤红肿、皮温升高，可触及4cm大小硬块，无波动感（脓肿尚未形成），局部压痛明显，乳头皲裂，挤压无溢脓，同侧腋窝淋巴结肿大压痛。","辅助检查":"检查计划：患者哺乳期（产后4周）右乳红肿热痛伴发热3天、体温最高38.8℃，需明确感染程度与病原，门诊即刻完善血常规检查，了解白细胞及中性粒细胞计数是否升高以评估细菌感染及炎症反应程度；查CRP评估炎症活动度与感染严重程度，并作为抗感染治疗疗效的动态随访指标；患者右乳可及硬块、有乳汁排出不畅及乳头皲裂，完善乳腺超声检查明确炎症累及范围、有无脓肿形成及脓腔位置与大小，为穿刺抽脓或切开引流提供脓腔定位，并与炎性乳腺癌相鉴别；因患者为哺乳期急性乳腺炎，超声同时评估乳汁淤积程度，指导排空乳汁与哺乳方式调整；若超声证实脓肿形成，行脓肿穿刺后完善脓液细菌培养+药敏（药物敏感试验），明确致病菌（以金黄色葡萄球菌常见）并指导抗生素精准选择，疗程依培养结果调整；同时完善乳汁培养，鉴别致病菌来源，指导是否可继续患侧哺乳；患者发热伴畏寒、乏力，因无糖尿病、高血压等基础病，查血糖了解糖代谢状况，明确有无隐匿性血糖异常影响感染控制与创口愈合；抗感染治疗中若炎症控制不佳、肿块不消或出现皮肤橘皮样改变、边界不清且进展快，需复查乳腺超声并完善钼靶或粗针穿刺活检以排除炎性乳腺癌。\n\n（检查清单）\n【必做】血常规（白细胞及中性粒细胞升高）、CRP；【影像学】乳腺超声（炎症范围、有无脓肿形成，用于脓腔定位）；【其他】脓液细菌培养+药敏（脓肿穿刺后）、乳汁培养。","初步诊断":"1. 急性乳腺炎（右，哺乳期）\n（注：哺乳期乳腺炎治疗：①排空乳汁是关键，继续哺乳（患侧先喂，哺乳前热敷或按摩）或用吸奶器排空，不可断奶；②抗感染：青霉素类（阿莫西林克拉维酸0.625g tid）或头孢类，疗程10~14天（依脓液培养调整）；③镇痛（布洛芬）；局部热敷；脓肿形成（波动感或超声证实）者行穿刺抽脓或切开引流；非哺乳期乳腺炎（浆细胞性或肉芽肿性）需专科处理（抗炎、部分需手术）；炎症控制不佳、肿块不消需排除炎性乳腺癌（皮肤橘皮样、边界不清、进展快）。）","处理方案":"【药物治疗】\n1. 抗感染：阿莫西林克拉维酸钾片 0.625g po tid×5~7天（青霉素过敏者选用头孢呋辛酯片 0.25g po bid×5~7天）；体温>38.5℃伴畏寒者首选静脉抗感染治疗，待退热后改口服。\n2. 对症止痛：布洛芬缓释胶囊 0.3g po bid×3~5天（哺乳期可用，可缓解疼痛并减轻炎症反应，不影响哺乳）。\n3. 退热（如发热）：对乙酰氨基酚片 0.5g po 必要时，每6~8小时1次，24小时不超过2g。\n【一般治疗及生活指导】\n1. 坚持哺乳或按时排空患侧乳汁：哺乳或吸奶器排空是治疗核心措施，哺乳前排空乳房、哺乳时先喂患侧，避免乳汁淤积；避免因疼痛停止哺乳。\n2. 充分休息，保证睡眠，多饮水，进食高蛋白、易消化饮食，保持情绪稳定。\n3. 局部处理：哺乳后予患侧乳房冷敷10~15分钟缓解疼痛、减轻水肿；忌热敷、忌暴力按摩推挤硬块，以免炎症扩散。\n4. 注意乳头卫生，哺乳前后清洗乳头，纠正乳头皲裂及含接不当；穿戴宽松、支撑性好的哺乳内衣。\n【随诊要求】\n1. 治疗3天后症状（疼痛、红肿、发热）无明显缓解或加重，需复诊调整方案。\n2. 若出现高热持续不退、局部皮肤波动感或穿刺抽出脓液，提示脓肿形成，需立即就诊行脓肿切开引流。\n3. 症状缓解后复查至肿块消退；反复发作或非哺乳期乳腺炎（肉芽肿性乳腺炎可能）者，建议乳腺外科专科门诊进一步检查（乳腺彩超、必要时活检）。"},"icd10_diagnosis":"","icd10_secondary":[],"icd9cm3_procedure":[]}},"locator":{"file":"门诊住院病历模板/病历模板包_全部_20261111.json","arrayRow":383,"caseRow":1},"sourceHash":"10e4fdb435986b7b85f847c3951d0cb0eafdce0f372c5617949c05b337149194","contentHash":"42ebbf1d152536d7edd578716345d7915ec4e24b5ee0fcedd0e2ce5ea3fe6604","pinyin":"ruxianyan","initials":"rxy","setting":"out","caseName":"门诊病历248","templateNames":["主诉","现病史","既往史","个人史及过敏史","体格检查","辅助检查","初步诊断","处理方案"],"emptyTemplates":[],"escapedNewlines":[],"quickFields":[["病例名称","门诊病历248",60],["模板名称","主诉 现病史 既往史 个人史及过敏史 体格检查 辅助检查 初步诊断 处理方案",30],["主要诊断编码","",30]]},{"id":"templates-7afc06f41c13a9113d1e","key":"v1-c9ccc21dfe2a3058|templates-7afc06f41c13a9113d1e","module":"templates","moduleKey":"v1-c9ccc21dfe2a3058|templates","version":"v1-c9ccc21dfe2a3058","title":"小儿厌食","category":"门诊病历模板","raw":{"name":"小儿厌食","category":"门诊病历模板","case":{"case_name":"门诊病历249","templates":{"主诉":"患儿食欲减退、进食量少6月，伴体重增长缓慢。","现病史":"患儿于6月前开始食欲减退，每餐进食量明显减少，进餐时间长、含饭不咽，偏食挑食，无恶心呕吐，无腹胀、腹痛，无便秘或腹泻，无异食癖等微量元素缺乏表现，有喂养不当、零食过多及强迫进食等精神因素，无发热、咳嗽等感染表现，大便正常，每日1次。生长发育（身高、体重百分位）：身高位于第25百分位，体重位于第10百分位。今日来我院门诊就诊。","既往史":"既往体健，否认高血压、糖尿病、冠心病等慢性病史。否认肝炎、结核等传染病史。否认手术外伤史。否认食物药物过敏史。预防接种史随社会。","个人史及过敏史":"患儿系第1胎第1产，足月顺产，出生体重3.2kg，无窒息抢救史。母乳喂养，按时添加辅食，预防接种按国家计划进行。生长发育同同龄儿童。","体格检查":"T36.5℃，P110次/分，R24次/分，体重12.5kg（百分位第10）。神志清，精神可、无欠佳，营养状况欠佳、略显消瘦，皮肤黏膜无苍白（无贫血貌），心肺听诊未见明显异常，腹平软，无压痛，肝脾未触及。","辅助检查":"【必做】一般评估为主；【其他】血常规（贫血筛查）、微量元素（锌、铁等，缺乏可致味觉减退、食欲下降）、肝功能、骨密度（维生素D）。","初步诊断":"1. 小儿厌食\n（注：行为与喂养指导为主：定时定量进餐（每餐20~30分钟）、正餐前不吃零食饮料、鼓励自主进食、营造轻松进餐氛围（避免强迫、追喂）、多样化辅食、保证适当活动量；补充锌（葡萄糖酸锌）及复合维生素（缺乏者）；中药调理（醒脾养儿颗粒，脾虚者）；排除并治疗原发病（贫血、感染、便秘等）；监测体重增长，连续不增或下降需进一步检查（内分泌、消化等），转儿童保健科随访。）","处理方案":"【药物治疗】\n1. 锌剂补充：葡萄糖酸锌口服液（10ml:35mg），一次10ml，每日2次，餐后服用，连用2～4周（锌缺乏是小儿厌食的常见病因，补锌可促进味觉恢复、增进食欲）。\n2. 调节肠道菌群：双歧杆菌三联活菌散，一次1g，每日3次，用低于40℃温开水冲服，连用1～2周，改善肠道微生态。\n3. 健脾消食中成药：健胃消食口服液，一次10ml，每日3次，餐前半小时服用，连用2周；或醒脾养儿颗粒，一次1袋（2g），每日2次，餐前冲服。\n4. 促消化酶类：复方胃蛋白酶散（或多酶片），一次1包，每日3次，餐后温水送服，连用1～2周，助消化、缓解腹胀。\n\n【一般治疗及生活指导】\n1. 饮食调护：定时定量进餐，少量多餐，食物多样化、注重色香味及软烂度，主食与蔬果、肉蛋合理搭配；正餐前1小时避免进食零食、糖果及含糖饮料，两餐间可少量饮水。\n2. 活动与作息：保证充足睡眠，每日户外活动1～2小时（如散步、游戏），适度运动可促进胃肠蠕动、增进食欲。\n3. 心理与进食习惯：营造轻松愉快的进餐氛围，不在餐桌上训斥、强迫或哄喂孩子，鼓励自主进食，纠正边吃边玩、追喂等不良习惯。\n4. 禁忌：忌生冷、油炸、肥甘厚腻及辛辣刺激性食物，忌暴饮暴食，忌饭前吃甜食、冷饮。\n\n【随诊要求】\n用药2周后复诊评估食欲及进食量改善情况；若食欲持续无改善、体重不增或下降，或伴腹胀、腹痛、呕吐、腹泻等不适，应及时复诊，必要时行微量元素（锌、铁）、血常规、甲状腺功能等检查以明确病因；治疗期间注意观察有无药物不良反应。"},"icd10_diagnosis":"","icd10_secondary":[],"icd9cm3_procedure":[]}},"locator":{"file":"门诊住院病历模板/病历模板包_全部_20261111.json","arrayRow":384,"caseRow":1},"sourceHash":"10e4fdb435986b7b85f847c3951d0cb0eafdce0f372c5617949c05b337149194","contentHash":"7bdc6a7e133574dd758c6f46e2eeaebc1771f0694f774621672a30fb87c743b8","pinyin":"xiaoeryanshi","initials":"xeys","setting":"out","caseName":"门诊病历249","templateNames":["主诉","现病史","既往史","个人史及过敏史","体格检查","辅助检查","初步诊断","处理方案"],"emptyTemplates":[],"escapedNewlines":[],"quickFields":[["病例名称","门诊病历249",60],["模板名称","主诉 现病史 既往史 个人史及过敏史 体格检查 辅助检查 初步诊断 处理方案",30],["主要诊断编码","",30]]},{"id":"templates-6dfcfbcdda637385e25a","key":"v1-c9ccc21dfe2a3058|templates-6dfcfbcdda637385e25a","module":"templates","moduleKey":"v1-c9ccc21dfe2a3058|templates","version":"v1-c9ccc21dfe2a3058","title":"小儿遗尿","category":"门诊病历模板","raw":{"name":"小儿遗尿","category":"门诊病历模板","case":{"case_name":"门诊病历250","templates":{"主诉":"夜间睡眠中不自主排尿6月","现病史":"患儿（年龄7岁，＞5岁）自3岁起夜间睡眠中不自主排尿，每周约5晚、每夜2次，白天排尿正常，无尿频尿急尿痛，无多饮多尿，无便秘、白天遗尿、排尿困难，可能合并膀胱功能异常，父母有无类似病史（家族性遗尿）：无，既往是否治疗过（药物/报警器）及效果：未治疗。今日来我院门诊就诊。","既往史":"既往体健，否认高血压、糖尿病、冠心病等慢性病史。否认肝炎、结核等传染病史。否认手术外伤史。否认食物药物过敏史。预防接种史随社会。","个人史及过敏史":"患儿系第1胎第1产，足月顺产，出生体重3.2kg，无窒息抢救史。母乳喂养，按时添加辅食，预防接种按国家计划进行。生长发育同同龄儿童。","体格检查":"T36.8℃，P90次/分，R20次/分。神志清，查体合作，精神智力发育正常。外生殖器检查：无异常，脊柱无异常（无脊膜膨出等，隐性脊柱裂查体），肛周及会阴感觉、运动正常。","辅助检查":"【必做】尿常规（排除尿路感染、糖尿病，查尿糖）、泌尿系超声（排除器质性病变：后尿道瓣膜（男）、神经源性膀胱）；【其他】腰骶椎X线（疑隐性脊柱裂）、尿动力学检查（白天症状或治疗无效时）。","初步诊断":"1. 原发性夜间遗尿症\n（注：基础治疗：行为治疗（睡前2小时限水、睡前排尿、夜间定时唤醒排尿，膀胱功能训练）、奖励机制（不责骂，心理支持很重要）；一线药物（6岁以上、行为治疗3个月无效）：醋酸去氨加压素（弥凝）0.2mg qn（睡前1小时，减少夜间尿量，起效快，需限水防低钠血症）或盐酸丙米嗪（三环类，12.5~25mg qn）；遗尿报警器（条件反射训练，疗效好复发少，需坚持2~3个月）；便秘者通便；多数有自愈倾向（年自愈率约15%），治疗至连续6个月无遗尿后渐停药，转儿童保健/泌尿专科随访。）","处理方案":"【药物治疗】\n1.去氨加压素（弥凝）片0.1～0.2mg，睡前1小时口服，服前1小时至服药后8小时内限饮，疗程3个月，见效后逐步减量、缓慢停药，避免反跳复发。\n2.奥昔布宁（尿多灵）片2.5～5mg，睡前口服，每日1～2次，适用于合并日间尿频、尿急等膀胱过度活动症表现者，疗程4～8周。\n3.盐酸丙咪嗪12.5～25mg，睡前顿服，为二线用药，适用于一线治疗无效者，用药前及用药期间监测心电图。\n【一般治疗及生活指导】\n1.睡前2小时限水及含水丰富食物（水果、汤类），睡前排空膀胱；白天规律排尿，每2～3小时1次，避免憋尿。\n2.夜间可设置闹钟定时唤醒排尿或使用遗尿报警器，建立膀胱充盈觉醒反射；保证充足睡眠，白天避免过度疲劳。\n3.心理疏导，家长勿斥责、讥讽患儿，鼓励其建立信心，做好床褥护理，记录遗尿日记。\n4.禁忌：睡前避免咖啡、茶、可乐等含咖啡因饮料及过咸、辛辣食物；睡前避免剧烈活动和情绪激动。\n【随诊要求】\n用药后2～4周复诊，评估疗效及不良反应（如低钠血症、口干、便秘、情绪改变），据情调整剂量；疗程结束复查评估疗效并指导停药。若遗尿持续至6岁以上、伴白天尿失禁、尿痛或排尿困难，或常规治疗效果欠佳，及时复诊，完善尿常规、泌尿系超声及尿动力学等检查。"},"icd10_diagnosis":"","icd10_secondary":[],"icd9cm3_procedure":[]}},"locator":{"file":"门诊住院病历模板/病历模板包_全部_20261111.json","arrayRow":385,"caseRow":1},"sourceHash":"10e4fdb435986b7b85f847c3951d0cb0eafdce0f372c5617949c05b337149194","contentHash":"64e6f59d4cb7f43a849336aa9ca34778b0603410652001e3f696489d74a86ed8","pinyin":"xiaoeryiniao","initials":"xeyn","setting":"out","caseName":"门诊病历250","templateNames":["主诉","现病史","既往史","个人史及过敏史","体格检查","辅助检查","初步诊断","处理方案"],"emptyTemplates":[],"escapedNewlines":[],"quickFields":[["病例名称","门诊病历250",60],["模板名称","主诉 现病史 既往史 个人史及过敏史 体格检查 辅助检查 初步诊断 处理方案",30],["主要诊断编码","",30]]},{"id":"templates-eb3eeb81398591f66aa7","key":"v1-c9ccc21dfe2a3058|templates-eb3eeb81398591f66aa7","module":"templates","moduleKey":"v1-c9ccc21dfe2a3058|templates","version":"v1-c9ccc21dfe2a3058","title":"小儿多动症","category":"门诊病历模板","raw":{"name":"小儿多动症","category":"门诊病历模板","case":{"case_name":"门诊病历251","templates":{"主诉":"注意力不集中、多动伴冲动6个月","现病史":"患儿（年龄8岁，起病于7岁前）于6岁开始出现注意力不集中（上课/作业时走神、粗心错误多、丢三落四、听而不闻）、活动过多（坐不住、小动作多、上课离座、奔跑攀爬）、冲动（插话、抢答、难以等待、情绪冲动），症状在学校、家庭两个及以上场合均存在，持续超过6个月，影响学习成绩及同伴关系，无智力低下（智力正常），无抽动、睡眠障碍、学习困难（读写计算），共病评估。有无出生窒息史及家族史（父母多动/酒精依赖等）：无。今日来我院门诊就诊。","既往史":"既往体健，否认高血压、糖尿病、冠心病等慢性病史。否认肝炎、结核等传染病史。否认手术外伤史。否认食物药物过敏史。预防接种史随社会。","个人史及过敏史":"患儿系第1胎第1产，足月顺产，出生体重3.2kg，无窒息抢救史。母乳喂养，按时添加辅食，预防接种按国家计划进行。生长发育同同龄儿童。","体格检查":"T36.8℃，P90次/分，R20次/分。神志清，查体合作，发育营养正常，心肺腹未见异常，神经系统检查无阳性体征（排除神经系统疾病，软化灶等）。","辅助检查":"【必做】临床评估为主：诊断量表（SNAP-IV或Conners量表，父母及教师评定）、智力测验（排除智力障碍）、发育评估；【其他】脑电图（排除癫痫，发作性事件鉴别）、头颅MRI（神经系统体征异常时）。","初步诊断":"1. 注意缺陷多动障碍（混合型：注意缺陷为主型/多动冲动为主型/混合型）\n（注：综合干预：①行为治疗与家长培训（强化正性行为、建立规律作息及规则、减少屏幕时间）；②学校支持（调整座位等）；③药物治疗（6岁以上、中重度）：一线中枢兴奋剂哌甲酯缓释片（专注达18mg qd起始，渐增量，晨服，监测食欲、睡眠、生长）、非兴奋剂托莫西汀（0.8~1.2mg/kg/d，分2次）；④共病（抽动、焦虑、学习困难）分别处理；药物治疗期间定期（每3个月）复评身高体重及症状，转儿童精神/保健专科长期随访，青春期后部分缓解。）","处理方案":"【药物治疗】\n1. 中枢兴奋剂（一线首选）：盐酸哌甲酯缓释片（专注达）18mg qd，每日晨起餐后口服1次，连用4周，疗效不足可每1-2周递增18mg，最大量：体重≤54kg者54mg/d，>54kg者72mg/d；或用哌甲酯普通片（利他林）5mg bid（晨起及午前各1次，下午4时后禁服），可逐周递增至10mg bid，疗程≥6个月。\n2. 非中枢兴奋剂（兴奋剂无效、不耐受或合并抽动障碍者选用）：盐酸托莫西汀胶囊（择思达）起始剂量10mg qd，1周后按体重调整：体重<70kg者0.8-1.2mg/kg/d（最大1.4mg/kg/d），体重≥70kg者最大100mg/d，分早晚2次服用，疗程≥6个月。\n3. 用药原则：小剂量起始、个体化缓慢滴定，见效后维持最低有效剂量，不可骤然停药（需逐渐减量）；服药期间监测食欲、睡眠、心率、血压及体重增长，出现失眠、食欲明显下降、心悸或抽动加重时减量或换药。\n\n【一般治疗及生活指导】\n1. 行为治疗与家长培训：采用正性强化、代币奖励、忽根据患者具体情况制定个体化方案不良行为等行为干预，家长与老师保持统一管教原则，避免打骂、责备，多鼓励表扬。\n2. 规律作息与睡眠：固定就寝与起床时间，保证每晚9-10小时睡眠，睡前1小时避免看电视、手机等屏幕刺激及剧烈活动。\n3. 饮食与活动：均衡饮食，减少高糖食品、含咖啡因饮料（可乐、浓茶、巧克力）及零食；每天保证至少1小时户外活动（跳绳、游泳、球类等），助其释放过剩精力；学习环境保持安静，作业分段完成（每段20-30分钟，中间休息）。\n4. 禁忌：禁止自行服用镇静安眠类及含咖啡因的复方感冒药物；避免长时间看电视、玩电子游戏（每日≤1小时）；不饮用功能性饮料。\n\n【随诊要求】\n1. 首次用药后2-4周复诊，评估疗效与不良反应并调整剂量；稳定后每1-3个月复诊1次，每次测量身高、体重、血压、心率，询问食欲、睡眠及情绪变化。\n2. 长期服药者每半年复查血常规、肝肾功能、心电图；学龄儿童每学期末与班主任沟通，评估课堂注意力、作业完成及学习成绩改善情况。\n3. 出现严重失眠、食欲明显减退、心悸、抽动加重或情绪低落、攻击行为时，应提前复诊调整治疗方案，不得擅自停药。"},"icd10_diagnosis":"","icd10_secondary":[],"icd9cm3_procedure":[]}},"locator":{"file":"门诊住院病历模板/病历模板包_全部_20261111.json","arrayRow":386,"caseRow":1},"sourceHash":"10e4fdb435986b7b85f847c3951d0cb0eafdce0f372c5617949c05b337149194","contentHash":"0fd1dc2185f4877e7a8660279950c5d96959f51255abc1494939b3f81c03b08d","pinyin":"xiaoerduodongzheng","initials":"xeddz","setting":"out","caseName":"门诊病历251","templateNames":["主诉","现病史","既往史","个人史及过敏史","体格检查","辅助检查","初步诊断","处理方案"],"emptyTemplates":[],"escapedNewlines":[],"quickFields":[["病例名称","门诊病历251",60],["模板名称","主诉 现病史 既往史 个人史及过敏史 体格检查 辅助检查 初步诊断 处理方案",30],["主要诊断编码","",30]]},{"id":"templates-02fb0abaa201a2691383","key":"v1-c9ccc21dfe2a3058|templates-02fb0abaa201a2691383","module":"templates","moduleKey":"v1-c9ccc21dfe2a3058|templates","version":"v1-c9ccc21dfe2a3058","title":"小儿湿疹","category":"门诊病历模板","raw":{"name":"小儿湿疹","category":"门诊病历模板","case":{"case_name":"门诊病历252","templates":{"主诉":"反复皮肤红斑、丘疹伴瘙痒6月","现病史":"患儿自婴儿期反复出现皮肤干燥、红斑、丘疹，好发于面颊、额部、头皮（婴儿：面颊额部头皮；儿童：肘窝腘窝颈部），伴剧烈瘙痒、搔抓、渗液结痂，时轻时重（冬重夏轻），无食物或环境过敏诱因、皮肤感染、睡眠影响，家族中有无过敏史（湿疹、哮喘、过敏性鼻炎，特应性体质）：有过敏性鼻炎史。今日来我院门诊就诊。","既往史":"既往体健，否认高血压、糖尿病、冠心病等慢性病史。否认肝炎、结核等传染病史。否认手术外伤史。否认食物药物过敏史。预防接种史随社会。","个人史及过敏史":"生于原籍，久居本地，无疫区疫水接触史，无特殊粉尘毒物放射性物质接触史。无吸烟、饮酒史，家庭无二手烟暴露。生活规律。否认食物药物过敏史。","体格检查":"T36.8℃，P90次/分，R20次/分。神志清，精神可。面颊可见红斑、丘疹、抓痕、渗液结痂（急性期）/皮肤增厚苔藓样变（慢性期）/干燥脱屑，皮肤干燥（+），无继发感染（脓疱、淋巴结肿大）。","辅助检查":"检查计划：患儿自婴儿期起反复出现面颊、额部、头皮皮肤干燥、红斑、丘疹伴剧烈瘙痒、搔抓渗液结痂，冬重夏轻，结合好发部位与家族过敏性鼻炎史，特应性皮炎（小儿湿疹）以一般临床诊断为主，依据病史、皮损形态与分布即可明确诊断，无需常规实验室检查；患儿有过敏性鼻炎等特应性体质表现，若常规保湿与外用糖皮质激素治疗后仍反复不愈，可完善过敏原检测，包括血清总IgE及特异性IgE（食物或吸入过敏原筛查），了解致敏原种类，指导环境规避与饮食管理，但该项不作为常规一线检查；患儿皮损有搔抓、渗液结痂，若出现脓性分泌物、局部红肿加重或伴发热，需完善皮肤细菌培养加药物敏感试验，明确是否继发感染（金黄色葡萄球菌感染），指导莫匹罗星或系统抗生素的选用；因患儿年龄小、皮疹泛发且瘙痒明显，必要时查血常规了解嗜酸性粒细胞计数及有无感染征象，评估炎症与过敏状态，为抗组胺药及外用药阶梯治疗提供参考；长期中重度反复发作、需系统免疫抑制剂或生物制剂治疗者，治疗前完善肝肾功能、血常规及结核感染筛查（如PPD或T-SPOT、胸部X线片），评估用药安全性并指导随访监测。\n\n（检查清单）\n【必做】一般临床诊断为主；【其他】过敏原检测（IgE及特异性IgE，食物或吸入过敏筛查，不作为常规一线）、皮肤细菌培养（疑继发感染时）。","初步诊断":"1. 特应性皮炎（小儿湿疹，亚急性：急性/亚急性/慢性）\n（注：基础护理为基石：保湿（足量润肤霜每日至少2次，沐浴后3分钟内）、温水沐浴（<10分钟）、避免刺激（过热、化纤、毛织品、香料）；药物治疗按阶梯：外用糖皮质激素（急性期：丁酸氢化可的松乳膏或糠酸莫米松，短期规范使用不恐惧；面部及皱褶用弱效）、钙调磷酸酶抑制剂（他克莫司或吡美莫司，面部及激素依赖部位）；瘙痒明显口服抗组胺药（西替利嗪滴剂或氯雷他定）；继发细菌感染用莫匹罗星或抗生素；中重度反复：光疗、系统免疫抑制剂（环孢素，专科）或生物制剂（度普利尤单抗）；管理搔抓（剪指甲）、避免明确过敏食物。）","处理方案":"【药物治疗】\n1. 丁酸氢化可的松乳膏（尤卓尔）1%：外用，每日2次，涂于患处，轻中度皮损连用3～5天，症状缓解后减为每日1次或隔日1次，同一部位连续使用不超过2周；面部、颈部及皮肤薄嫩处选用弱效制剂并缩短疗程。\n2. 西替利嗪滴剂：6个月～2岁每次2.5mg（约5滴），2～6岁每次5mg（约10滴），均为每日1次，连用7～14天，用于明显瘙痒影响睡眠者；或氯雷他定糖浆2～6岁每次5ml，每日1次。\n3. 保湿修复剂（如二甲硅油乳膏、医用凡士林或丝塔芙保湿霜）：全身涂抹，每日2次，洗澡后3分钟内立即足量使用，急性期后长期维持。\n4. 莫匹罗星软膏：皮损伴渗出、结痂或脓疱等继发细菌感染时外用，每日2～3次，连用5～7天。\n\n【一般治疗及生活指导】\n1. 皮肤护理：每日温水（37℃左右）洗浴5～10分钟，避免热水烫洗、肥皂及碱性洗涤剂；浴后3分钟内涂保湿剂，穿纯棉宽松衣物，避免羊毛、化纤织物直接接触皮肤。\n2. 饮食管理：母乳喂养者母亲忌辛辣刺激及海鲜、牛奶、鸡蛋、坚果等易致敏食物观察1～2周；添加辅食逐一少量尝试，每种观察3～5天，明确致敏食物后回避。\n3. 环境与起居：保持室温22～26℃、湿度50%～60%，避免过热、出汗及尘螨、宠物皮屑等刺激；勤剪指甲，夜间戴棉质手套，避免搔抓加重皮损。\n4. 禁忌：严禁使用强效糖皮质激素、偏方或刺激性药水（如酒精、紫药水）外涂；避免过度清洗和日光暴晒。\n\n【随诊要求】\n治疗3～5天复诊评估疗效与皮肤状况；若瘙痒加重、皮疹泛发、渗液增多，或出现发热、脓疱、红肿扩大等继发感染征象，应及时复诊。皮损控制后建议每2～4周随访1次，保湿治疗至少维持至症状缓解后4周，以防复发。"},"icd10_diagnosis":"","icd10_secondary":[],"icd9cm3_procedure":[]}},"locator":{"file":"门诊住院病历模板/病历模板包_全部_20261111.json","arrayRow":387,"caseRow":1},"sourceHash":"10e4fdb435986b7b85f847c3951d0cb0eafdce0f372c5617949c05b337149194","contentHash":"d7c2398dbd3a2249a94ccbdd675444a2328aaae8b84ff1554682d24775aeb84c","pinyin":"xiaoershizhen","initials":"xesz","setting":"out","caseName":"门诊病历252","templateNames":["主诉","现病史","既往史","个人史及过敏史","体格检查","辅助检查","初步诊断","处理方案"],"emptyTemplates":[],"escapedNewlines":[],"quickFields":[["病例名称","门诊病历252",60],["模板名称","主诉 现病史 既往史 个人史及过敏史 体格检查 辅助检查 初步诊断 处理方案",30],["主要诊断编码","",30]]},{"id":"templates-930323b22d0943a2ab14","key":"v1-c9ccc21dfe2a3058|templates-930323b22d0943a2ab14","module":"templates","moduleKey":"v1-c9ccc21dfe2a3058|templates","version":"v1-c9ccc21dfe2a3058","title":"小儿哮喘","category":"门诊病历模板","raw":{"name":"小儿哮喘","category":"门诊病历模板","case":{"case_name":"门诊病历253","templates":{"主诉":"反复喘息、咳嗽1年，加重3天","现病史":"患儿于4岁起反复发作喘息，多于上呼吸道感染或接触过敏原（尘螨、花粉、毛绒玩具）或运动或冷空气或情绪激动后发作，夜间及凌晨为著，伴咳嗽（常为干咳、运动后及夜间明显）、胸闷，呼气性呼吸困难，可闻及喘息声，自行缓解或经雾化/用药后缓解，4天前受凉后再发，夜间不能平卧，影响睡眠，精神食欲欠佳。家族过敏史（父母哮喘/湿疹/鼻炎）：有哮喘史，既往用药（吸入激素/孟鲁司特，长期控制用药情况）：布地奈德气雾剂吸入，孟鲁司特口服。今日来我院门诊就诊。","既往史":"既往体健，否认高血压、糖尿病、冠心病等慢性病史。否认肝炎、结核等传染病史。否认手术外伤史。否认食物药物过敏史。预防接种史随社会。","个人史及过敏史":"生于原籍，久居本地，无疫区疫水接触史，无特殊粉尘毒物放射性物质接触史。无吸烟、饮酒史，家庭无二手烟暴露。生活规律。否认食物药物过敏史。","体格检查":"T36.8℃，P100次/分，R24次/分（增快），SpO294%。神志清，精神可，可闻及喘息，呼吸稍促，无三凹征、鼻翼扇动、口唇发绀（重度征象），双肺可闻及呼气相哮鸣音，呼气相延长，心率100次/分。","辅助检查":"【必做】肺功能（>5~6岁可配合者：支气管舒张试验，FEV1改善≥12%支持哮喘）、呼出气一氧化氮（FeNO，气道嗜酸性炎症）、过敏原检测（皮肤点刺/血清IgE）；【影像学】胸部X线片（排除肺炎、异物、先天畸形）；【其他】支气管镜（异物吸入疑诊，婴幼儿难治性喘息）。","初步诊断":"1. 儿童哮喘（急性发作期轻度/缓解期）\n（注：急性发作：轻中度，吸入速效β2激动剂（沙丁胺醇气雾剂+储雾罐，每20分钟2喷×1小时）+口服激素（泼尼松1~2mg/kg/d×3~5天）；重度（说话困难、SpO2<92%、三凹征），急诊：吸氧、雾化沙丁胺醇+异丙托溴铵、全身激素、必要时无创通气；缓解期长期控制（ICS吸入糖皮质激素（布地奈德气雾剂/雾化）为基础，按GINA阶梯方案、白三烯受体拮抗剂（孟鲁司特4~5mg qn，<6岁首选口服/过敏性鼻炎并哮喘）、LABA（≥6岁，ICS控制不佳时联合）；规避过敏原及烟草、接种疫苗（流感）、哮喘行动计划书、定期复评（每3个月）控制水平调整方案；多数儿童哮喘预后好（青春期部分缓解）。）","处理方案":"【药物治疗】\n1.吸入性糖皮质激素（ICS，哮喘长期控制首选）：布地奈德气雾剂，每次1~2揿（100~200μg），每日2次吸入；疗程至少3个月，依控制情况阶梯减量，不可自行停药。\n2.短效β2受体激动剂（SABA，急性缓解首选）：硫酸沙丁胺醇气雾剂，发作时按需吸入1~2揿，每日不超过8揿；症状缓解后可停用，若每日需用超过2次提示控制不佳，应及时就医。\n3.白三烯受体拮抗剂（辅助控制）：孟鲁司特钠咀嚼片5mg（6岁以上）每晚1次口服，疗程4~8周，可与ICS联合使用。\n【一般治疗及生活指导】\n1.规避过敏原及诱因：避免接触尘螨、花粉、动物皮毛、二手烟及刺激性气味；家中勤打扫、通风，床单被褥每周用热水清洗晾晒。\n2.饮食清淡易消化，避免海鲜、花生、牛奶等可疑致敏食物及冰冷、过甜食物；多饮水，保证营养均衡。\n3.适度运动增强体质：可选择游泳、慢跑等有氧运动，运动前可预防性吸入沙丁胺醇1揿；避免剧烈跑跳及寒冷天气室外运动诱发发作。\n4.注意保暖，预防上呼吸道感染；流感季节可接种流感疫苗，遵医嘱可考虑接种肺炎疫苗。\n【随诊要求】\n每1~3个月门诊复诊，评估哮喘控制水平（哮喘控制测试评分、呼气峰流速监测），据此调整吸入激素剂量；复查肺功能及呼出气一氧化氮（FeNO）；急性发作或症状反复、控制不佳时随时复诊。"},"icd10_diagnosis":"","icd10_secondary":[],"icd9cm3_procedure":[]}},"locator":{"file":"门诊住院病历模板/病历模板包_全部_20261111.json","arrayRow":388,"caseRow":1},"sourceHash":"10e4fdb435986b7b85f847c3951d0cb0eafdce0f372c5617949c05b337149194","contentHash":"c19a2e79ab1c6a10d1c73e36d89acb69998572f5035933c386e91862476d4e2b","pinyin":"xiaoerxiaochuan","initials":"xexc","setting":"out","caseName":"门诊病历253","templateNames":["主诉","现病史","既往史","个人史及过敏史","体格检查","辅助检查","初步诊断","处理方案"],"emptyTemplates":[],"escapedNewlines":[],"quickFields":[["病例名称","门诊病历253",60],["模板名称","主诉 现病史 既往史 个人史及过敏史 体格检查 辅助检查 初步诊断 处理方案",30],["主要诊断编码","",30]]},{"id":"templates-10d243d46471909f8b1f","key":"v1-c9ccc21dfe2a3058|templates-10d243d46471909f8b1f","module":"templates","moduleKey":"v1-c9ccc21dfe2a3058|templates","version":"v1-c9ccc21dfe2a3058","title":"电击伤","category":"门诊病历模板","raw":{"name":"电击伤","category":"门诊病历模板","case":{"case_name":"门诊病历254","templates":{"主诉":"触电后双手麻木、灼痛3小时","现病史":"患者于2小时前在工地接触380V电源时触电，触电后当即被弹开（或意识丧失约1分钟后清醒），自觉双手麻木、疼痛，局部皮肤可见烧伤创面约2cm×3cm，深达Ⅱ度，伴心悸、胸闷、头晕，无恶心、呕吐、抽搐，无大小便失禁。急来我院就诊。发病以来精神、食欲、睡眠、大小便、体重无明显变化。","既往史":"既往体健，否认高血压、糖尿病、冠心病等慢性病史。否认肝炎、结核等传染病史。否认手术外伤史。否认食物药物过敏史。预防接种史随社会。","个人史及过敏史":"生于原籍，久居本地，无疫区疫水接触史，无特殊粉尘毒物放射性物质接触史。不吸烟，不饮酒。生活规律。否认食物药物过敏史。","体格检查":"T 36.8℃，P 80次/分，R 18次/分，BP 125/80mmHg。神志清楚，精神可，自主体位，查体合作。皮肤黏膜无黄染，浅表淋巴结未触及肿大。颈软，无抵抗。双肺呼吸音清，未闻及干湿性啰音。心率80次/分，律齐，各瓣膜听诊区未闻及病理性杂音。腹平软，无压痛，肝脾肋下未触及。生理反射存在，病理反射未引出。","辅助检查":"检查计划：患者触电后双手麻木灼痛3小时，局部可见深达Ⅱ度烧伤创面，伴心悸、胸闷、头晕，入院即刻完善心电图检查，明确有无电击所致心律失常、心肌缺血或传导阻滞，必要时持续心电监护并定期复查心电图观察动态演变；查血常规评估有无应激性白细胞升高及失血、感染风险；查尿常规了解有无肌红蛋白尿，明确电击致肌肉损伤后横纹肌溶解及急性肾损伤风险；查便常规了解有无消化道应激性黏膜损伤出血，作为应激状态下的基础评估；完善肝肾功能检查，明确电流对肝脏及肾脏的损伤程度，并为后续用药经肝肾代谢提供剂量调整依据；查血糖了解应激性高血糖及能量代谢状况；查血脂四项了解血脂水平，评估动脉粥样硬化与心血管事件风险，指导后续降脂治疗；完善电解质检查，明确有无高钾、低钾等电解质紊乱，排除电解质异常所致心律失常；患者触电后胸闷、心悸，完善心肌酶与肌钙蛋白检查排除电击所致急性心肌损伤；完善胸部X线片检查明确有无电击后肺挫伤、吸入性损伤及心脏扩大等表现；完善腹部超声了解电流通过腹部后有无腹腔脏器损伤、积液或出血；因创面为深Ⅱ度烧伤，创面分泌物培养加药敏待有分泌物时完善，明确感染病原并指导抗菌治疗，必要时请烧伤科、心内科及外科会诊，其他检查根据病情需要选择相应检查。\n\n（检查清单）\n【必做检查】\n血常规、尿常规、便常规、肝肾功能、血糖、血脂、电解质\n\n【影像学检查】\n心电图、胸部X线片、腹部超声\n\n【其他检查】\n根据病情需要选择相应检查","初步诊断":"1. 电击伤\n（注：根据患者病史、体征及辅助检查综合判断，必要时请相关科室会诊。）","处理方案":"【药物治疗】\n1. 预防感染（电击创面及深部组织损伤）：头孢呋辛酯片 0.25g bid×5天；创面较深或污染明显者加用甲硝唑片 0.4g tid×5天（头孢过敏者改左氧氟沙星片 0.5g qd×5天）。\n2. 营养心肌、改善心肌代谢（电击可致心肌损伤、心律失常）：辅酶Q10胶囊 10mg tid×2周；门冬氨酸钾镁片 2片 tid×1周，注意监测心电图及血钾。\n3. 神经营养（肢体麻木、感觉异常）：甲钴胺片 0.5mg tid×2周。\n4. 破伤风预防：创面有破损者予以破伤风抗毒素（TAT）1500U 肌注（皮试阴性后），或破伤风人免疫球蛋白 250U 肌注1次。\n【一般治疗及生活指导】\n1. 休息：电击后24～72小时为迟发性心律失常高发期，建议卧床休息、避免剧烈活动及情绪激动，不饮浓茶、咖啡及酒精类饮品，密切观察有无心悸、胸闷、头晕、黑矇，异常立即就诊。\n2. 创面护理：保持创面清洁干燥，勿自行撕除焦痂、挑破水疱，按医嘱换药；观察创面有无红肿、渗液增多、异味等感染征象，焦痂脱落前避免沾水及抓挠。\n3. 饮食：高蛋白、高维生素易消化饮食（鱼、蛋、瘦肉、新鲜蔬果），每日饮水2000ml以上，稀释尿液、促进肌红蛋白排出，保护肾功能。\n4. 禁忌：1周内避免接触带电设备、高空作业及驾驶，禁止饮酒；肢体麻木或肌力减退者避免提重物，注意感觉减退区域防烫伤、防冻伤。\n【随诊要求】\n电击后24小时内复查心电图，动态监测心肌酶谱；1周后复诊复查心电图、心肌酶及尿常规（监测肌红蛋白尿）。出现心悸、胸闷、晕厥、肢体麻木加重或创面红肿化脓者随时急诊就诊。创面未愈合者每2～3天门诊换药复诊，直至创面愈合；如心电图或心肌酶持续异常，建议心内科进一步随访。"},"icd10_diagnosis":"","icd10_secondary":[],"icd9cm3_procedure":[]}},"locator":{"file":"门诊住院病历模板/病历模板包_全部_20261111.json","arrayRow":389,"caseRow":1},"sourceHash":"10e4fdb435986b7b85f847c3951d0cb0eafdce0f372c5617949c05b337149194","contentHash":"13a3193fdc677939311ff577cd847d32fa5fd3928bc9474f0ed00e0de1412a1d","pinyin":"dianjishang","initials":"djs","setting":"out","caseName":"门诊病历254","templateNames":["主诉","现病史","既往史","个人史及过敏史","体格检查","辅助检查","初步诊断","处理方案"],"emptyTemplates":[],"escapedNewlines":[],"quickFields":[["病例名称","门诊病历254",60],["模板名称","主诉 现病史 既往史 个人史及过敏史 体格检查 辅助检查 初步诊断 处理方案",30],["主要诊断编码","",30]]},{"id":"templates-7126d1a92454147b0b51","key":"v1-c9ccc21dfe2a3058|templates-7126d1a92454147b0b51","module":"templates","moduleKey":"v1-c9ccc21dfe2a3058|templates","version":"v1-c9ccc21dfe2a3058","title":"蜂蜇伤","category":"门诊病历模板","raw":{"name":"蜂蜇伤","category":"门诊病历模板","case":{"case_name":"门诊病历255","templates":{"主诉":"蜂蜇伤后局部疼痛、肿胀3小时","现病史":"患者于2小时前在公园被蜂蜇伤右手背，蜇伤后立即出现局部疼痛、红肿、灼热感，伴瘙痒，蜇伤处可见毒刺，无恶心、呕吐、腹痛、腹泻，无头晕、心慌、胸闷、呼吸困难，无全身皮疹等全身过敏反应（如有全身过敏反应表现请按实际填写）。曾予自行拔刺、涂药处理。急来我院就诊。发病以来精神、食欲、睡眠、大小便、体重无明显变化。","既往史":"既往体健，否认高血压、糖尿病、冠心病等慢性病史。否认肝炎、结核等传染病史。否认手术外伤史。否认食物药物过敏史。预防接种史随社会。","个人史及过敏史":"生于原籍，久居本地，无疫区疫水接触史，无特殊粉尘毒物放射性物质接触史。不吸烟，不饮酒。生活规律。否认食物药物过敏史。","体格检查":"T 36.8℃，P 80次/分，R 18次/分，BP 125/80mmHg。神志清楚，精神可，自主体位，查体合作。皮肤黏膜无黄染，浅表淋巴结未触及肿大。颈软，无抵抗。双肺呼吸音清，未闻及干湿性啰音。心率80次/分，律齐，各瓣膜听诊区未闻及病理性杂音。腹平软，无压痛，肝脾肋下未触及。生理反射存在，病理反射未引出。","辅助检查":"检查计划：患者右手背被蜂蜇伤后局部疼痛、红肿灼热伴瘙痒，目前无头晕、心慌、胸闷、呼吸困难及全身皮疹，为评估毒素吸收后有无全身炎症反应及迟发过敏，入院即刻完善血常规检查，了解白细胞及嗜酸性粒细胞计数，明确有无感染及过敏反应倾向；查尿常规了解有无蜂毒所致血红蛋白尿、肌红蛋白尿及肾小管损伤，评估肾脏受累风险；查便常规了解有无消化道黏膜损伤出血，作为蜂毒全身毒性反应的基线评估；蜂毒可致溶血及多脏器损害，完善肝肾功能检查明确有无肝细胞损伤与肾功能不全，并为抗过敏及抗感染用药提供代谢依据；查血糖了解应激状态下的糖代谢变化，评估创面愈合与感染风险；查血脂四项了解血脂水平，评估基础心血管风险；完善电解质检查明确有无溶血或呕吐所致电解质紊乱及高钾血症，排除电解质异常引起的心律失常；蜂毒可诱发心肌损伤及过敏相关心血管事件，入院即刻完善心电图检查明确有无心律失常及心肌缺血，必要时复查观察动态演变；完善胸部X线片检查排除蜇伤后过敏所致支气管痉挛性肺部改变及继发肺部感染；完善腹部超声了解有无腹部脏器受累与腹腔积液，排除蜂毒所致内脏损伤；因局部红肿明显并可见毒刺、有继发感染可能，必要时完善创面分泌物培养加药敏明确病原，指导抗生素选用；若出现全身过敏反应表现，即加查血清总IgE及类胰蛋白酶明确过敏机制，必要时留观监护并根据病情需要选择相应检查。\n\n（检查清单）\n【必做检查】\n血常规、尿常规、便常规、肝肾功能、血糖、血脂、电解质\n\n【影像学检查】\n心电图、胸部X线片、腹部超声\n\n【其他检查】\n根据病情需要选择相应检查","初步诊断":"1. 蜂蜇伤\n（注：根据患者病史、体征及辅助检查综合判断，必要时请相关科室会诊。）","处理方案":"【药物治疗】\n1. 抗组胺药：氯雷他定片 10mg qd×3~5天（或西替利嗪片 10mg qd×3~5天），用于止痒、消退皮疹。\n2. 局部外用：丁酸氢化可的松乳膏（尤卓尔）适量涂患处 bid×3~5天，未破溃处可加用炉甘石洗剂外涂，破溃处注意消毒后外用莫匹罗星软膏。\n3. 口服糖皮质激素（肿胀明显、泛发风团或血管性水肿者）：泼尼松片 30mg qd×3天，症状缓解后遵医嘱减停。\n4. 对症止痛（疼痛剧烈者）：布洛芬缓释胶囊 0.3g bid，疼痛缓解即停；伤口较深或污染明显者加用破伤风抗毒素（TAT）1500IU 肌注（皮试阴性后）。\n【一般治疗及生活指导】\n1. 立即用镊子或硬卡片沿皮肤平行方向刮除毒刺，切勿挤压伤口（挤压可促使更多毒液注入）；蜜蜂蜇伤用肥皂水等碱性液冲洗，胡蜂（黄蜂）蜇伤用食醋等酸性液冲洗，随后局部冷敷（每次15~20分钟，间隔1小时）。\n2. 保持伤口清洁干燥，勿搔抓、勿热敷、勿涂擦草药等偏方，避免剧烈活动，抬高患肢以减轻肿胀。\n3. 清淡饮食，忌辛辣刺激性食物及海鲜等易致敏食物，多饮水促进毒物排泄，禁酒。\n4. 密切观察：若出现全身皮疹、胸闷气促、喉头水肿、头晕心慌、恶心呕吐等全身过敏表现，立即就近急诊就医；既往有蜂蜇过敏史者建议随身携带抗过敏药物。\n【随诊要求】\n1. 用药后3天复诊，评估肿胀、瘙痒及皮疹消退情况，调整用药。\n2. 若24~48小时内出现发热、伤口红肿范围持续扩大、化脓或任何全身过敏表现，随时复诊或急诊就诊。\n3. 既往有严重蜂蜇过敏史者，建议至变态反应科就诊，评估过敏原检测及脱敏（免疫治疗）指征。"},"icd10_diagnosis":"","icd10_secondary":[],"icd9cm3_procedure":[]}},"locator":{"file":"门诊住院病历模板/病历模板包_全部_20261111.json","arrayRow":390,"caseRow":1},"sourceHash":"10e4fdb435986b7b85f847c3951d0cb0eafdce0f372c5617949c05b337149194","contentHash":"aac18f098101880bf53bba95e8facdc9d5a082ac93c04034d7e357a764712a9d","pinyin":"fengzheshang","initials":"fzs","setting":"out","caseName":"门诊病历255","templateNames":["主诉","现病史","既往史","个人史及过敏史","体格检查","辅助检查","初步诊断","处理方案"],"emptyTemplates":[],"escapedNewlines":[],"quickFields":[["病例名称","门诊病历255",60],["模板名称","主诉 现病史 既往史 个人史及过敏史 体格检查 辅助检查 初步诊断 处理方案",30],["主要诊断编码","",30]]},{"id":"templates-d61a9e8988c3758b27e0","key":"v1-c9ccc21dfe2a3058|templates-d61a9e8988c3758b27e0","module":"templates","moduleKey":"v1-c9ccc21dfe2a3058|templates","version":"v1-c9ccc21dfe2a3058","title":"蛇咬伤","category":"门诊病历模板","raw":{"name":"蛇咬伤","category":"门诊病历模板","case":{"case_name":"门诊病历256","templates":{"主诉":"蛇咬伤后伤口肿痛2小时","现病史":"患者于2小时前在田间被竹叶青咬伤右足背，咬伤后立即出现伤口疼痛、肿胀，伴出血，自行挤压、冲洗处理，伴恶心、呕吐、头晕，无头晕加重等全身中毒表现，无视物模糊、眼睑下垂、四肢乏力、呼吸困难。急来我院就诊。发病以来精神、食欲、睡眠、大小便、体重无明显变化。","既往史":"既往体健，否认高血压、糖尿病、冠心病等慢性病史。否认肝炎、结核等传染病史。有无过敏史（尤其马血清制品、破伤风抗毒素过敏史）：无。预防接种史随社会。","个人史及过敏史":"生于原籍，久居本地，无疫区疫水接触史。否认药物食物过敏史。有无破伤风抗毒素/抗蛇毒血清过敏史：无。","体格检查":"T 36.8℃，P 90次/分，R 20次/分，BP 120/80mmHg。神志清楚，精神可，查体合作。\n【伤口局部】右足背部位可见咬痕（牙痕）2个，间距1.5cm，伤口及周围肿胀明显（范围：以伤口为中心直径约5cm），皮肤颜色青紫，局部压痛（+），活动性出血（有），伤口周围感觉异常（有）。\n【全身】皮肤黏膜有无出血点、瘀斑：无；眼睑有无下垂：无；有无复视：无；瞳孔等大等圆，对光反射灵敏；颈软；双肺呼吸音清，未闻及干湿性啰音；心率90次/分，律齐；腹平软，无压痛；四肢肌力5级，肌张力正常；生理反射存在，病理反射未引出。","辅助检查":"【必做检查】\n血常规、凝血功能（PT/APTT/FIB/D-二聚体），筛查蛇毒所致DIC及出血倾向（关键！）、肝肾功能、心肌酶谱（CK、CK-MB）、电解质、尿常规（血尿/肌红蛋白尿，筛查横纹肌溶解）\n\n【蛇毒相关】\n蛇毒检测（如医院可开展）、伤口分泌物细菌培养（伤口感染时）\n\n【其他检查】\n心电图（心肌毒蛇伤时）、胸片（呼吸困难时）、神经功能评估（神经毒蛇伤：肌力/呼吸肌功能）","初步诊断":"1. 蛇咬伤（毒蛇咬伤/无毒蛇咬伤待定）\n（注：根据咬痕、蛇种辨认、局部及全身表现综合判断；必要时请急诊科/中毒科会诊。）","处理方案":"【关键处理】\n1. 抗蛇毒血清（如有明确毒蛇咬伤证据或严重中毒表现）：尽快使用，皮试后按说明书剂量静脉给药，观察过敏反应（备肾上腺素）\n2. 破伤风抗毒素（TAT）或破伤风免疫球蛋白（TIG）1500IU肌注（先皮试）\n3. 伤口处理：清水或生理盐水冲洗伤口，消毒；禁止切开排毒、禁止用口吸吮、禁止长时间止血带捆扎（可现场宽绷带轻压制动）、禁止冰敷、禁止酒精敷伤口\n4. 留院观察至少24小时（蛇咬伤可迟发中毒，尤其神经毒/血循毒）；重症者住院治疗\n\n【药物治疗】\n抗过敏：地塞米松5-10mg iv（过敏反应时）；抗组胺药\n对症：止痛（对乙酰氨基酚等）、消肿（抬高患肢）\n出现DIC/横纹肌溶解/呼吸衰竭时按相应急症处理\n\n【一般治疗及生活指导】\n患肢制动、抬高，避免活动；大量饮水；密切观察伤口及全身症状变化；记录肿胀范围、尿量\n\n【随诊要求】\n留观/住院期间密切监测生命体征、凝血功能、尿量；出院后2-3天复查血常规、凝血功能、肝肾功能；如肿胀加重、发热、出血、呼吸困难及时就诊；禁烟酒"},"icd10_diagnosis":"","icd10_secondary":[],"icd9cm3_procedure":[]}},"locator":{"file":"门诊住院病历模板/病历模板包_全部_20261111.json","arrayRow":391,"caseRow":1},"sourceHash":"10e4fdb435986b7b85f847c3951d0cb0eafdce0f372c5617949c05b337149194","contentHash":"83b10231194507a7b4e9a77b82281e6f16af84e2cd62512e5b6d958db1e03baf","pinyin":"sheyaoshang","initials":"sys","setting":"out","caseName":"门诊病历256","templateNames":["主诉","现病史","既往史","个人史及过敏史","体格检查","辅助检查","初步诊断","处理方案"],"emptyTemplates":[],"escapedNewlines":[],"quickFields":[["病例名称","门诊病历256",60],["模板名称","主诉 现病史 既往史 个人史及过敏史 体格检查 辅助检查 初步诊断 处理方案",30],["主要诊断编码","",30]]},{"id":"templates-bf0abc89da7e4bb20dde","key":"v1-c9ccc21dfe2a3058|templates-bf0abc89da7e4bb20dde","module":"templates","moduleKey":"v1-c9ccc21dfe2a3058|templates","version":"v1-c9ccc21dfe2a3058","title":"犬咬伤","category":"门诊病历模板","raw":{"name":"犬咬伤","category":"门诊病历模板","case":{"case_name":"门诊病历257","templates":{"主诉":"被犬咬伤左小腿2小时","现病史":"患者于2小时前被家养犬（未接种狂犬病疫苗）咬伤左小腿后外侧，当时伤口疼痛、出血量不多，咬伤处裤管破损。自行用清水冲洗后未做特殊处理，为行伤口处置及狂犬病预防来我院就诊。咬伤前无该犬异常表现（攻击性增强/流涎/畏光等不详，待确认犬只健康状况）。发病以来精神可，无发热、无头痛、无恐水怕风等表现。","既往史":"既往体健，否认高血压、糖尿病、冠心病等慢性病史。否认肝炎、结核等传染病史。否认手术外伤史。否认食物药物过敏史。预防接种史随社会。","个人史及过敏史":"生于原籍，久居本地，无疫区疫水接触史，无特殊粉尘毒物放射性物质接触史。不吸烟，不饮酒。生活规律。否认食物药物过敏史。","体格检查":"T 36.6℃，P 80次/分，R 18次/分，BP 118/76mmHg。神志清楚，查体合作。左小腿后外侧可见2处皮肤咬痕及撕裂伤口，长约（0.5~1）cm，深达皮下，边缘不整，伤口周围轻度红肿，无明显活动性出血，无异味分泌物；左下肢活动、感觉、末梢血运正常。浅表淋巴结未触及肿大。心肺听诊未闻及明显异常。","辅助检查":"【必做】伤口评估后一般无需常规化验；伤口深、污染重者查血常规；【影像学】咬伤深及骨骼、关节或疑骨折时行X线片；【其他】如需接种狂犬病疫苗，无特殊化验要求。","初步诊断":"1. 犬咬伤（左小腿）\n（注：重点评估狂犬病暴露分级（Ⅱ~Ⅲ级）及破伤风风险，决定疫苗及被动免疫制剂使用。）","处理方案":"【药物治疗】\n1. 狂犬病疫苗（Vero细胞/人二倍体细胞疫苗）：咬伤后24小时内于三角肌（成人）肌注第1剂；采用2-1-1程序者（当日上臂三角肌各注射1剂，第7日、第21日各1剂），或5针程序者（第0、3、7、14、28天各1剂），全程按时完成；III级暴露（穿透性皮肤咬伤、抓伤出血或黏膜/破损皮肤污染）者，首剂同时加用狂犬病人免疫球蛋白20IU/kg，尽量在伤口周围作浸润注射，剩余量肌注。\n2. 破伤风预防：咬伤属污染伤口，予破伤风抗毒素（TAT）1500IU肌注（皮试阴性后），或破伤风人免疫球蛋白250IU肌注（TAT过敏者）；既往5年内曾完成破伤风类毒素加强接种者可免注。\n3. 抗感染（伤口深、污染重或已化脓者）：阿莫西林克拉维酸钾片0.625g口服 bid×5天；青霉素过敏者予多西环素片0.1g口服 bid×5天或头孢呋辛酯片0.25g口服 bid×5天。\n4. 疼痛明显者：布洛芬缓释胶囊0.3g口服 bid×3天（饭后服用，溃疡病史者慎用）。\n\n【一般治疗及生活指导】\n1. 伤口处理：立即用肥皂水（或其他弱碱性清洁剂）与流动清水交替彻底冲洗伤口至少15分钟，继以碘伏或75%酒精消毒；伤口原则上不予缝合、不予包扎，清创后开放引流，仅伤及大血管需止血时例外。\n2. 休息与活动：咬伤位于下肢或伤口较深者减少活动、抬高患肢，避免剧烈运动和伤口局部受压；伤口愈合前保持干燥，避免浸水、泡澡。\n3. 饮食与禁忌：忌辛辣刺激性食物，狂犬病疫苗接种全程及接种后2周内忌饮酒、忌浓茶咖啡，多饮水，保证优质蛋白摄入以促进愈合。\n4. 观察：如肇事犬可追踪，观察10日，若犬在10日内死亡或出现异常（狂躁、流涎、怕水），立即就医补种疫苗；伤口出现红肿加剧、疼痛、脓性分泌物或发热等感染征象时随时复诊。\n\n【随诊要求】\n1. 严格按狂犬病疫苗免疫程序按时复诊接种后续剂次（2-1-1程序第7、21日，或5针程序第3、7、14、28天），不得中断或延迟。\n2. 咬伤后3-5天复诊评估伤口愈合及有无感染，必要时调整抗感染方案；未缝合伤口密切观察引流情况。\n3. 全程接种后（如条件允许）可于末次接种后2-4周复查狂犬病中和抗体；若出现发热、恐水、怕风、吞咽困难、抽搐等异常表现，立即急诊就诊。"},"icd10_diagnosis":"","icd10_secondary":[],"icd9cm3_procedure":[]}},"locator":{"file":"门诊住院病历模板/病历模板包_全部_20261111.json","arrayRow":392,"caseRow":1},"sourceHash":"10e4fdb435986b7b85f847c3951d0cb0eafdce0f372c5617949c05b337149194","contentHash":"ace60b93fab6636bf45f5b8e05a8ef6c52528388b79135a674a2e58b427b4efc","pinyin":"quanyaoshang","initials":"qys","setting":"out","caseName":"门诊病历257","templateNames":["主诉","现病史","既往史","个人史及过敏史","体格检查","辅助检查","初步诊断","处理方案"],"emptyTemplates":[],"escapedNewlines":[],"quickFields":[["病例名称","门诊病历257",60],["模板名称","主诉 现病史 既往史 个人史及过敏史 体格检查 辅助检查 初步诊断 处理方案",30],["主要诊断编码","",30]]},{"id":"templates-9a648b496b6caaa308b5","key":"v1-c9ccc21dfe2a3058|templates-9a648b496b6caaa308b5","module":"templates","moduleKey":"v1-c9ccc21dfe2a3058|templates","version":"v1-c9ccc21dfe2a3058","title":"一氧化碳中毒","category":"门诊病历模板","raw":{"name":"一氧化碳中毒","category":"门诊病历模板","case":{"case_name":"门诊病历258","templates":{"主诉":"头痛、头晕伴恶心、意识模糊3小时","现病史":"患者于2小时前在密闭房间内使用燃气热水器洗澡环境中停留后出现头痛、头晕、恶心、呕吐、乏力、心悸，渐出现意识模糊，被发现时呼之不应，无抽搐，无大小便失禁，脱离现场后意识恢复。同处环境者有无类似症状：有。既往有无心脏病、脑血管病史：无。今日来我院急诊就诊。","既往史":"既往体健，否认高血压、糖尿病、冠心病等慢性病史。否认肝炎、结核等传染病史。否认手术外伤史。否认食物药物过敏史。预防接种史随社会。","个人史及过敏史":"生于原籍，久居本地，无疫区疫水接触史，无特殊粉尘毒物放射性物质接触史。不吸烟，不饮酒。生活规律。否认食物药物过敏史。","体格检查":"T____℃，P____次/分，R____次/分，BP____/____mmHg，SpO2____%（脉搏血氧饱和度可假性正常，CO中毒重要特征）。神志____（清楚/嗜睡/昏迷），皮肤黏膜及口唇____（樱桃红色；典型但非必有），双侧瞳孔等大等圆、对光反射____，心肺听诊____，四肢肌张力及腱反射____，病理征____。","辅助检查":"【必做】血碳氧血红蛋白（HbCO，升高（>10%）为诊断依据；脱离环境后随时间下降，尽早采血）、血气分析（代谢性酸中毒）、心电图（心肌缺血）、心肌损伤标志物（心肌受损评估）、血常规、肝肾功能；【影像学】头颅CT（昏迷者排除脑水肿、脑梗死，迟发性脑病评估）、脑MRI（疑迟发性脑病时）。","初步诊断":"1. 急性一氧化碳中毒（轻度：轻度（HbCO 10~20%）/中度（20~40%）/重度（>40%））\n（注：立即脱离中毒环境、保持呼吸道通畅、吸氧；中重度：尽早高压氧治疗（2~3小时内效果最佳，减少迟发性脑病发生）；轻中度：高浓度面罩吸氧（4~6小时）；对症（脑水肿：甘露醇、糖皮质激素；防治并发症）；观察警惕迟发性脑病（中毒后2~60天出现精神神经症状，记忆力减退、痴呆、震颤麻痹），重度者建议高压氧疗程（10~20次）并随访神经系统；家庭宣教（通风、煤气报警器）。）","处理方案":"【药物治疗】\n根据病情紧急处理，具体用药根据诊断和生命体征决定。\n\n【一般治疗及生活指导】\n卧床休息，密切监测生命体征，保持呼吸道通畅，建立静脉通路。\n\n【随诊要求】\n根据病情决定是否住院或留观，如症状加重立即就诊。"},"icd10_diagnosis":"","icd10_secondary":[],"icd9cm3_procedure":[]}},"locator":{"file":"门诊住院病历模板/病历模板包_全部_20261111.json","arrayRow":393,"caseRow":1},"sourceHash":"10e4fdb435986b7b85f847c3951d0cb0eafdce0f372c5617949c05b337149194","contentHash":"88bdccdcd40371b216c49464b402f08ab196df94f3a0a6db826783fbd9fc1cbc","pinyin":"yiyanghuatanzhongdu","initials":"yyhtzd","setting":"out","caseName":"门诊病历258","templateNames":["主诉","现病史","既往史","个人史及过敏史","体格检查","辅助检查","初步诊断","处理方案"],"emptyTemplates":[],"escapedNewlines":[],"quickFields":[["病例名称","门诊病历258",60],["模板名称","主诉 现病史 既往史 个人史及过敏史 体格检查 辅助检查 初步诊断 处理方案",30],["主要诊断编码","",30]]},{"id":"templates-6c1c65a03a40671bd898","key":"v1-c9ccc21dfe2a3058|templates-6c1c65a03a40671bd898","module":"templates","moduleKey":"v1-c9ccc21dfe2a3058|templates","version":"v1-c9ccc21dfe2a3058","title":"急性会厌炎","category":"门诊病历模板","raw":{"name":"急性会厌炎","category":"门诊病历模板","case":{"case_name":"门诊病历259","templates":{"主诉":"咽痛伴吞咽困难、呼吸困难3小时。","现病史":"患者于3小时前无明显诱因出现咽喉部剧烈疼痛，吞咽时加重，伴言语含糊（口中含物感）、流涎，继而出现吸气性呼吸困难、吸气性喉鸣，无发热、无咳嗽咳痰，无声音嘶哑。自服阿莫西林（剂量不详）无效，症状进行性加重，急来我院就诊。发病以来精神紧张，未进食水。","既往史":"既往体健，否认高血压、糖尿病、冠心病等慢性病史。否认肝炎、结核等传染病史。否认手术外伤史。否认食物药物过敏史。预防接种史随社会。","个人史及过敏史":"生于原籍，久居本地，无疫区疫水接触史，无特殊粉尘毒物放射性物质接触史。不吸烟，不饮酒。生活规律。否认食物药物过敏史。","体格检查":"T 38.0℃，P 110次/分，R 24次/分，BP 130/80mmHg，SpO2 95%（吸空气）。急性病容，端坐呼吸，吸气性三凹征（+），口唇无明显发绀。间接喉镜检查（在备好气管切开包条件下谨慎进行）：会厌舌面明显充血、水肿呈球形，活动受限，声门窥不清。双肺呼吸音清，未闻及干湿性啰音。颈部无明显肿胀，无捻发感。","辅助检查":"检查计划：患者咽痛伴吞咽困难、呼吸困难3小时，出现言语含糊（口中含物感）、流涎及吸气性喉鸣，考虑急性会厌炎，本病起病急骤、可迅速进展为喉梗阻窒息，属耳鼻喉科急症，入院即刻完善血常规检查了解白细胞及中性粒细胞计数，明确细菌感染程度并指导抗生素选择；查CRP评估炎症反应程度，作为抗感染治疗疗效的动态随访指标；患者有剧烈咽喉疼痛与会厌肿胀，完善颈部侧位X线片检查，明确会厌肿胀影是否呈典型“拇指征”，了解咽后间隙及会厌前间隙情况，为诊断提供影像依据；喉镜检查可直接观察会厌及声门形态并明确气道梗阻程度，但检查过程中有诱发喉痉挛、加重窒息的风险，必须在具备紧急气道管理（气管插管、气管切开、抢救药品与设备）的条件下由耳鼻喉科医师进行，且动作轻柔、操作时间尽量缩短；患者病情危重、存在吸气性呼吸困难与喉鸣，不移动至检查室，先在床旁完成评估与气道保护（高流量吸氧、先保气道，必要时建立人工气道），待气道安全后再完善相关检查；患者因呼吸困难、未进食水，完善电解质及血气分析检查，明确有无因呼吸费力、进食减少所致电解质紊乱及低氧血症、二氧化碳潴留，评估通气功能状态；因存在吞咽困难、经口摄入不足，查血糖了解应激性高血糖及能量代谢状况；为评估感染对全身的影响及抗感染用药安全，查肝肾功能与尿常规，明确肝肾功能状态并作为用药剂量调整依据；完善心电图检查排除感染、缺氧所致心肌缺血及心律失常；必要时完善颈部增强CT明确会厌及颈部软组织肿胀范围与有无脓肿形成，为是否需切开引流提供依据。\n\n（检查清单）\n【必做】血常规、CRP；【影像学】颈部侧位X线片（可见会厌肿胀影，呈典型拇指征）；【注意】喉镜检查有诱发喉痉挛窒息风险，患者具备紧急气道管理条件下进行；病情危重者不移动检查，先保气道。","初步诊断":"1. 急性会厌炎\n（注：本病可迅速进展为喉梗阻窒息，属耳鼻喉科急症，建议急诊留观或住院，密切监测呼吸。）","处理方案":"【药物治疗】\n1. 头孢呋辛酯片0.25g bid 口服×5-7天（青霉素或头孢过敏者改用阿奇霉素片0.5g qd×5天），覆盖流感嗜血杆菌、链球菌等常见致病菌。\n2. 醋酸泼尼松片30mg 晨起顿服×3天，第4天减至20mg、第5天减至10mg后停药，迅速减轻会厌水肿、防止喉梗阻。\n3. 布地奈德混悬液2mg+生理盐水2ml 雾化吸入 bid×3-5天，局部抗炎消肿，缓解咽痛及吞咽不适。\n\n【一般治疗及生活指导】\n1. 卧床休息、取半卧位，尽量减少说话，避免会厌摩擦刺激加重水肿。\n2. 进温凉流质或半流质饮食（如米粥、藕粉），少量多餐，忌过热、过硬及辛辣刺激性食物，以免刺激会厌诱发呛咳。\n3. 禁烟、禁酒；保持室内空气湿润，多饮温水；避免剧烈活动及用力擤鼻、咳嗽。\n4. 密切观察呼吸情况，一旦出现吸气性呼吸困难、喉喘鸣、犬吠样咳嗽或烦躁不安，立即就近急诊处理，切勿等待。\n\n【随诊要求】\n1. 用药后24-48小时复诊，复查间接喉镜或电子喉镜，评估会厌充血水肿消退情况，决定是否减量或停药。\n2. 疗程结束后仍有咽痛、发热或声音改变者，需复诊进一步检查（血常规、喉镜）排除脓肿等并发症。\n3. 治疗期间若呼吸困难加重、发热持续不退或吞咽疼痛加剧，随时急诊就诊，必要时住院观察以防气道梗阻。"},"icd10_diagnosis":"","icd10_secondary":[],"icd9cm3_procedure":[]}},"locator":{"file":"门诊住院病历模板/病历模板包_全部_20261111.json","arrayRow":394,"caseRow":1},"sourceHash":"10e4fdb435986b7b85f847c3951d0cb0eafdce0f372c5617949c05b337149194","contentHash":"ee1b38102516bcfbddb8d603b6982beb582ce26aa1a634efcae4e35a6089335a","pinyin":"jixinghuiyanyan","initials":"jxhyy","setting":"out","caseName":"门诊病历259","templateNames":["主诉","现病史","既往史","个人史及过敏史","体格检查","辅助检查","初步诊断","处理方案"],"emptyTemplates":[],"escapedNewlines":[],"quickFields":[["病例名称","门诊病历259",60],["模板名称","主诉 现病史 既往史 个人史及过敏史 体格检查 辅助检查 初步诊断 处理方案",30],["主要诊断编码","",30]]},{"id":"templates-a2322c0fce132e536a8f","key":"v1-c9ccc21dfe2a3058|templates-a2322c0fce132e536a8f","module":"templates","moduleKey":"v1-c9ccc21dfe2a3058|templates","version":"v1-c9ccc21dfe2a3058","title":"慢性鼻窦炎","category":"门诊病历模板","raw":{"name":"慢性鼻窦炎","category":"门诊病历模板","case":{"case_name":"门诊病历260","templates":{"主诉":"鼻塞、流脓涕伴嗅觉减退12周","现病史":"患者鼻塞、流涕症状反复发作持续超过12周，每年发作4次，涕为黏脓性，伴头面部胀痛、嗅觉减退，咽后壁分泌物倒流（痰多、清嗓），有鼻息肉、哮喘、阿司匹林耐受不良（阿司匹林三联征）、变应性鼻炎、牙源性因素（上颌窦、牙根尖炎），无发热，无视力下降。今日来我院门诊就诊。","既往史":"既往体健，否认高血压、糖尿病、冠心病等慢性病史。否认肝炎、结核等传染病史。否认手术外伤史。否认食物药物过敏史。预防接种史随社会。","个人史及过敏史":"生于原籍，久居本地，无疫区疫水接触史，无特殊粉尘毒物放射性物质接触史。不吸烟，不饮酒。生活规律。否认食物药物过敏史。","体格检查":"T36.8℃，P78次/分，R18次/分，BP122/78mmHg。神志清楚，查体合作。鼻黏膜充血，中鼻道可见黏脓性分泌物，下鼻甲肿大，鼻中隔偏曲。咽后壁黏涕附着。","辅助检查":"【必做】鼻内镜检查（观察窦口、分泌物、有无鼻息肉，诊断关键）；【影像学】鼻窦CT（冠状位：窦腔黏膜增厚、窦口阻塞、有无骨改变，评估及术前必备）；【其他】过敏原检测（合并变应性鼻炎）、鼻分泌物或窦腔细菌培养（急性加重时）、嗅功能测试。","初步诊断":"1. 慢性鼻窦炎（不伴鼻息肉型：不伴鼻息肉，非嗜酸性：非嗜酸性）\n（注：药物治疗（3个月以上）：鼻用糖皮质激素（糠酸莫米松鼻喷剂喷鼻bid，一线抗炎）、生理盐水鼻腔冲洗（每日1~2次）、短期口服糖皮质激素（伴鼻息肉急性加重：泼尼松30~40mg/d×7~10天）、大环内酯类（克拉霉素0.25g bid×8~12周，慢性炎症型，需权衡）；伴变应性鼻炎者抗组胺药；手术指征：规范药物治疗3个月无效、伴鼻息肉阻塞、出现并发症：行功能性鼻内镜手术（FESS）；术后继续药物治疗及冲洗防复发。）","处理方案":"【药物治疗】\n1.抗生素（急性发作期）：阿莫西林克拉维酸钾片0.625g po bid，疗程10-14天；青霉素过敏者改用克拉霉素片0.25g po bid，疗程10-14天。\n2.鼻用糖皮质激素：糠酸莫米松鼻喷雾剂每次2喷（每喷50μg）qd，连用8-12周。\n3.黏液促排剂：桉柠蒎肠溶软胶囊0.3g po tid，饭前半小时凉开水送服，疗程2-4周；或欧龙马滴剂每次15滴 po tid。\n4.鼻腔冲洗：生理盐水（或2.3%高渗盐水）鼻腔冲洗，每日1-2次，每次每侧约200ml，可长期维持。\n\n【一般治疗及生活指导】\n1.休息与作息：保证充足睡眠，避免熬夜及过度劳累，增强机体抵抗力；注意保暖，预防感冒。\n2.饮食：清淡饮食，多饮水，忌烟酒，避免辛辣刺激、过食肥甘厚腻之品。\n3.活动与防护：适当进行快走、慢跑等有氧运动增强体质；感冒流行季节外出佩戴口罩；有过敏史者避免接触尘螨、花粉等过敏原。\n4.禁忌：避免用力擤鼻（应单侧交替轻擤），勿用手挖鼻；急性感染期避免游泳、潜水及高空飞行，以免气压变化加重鼻窦炎症。\n\n【随诊要求】\n1.用药2周后复诊评估疗效，观察鼻塞、流涕、头痛等症状改善情况；若症状无缓解或出现剧烈头痛、发热、眶患者肿、视力下降等，需及时就诊。\n2.规范治疗8-12周后复查鼻内镜和（或）鼻窦CT，评估黏膜炎症转归，指导后续用药方案。\n3.症状反复发作或经规范内科治疗无效者，转耳鼻喉科进一步评估，必要时行鼻内镜手术，术后遵医嘱定期复查换药。"},"icd10_diagnosis":"","icd10_secondary":[],"icd9cm3_procedure":[]}},"locator":{"file":"门诊住院病历模板/病历模板包_全部_20261111.json","arrayRow":395,"caseRow":1},"sourceHash":"10e4fdb435986b7b85f847c3951d0cb0eafdce0f372c5617949c05b337149194","contentHash":"bd4055acc2691004fc70e29e15fd6606e59ad157ae8728e7560f10f64496e475","pinyin":"manxingbidouyan","initials":"mxbdy","setting":"out","caseName":"门诊病历260","templateNames":["主诉","现病史","既往史","个人史及过敏史","体格检查","辅助检查","初步诊断","处理方案"],"emptyTemplates":[],"escapedNewlines":[],"quickFields":[["病例名称","门诊病历260",60],["模板名称","主诉 现病史 既往史 个人史及过敏史 体格检查 辅助检查 初步诊断 处理方案",30],["主要诊断编码","",30]]},{"id":"templates-890f4894ec6c4129fab0","key":"v1-c9ccc21dfe2a3058|templates-890f4894ec6c4129fab0","module":"templates","moduleKey":"v1-c9ccc21dfe2a3058|templates","version":"v1-c9ccc21dfe2a3058","title":"过敏性紫癜肾炎","category":"门诊病历模板","raw":{"name":"过敏性紫癜肾炎","category":"门诊病历模板","case":{"case_name":"门诊病历261","templates":{"主诉":"双下肢紫癜伴血尿、水肿2周","现病史":"患儿/患者于2周前出现双下肢及臀部紫癜（对称性、高出皮面、压之不褪色），伴腹痛、关节痛（紫癜伴随症状），1周前出现尿色改变（洗肉水样血尿）、泡沫尿（蛋白尿）、眼睑及下肢水肿，尿量减少（正常/减少），血压升高（有无升高），无发热。发病前有无上呼吸道感染史：有上呼吸道感染史。今日来我院门诊就诊。","既往史":"既往体健，否认高血压、糖尿病、冠心病等慢性病史。否认肝炎、结核等传染病史。否认手术外伤史。否认食物药物过敏史。预防接种史随社会。","个人史及过敏史":"生于原籍，久居本地，无疫区疫水接触史，无特殊粉尘毒物放射性物质接触史。不吸烟，不饮酒。生活规律。否认食物药物过敏史。","体格检查":"T36.5℃，P96次/分，R22次/分，BP118/76mmHg（升高，肾炎重要体征）。神志清楚，查体合作。双下肢及臀部可见对称性紫癜，部分融合，无破溃。眼睑及双下肢水肿（+/-）。腹平软，无压痛，关节无肿胀（有无肿胀）。肾区无叩击痛。","辅助检查":"【必做】尿常规（血尿、蛋白尿：核心监测）、24小时尿蛋白定量、肾功能（血肌酐、eGFR）、血常规、血白蛋白、血脂；【其他】血清IgA（可升高）、肾穿刺活检（大量蛋白尿/肾功能下降/肾病综合征表现时，病理示IgA沉积的系膜增生性肾炎，明确严重程度指导治疗）。","初步诊断":"1. 过敏性紫癜性肾炎（IgA血管炎肾损害，Ⅲ级）\n（注：治疗依据肾脏受累严重度：仅镜下血尿或轻度蛋白尿（<0.5g/24h），观察随访（每2~4周查尿常规，至少随访6个月）；中度蛋白尿（0.5~1g/24h），ACEI/ARB+随访；肾病综合征范围或肾功能下降，糖皮质激素（泼尼松1~2mg/kg/d或甲泼尼龙冲击）+免疫抑制剂（环磷酰胺或吗替麦考酚酯，重症），请肾内科/儿科专科治疗；高血压者降压；多数儿童预后好（自限性），成人预后较差；缓解后仍需长期随访尿常规及肾功能（复发及进展风险）。）","处理方案":"【药物治疗】\n1. 糖皮质激素：泼尼松片0.5mg/(kg·d)（成人常规30～40mg）晨起顿服，疗程4～8周，症状缓解后每2周减量5mg至停药；适用于尿蛋白明显增多或伴肾病综合征表现者。\n2. 抗组胺药：氯雷他定片10mg qd（或西替利嗪片10mg qd），连用2～4周，控制皮肤紫癜及过敏症状。\n3. 抗血小板聚集、改善微循环：双嘧达莫片50mg tid，疗程4～8周。\n4. 血管紧张素Ⅱ受体拮抗剂：缬沙坦胶囊80mg qd（或厄贝沙坦片150mg qd），用于24小时尿蛋白定量>0.5g者，长期服用并定期监测血压。\n\n【一般治疗及生活指导】\n1. 急性期卧床休息2～4周，避免剧烈活动和劳累，注意保暖，积极防治上呼吸道感染（感染是本病复发及加重的重要诱因）。\n2. 饮食：低盐、优质低蛋白饮食（蛋白质0.8g/(kg·d)），暂禁鱼、虾、蟹、贝类、牛羊肉等异种蛋白及辛辣刺激性食物，病情稳定后逐一谨慎恢复。\n3. 仔细查找并避免接触可疑过敏原（药物、食物、花粉等），停用一切可疑致敏药物。\n4. 保持皮肤清洁干燥，避免搔抓，防止紫癜破溃继发感染。\n\n【随诊要求】\n1. 每周复查尿常规、血压1次，直至尿检转阴；转阴后每2～4周复查1次，持续随访至少6～12个月。\n2. 每2～4周复查24小时尿蛋白定量、肾功能、血清白蛋白。\n3. 若蛋白尿持续>1g/24h或肾功能进行性下降，建议行肾穿刺活检明确病理分级并调整治疗方案，必要时转肾内科住院诊治。\n4. 出现腹痛、黑便、关节肿痛、紫癜增多或尿量减少时随时复诊。"},"icd10_diagnosis":"","icd10_secondary":[],"icd9cm3_procedure":[]}},"locator":{"file":"门诊住院病历模板/病历模板包_全部_20261111.json","arrayRow":396,"caseRow":1},"sourceHash":"10e4fdb435986b7b85f847c3951d0cb0eafdce0f372c5617949c05b337149194","contentHash":"b65bf648080cc67d73f7f3acfa06d3d9d3a58e89f90f9f25a7269331b69fb675","pinyin":"guominxingzidianshenyan","initials":"gmxzdsy","setting":"out","caseName":"门诊病历261","templateNames":["主诉","现病史","既往史","个人史及过敏史","体格检查","辅助检查","初步诊断","处理方案"],"emptyTemplates":[],"escapedNewlines":[],"quickFields":[["病例名称","门诊病历261",60],["模板名称","主诉 现病史 既往史 个人史及过敏史 体格检查 辅助检查 初步诊断 处理方案",30],["主要诊断编码","",30]]},{"id":"templates-b232c622fc53f7159a88","key":"v1-c9ccc21dfe2a3058|templates-b232c622fc53f7159a88","module":"templates","moduleKey":"v1-c9ccc21dfe2a3058|templates","version":"v1-c9ccc21dfe2a3058","title":"肺真菌感染","category":"门诊病历模板","raw":{"name":"肺真菌感染","category":"门诊病历模板","case":{"case_name":"门诊病历262","templates":{"主诉":"发热、咳嗽、咳痰伴咯血2周","现病史":"患者（基础病：长期糖皮质激素（血液病/器官移植后免疫抑制/长期糖皮质激素/糖尿病/COPD长期广谱抗生素/化疗））于2周前出现发热（抗细菌抗生素无效）、咳嗽、咳痰（可带血丝或咯血）、胸闷胸痛，有胸痛、呼吸困难进行性加重（有无胸痛、呼吸困难进行性加重），体重下降、乏力。有无肺结核病史：无肺结核病史。今日来我院门诊就诊。","既往史":"既往体健，否认高血压、糖尿病、冠心病等慢性病史。否认肝炎、结核等传染病史。否认手术外伤史。否认食物药物过敏史。预防接种史随社会。","个人史及过敏史":"生于原籍，久居本地，无疫区疫水接触史，无特殊粉尘毒物放射性物质接触史。不吸烟，不饮酒。生活规律。否认食物药物过敏史。","体格检查":"T38.2℃，P96次/分，R22次/分，BP118/72mmHg，SpO2 92%。神志清楚，慢性消耗病容。右肺呼吸音减低，可闻及湿啰音，心率96次/分。口腔无白斑（有无白斑，念珠菌），杵状指（+/-）。","辅助检查":"检查计划：患者有长期糖皮质激素使用等免疫抑制基础，发热、咳嗽、咳痰伴咯血2周且抗细菌抗生素治疗无效，需首先明确肺部病变性质，入院完善胸部CT检查，观察有无曲霉球（空洞内球状物、空气新月征）、侵袭性曲霉病的结节伴晕轮征、空洞及楔形实变，或隐球菌结节等特征性影像，明确病变范围与形态；查血常规了解白细胞及中性粒细胞计数、有无贫血，评估感染与免疫状态；查CRP评估炎症活动程度，作为抗真菌治疗疗效的动态随访指标；免疫低下患者侵袭性真菌感染筛查首选血清学，完善G试验（1,3-β-D葡聚糖）了解有无侵袭性真菌感染；完善GM试验（半乳甘露聚糖）明确有无侵袭性曲霉病，其动态变化可指导抗真菌疗程；完善痰真菌培养及涂片（必要时经支气管镜采集支气管肺泡灌洗液培养），明确病原菌种并指导抗真菌药物选择；因患者持续发热、免疫抑制状态易合并血流感染，完善血培养明确有无真菌或合并细菌血流感染；患者有咯血，需与肺结核鉴别，完善痰抗酸染色及结核分枝杆菌核酸检测，明确有无肺结核；为明确诊断金标准，必要时行支气管镜+肺泡灌洗液真菌培养或肺穿刺活检，组织病理见菌丝可确诊（诊断金标准）；隐球菌抗原（血清，必要时脑脊液）用于明确有无隐球菌病及中枢神经系统受累；患者需长期使用伏立康唑或两性霉素B等抗真菌药，完善肝肾功能与电解质检查，明确基础肝肾功能并作为药物浓度及肝肾毒性监测的基线，指导剂量调整；治疗期间定期复查胸部CT、G试验与GM试验评估病灶吸收情况。\n\n（检查清单）\n【必做】胸部CT（曲霉球（空洞内球状物、空气新月征）、侵袭性曲霉病（结节伴晕轮征、空洞、楔形实变）、隐球菌结节等影像特征）、血常规、CRP、G试验（1,3-β-D葡聚糖，侵袭性真菌感染筛查）、GM试验（半乳甘露聚糖：侵袭性曲霉病重要指标）、真菌培养（痰/支气管肺泡灌洗液）、血培养；【确诊】支气管镜+肺泡灌洗液真菌培养/肺穿刺活检（组织病理见菌丝：金标准）；【其他】隐球菌抗原（血清/脑脊液：隐球菌病）。","初步诊断":"1. 肺真菌感染（侵袭性曲霉病：侵袭性曲霉病，待病原学明确）\n（注：侵袭性曲霉病（免疫低下高危），尽早经验性抗真菌：伏立康唑（首剂6mg/kg q12h×2次后4mg/kg q12h静滴或口服200mg bid，一线）或两性霉素B脂质体，疗程至病灶吸收（常6~12周以上）；肺曲霉球（免疫正常、陈旧空洞内），无症状观察，大咯血者手术切除或支气管动脉栓塞；隐球菌病，氟康唑（轻中度400mg qd）或两性霉素B+氟胞嘧啶（重症或中枢受累）；治疗原发病（减停免疫抑制剂、控制血糖）；血液科/呼吸科专科协作，监测药物浓度及肝肾毒性。）","处理方案":"【药物治疗】\n1. 抗真菌治疗（首选方案）：伏立康唑片 200mg 口服 q12h（首日负荷剂量400mg q12h，空腹或餐后1小时服用，避免与利福平、卡马西平等同服），疗程至少6～12周，依据临床症状及胸部影像学转归动态调整。\n2. 备选方案：伊曲康唑口服液 200mg 口服 bid（餐后服用）；或泊沙康唑肠溶片 300mg 口服 bid（与脂肪餐同服）；唑类不耐受、耐药或重症者选用棘白菌素类如卡泊芬净（首剂70mg静脉滴注，继以50mg qd），病情稳定后序贯口服唑类维持。\n3. 祛痰对症治疗：盐酸氨溴索片 30mg 口服 tid；痰液黏稠者加用乙酰半胱氨酸泡腾片 600mg 口服 qd，必要时生理盐水雾化吸入以稀释痰液。\n4. 合并细菌感染时依据痰培养及药敏结果加用敏感抗菌药物，如左氧氟沙星片 0.5g 口服 qd×5～7天；退热、止咳等对症处理。\n【一般治疗及生活指导】\n1. 休息与活动：急性期卧床休息，避免剧烈运动及重体力劳动；病情稳定后循序渐进恢复活动，注意劳逸结合、避免劳累诱发病情反复。\n2. 饮食：高蛋白、高维生素、易消化饮食，保证充足热量，每日饮水1500～2000ml；忌辛辣刺激及油腻食物，戒烟戒酒。\n3. 环境防护：居室保持通风干燥，避免进入地下室、仓库等霉变环境，不食用久置变质食物，清理霉变物品时佩戴防护口罩；痰真菌培养阳性期间注意呼吸道卫生、勤洗手。\n4. 病情监测：密切观察有无咯血、胸痛、呼吸困难加重等表现，出现上述症状立即就诊；长期服用伏立康唑者注意有无畏光、视物模糊、皮肤光敏等不良反应。\n【随诊要求】\n1. 治疗期间每2～4周门诊复诊，复查血常规、肝肾功能、电解质及胸部CT，评估疗效与药物不良反应。\n2. 疗程结束前复查胸部CT及真菌学检查（痰培养、G试验/GM试验）判断是否治愈；症状无缓解或加重、出现咯血者随时复诊。\n3. 长期唑类治疗者定期监测伏立康唑血药浓度（目标谷浓度1.0～5.5mg/L）及心电图QT间期；合并糖尿病、慢阻肺、血液病等基础疾病者同步规范控制原发病，治疗结束后建议每3～6个月随访1年以防复发。"},"icd10_diagnosis":"","icd10_secondary":[],"icd9cm3_procedure":[]}},"locator":{"file":"门诊住院病历模板/病历模板包_全部_20261111.json","arrayRow":397,"caseRow":1},"sourceHash":"10e4fdb435986b7b85f847c3951d0cb0eafdce0f372c5617949c05b337149194","contentHash":"66056751ec253769f273a64960854ec05fa018800ee80fdda29b71a5063fddd6","pinyin":"feizhenjunganran","initials":"fzjgr","setting":"out","caseName":"门诊病历262","templateNames":["主诉","现病史","既往史","个人史及过敏史","体格检查","辅助检查","初步诊断","处理方案"],"emptyTemplates":[],"escapedNewlines":[],"quickFields":[["病例名称","门诊病历262",60],["模板名称","主诉 现病史 既往史 个人史及过敏史 体格检查 辅助检查 初步诊断 处理方案",30],["主要诊断编码","",30]]},{"id":"templates-00bc408a66dad00a8d4c","key":"v1-c9ccc21dfe2a3058|templates-00bc408a66dad00a8d4c","module":"templates","moduleKey":"v1-c9ccc21dfe2a3058|templates","version":"v1-c9ccc21dfe2a3058","title":"肺寄生虫病","category":"门诊病历模板","raw":{"name":"肺寄生虫病","category":"门诊病历模板","case":{"case_name":"门诊病历263","templates":{"主诉":"咳嗽、咳痰伴发热2周","现病史":"患者有生食淡水蟹、蝲蛄（肺吸虫）、进食未煮熟的猪肉、牛肉（囊虫病）、疫水接触（血吸虫）、生食蛇胆、蛙（曼氏裂头蚴）等病史，于3周后出现咳嗽、咳痰（烂桃样痰，肺吸虫特征）、咯血、胸痛、发热（低热为主），有游走性皮下包块、腹痛腹泻、头痛抽搐（有无游走性皮下包块、腹痛腹泻、头痛抽搐，肺吸虫脑型/囊虫脑型表现），体重下降。今日来我院门诊就诊。","既往史":"既往体健，否认高血压、糖尿病、冠心病等慢性病史。否认肝炎、结核等传染病史。否认手术外伤史。否认食物药物过敏史。预防接种史随社会。","个人史及过敏史":"生于原籍，久居本地，无疫区疫水接触史，无特殊粉尘毒物放射性物质接触史。不吸烟，不饮酒。生活规律。否认食物药物过敏史。","体格检查":"T37.8℃，P88次/分，R20次/分，BP112/70mmHg。神志清楚，查体合作。双肺呼吸音减低，可闻及湿啰音，皮下可及游走性包块（皮下可及游走性包块/结节，肺吸虫或囊虫），腹部压痛（压痛/肝脾肿大，血吸虫）。","辅助检查":"检查计划：患者有生食淡水蟹、蝲蛄及未煮熟猪肉、牛肉，疫水接触等流行病学史，3周后出现咳嗽、咳痰（烂桃样痰）、咯血、胸痛及低热，并有游走性皮下包块、腹痛腹泻、头痛抽搐等表现，首先完善胸部X线片或CT检查，明确有无肺吸虫所致多房囊状阴影、隧道征、胸膜肥厚与胸腔积液，或血吸虫所致粟粒样结节，了解肺部病变部位与范围；寄生虫感染的特征性实验室改变为嗜酸性粒细胞显著升高，完善血常规检查明确嗜酸性粒细胞计数及比例，评估感染活动度并作为治疗随访指标；肺吸虫病的病原学确诊依据为痰中查见虫卵，完善痰找虫卵（痰涂片镜检找肺吸虫卵）明确诊断；完善血清特异性抗体检查（ELISA，肺吸虫、囊虫或血吸虫抗体），明确感染病原种类，指导吡喹酮或阿苯达唑的选用；因虫卵可随痰或粪排出，完善粪便虫卵检查（肺吸虫或血吸虫虫卵）了解有无消化道排虫，提高病原检出率；患者有游走性皮下包块，必要时行皮下结节活检明确有无囊虫或裂头蚴感染，为诊断提供组织学依据；患者有头痛、抽搐，提示脑型肺吸虫或脑囊虫可能，完善头颅CT或MRI检查明确有无颅内病灶、脑水肿及占位，评估中枢神经系统受累并指导是否需激素预防脑水肿；因需长期使用吡喹酮或阿苯达唑，治疗前完善肝肾功能与心电图检查，明确基础肝肾功能及心律情况，作为用药安全性与疗程中随访的基线；治疗期间定期复查血常规（嗜酸性粒细胞）及胸部影像，评估病灶吸收与疗效。\n\n（检查清单）\n【必做】胸部X线片或CT（肺吸虫：多房囊状阴影、隧道征、胸膜肥厚积液；血吸虫：粟粒样结节）、血常规（嗜酸性粒细胞显著升高，寄生虫感染特征）、痰找虫卵（肺吸虫卵）、血清特异性抗体（ELISA，肺吸虫或囊虫或血吸虫抗体）；【其他】粪便虫卵（肺吸虫或血吸虫，虫卵可随痰或粪排出）、皮下结节活检（囊虫或裂头蚴）、头颅CT或MRI（脑囊虫或脑型肺吸虫）。","初步诊断":"1. 肺寄生虫病（肺吸虫病：肺吸虫病，待病原学确诊）\n（注：肺吸虫病，吡喹酮25mg/kg tid×3天（首选，治愈率高）；脑囊虫病，阿苯达唑15mg/kg/d×8~30天（多疗程），治疗中激素预防脑水肿（囊虫死亡反应）；肺血吸虫，吡喹酮（40mg/kg单剂或分2次）；预防为主：不生食淡水蟹虾、不饮生水、不接触疫水、注意饮食卫生；治疗期间随访嗜酸性粒细胞及影像吸收，合并脑囊虫者神经科协作（癫痫处理）。）","处理方案":"【药物治疗】\n1. 首选抗吸虫治疗，予吡喹酮片（广谱抗吸虫药）：成人每次25mg/kg，每日3次，连服2~3天（总剂量约150mg/kg），餐间半空腹温水送服，用于肺吸虫病；肺血吸虫病可予总剂量60mg/kg，分2日、每日3次口服。\n2. 肺包虫病（棘球蚴病）首选阿苯达唑片：成人400mg，每日2次，连服3~6个月为一疗程，可连续2~3个疗程（疗程间隔2周），服药期间每月监测肝功能。\n3. 对症治疗：咳嗽痰多者予氨溴索片30mg tid祛痰；咯血明显者予酚磺乙胺片0.5g tid口服止血；继发细菌感染者可加用阿莫西林克拉维酸钾片0.457g tid×7天。\n【一般治疗及生活指导】\n1. 休息：急性期或发热、咯血明显者卧床休息，避免剧烈活动及重体力劳动；恢复期注意劳逸结合，保证充足睡眠。\n2. 饮食：给予高蛋白、高维生素、易消化饮食，保证热量；忌烟酒及辛辣刺激性食物，咯血期进温凉流质或半流质饮食。\n3. 禁忌与预防：严禁进食未煮熟的溪蟹、蝲蛄、醉蟹、生鱼片及生虾等（肺吸虫等主要感染途径）；包虫病流行区避免与犬类密切接触，防止犬粪污染水源和食物，饭前便后洗手。\n4. 活动：咯血停止、病情稳定后逐步恢复日常活动，保持居室通风，避免受凉感冒诱发继发感染。\n【随诊要求】\n1. 治疗结束后1个月复查胸部X线或CT，评估肺部病灶吸收情况，必要时3个月后再次复查。\n2. 每1~2个月复查外周血嗜酸性粒细胞计数，直至恢复正常。\n3. 肺包虫病服用阿苯达唑期间每1~3个月复查肝功能、肾功能及血常规，出现黄疸、肝区不适、食欲减退时随时复诊。\n4. 治疗期间或随访中咳嗽、咯血、胸痛等原有症状复发或加重，或出现新发症状（如头痛、癫痫发作提示脑型病变）应立即复诊；完成疗程后建议每3~6个月随访一次，共1~2年。"},"icd10_diagnosis":"","icd10_secondary":[],"icd9cm3_procedure":[]}},"locator":{"file":"门诊住院病历模板/病历模板包_全部_20261111.json","arrayRow":398,"caseRow":1},"sourceHash":"10e4fdb435986b7b85f847c3951d0cb0eafdce0f372c5617949c05b337149194","contentHash":"904836892b9bd2b4763b64f970fe68e146b3ef70221b90566464a121e0d5ed03","pinyin":"feijishengchongbing","initials":"fjscb","setting":"out","caseName":"门诊病历263","templateNames":["主诉","现病史","既往史","个人史及过敏史","体格检查","辅助检查","初步诊断","处理方案"],"emptyTemplates":[],"escapedNewlines":[],"quickFields":[["病例名称","门诊病历263",60],["模板名称","主诉 现病史 既往史 个人史及过敏史 体格检查 辅助检查 初步诊断 处理方案",30],["主要诊断编码","",30]]},{"id":"templates-cc0e7d165ac54394c60e","key":"v1-c9ccc21dfe2a3058|templates-cc0e7d165ac54394c60e","module":"templates","moduleKey":"v1-c9ccc21dfe2a3058|templates","version":"v1-c9ccc21dfe2a3058","title":"职业性肺病","category":"门诊病历模板","raw":{"name":"职业性肺病","category":"门诊病历模板","case":{"case_name":"门诊病历264","templates":{"主诉":"咳嗽、气短进行性加重2年","现病史":"患者从事采矿（采矿/石棉/纺织/焊接/农业等）职业10年，长期接触矽尘（矽尘/石棉尘/煤尘/棉尘/电焊烟尘等），于8年前渐出现咳嗽、咳痰、活动后气短进行性加重，脱离接触后症状仍进展（缓解/仍进展），无胸痛、咯血、发热（有无胸痛、咯血、发热），痰无黑痰（有无黑痰，煤工尘肺）。今日来我院门诊就诊。","既往史":"既往体健，否认高血压、糖尿病、冠心病等慢性病史。否认肝炎、结核等传染病史。否认手术外伤史。否认食物药物过敏史。预防接种史随社会。","个人史及过敏史":"生于原籍，久居本地，无疫区疫水接触史，无特殊粉尘毒物放射性物质接触史。不吸烟，不饮酒。生活规律。否认食物药物过敏史。","体格检查":"T36.6℃，P82次/分，R20次/分，BP124/78mmHg，SpO2 94%。神志清楚，呼吸稍促，口唇无发绀（无发绀）。双肺呼吸音减低（减低），可闻及干湿啰音（干湿啰音或爆裂音，石棉肺），杵状指（+/-）。心界正常。","辅助检查":"【必做】胸部X线片（矽肺：小结节影、大阴影、肺门蛋壳样钙化；石棉肺：胸膜斑、弥漫间质纤维化，按尘肺X线诊断标准分级）、肺功能（限制性通气障碍：FVC、DLCO下降）、血气分析；【影像学】胸部HRCT（早期病变及间质纤维化评估）；【其他】肺活检（疑诊职业性肺病诊断困难时）。","初步诊断":"1. 职业性尘肺病（壹期：矽肺）\n（注：本病无特效治愈方法，核心为：①立即脱离粉尘接触环境（调离岗位），最重要；②对症治疗（止咳祛痰、支气管扩张剂，气流受限者、家庭氧疗（低氧时））；③防治并发症（肺结核，矽肺易合并结核需定期筛查；呼吸道感染，疫苗；肺心病）；④肺康复锻炼；⑤职业病患者劳动能力鉴定及工伤保险待遇；石棉接触者注意间皮瘤、肺癌长期监测（戒烟）；定期随访胸片及肺功能。）","处理方案":"【药物治疗】\n1. 延缓肺纤维化：汉防己甲素片60mg po tid，3个月为1疗程，间隔1~2个月可重复疗程，用药期间定期复查肝功能。\n2. 止咳祛痰：盐酸氨溴索片30mg po tid×7~14天；或乙酰半胱氨酸泡腾片600mg po qd。\n3. 解痉平喘（合并气流受限时）：噻托溴铵粉雾剂18μg吸入 qd；喘息急性发作时沙丁胺醇气雾剂100~200μg按需吸入。\n4. 合并细菌感染（脓痰、发热、感染指标升高）：阿莫西林克拉维酸钾片0.375g po tid×7天；青霉素过敏者改用左氧氟沙星片0.5g po qd×7天。\n\n【一般治疗及生活指导】\n1. 立即脱离粉尘作业环境，调离粉尘作业岗位，避免继续接触各类生产性粉尘及刺激性气体。\n2. 戒烟并避免二手烟，加强营养，予高蛋白、高维生素易消化饮食，保证充足睡眠，预防呼吸道感染。\n3. 坚持呼吸功能锻炼（缩唇呼吸、腹式呼吸），依据心肺功能进行散步、太极拳等低强度有氧活动，避免剧烈运动及过度劳累。\n4. 冬春季接种流感疫苗及23价肺炎球菌多糖疫苗，减少急性加重发作。\n\n【随诊要求】\n1. 每6~12个月复查肺功能及血氧饱和度，每1~2年行胸部X线或HRCT检查，按GBZ 70标准动态随访观察。\n2. 每年接受职业病健康检查及尘肺病诊断复查，适时进行劳动能力鉴定。\n3. 出现咳嗽咳痰加重、咯血、胸痛、进行性呼吸困难、发绀或发热时，随时返院就诊。"},"icd10_diagnosis":"","icd10_secondary":[],"icd9cm3_procedure":[]}},"locator":{"file":"门诊住院病历模板/病历模板包_全部_20261111.json","arrayRow":399,"caseRow":1},"sourceHash":"10e4fdb435986b7b85f847c3951d0cb0eafdce0f372c5617949c05b337149194","contentHash":"15caebe55a6fd3244788f8faf6682fb2934ff0f127fb84304c292dbf9ed9ecbe","pinyin":"zhiyexingfeibing","initials":"zyxfb","setting":"out","caseName":"门诊病历264","templateNames":["主诉","现病史","既往史","个人史及过敏史","体格检查","辅助检查","初步诊断","处理方案"],"emptyTemplates":[],"escapedNewlines":[],"quickFields":[["病例名称","门诊病历264",60],["模板名称","主诉 现病史 既往史 个人史及过敏史 体格检查 辅助检查 初步诊断 处理方案",30],["主要诊断编码","",30]]},{"id":"templates-a64a804972713004592c","key":"v1-c9ccc21dfe2a3058|templates-a64a804972713004592c","module":"templates","moduleKey":"v1-c9ccc21dfe2a3058|templates","version":"v1-c9ccc21dfe2a3058","title":"放射性肺炎","category":"门诊病历模板","raw":{"name":"放射性肺炎","category":"门诊病历模板","case":{"case_name":"门诊病历265","templates":{"主诉":"干咳、气短伴低热2周","现病史":"患者因肺癌（肺癌/乳腺癌/食管癌/淋巴瘤等）于2026年03月接受胸部放射治疗，累及右肺野，总剂量60Gy，放疗结束后4周出现干咳、活动后气短、低热（体温波动于37.3~38℃）、胸痛，无咯血（有无咯血），症状进行性加重，抗感染治疗（抗生素）无效。今日来我院门诊就诊。","既往史":"既往体健，否认高血压、糖尿病、冠心病等慢性病史。否认肝炎、结核等传染病史。否认手术外伤史。否认食物药物过敏史。预防接种史随社会。","个人史及过敏史":"生于原籍，久居本地，无疫区疫水接触史，无特殊粉尘毒物放射性物质接触史。不吸烟，不饮酒。生活规律。否认食物药物过敏史。","体格检查":"T37.6℃，P92次/分，R22次/分，BP126/78mmHg，SpO2 94%。神志清楚，呼吸促，口唇无发绀。放疗区域皮肤色素沉着（色素沉着/纤维化），双肺右肺（放疗野相应部位）呼吸音减低，可闻及爆裂音（湿啰音或爆裂音）。","辅助检查":"【必做】胸部CT（放疗野内片状磨玻璃影或实变影、纤维化条索，与放射野一致的分布特征，诊断关键）、血常规、CRP、肺功能（弥散功能下降）、血气分析；【鉴别】痰培养（排除感染）、肿瘤标志物（排除肿瘤进展）；【其他】支气管镜（鉴别肿瘤复发或感染）。","初步诊断":"1. 放射性肺炎（急性期：急性期（放疗后1~3个月））\n（注：轻症（无呼吸困难），观察随访，多数自行吸收；症状明显（咳嗽、气短、发热）：糖皮质激素（泼尼松30~60mg/d，症状缓解后渐减，疗程常需4~12周，切忌骤停致反跳）+对症（镇咳、吸氧（低氧时））；继发感染加抗生素；纤维化期（不可逆）：长期氧疗、肺康复、防治感染，尼达尼布（放射性肺纤维化，部分证据）专科评估；与放疗科协作调整后续放疗计划；戒烟。）","处理方案":"【药物治疗】\n1.糖皮质激素（首选核心治疗）：泼尼松片（强的松）30-60mg/d（0.5-1mg/kg）晨起顿服，症状缓解后每1-2周减量5-10mg，总疗程4-12周，缓慢减停，避免骤停致病情反跳；重症或进展快者可用甲泼尼龙片24-48mg/d替代。\n2.镇咳：右美沙芬片15-30mg tid po×5-7天，或复方甲氧那明胶囊2粒 tid po×5-7天，剧烈干咳影响休息者选用。\n3.祛痰：盐酸氨溴索片30mg tid po×7-14天，或乙酰半胱氨酸泡腾片600mg qd po×7-14天，稀释痰液促进排痰。\n4.继发细菌感染时（发热、脓痰、血象升高等）加用：阿莫西林克拉维酸钾片0.625g tid po×7天，或左氧氟沙星片0.5g qd po×7天。\n【一般治疗及生活指导】\n1.休息：急性期卧床休息或减少活动，避免劳累及剧烈运动，保证充足睡眠，减轻心肺负担。\n2.饮食：高蛋白、高维生素、易消化饮食，每日饮水1500-2000ml以稀释痰液；忌辛辣刺激及过咸饮食，禁烟酒。\n3.防护：避免受凉、预防上呼吸道感染，少去人群密集场所；保持室内空气流通湿润（相对湿度50%-60%），必要时可戴口罩减少刺激性气体、粉尘吸入。\n4.随访放疗计划：遵放疗科安排完成或调整后续放疗；放疗区域皮肤保持清洁干燥，避免摩擦、搔抓及暴晒。\n【随诊要求】\n1.治疗期间每2-4周复诊1次，评估咳嗽、气促、发热等症状变化及胸部CT改变，据此调整激素剂量；切勿自行停药或减量。\n2.若出现进行性呼吸困难、口唇发绀、咯血或新发发热，须立即就近急诊就诊。\n3.疗程结束后每3-6个月复查胸部CT及肺功能（含弥散功能），随访至少1年，动态观察肺纤维化进展及原发肿瘤变化。\n4.长期使用激素者定期监测血压、血糖，注意骨质疏松及继发感染等不良反应，必要时予补钙及维生素D。"},"icd10_diagnosis":"","icd10_secondary":[],"icd9cm3_procedure":[]}},"locator":{"file":"门诊住院病历模板/病历模板包_全部_20261111.json","arrayRow":400,"caseRow":1},"sourceHash":"10e4fdb435986b7b85f847c3951d0cb0eafdce0f372c5617949c05b337149194","contentHash":"a3201989f47cdccc3e070b249b04a41678860689cebeddad8e4fa15304dac0cd","pinyin":"fangshexingfeiyan","initials":"fsxfy","setting":"out","caseName":"门诊病历265","templateNames":["主诉","现病史","既往史","个人史及过敏史","体格检查","辅助检查","初步诊断","处理方案"],"emptyTemplates":[],"escapedNewlines":[],"quickFields":[["病例名称","门诊病历265",60],["模板名称","主诉 现病史 既往史 个人史及过敏史 体格检查 辅助检查 初步诊断 处理方案",30],["主要诊断编码","",30]]},{"id":"templates-babdee5d861fd0187ada","key":"v1-c9ccc21dfe2a3058|templates-babdee5d861fd0187ada","module":"templates","moduleKey":"v1-c9ccc21dfe2a3058|templates","version":"v1-c9ccc21dfe2a3058","title":"吸入性肺炎","category":"门诊病历模板","raw":{"name":"吸入性肺炎","category":"门诊病历模板","case":{"case_name":"门诊病历266","templates":{"主诉":"误吸后发热、咳嗽伴呼吸困难3天","现病史":"患者（存在吞咽困难/意识障碍/胃食管反流/气管食管瘘/长期卧床等误吸高危因素）于3天前发生进食呛咳（进食呛咳/呕吐物误吸/胃内容物反流吸入）后出现发热（体温最高38.9℃）、咳嗽、咳脓臭痰（泡沫痰或脓臭痰，厌氧菌感染）、气促、胸痛，无发绀、无意识改变（有无发绀、意识改变），进食水呛咳史：有进食水呛咳史。今日来我院急诊就诊。","既往史":"既往体健，否认高血压、糖尿病、冠心病等慢性病史。否认肝炎、结核等传染病史。否认手术外伤史。否认食物药物过敏史。预防接种史随社会。","个人史及过敏史":"生于原籍，久居本地，无疫区疫水接触史，无特殊粉尘毒物放射性物质接触史。不吸烟，不饮酒。生活规律。否认食物药物过敏史。","体格检查":"T38.9℃，P104次/分，R24次/分，BP118/72mmHg，SpO2 92%。神志清楚，呼吸急促，口唇发绀（+），口腔卫生差（差）。双肺可闻及右下肺湿啰音（右下肺或双下肺湿啰音，重力依赖区），叩诊浊音（浊音，实变或肺不张）。心率104次/分。","辅助检查":"【必做】胸部X线片或CT（右下肺背段实变影、坏死空洞，好发部位提示误吸）、血常规（白细胞升高）、CRP、血气分析（低氧血症）、痰培养+药敏（含厌氧菌培养）；【其他】吞咽功能评估（反复误吸者，饮水试验、吞咽造影）、支气管镜（吸出异物或脓性分泌物，诊断及治疗）。","初步诊断":"1. 吸入性肺炎（右下肺：右下肺）\n（注：治疗：①防止再误吸，床头抬高30~45°、暂停经口进食（必要时鼻饲）、口咽分泌物吸引；②抗感染（覆盖厌氧菌，吸入性肺炎常见混合感染）：轻中度阿莫西林克拉维酸0.625g tid或哌拉西林他唑巴坦，重症（院内或坏死性肺炎）用碳青霉烯类（美罗培南）或万古霉素（MRSA高危）+甲硝唑或克林霉素，疗程7~14天（坏死性更长）；③氧疗或呼吸支持、补液、气道廓清；④治疗基础病（脑血管病吞咽障碍康复训练、抗反流）。）","处理方案":"【药物治疗】\n1.抗感染治疗（覆盖口咽部厌氧菌，门诊轻中度首选）：阿莫西林克拉维酸钾片0.457g（含阿莫西林0.4g）口服，每次1片，每日3次，疗程7～10天；对青霉素过敏者改用莫西沙星片0.4g口服，每日1次，疗程7天。厌氧菌感染证据明显（口腔卫生差、坏死性肺炎）者联用甲硝唑片0.4g口服，每日3次，疗程7天。\n2.祛痰治疗：盐酸氨溴索片30mg口服，每日3次，疗程5～7天；或乙酰半胱氨酸泡腾片600mg溶于温水后口服，每日1次，疗程5～7天，稀释痰液、促进排痰。\n3.对症治疗：发热或胸痛明显者，予布洛芬缓释胶囊0.3g口服，每日2次，按需使用，不超过3天。\n【一般治疗及生活指导】\n1.进食体位：进食时及餐后30～60分钟内保持坐位或半卧位，床头抬高30°～45°，严禁平卧进食；小口慢咽、细嚼慢咽，进食时不说话，防止再次误吸。\n2.口腔护理：每日早晚及饭后刷牙、漱口，保持口腔清洁，减少口咽部致病菌定植；佩戴义齿者每日取下清洁。\n3.休息与饮食：急性期注意休息、保证充足睡眠、避免劳累；饮食清淡易消化、富含蛋白质，避免辛辣刺激及过冷过热食物，吞咽欠佳者食物宜软烂糊状并适当增稠。\n4.活动指导：症状好转后循序渐进恢复日常活动，避免剧烈运动诱发呛咳；有咳嗽反射减弱或吞咽困难者避免独自进食。\n【随诊要求】\n1.用药3～5天后复诊，评估体温、咳嗽咳痰及肺部体征变化；若用药72小时仍持续发热或症状加重，立即复诊或急诊就诊。\n2.疗程结束后复查血常规、C反应蛋白及胸部影像学，评估炎症控制及病灶吸收情况。\n3.反复发生误吸（如脑血管病后遗症、吞咽功能障碍者）建议转诊康复科行吞咽功能评估及摄食训练，预防复发。"},"icd10_diagnosis":"","icd10_secondary":[],"icd9cm3_procedure":[]}},"locator":{"file":"门诊住院病历模板/病历模板包_全部_20261111.json","arrayRow":401,"caseRow":1},"sourceHash":"10e4fdb435986b7b85f847c3951d0cb0eafdce0f372c5617949c05b337149194","contentHash":"7ce75ad15060f34df8544bc34960620b42d7d0213e13268f4cbf70591eb4ae92","pinyin":"xiruxingfeiyan","initials":"xrxfy","setting":"out","caseName":"门诊病历266","templateNames":["主诉","现病史","既往史","个人史及过敏史","体格检查","辅助检查","初步诊断","处理方案"],"emptyTemplates":[],"escapedNewlines":[],"quickFields":[["病例名称","门诊病历266",60],["模板名称","主诉 现病史 既往史 个人史及过敏史 体格检查 辅助检查 初步诊断 处理方案",30],["主要诊断编码","",30]]},{"id":"templates-03b5552096be68e08436","key":"v1-c9ccc21dfe2a3058|templates-03b5552096be68e08436","module":"templates","moduleKey":"v1-c9ccc21dfe2a3058|templates","version":"v1-c9ccc21dfe2a3058","title":"高血压急症","category":"门诊病历模板","raw":{"name":"高血压急症","category":"门诊病历模板","case":{"case_name":"门诊病历267","templates":{"主诉":"血压急剧升高伴头痛、呕吐3小时","现病史":"患者有高血压病史10年，平素血压控制不佳，未规律服药（服药情况），于6小时前停降压药（停降压药/情绪激动/劳累/摄入大量盐/拟交感药物后）出现血压急剧升高（达200/120mmHg），伴剧烈头痛、恶心呕吐、视物模糊（剧烈头痛、恶心呕吐、视物模糊，高血压脑病；胸痛、呼吸困难，急性心衰或主动脉夹层；偏瘫失语抽搐，脑卒中；血尿少尿，肾损害；心悸大汗，嗜铬细胞瘤危象），意识清楚。今日来我院急诊就诊。","既往史":"既往体健，否认高血压、糖尿病、冠心病等慢性病史。否认肝炎、结核等传染病史。否认手术外伤史。否认食物药物过敏史。预防接种史随社会。","个人史及过敏史":"生于原籍，久居本地，无疫区疫水接触史，无特殊粉尘毒物放射性物质接触史。不吸烟，不饮酒。生活规律。否认食物药物过敏史。","体格检查":"T____℃，P____次/分，R____次/分，左上肢BP____/____mmHg，右上肢BP____/____mmHg（双上肢差>20mmHg疑主动脉夹层）。神志____（清楚/嗜睡/昏迷），____（有无视盘水肿（眼底镜）、颈静脉怒张、肺部啰音（心衰）、心界扩大、神经系统体征（偏瘫/病理征））。","辅助检查":"检查计划：患者高血压病史10年、平素未规律服药且6小时前自行停用降压药，血压急剧升至200/120mmHg并出现剧烈头痛、恶心呕吐、视物模糊，提示高血压脑病，急诊即刻完善心电图检查以明确有无心肌缺血或左室肥厚等高血压心脏损害；患者血压重度升高存在心肌灌注不足风险，查心肌肌钙蛋白排除急性心肌损伤；血压急剧升高可致肾灌注下降及急性肾损伤，完善肾功能（肌酐、eGFR）检查明确有无肾损害并指导静脉降压药物选择与剂量调整；患者呕吐明显且有脱水可能，完善电解质检查排除低钾低钠等电解质紊乱所致心律失常；查尿常规了解有无蛋白尿或血尿以评估高血压肾损害程度；患者诉视物模糊，急诊完善眼底检查明确有无高血压视网膜病变及视乳头水肿，评估高血压脑病严重程度；患者有头痛呕吐等神经系统症状，急诊完善头颅CT检查排除脑出血或脑梗死；患者存在急性左心衰风险，查胸部X线片明确有无肺水肿及心影增大；患者血压急剧升高需警惕主动脉夹层，如有胸痛、呼吸困难或双上肢血压不对称，急诊完成主动脉CTA明确有无主动脉夹层，决不允许漏诊；患者为育龄女性时需完善妊娠试验排除妊娠期高血压疾病（子痫前期）以免影响降压药物选择；住院期间在ICU/CCU严密监测下静脉降压，定期复查血压、心电图及肾功能以评估靶器官灌注与降压安全性。\n\n（检查清单）\n【必做】心电图（心肌缺血或左室肥厚）、心肌肌钙蛋白、肾功能（肌酐、eGFR）、电解质、尿常规（蛋白尿或血尿）、眼底检查；【影像学】头颅CT（脑出血或梗死，神经症状时）、胸部X线片（肺水肿，心衰时）、主动脉CTA（疑主动脉夹层）；【其他】妊娠试验（育龄女性，子痫前期）。","初步诊断":"1. 高血压急症（血压200/120mmHg，伴高血压脑病靶器官损害：高血压脑病）\n（注：高血压急症为内科急症，需急诊住院，在ICU/CCU严密监测下静脉降压：目标为第1小时平均动脉压下降不超过25%，随后2~6小时降至160/100~110mmHg，24~48小时逐步降至正常（除外主动脉夹层或子痫，需更快降至安全范围：夹层目标收缩压100~120mmHg、心率60次/分）；常用药：乌拉地尔、尼卡地平、硝普钠（夹层或重症）、拉贝洛尔（妊娠或卒中）、硝酸甘油（急性心衰或冠脉综合征）；避免过快降压（致脑、肾、冠脉灌注不足）；查明并去除诱因（停药依从性、继发性高血压筛查）。）","处理方案":"【药物治疗】\n1. 乌拉地尔注射液：首剂12.5mg用生理盐水稀释后缓慢静脉注射（5分钟以上），继以100~400μg/min持续静脉泵入，每5~10分钟根据血压调整泵速；1小时内收缩压下降不超过25%，2~6小时内逐步降至160/100mmHg左右，达标后维持24~72小时，再逐渐减量并过渡为口服降压药。\n2. 硝普钠注射液：以0.5μg/(kg·min)起始持续静脉泵入，每5~10分钟递增0.5μg/(kg·min)，常用3μg/(kg·min)，最大不超过10μg/(kg·min)；需避光输注，疗程不超过72小时，用药期间持续监测血压并警惕氰化物蓄积（适用于合并急性左心衰、肺水肿者）。\n3. 血压平稳后口服维持治疗：氨氯地平片5mg qd，晨起口服；联合缬沙坦胶囊80mg qd。长期服用，1周后复诊评估，未达标者每1~2周调整剂量（氨氯地平可增至10mg qd，缬沙坦可增至160mg qd），并复查肾功能、电解质以指导用药。\n\n【一般治疗及生活指导】\n1. 急性期绝对卧床休息，保持环境安静，避免情绪激动、用力排便、剧烈咳嗽及屏气等诱发血压骤升的行为。\n2. 严格低盐低脂饮食（每日食盐<5g），戒烟限酒，忌浓茶、咖啡等刺激性饮品，少量多餐，避免饱餐。\n3. 每日早晚各测量1次血压并记录（晨起及睡前各一次），同时监测心率；如出现剧烈头痛、胸痛、呼吸困难、视物模糊或肢体麻木，立即急诊就诊。\n4. 急性期避免剧烈活动和热水浴，改变体位时动作缓慢，防止体位性低血压及跌倒。\n\n【随诊要求】\n1. 静脉降压治疗期间患者急诊留观或住院持续监测血压，不得自行离院；出院后1周内门诊复诊，复查血压、血电解质及肾功能，调整口服降压方案。\n2. 血压达标（<140/90mmHg）后每1~3个月门诊复诊1次，每3~6个月复查心电图、肾功能、尿常规及眼底检查，评估靶器官损害。\n3. 若血压持续升高（≥180/120mmHg）且伴上述任一危重症状，应立即急诊就诊，不可等待预约复诊；调整降压药物医师指导下进行，切勿自行停药或增减剂量。"},"icd10_diagnosis":"","icd10_secondary":[],"icd9cm3_procedure":[]}},"locator":{"file":"门诊住院病历模板/病历模板包_全部_20261111.json","arrayRow":402,"caseRow":1},"sourceHash":"10e4fdb435986b7b85f847c3951d0cb0eafdce0f372c5617949c05b337149194","contentHash":"d3c986607ec66e37220da5ec74ac37474cd876d23bee3e70571a54f20406b278","pinyin":"gaoxueyajizheng","initials":"gxyjz","setting":"out","caseName":"门诊病历267","templateNames":["主诉","现病史","既往史","个人史及过敏史","体格检查","辅助检查","初步诊断","处理方案"],"emptyTemplates":[],"escapedNewlines":[],"quickFields":[["病例名称","门诊病历267",60],["模板名称","主诉 现病史 既往史 个人史及过敏史 体格检查 辅助检查 初步诊断 处理方案",30],["主要诊断编码","",30]]},{"id":"templates-216154083f9efbf13e79","key":"v1-c9ccc21dfe2a3058|templates-216154083f9efbf13e79","module":"templates","moduleKey":"v1-c9ccc21dfe2a3058|templates","version":"v1-c9ccc21dfe2a3058","title":"高血压亚急症","category":"门诊病历模板","raw":{"name":"高血压亚急症","category":"门诊病历模板","case":{"case_name":"门诊病历268","templates":{"主诉":"血压显著升高伴头痛、头晕1周","现病史":"患者有高血压病史5年，平素口服氨氯地平片（降压药），近3天（停药/漏服/情绪波动/劳累/大量饮酒后）血压升高（家庭自测达186/112mmHg），伴头痛、头晕、鼻出血、心悸，无胸痛，无气短，无肢体麻木无力，无言语不清，无视力模糊。意识清楚，排尿正常。今日来我院门诊就诊。","既往史":"既往体健，否认高血压、糖尿病、冠心病等慢性病史。否认肝炎、结核等传染病史。否认手术外伤史。否认食物药物过敏史。预防接种史随社会。","个人史及过敏史":"生于原籍，久居本地，无疫区疫水接触史，无特殊粉尘毒物放射性物质接触史。不吸烟，不饮酒。生活规律。否认食物药物过敏史。","体格检查":"T36.5℃，P88次/分，R18次/分，BP186/112mmHg（坐位，双侧，休息5分钟后复测确认）。神志清楚，查体合作。眼底未见出血渗出，无视盘水肿，心肺听诊未见明显异常，腹软无压痛，神经系统检查无阳性体征，双下肢无水肿。","辅助检查":"【必做】尿常规、肾功能、电解质、血糖、血脂、心电图；【其他】超声心动图（左室肥厚评估，慢性靶器官损害）、眼底检查。","初步诊断":"1. 高血压亚急症（血压显著升高，无明显急性靶器官损害）\n（注：与高血压急症的关键鉴别：亚急症无急性靶器官损害，通常不需急诊静脉降压；处理：①恢复/调整口服降压药（寻找原因：依从性差、药物不足、继发因素）；②口服短效降压药过渡（如卡托普利12.5~25mg）后在门诊/急诊观察数小时，血压平稳（<160/100mmHg）后回家调整长期方案；③避免过快降压及舌下含服硝苯地平（可致急剧低血压、心脑血管事件，禁用）；④健康宣教（规律服药、监测血压、限盐减重）；若出现任何靶器官损害症状（胸痛、气短、神经症状、视力改变）立即按急症处理。）","处理方案":"【药物治疗】\n1.血管紧张素转换酶抑制剂（ACEI）：卡托普利片12.5mg tid po（餐前1小时服用），首剂服药后卧床观察1-2小时，若血压仍≥180/110mmHg可间隔1小时追加12.5mg，单次不超过25mg；疗程1周，1周后复诊，血压平稳后换用长效制剂（如培哚普利片4mg qd po）长期维持。用药期间监测血钾、肌酐，出现持续性干咳或血管神经性水肿（口唇、面部肿胀）立即停药就诊。\n2.钙通道阻滞剂（CCB）：氨氯地平片5mg qd po，晨服，连用4周；若1周后血压仍≥140/90mmHg可加量至10mg qd。禁用舌下含服硝苯地平普通片，以免血压骤降诱发心脑血管缺血事件；用药后出现明显踝部水肿、面部潮红者复诊调整。\n3.β受体阻滞剂：适用于静息心率≥80次/分或合并冠心病者，美托洛尔缓释片47.5mg qd po，晨服，疗程≥4周；静息心率<55次/分或出现明显乏力、头晕时减至23.75mg qd或停药，不宜突然停药。\n4.利尿剂：伴双下肢水肿、尿量减少等容量负荷过重者，氢氯噻嗪片12.5mg qd po，晨服，疗程3-5天；用药期间监测血钾、尿酸、血糖，低钾血症、痛风急性发作期禁用。\n\n【一般治疗及生活指导】\n1.休息：急性期血压未降至160/100mmHg以下前，避免剧烈活动、情绪激动、用力排便及屏气动作，保证每晚睡眠7-8小时，可午后小憩30分钟。\n2.饮食：严格低盐低脂饮食，每日钠盐摄入<5g（约一啤酒瓶盖），忌咸菜、腊肉、腌制品及浓茶、咖啡，戒烟限酒（男性酒精<25g/d，女性<15g/d）。\n3.运动：血压达标且头晕、心悸等症状消失后，开始规律中等强度有氧运动（快走、太极拳、慢跑、游泳等），每周≥5次、每次30-40分钟，运动中心率控制在（170-年龄）次/分以内，运动前后各热身放松5-10分钟。\n4.监测与服药：每日早晚固定时间（6:00-8:00、18:00-20:00）各测血压1次并记录；严格遵医嘱规律服药，不可擅自停药、减量或自行换药，避免血压波动。\n\n【随诊要求】\n1.首诊用药后24-48小时门诊复诊，复查血压并评估药物疗效及不良反应；1周后再次复诊，根据血压水平决定药物调整方案。\n2.血压达标（<140/90mmHg，≥65岁老年人<150/90mmHg）后每2-4周复诊1次，稳定后每1-3个月随访1次，定期复查血常规、肝肾功能、电解质、血脂、血糖、尿常规及心电图。\n3.若居家监测血压持续≥180/120mmHg，或出现剧烈头痛、胸痛、胸闷、呼吸困难、视物模糊、言语不清、肢体麻木无力、晕厥等任一靶器官损害表现，立即急诊就诊，不得等待预约复诊。"},"icd10_diagnosis":"","icd10_secondary":[],"icd9cm3_procedure":[]}},"locator":{"file":"门诊住院病历模板/病历模板包_全部_20261111.json","arrayRow":403,"caseRow":1},"sourceHash":"10e4fdb435986b7b85f847c3951d0cb0eafdce0f372c5617949c05b337149194","contentHash":"fe677adf7b2992fefd513423efbba4b08b03b88ee011babd61ffa77d582a6b57","pinyin":"gaoxueyayajizheng","initials":"gxyyjz","setting":"out","caseName":"门诊病历268","templateNames":["主诉","现病史","既往史","个人史及过敏史","体格检查","辅助检查","初步诊断","处理方案"],"emptyTemplates":[],"escapedNewlines":[],"quickFields":[["病例名称","门诊病历268",60],["模板名称","主诉 现病史 既往史 个人史及过敏史 体格检查 辅助检查 初步诊断 处理方案",30],["主要诊断编码","",30]]},{"id":"templates-71f95b7ae96616aea3f2","key":"v1-c9ccc21dfe2a3058|templates-71f95b7ae96616aea3f2","module":"templates","moduleKey":"v1-c9ccc21dfe2a3058|templates","version":"v1-c9ccc21dfe2a3058","title":"主动脉瘤","category":"门诊病历模板","raw":{"name":"主动脉瘤","category":"门诊病历模板","case":{"case_name":"门诊病历269","templates":{"主诉":"腹部搏动性包块伴隐痛1月","现病史":"患者于2周前（体检/因他病检查）发现腹主动脉瘤（直径约4.8cm），近2周自觉腹部隐痛/搏动感，无腰背部放射痛，无突发剧痛（破裂先兆/破裂征象，需急诊），无下肢缺血表现，无声音嘶哑、吞咽困难（压迫症状），无高血压（控制情况）、动脉粥样硬化、马凡综合征、吸烟及家族性动脉瘤史。今日来我院门诊就诊。","既往史":"既往体健，否认高血压、糖尿病、冠心病等慢性病史。否认肝炎、结核等传染病史。否认手术外伤史。否认食物药物过敏史。预防接种史随社会。","个人史及过敏史":"生于原籍，久居本地，无疫区疫水接触史，无特殊粉尘毒物放射性物质接触史。不吸烟，不饮酒。生活规律。否认食物药物过敏史。","体格检查":"T36.4℃，P76次/分，R18次/分，BP138/82mmHg（双上肢/下肢血压）。神志清楚，查体合作。腹平软，脐周可触及搏动性膨胀性包块，约5cm宽，轻压痛，腹部血管杂音（-），双下肢皮温正常、动脉搏动正常，足背动脉搏动存在。","辅助检查":"【必做】腹部超声（腹主动脉内径，筛查及随访首选）、CTA（主动脉全程三维，精确测量瘤体大小、形态、累及分支，术前必备）；【影像学】腹部X线（动脉瘤壁钙化影）、MRA（造影剂禁忌者）；【其他】血常规、肾功能（术前评估）、动脉瘤破裂时急诊血红蛋白动态监测。","初步诊断":"1. 腹主动脉瘤（直径4.8cm）\n（注：随访与干预依据直径及增长速度：腹主动脉瘤<5.5cm（男）或<5.0cm（女），每6~12个月超声随访（快速增大（>1cm/年）需干预）；≥5.5cm（男）或≥5.0cm（女）、有症状或增长迅速：择期手术，腔内修复术（EVAR，首选）或开放手术（人工血管置换）；控制血压（β受体阻滞剂）、他汀、戒烟；若突发剧烈腹痛/腰背痛伴血压下降，高度提示破裂，为致命急症，需立即急诊（快速补液、急诊EVAR/手术）；筛查：65岁以上吸烟男性超声筛查。）","处理方案":"【药物治疗】\n1. 琥珀酸美托洛尔缓释片47.5mg qd po（首选β受体阻滞剂，控制静息心率60~70次/分、血压<130/80mmHg，降低主动脉壁张力及压力上升速率dP/dt，延缓瘤体扩张；心率不达标者可增至95mg qd或分次口服）\n2. 苯磺酸氨氯地平片5mg qd po（β受体阻滞剂基础上血压仍不达标时联用钙通道阻滞剂；血压≥160/100mmHg者初始可联合降压，逐步调整至目标血压）\n3. 阿托伐他汀钙片20mg qn po（动脉粥样硬化性主动脉瘤者长期降脂、稳定斑块，LDL-C目标<1.8mmol/L；合并高同型半胱氨酸血症者加叶酸0.8mg qd）\n\n【一般治疗及生活指导】\n1. 严格戒烟、限酒，低盐低脂、高纤维饮食，控制体重，保持大便通畅，避免用力排便及长期憋气（Valsalva动作）。\n2. 避免剧烈运动、提重物、负重、剧烈咳嗽及情绪激动等引起血压骤升的活动；日常可行散步等舒缓有氧运动，运动时心率不超过静息心率+20次/分。\n3. 每日早晚居家自测血压并记录，规律作息，保证睡眠；出现血压波动或头痛、胸闷时及时联系医师调整方案。\n\n【随诊要求】\n1. 每3~6个月门诊复诊，行超声或主动脉CTA复查，监测瘤体直径及扩张速度（半年内增大>0.5cm或直径达临界值者缩短复查间隔至1~3个月）。\n2. 出现突发胸背部或腹部撕裂样剧痛、晕厥、声嘶、吞咽困难、下肢缺血或腹痛放射至腰背时，立即急诊就诊，警惕瘤体破裂或夹层。\n3. 腹主动脉瘤最大径≥5cm、胸主动脉瘤≥5.5cm或短期内快速增大、出现压迫症状者，建议转血管外科/心脏大血管外科评估开放手术或腔内修复（EVAR）指征。"},"icd10_diagnosis":"","icd10_secondary":[],"icd9cm3_procedure":[]}},"locator":{"file":"门诊住院病历模板/病历模板包_全部_20261111.json","arrayRow":404,"caseRow":1},"sourceHash":"10e4fdb435986b7b85f847c3951d0cb0eafdce0f372c5617949c05b337149194","contentHash":"b66b595cc5d3062e875301e8819fe995aa6918237a8602ba2154fad672442b93","pinyin":"zhudongmailiu","initials":"zdml","setting":"out","caseName":"门诊病历269","templateNames":["主诉","现病史","既往史","个人史及过敏史","体格检查","辅助检查","初步诊断","处理方案"],"emptyTemplates":[],"escapedNewlines":[],"quickFields":[["病例名称","门诊病历269",60],["模板名称","主诉 现病史 既往史 个人史及过敏史 体格检查 辅助检查 初步诊断 处理方案",30],["主要诊断编码","",30]]},{"id":"templates-bbb50c29b28be7825419","key":"v1-c9ccc21dfe2a3058|templates-bbb50c29b28be7825419","module":"templates","moduleKey":"v1-c9ccc21dfe2a3058|templates","version":"v1-c9ccc21dfe2a3058","title":"周围动脉疾病","category":"门诊病历模板","raw":{"name":"周围动脉疾病","category":"门诊病历模板","case":{"case_name":"门诊病历270","templates":{"主诉":"行走后小腿疼痛2年，加重1月","现病史":"患者于3年前开始行走200米后出现小腿/大腿酸胀疼痛、乏力，休息5分钟后缓解（间歇性跛行），2月来行走距离明显缩短，夜间静息痛（患足抬高加重、下垂缓解，静息痛为重症信号），无足趾苍白发绀，无溃疡坏疽，无患肢发凉麻木，无糖尿病、高血压、血脂异常、吸烟等危险因素。今日来我院门诊就诊。","既往史":"既往体健，否认高血压、糖尿病、冠心病等慢性病史。否认肝炎、结核等传染病史。否认手术外伤史。否认食物药物过敏史。预防接种史随社会。","个人史及过敏史":"生于原籍，久居本地，无疫区疫水接触史，无特殊粉尘毒物放射性物质接触史。不吸烟，不饮酒。生活规律。否认食物药物过敏史。","体格检查":"T36.5℃，P78次/分，R18次/分，BP138/82mmHg（双上肢/双踝，计算踝肱指数ABI）。患肢皮肤苍白、皮温低，汗毛脱落、趾甲增厚、肌肉萎缩，足背动脉/胫后动脉搏动减弱，对侧正常，股动脉搏动可，血管杂音（-），足趾无溃疡、无坏疽、感觉减退。","辅助检查":"【必做】踝肱指数（ABI：正常1.0~1.4，<0.9诊断周围动脉疾病，<0.4提示严重缺血）、下肢动脉彩色多普勒超声（狭窄/闭塞部位及程度）；【影像学】下肢动脉CTA或MRA（精确评估，术前）；【其他】血糖、血脂、肾功能（动脉粥样硬化危险因素评估）。","初步诊断":"1. 下肢动脉粥样硬化闭塞症（间歇性跛行期）\n（注：①危险因素控制：戒烟（最重要）、他汀（阿托伐他汀20mg qd）、控制血压血糖、抗血小板（阿司匹林100mg qd或氯吡格雷75mg qd）；②运动康复（监督下步行锻炼，每周3次每次30~45分钟，促进侧支循环）；③药物：西洛他唑100mg bid（改善跛行症状，心衰者禁用）或己酮可可碱；④介入/手术指征：静息痛、溃疡坏疽（严重肢体缺血，CLTI，需急诊评估）、跛行严重影响生活且药物治疗无效：腔内成形（PTA+支架）/旁路移植；⑤足部护理（防外伤，糖尿病者尤甚）；若肢体突然剧痛苍白无脉（急性动脉栓塞）为急诊，需立即处理（6小时内再通）。）","处理方案":"【药物治疗】\n1. 抗血小板药物：阿司匹林肠溶片100mg qd口服，长期服用；阿司匹林不耐受者改用氯吡格雷片75mg qd口服。\n2. 调脂药物（他汀类）：阿托伐他汀钙片20mg qn口服，长期服用，LDL-C目标值<1.8mmol/L。\n3. 改善间歇性跛行症状药物：西洛他唑片100mg bid口服（餐前半小时服用），疗程4-12周，充血性心力衰竭者禁用；不耐受者改用贝前列素钠片40μg tid口服。\n4. 降压治疗（合并高血压者）：氨氯地平片5mg qd口服，血压控制目标<140/90mmHg，避免过度降压。\n\n【一般治疗及生活指导】\n1. 严格戒烟（包括二手烟），烟草是周围动脉疾病最重要且可干预的危险因素，戒烟可显著延缓疾病进展。\n2. 饮食控制：低盐低脂饮食，控制体重；合并糖尿病者严格控制血糖，糖化血红蛋白目标<7%。\n3. 步行锻炼：每日坚持步行锻炼30-45分钟，每周至少5次，行走至出现间歇性跛行疼痛时短暂休息缓解后再继续，持续3-6个月可明显延长跛行距离。\n4. 足部护理：每日检查双足皮肤颜色、温度及有无破损、感染，穿宽松柔软的鞋袜，避免外伤、烫伤及过度修剪趾甲，保持足部清洁干燥，出现足部伤口及时就诊。\n\n【随诊要求】\n建议每1-3个月门诊复诊1次，评估间歇性跛行距离、静息痛及溃疡等病情变化，监测血压、血脂（LDL-C）及血糖达标情况；每6-12个月复查踝肱指数（ABI）评估动脉缺血进展；若出现突发肢端苍白、疼痛、麻木、无脉等急性肢体缺血表现，或静息痛加重、足部溃疡坏疽，需立即急诊就诊。"},"icd10_diagnosis":"","icd10_secondary":[],"icd9cm3_procedure":[]}},"locator":{"file":"门诊住院病历模板/病历模板包_全部_20261111.json","arrayRow":405,"caseRow":1},"sourceHash":"10e4fdb435986b7b85f847c3951d0cb0eafdce0f372c5617949c05b337149194","contentHash":"f4b3bc2d63b18f876766a99734bbeb1d96f5f6d24f3cf381a351eb611348690a","pinyin":"zhouweidongmaijibing","initials":"zwdmjb","setting":"out","caseName":"门诊病历270","templateNames":["主诉","现病史","既往史","个人史及过敏史","体格检查","辅助检查","初步诊断","处理方案"],"emptyTemplates":[],"escapedNewlines":[],"quickFields":[["病例名称","门诊病历270",60],["模板名称","主诉 现病史 既往史 个人史及过敏史 体格检查 辅助检查 初步诊断 处理方案",30],["主要诊断编码","",30]]},{"id":"templates-51be2fd4941d98f43ab3","key":"v1-c9ccc21dfe2a3058|templates-51be2fd4941d98f43ab3","module":"templates","moduleKey":"v1-c9ccc21dfe2a3058|templates","version":"v1-c9ccc21dfe2a3058","title":"静脉炎","category":"门诊病历模板","raw":{"name":"静脉炎","category":"门诊病历模板","case":{"case_name":"门诊病历271","templates":{"主诉":"浅静脉红肿、条索状硬结伴疼痛3天","现病史":"患者于3天前出现左上肢（下肢大隐静脉/上肢，常与静脉输液相关）走行区红肿、疼痛，可触及条索状硬结，局部皮温升高，无发热，无全身感染征象，无肢体肿胀（深静脉血栓需排除（血栓性浅静脉炎可蔓延/并发深静脉血栓））。近期有静脉输液/置管，无静脉曲张、外伤及高凝状态。今日来我院门诊就诊。","既往史":"既往体健，否认高血压、糖尿病、冠心病等慢性病史。否认肝炎、结核等传染病史。否认手术外伤史。否认食物药物过敏史。预防接种史随社会。","个人史及过敏史":"生于原籍，久居本地，无疫区疫水接触史，无特殊粉尘毒物放射性物质接触史。不吸烟，不饮酒。生活规律。否认食物药物过敏史。","体格检查":"T36.7℃，P82次/分，R18次/分，BP126/78mmHg。神志清楚，查体合作。左上肢浅静脉走行区皮肤红肿、皮温升高，可触及条索状硬结，约4cm长，压痛明显，局部无波动感，患肢无肿胀，Homans征（-）。","辅助检查":"【必做】静脉彩色多普勒超声（确认血栓位于浅静脉及范围，排除累及深静脉，深静脉血栓需按DVT处理）；【其他】血常规、CRP（感染征象评估）、D-二聚体。","初步诊断":"1. 血栓性浅静脉炎（左上肢头静脉）\n（注：治疗：抬高患肢、局部热敷或硫酸镁湿敷；NSAIDs（塞来昔布200mg bid或外用双氯芬酸）抗炎镇痛；压迫治疗（弹力袜，下肢）；血栓蔓延或高危险因素者：低分子肝素预防性抗凝（防深静脉血栓，血栓靠近隐股静脉交界处或>5cm时）；继发细菌感染（红肿加剧、发热、脓性，化脓性浅静脉炎）需抗感染（静脉输液相关常为革兰阳性菌，万古霉素等）甚至切开引流；停用/拔除相关静脉导管；反复发生需查高凝状态及肿瘤筛查。）","处理方案":"【药物治疗】\n1. 非甾体抗炎药：双氯芬酸二乙胺乳胶剂（扶他林）外用患处，每次3-4g，每日3-4次，涂后轻柔按摩，疗程5-7天；疼痛明显者可加用布洛芬缓释胶囊0.3g bid po，疗程3-5天。\n2. 抗栓抗凝药：利伐沙班片10mg qd po，疗程10天（用于血栓性浅静脉炎，排除出血高危因素后使用）；或阿司匹林肠溶片100mg qd po，疗程2周。\n3. 改善静脉循环药：地奥司明片（爱脉朗）0.5g bid po（早晚餐时服），疗程2周；局部外用多磺酸粘多糖乳膏（喜辽妥）2-3次/日，涂抹患处条索状区域。\n【一般治疗及生活指导】\n1. 休息与体位：急性期患肢抬高制动（高于心脏水平约15-20cm），避免久站久坐及剧烈活动，减轻静脉回流负荷。\n2. 活动指导：症状缓解后尽早适量活动，行踝泵运动（每小时5-10次踝关节屈伸），促进静脉回流，预防血栓蔓延。\n3. 局部护理：急性期（48小时内）严禁热敷、按摩、挤压患处及理疗，以免血栓脱落；红肿消退后可改为温敷。\n4. 禁忌：戒烟戒酒；输液所致静脉炎者避免同一静脉及同侧肢体短期内反复穿刺，必要时更换输液部位或使用静脉留置针。\n【随诊要求】\n治疗3-5天后复诊评估局部红肿、疼痛及条索状硬结变化；若红肿范围扩大、疼痛加剧、出现发热或沿静脉走行条索延长，应立即复诊并行下肢静脉超声排除深静脉血栓；治疗2周症状未缓解或反复发作者，建议行静脉彩超及凝血功能检查，必要时转血管外科进一步诊治。"},"icd10_diagnosis":"","icd10_secondary":[],"icd9cm3_procedure":[]}},"locator":{"file":"门诊住院病历模板/病历模板包_全部_20261111.json","arrayRow":406,"caseRow":1},"sourceHash":"10e4fdb435986b7b85f847c3951d0cb0eafdce0f372c5617949c05b337149194","contentHash":"b9c4e3ffc3fe05094e1c13725632d43159b890b83a74c7e5ee8f0e6e84c62a4c","pinyin":"jingmaiyan","initials":"jmy","setting":"out","caseName":"门诊病历271","templateNames":["主诉","现病史","既往史","个人史及过敏史","体格检查","辅助检查","初步诊断","处理方案"],"emptyTemplates":[],"escapedNewlines":[],"quickFields":[["病例名称","门诊病历271",60],["模板名称","主诉 现病史 既往史 个人史及过敏史 体格检查 辅助检查 初步诊断 处理方案",30],["主要诊断编码","",30]]},{"id":"templates-995b2cebe06076d0042a","key":"v1-c9ccc21dfe2a3058|templates-995b2cebe06076d0042a","module":"templates","moduleKey":"v1-c9ccc21dfe2a3058|templates","version":"v1-c9ccc21dfe2a3058","title":"血栓性静脉炎","category":"门诊病历模板","raw":{"name":"血栓性静脉炎","category":"门诊病历模板","case":{"case_name":"门诊病历272","templates":{"主诉":"下肢肿胀、疼痛伴浅静脉红肿3天","现病史":"患者于4天前出现右下肢肿胀、胀痛，皮肤绷紧，同时可见浅静脉走行区红肿、条索状硬结、触痛，行走时加重，抬高患肢减轻，无发热。无静脉曲张，无近期手术、外伤、制动，无静脉输液置管，无肿瘤、妊娠及口服避孕药等高危因素。今日来我院门诊就诊。","既往史":"既往体健，否认高血压、糖尿病、冠心病等慢性病史。否认肝炎、结核等传染病史。否认手术外伤史。否认食物药物过敏史。预防接种史随社会。","个人史及过敏史":"生于原籍，久居本地，无疫区疫水接触史，无特殊粉尘毒物放射性物质接触史。不吸烟，不饮酒。生活规律。否认食物药物过敏史。","体格检查":"T36.8℃，P84次/分，R18次/分，BP128/80mmHg。神志清楚，查体合作。右下肢肿胀（周径较对侧：小腿3cm、大腿4cm），大隐静脉走行区可触及红肿条索、压痛（+），皮温升高，Homans征（+），足背动脉搏动正常。","辅助检查":"检查计划：患者4天前出现右下肢肿胀、胀痛，大隐静脉走行区红肿并呈条索状硬结、触痛，行走后加重、抬高患肢减轻，符合血栓性浅静脉炎表现，需下肢静脉彩色多普勒超声检查以区分单纯浅静脉血栓与合并深静脉血栓，此点直接决定治疗方案为抗炎止痛抑或足量抗凝，为最关键检查；查D-二聚体了解血栓形成及纤溶活动情况，协助判断血栓范围与病程；完善血常规检查了解有无感染及血小板水平，排除化脓性血栓性静脉炎并为抗凝治疗提供安全基线；查凝血功能明确凝血状态，评估低分子肝素抗凝的安全性；查肝肾功能了解肝肾代谢情况，为选择低分子肝素或直接口服抗凝药及疗程制定提供依据；患者4天内血栓形成且无明显诱因，完善肿瘤筛查（肿瘤标志物及必要影像学）以排除恶性肿瘤所致高凝状态，尤其适用于45岁以上、无诱因反复血栓者；患者否认静脉曲张、近期手术、外伤、制动及静脉置管史，仍需查抗心磷脂抗体、蛋白C及蛋白S等易栓症筛查项目以明确有无遗传性或获得性高凝因素；若出现胸痛、呼吸困难或咯血，需急诊完善肺动脉CTA排除血栓脱落所致肺栓塞。\n\n（检查清单）\n【必做】下肢静脉彩色多普勒超声（区分单纯浅静脉血栓与合并深静脉血栓，决定治疗方案关键）；【其他】D-二聚体、血常规、肿瘤筛查（无诱因反复血栓，45岁以上）。","初步诊断":"1. 血栓性浅静脉炎（右下肢大隐静脉，伴深静脉血栓）\n（注：单纯浅静脉血栓：抬高患肢、热敷、NSAIDs抗炎止痛、弹力袜压迫；血栓>5cm、靠近隐股静脉交界、症状重或高危者：预防剂量低分子肝素抗凝（如依诺肝素40mg qd×4周）或直接口服抗凝药；合并深静脉血栓者按DVT足量抗凝（≥3个月）；化脓性血栓性浅静脉炎（输液相关、发热脓毒症），全身抗生素+切除受累静脉；治疗基础静脉曲张（硬化/剥脱）防复发；穿弹力袜、避免久站久坐。）","处理方案":"【药物治疗】\n1. 抗凝治疗（血栓蔓延风险高或累及大隐/小隐静脉主干时）：利伐沙班片 15mg bid 口服，连用3周后改为20mg qd，总疗程4~6周；或依诺肝素钠注射液 4000IU（0.4ml）皮下注射 q12h，疗程5~7天。治疗期间监测有无出血倾向。\n2. 非甾体抗炎药：塞来昔布胶囊 0.2g bid 口服，疗程3~5天，缓解局部红肿疼痛；或双氯芬酸钠缓释片 75mg qd 口服，疗程5天。\n3. 静脉活性药物：地奥司明片 0.9g bid 口服（餐时服用），疗程2~4周，改善静脉张力、减轻患肢肿胀。\n4. 局部用药：多磺酸粘多糖乳膏（喜辽妥）外涂患处 bid；局部红肿明显者予50%硫酸镁溶液湿敷 bid，每次20~30分钟。\n\n【一般治疗及生活指导】\n1. 休息与体位：急性期卧床休息，抬高患肢30°~45°（高于心脏水平），避免久站久坐及下肢长时间受压。\n2. 局部护理：患肢可穿医用弹力袜或弹力绷带加压支持，严禁按摩、挤压、搔抓患处，避免局部热敷过久，防止血栓脱落。\n3. 活动指导：急性症状缓解后（约3~7天）尽早下床活动，穿戴弹力袜适度行走，避免剧烈运动及长时间行走。\n4. 生活禁忌：戒烟限酒，控制体重，停用避孕药等雌激素类药物；多饮水，保持大便通畅，避免用力排便等腹压骤增动作。\n\n【随诊要求】\n1. 用药后1周门诊复诊，评估局部红肿、疼痛消退情况并复查D-二聚体；症状无缓解或加重者，复查下肢静脉超声明确有无深静脉血栓形成。\n2. 抗凝治疗期间注意观察牙龈出血、皮肤瘀斑、鼻衄、黑便、血尿等出血征象，一旦出现立即就诊，调整抗凝方案。\n3. 若突发胸痛、呼吸困难、咯血或晕厥，立即急诊就诊，警惕肺栓塞可能。\n4. 疗程结束（4~6周）后复查静脉超声评估血栓消退情况；反复发作或合并下肢静脉曲张者，建议血管外科评估进一步治疗。"},"icd10_diagnosis":"","icd10_secondary":[],"icd9cm3_procedure":[]}},"locator":{"file":"门诊住院病历模板/病历模板包_全部_20261111.json","arrayRow":407,"caseRow":1},"sourceHash":"10e4fdb435986b7b85f847c3951d0cb0eafdce0f372c5617949c05b337149194","contentHash":"b12e4abf2720f5abb2dc326c37b184dc57540c09119bdd62fd252d64085f3d92","pinyin":"xueshuanxingjingmaiyan","initials":"xsxjmy","setting":"out","caseName":"门诊病历272","templateNames":["主诉","现病史","既往史","个人史及过敏史","体格检查","辅助检查","初步诊断","处理方案"],"emptyTemplates":[],"escapedNewlines":[],"quickFields":[["病例名称","门诊病历272",60],["模板名称","主诉 现病史 既往史 个人史及过敏史 体格检查 辅助检查 初步诊断 处理方案",30],["主要诊断编码","",30]]},{"id":"templates-1db6a68849a537c042b6","key":"v1-c9ccc21dfe2a3058|templates-1db6a68849a537c042b6","module":"templates","moduleKey":"v1-c9ccc21dfe2a3058|templates","version":"v1-c9ccc21dfe2a3058","title":"淋巴水肿","category":"门诊病历模板","raw":{"name":"淋巴水肿","category":"门诊病历模板","case":{"case_name":"门诊病历273","templates":{"主诉":"肢体进行性肿胀1年","现病史":"患者于3年前（时间）开始出现右上肢（上肢，乳腺癌术后（腋窝淋巴结清扫/放疗）；下肢，妇科肿瘤术后/腹股沟淋巴结清扫/放疗/丝虫病疫区居住/先天性）进行性肿胀，晨起减轻、日间及活动后加重，皮肤紧绷，无疼痛或轻度胀痛，无皮肤发红发热（蜂窝织炎反复发作史），无皮肤增厚变硬，无凹陷性水肿（后期纤维化），无发热。今日来我院门诊就诊。","既往史":"既往体健，否认高血压、糖尿病、冠心病等慢性病史。否认肝炎、结核等传染病史。否认手术外伤史。否认食物药物过敏史。预防接种史随社会。","个人史及过敏史":"生于原籍，久居本地，无疫区疫水接触史，无特殊粉尘毒物放射性物质接触史。不吸烟，不饮酒。生活规律。否认食物药物过敏史。","体格检查":"T36.6℃，P78次/分，R18次/分，BP124/76mmHg。神志清楚，查体合作。右上肢（上肢/下肢）明显肿胀（周径较对侧：上臂/前臂或大腿/小腿分别3cm），皮肤光滑紧张，无增厚变硬（Stemmer征阴性，第二趾/指背皮肤可以捏起），按压凹陷性，无发红，患肢活动轻度受限，浅表静脉正常，动脉搏动正常。","辅助检查":"【必做】一般临床诊断为主（淋巴水肿主要靠病史体征，术后/放疗后单侧肢体肿胀）；【影像学】淋巴显像（核素淋巴闪烁造影，淋巴回流障碍确认）、MRI（软组织水肿评估）；【其他】静脉超声（排除静脉性水肿，DVT后综合征）、超声（排除肿瘤复发压迫）。","初步诊断":"1. 淋巴水肿（继发性（术后/放疗后），右上肢，Ⅱ期）\n（注：综合消肿治疗（CDT）为核心：①手法淋巴引流（专业治疗师）；②压力治疗（多层绷带/弹力袜，白天穿戴，压力分级恰当）；③皮肤护理（保湿、防破损感染，蜂窝织炎是常见并发症，反复感染加重水肿，发生后足疗程抗生素（青霉素/一代头孢））；④功能锻炼；药物：香豆素类（疗效有限），苯吡喃酮已少用；手术（保守无效的重度）：淋巴管-静脉吻合（LVA）、血管化淋巴结移植（VLNT），专科评估；抬高患肢、避免患肢采血注射/提重物（上肢）、控制体重，早期干预效果最好。）","处理方案":"【药物治疗】\n1. 预防及控制急性淋巴管炎/蜂窝织炎：首选青霉素类，阿莫西林胶囊0.5g tid×7天；或阿莫西林克拉维酸钾片0.625g bid×7天。青霉素过敏者改用头孢呋辛酯片0.25g bid×7天。反复感染（≥2次/年）者予苄星青霉素120万U深部肌注，每月1次预防。\n2. 合并足癣等真菌感染（常见诱因）：予盐酸特比萘芬乳膏外用bid，疗程2周；感染较重者可加口服盐酸特比萘芬片250mg qd×2周。\n3. 辅助消肿：马栗种子提取物（七叶皂苷类，如迈之灵片）150mg（2片）bid，餐后服，疗程4~8周，可减轻胀痛感。\n4. 疼痛明显者：洛索洛芬钠片60mg tid餐后服，按需使用，连续不超过5天。\n\n【一般治疗及生活指导】\n1. 体位与休息：休息时将患肢抬高至高于心脏水平，每日3~4次、每次30分钟以上；避免久站、久坐及患肢长时间下垂。\n2. 皮肤护理：每日温水清洗并涂抹保湿霜，保持皮肤完整，防干燥皲裂；避免患肢注射、采血、针灸、拔罐、纹身及佩戴过紧饰品，防蚊虫叮咬和外伤，防止继发感染。\n3. 活动与运动：白天佩戴压力梯度弹力袜（或弹力绷带），坚持踝泵运动及渐进性抗阻训练，促进淋巴回流；避免剧烈运动和长途飞行后久坐不动。\n4. 饮食：低盐低脂饮食，控制体重，戒烟限酒；保证优质蛋白摄入，增强组织修复能力。\n\n【随诊要求】\n1. 每周于固定点（膝上10cm、膝下10cm、踝上5cm）测量患肢周径并记录，评估肿胀变化及压力装置疗效。\n2. 若出现患肢红、肿、热、痛加重或伴发热，提示继发感染，须立即就诊。\n3. 每1~3个月复诊1次，必要时行患肢静脉彩超排除深静脉血栓、淋巴显像评估淋巴回流功能；病情稳定后每3~6个月复诊1次。"},"icd10_diagnosis":"","icd10_secondary":[],"icd9cm3_procedure":[]}},"locator":{"file":"门诊住院病历模板/病历模板包_全部_20261111.json","arrayRow":408,"caseRow":1},"sourceHash":"10e4fdb435986b7b85f847c3951d0cb0eafdce0f372c5617949c05b337149194","contentHash":"e4c72340f840dd18b678d8e8f5f3e91c0d0c49b7c82586768f02a0e7dd40a74a","pinyin":"linbashuizhong","initials":"lbsz","setting":"out","caseName":"门诊病历273","templateNames":["主诉","现病史","既往史","个人史及过敏史","体格检查","辅助检查","初步诊断","处理方案"],"emptyTemplates":[],"escapedNewlines":[],"quickFields":[["病例名称","门诊病历273",60],["模板名称","主诉 现病史 既往史 个人史及过敏史 体格检查 辅助检查 初步诊断 处理方案",30],["主要诊断编码","",30]]},{"id":"templates-440cdab141a9964c87e1","key":"v1-c9ccc21dfe2a3058|templates-440cdab141a9964c87e1","module":"templates","moduleKey":"v1-c9ccc21dfe2a3058|templates","version":"v1-c9ccc21dfe2a3058","title":"高原性心脏病","category":"门诊病历模板","raw":{"name":"高原性心脏病","category":"门诊病历模板","case":{"case_name":"门诊病历274","templates":{"主诉":"呼吸困难、心悸伴口唇发绀3天","现病史":"患者于3天前从平原进入高原（海拔4500m），出现进行性呼吸困难、心悸、乏力、口唇发绀，活动耐力明显下降，有咳嗽、咳白色泡沫痰（肺水肿表现），无头痛头晕恶心（高原反应），无下肢水肿，无腹胀少尿（右心衰表现），休息后缓解不明显。既往无心脏病、肺病及高原居住史（高原适应情况）。今日来我院就诊。","既往史":"既往体健，否认高血压、糖尿病、冠心病等慢性病史。否认肝炎、结核等传染病史。否认手术外伤史。否认食物药物过敏史。预防接种史随社会。","个人史及过敏史":"生于原籍，久居本地，无疫区疫水接触史，无特殊粉尘毒物放射性物质接触史。不吸烟，不饮酒。生活规律。否认食物药物过敏史。","体格检查":"T36.9℃，P118次/分（增快），R26次/分（增快），BP130/84mmHg，SpO2 76%（显著降低，高原肺水肿时常<80%）。神志清楚，口唇及甲床发绀（+），颈静脉怒张，双肺可闻及湿啰音（肺水肿），心率118次/分，律齐，肺动脉瓣第二心音亢进（+），三尖瓣区收缩期杂音，肝肿大，双下肢水肿（-）。","辅助检查":"检查计划：患者由平原快速进入海拔4500m高原3天，出现进行性呼吸困难、心悸、口唇发绀、咳嗽咳白色泡沫痰且活动耐力明显下降，急诊即刻完善血气分析明确低氧血症程度及有无呼吸性碱中毒，评估是否需要高流量吸氧或转运至高压氧舱；查血常规了解红细胞及血红蛋白升高程度，评估长期缺氧所致的代偿性红细胞增多；患者有肺水肿表现，查胸部X线片明确有无双肺斑片状阴影及心影增大，鉴别高原肺水肿与高原性心脏病；完善超声心动图检查以了解右心室有无扩大、肺动脉压力是否升高及三尖瓣反流情况，此为高原性心脏病诊断的关键依据；查心电图了解有无右室肥大、肺型P波等右心负荷增重表现；完善肝肾功能检查评估全身缺氧所致脏器损害及为呋塞米等药物使用提供依据；查电解质明确有无电解质紊乱；完善心肌肌钙蛋白检查排除急性心肌损伤或心肌梗死；患者病情危重，需查凝血功能及D-二聚体排除肺栓塞所致急性呼吸困难；治疗期间动态复查血气分析及超声心动图评估吸氧、硝苯地平降肺动脉压及呋塞米利尿治疗的疗效。\n\n（检查清单）\n【必做】血气分析（低氧血症、呼吸性碱中毒）、血常规（红细胞及血红蛋白升高，长期缺氧代偿）、胸部X线片（高原肺水肿：双肺斑片状阴影、心影增大，高原心脏病）；【影像学】超声心动图（右室扩大、肺动脉压升高，诊断关键）；【其他】心电图（右室肥大、肺型P波）、肝肾功能。","初步诊断":"1. 高原性心脏病（急性（高原肺水肿/右心衰），伴肺动脉高压）\n（注：急性高原肺水肿为致命急症，立即：①下撤至低海拔（最重要，越早越好）；②吸氧（高流量面罩/便携氧）；③绝对卧床、保暖；④药物治疗：硝苯地平10mg舌下含服（降肺动脉压，高原肺水肿预防及治疗）、呋塞米20~40mg（肺水肿，注意血压）、地塞米松8mg（高原脑水肿并防）；⑤严重者转运至医院（高压氧舱）；慢性高原心脏病：长期氧疗、降低肺动脉压药物（西地那非等）专科管理，移居低海拔可逆转；进入高原前预防（阶梯适应、乙酰唑胺，预防高原病）。）","处理方案":"【药物治疗】\n1.利尿剂：呋塞米片20mg qd，晨服，水肿明显者可增至40mg qd，联合螺内酯片20mg qd口服；疗程视水肿消退情况，一般1-4周，期间监测血钾及电解质。\n2.改善心室重构：贝那普利片10mg qd，或缬沙坦胶囊80mg qd口服，长期维持；注意监测血压及肾功能，血压偏低者减量。\n3.强心治疗：地高辛片0.125mg qd口服，适用于右心衰竭明显、心室率偏快者，长期维持；定期监测心率（目标55-60次/分以上），必要时监测血药浓度。\n4.改善缺氧及支气管解痉：多索茶碱片0.2g bid口服，疗程1-2周；合并低氧血症者同时给予低流量吸氧1-2L/min。\n\n【一般治疗及生活指导】\n1.休息：急性期卧床休息，避免劳累及剧烈活动；病情稳定后循序渐进恢复活动，以活动后不出现心悸、气促为度。\n2.饮食：低盐低脂饮食，每日食盐摄入<3g，适当控制饮水量，少量多餐避免过饱，多食优质蛋白及富含维生素食物。\n3.活动与环境：尽量减少在高海拔地区的停留时间，条件允许时应转至低海拔地区或平原生活；避免饮酒、吸烟及受凉感冒。\n4.监测：每日自测体重及记录尿量，若体重短期内增加或尿量明显减少，提示水钠潴留加重，应及时就医。\n\n【随诊要求】\n1.每1-3个月门诊复诊1次，复查心电图、心脏彩超、血常规、肝肾功能及电解质。\n2.服药期间若出现心悸、气促加重、双下肢水肿加重、少尿或头晕乏力等症状，应及时就诊。\n3.返回低海拔地区后症状明显缓解者，仍建议定期随访至少1年，动态评估肺动脉压及右心功能恢复情况。"},"icd10_diagnosis":"","icd10_secondary":[],"icd9cm3_procedure":[]}},"locator":{"file":"门诊住院病历模板/病历模板包_全部_20261111.json","arrayRow":409,"caseRow":1},"sourceHash":"10e4fdb435986b7b85f847c3951d0cb0eafdce0f372c5617949c05b337149194","contentHash":"13126630026a998b4444a038c84d3ecccb5da1c5facd9deb18a69b881d5aee21","pinyin":"gaoyuanxingxinzangbing","initials":"gyxxzb","setting":"out","caseName":"门诊病历274","templateNames":["主诉","现病史","既往史","个人史及过敏史","体格检查","辅助检查","初步诊断","处理方案"],"emptyTemplates":[],"escapedNewlines":[],"quickFields":[["病例名称","门诊病历274",60],["模板名称","主诉 现病史 既往史 个人史及过敏史 体格检查 辅助检查 初步诊断 处理方案",30],["主要诊断编码","",30]]},{"id":"templates-8633ab023d0e1c2d8961","key":"v1-c9ccc21dfe2a3058|templates-8633ab023d0e1c2d8961","module":"templates","moduleKey":"v1-c9ccc21dfe2a3058|templates","version":"v1-c9ccc21dfe2a3058","title":"食管贲门失弛缓症","category":"门诊病历模板","raw":{"name":"食管贲门失弛缓症","category":"门诊病历模板","case":{"case_name":"门诊病历275","templates":{"主诉":"吞咽困难、反流伴胸骨后疼痛1年","现病史":"患者于3年前开始出现吞咽困难，固体及流质食物均感下咽不畅（与机械性梗阻不同，失弛缓症特征：液体固体均困难、与情绪及进食速度相关），胸骨后梗阻感/疼痛，进食后反流（未消化食物，不含胃酸），夜间反流可致呛咳、吸入性肺炎，体重下降约8kg，症状缓慢进行性加重，无烧心（少见），饮水或Valsalva动作可助吞咽（特征）。今日来我院门诊就诊。","既往史":"既往体健，否认高血压、糖尿病、冠心病等慢性病史。否认肝炎、结核等传染病史。否认手术外伤史。否认食物药物过敏史。预防接种史随社会。","个人史及过敏史":"生于原籍，久居本地，无疫区疫水接触史，无特殊粉尘毒物放射性物质接触史。不吸烟，不饮酒。生活规律。否认食物药物过敏史。","体格检查":"T36.5℃，P76次/分，R18次/分，BP118/72mmHg。神志清楚，查体合作，营养状况消瘦。胸部及腹部检查未见明显异常，无上腹压痛，无锁骨上淋巴结肿大（排除恶性梗阻）。","辅助检查":"【必做】食管钡餐造影（鸟嘴样/漏斗样改变：食管下段光滑狭窄、食管扩张，特征性表现）、胃镜（排除假性失弛缓（贲门癌，内镜可见）、食管炎，内镜下贲门紧闭但镜身可通过）；【确诊】高分辨率食管测压（HRM：食管下括约肌松弛障碍、食管体部蠕动消失，诊断金标准及分型（芝加哥分型））；【其他】胸部CT（排除纵隔肿瘤压迫）。","初步诊断":"1. 贲门失弛缓症（Ⅱ型：芝加哥分型Ⅰ/Ⅱ/Ⅲ型）\n（注：治疗：①药物（疗效短暂）：硝酸酯类（硝酸异山梨酯5mg餐前舌下）或钙通道阻滞剂（硝苯地平10mg餐前舌下），缓解症状，仅用于轻症/术前过渡；②内镜下治疗：球囊扩张术（POEM，经口内镜肌切开术（近年首选，创伤小疗效好）或内镜下球囊扩张（复发率高，可重复））；③外科手术（腹腔镜Heller肌切开+抗反流手术，扩张/POEM失败者）；④肉毒毒素注射（老年/不能耐受手术者，疗效维持数月）；治疗前必须胃镜排除贲门癌；术后随访症状、营养状态，警惕食管癌长期风险（食管炎-化生）。）","处理方案":"【药物治疗】\n1. 钙通道阻滞剂（首选）：硝苯地平控释片（拜新同）30mg qd口服，或餐前15分钟舌下含服硝苯地平片10mg，疗程2-4周，症状缓解后遵医嘱减量或维持，可缓解食管下括约肌痉挛性收缩。\n2. 硝酸酯类：硝酸异山梨酯片（消心痛）5-10mg tid，餐前15-30分钟舌下含服或口服，疗程2-4周，与钙通道阻滞剂可联合或交替使用，注意低血压、头痛等不良反应。\n3. 内镜下注射治疗（适用于不宜手术或内镜切开者）：内镜下于贲门食管下括约肌处行肉毒毒素分4象限注射，总剂量100U/次，疗效一般维持6-12个月，可重复注射。\n\n【一般治疗及生活指导】\n1. 少食多餐、细嚼慢咽，避免过冷、过热及辛辣刺激性食物，进食时保持坐位或立位，餐后1小时内避免平卧，以防食管内食物潴留。\n2. 睡前2-3小时禁食禁水，睡眠时抬高床头15-30cm或使用高枕，利用重力促进食管排空，减少反流及误吸风险。\n3. 出现进食哽噎或反流时勿强行下咽，可站立位空咽数次或轻叩胸骨后辅助排空，必要时自行诱发呕吐缓解潴留；避免饮酒、吸烟及大口快速进食，保持情绪平稳，避免紧张焦虑。\n\n【随诊要求】\n1. 服药2-4周后复诊评估吞咽困难、反流等症状缓解情况；若症状无改善或加重，及时复查高分辨率食管测压及食管造影，评估是否需要内镜下肌切开术（POEM）、球囊扩张或外科手术（Heller术）治疗。\n2. 每1-2年复查胃镜，监测食管黏膜炎症、贲门黏膜损伤及远期Barrett食管、食管癌风险，病程长者尤其重视。\n3. 若出现剧烈胸痛、发热、呕血、黑便或进行性体重下降等警示症状，立即就诊，行急诊内镜及影像学检查排除并发症。"},"icd10_diagnosis":"","icd10_secondary":[],"icd9cm3_procedure":[]}},"locator":{"file":"门诊住院病历模板/病历模板包_全部_20261111.json","arrayRow":410,"caseRow":1},"sourceHash":"10e4fdb435986b7b85f847c3951d0cb0eafdce0f372c5617949c05b337149194","contentHash":"a60ebb6db95220441f90b2d4df305a196c687e40a7b7d98679e9b54b94de1452","pinyin":"shiguanbenmenshichihuanzheng","initials":"sgbmschz","setting":"out","caseName":"门诊病历275","templateNames":["主诉","现病史","既往史","个人史及过敏史","体格检查","辅助检查","初步诊断","处理方案"],"emptyTemplates":[],"escapedNewlines":[],"quickFields":[["病例名称","门诊病历275",60],["模板名称","主诉 现病史 既往史 个人史及过敏史 体格检查 辅助检查 初步诊断 处理方案",30],["主要诊断编码","",30]]},{"id":"templates-a95ed62b828ae2092e18","key":"v1-c9ccc21dfe2a3058|templates-a95ed62b828ae2092e18","module":"templates","moduleKey":"v1-c9ccc21dfe2a3058|templates","version":"v1-c9ccc21dfe2a3058","title":"食管裂孔疝","category":"门诊病历模板","raw":{"name":"食管裂孔疝","category":"门诊病历模板","case":{"case_name":"门诊病历276","templates":{"主诉":"烧心、反酸1年，伴胸骨后疼痛1周","现病史":"患者于5年前开始反复烧心、反酸（餐后、平卧、弯腰、腹压增高时加重），胸骨后烧灼样疼痛（可向背或肩放射，需与心绞痛鉴别）、嗳气、上腹胀，有无吞咽困难、恶心、慢性咳嗽、声音嘶哑（反流至咽喉），夜间反流可致呛醒。有无肥胖、慢性咳嗽、便秘、妊娠及举重等腹压增高因素：无。今日来我院门诊就诊。","既往史":"既往体健，否认高血压、糖尿病、冠心病等慢性病史。否认肝炎、结核等传染病史。否认手术外伤史。否认食物药物过敏史。预防接种史随社会。","个人史及过敏史":"生于原籍，久居本地，无疫区疫水接触史，无特殊粉尘毒物放射性物质接触史。不吸烟，不饮酒。生活规律。否认食物药物过敏史。","体格检查":"T36.7℃，P82次/分，R18次/分，BP126/78mmHg，BMI24.5kg/m²。神志清楚，查体合作。上腹轻压痛（-），心肺听诊未见明显异常（心绞痛鉴别，行心电图）。","辅助检查":"【必做】胃镜（食管裂孔疝（滑动型：贲门上移、His角变钝；食管旁型：贲门位置正常但胃经裂孔疝入）、反流性食管炎（LA分级）、Barrett食管）；【影像学】食管钡餐造影（裂孔疝及反流，滑动型立位可复位）；【其他】24小时食管pH监测及测压（症状不典型或术前评估）。","初步诊断":"1. 食管裂孔疝（滑动型：滑动型/食管旁型/混合型）\n（注：无症状滑动型小疝无需治疗；反流症状治疗同GERD：生活方式（减重、抬高床头、睡前3小时不进食）+质子泵抑制剂（奥美拉唑20mg bid或埃索美拉唑20mg qd~bid，疗程4~8周后按需维持）；食管旁型疝（胃嵌顿风险：扭转/梗阻/出血）即使症状轻也建议手术（腹腔镜修补+胃底折叠）；手术指征：药物治疗无效的重度反流、食管旁型、并发症（狭窄、Barrett进展、反复吸入性肺炎）；紧急情况：突发胸痛呕吐不能进食（胃扭转/嵌顿）立即急诊。）","处理方案":"【药物治疗】\n1.质子泵抑制剂（首选）：奥美拉唑肠溶胶囊20mg qd，早餐前30分钟口服，症状重者增至20mg bid，疗程4-8周；维持治疗可减量至10-20mg qd。\n2.H2受体拮抗剂：法莫替丁片20mg bid，用于轻症或PPI维持期减量替代。\n3.促胃肠动力药：莫沙必利片5mg tid，三餐前口服，增强食管下括约肌张力、促进胃排空，与抑酸药联用。\n4.胃黏膜保护剂：铝碳酸镁咀嚼片1.0g tid，餐后1小时嚼服，中和反流物、保护食管黏膜，按需加用。\n【一般治疗及生活指导】\n1.饮食：少食多餐、细嚼慢咽，避免过饱及餐后立即平卧；忌高脂、油炸、辛辣刺激性食物及浓茶、咖啡、巧克力、碳酸饮料；睡前3小时禁食禁水。\n2.体位：餐后保持直立位或缓慢散步30分钟，避免弯腰、提重物、用力排便等增加腹压的动作；睡眠时抬高床头15-20cm或垫高上半身，减少夜间反流。\n3.体重管理：超重或肥胖者应控制体重、减少腹围，避免紧束腰带及穿紧身衣裤。\n4.戒除不良习惯：戒烟、戒酒，避免长期服用可松弛食管下括约肌的药物（如钙通道阻滞剂、硝酸酯类等，需在医师指导下调整）。\n【随诊要求】\n1.用药2-4周后复诊，评估烧心、反酸、胸痛等症状缓解情况；症状未缓解或加重者，复查胃镜、上消化道钡餐或食管24小时pH监测及食管测压。\n2.若出现吞咽困难、吞咽痛、呕血或黑便、贫血、不明原因消瘦等，及时就诊。\n3.长期服用PPI者定期复诊，评估长期抑酸治疗的必要性，必要时监测血铁、维生素B12及骨密度。\n4.内科治疗3-6个月无效，或并发反流性食管炎、食管狭窄、食管溃疡出血、疝嵌顿等，转外科评估行腹腔镜食管裂孔疝修补术。"},"icd10_diagnosis":"","icd10_secondary":[],"icd9cm3_procedure":[]}},"locator":{"file":"门诊住院病历模板/病历模板包_全部_20261111.json","arrayRow":411,"caseRow":1},"sourceHash":"10e4fdb435986b7b85f847c3951d0cb0eafdce0f372c5617949c05b337149194","contentHash":"7a339f846275c2e224c1753621bac0cfa99ca48fb83bfe3084e4eda10c6e190a","pinyin":"shiguanliekongshan","initials":"sglks","setting":"out","caseName":"门诊病历276","templateNames":["主诉","现病史","既往史","个人史及过敏史","体格检查","辅助检查","初步诊断","处理方案"],"emptyTemplates":[],"escapedNewlines":[],"quickFields":[["病例名称","门诊病历276",60],["模板名称","主诉 现病史 既往史 个人史及过敏史 体格检查 辅助检查 初步诊断 处理方案",30],["主要诊断编码","",30]]},{"id":"templates-cd08131f4a82cfd923f6","key":"v1-c9ccc21dfe2a3058|templates-cd08131f4a82cfd923f6","module":"templates","moduleKey":"v1-c9ccc21dfe2a3058|templates","version":"v1-c9ccc21dfe2a3058","title":"Barrett食管","category":"门诊病历模板","raw":{"name":"Barrett食管","category":"门诊病历模板","case":{"case_name":"门诊病历277","templates":{"主诉":"反复反酸、烧心5年","现病史":"患者有胃食管反流病史____年（反酸烧心反复发作，用药情况：PPI长期/间断），于____（时间）胃镜检查发现食管下段____（长度____cm的粉红色柱状上皮取代鳞状上皮：Barrett食管），活检病理示____（肠上皮化生：含杯状细胞），目前反流症状____（控制/仍明显），无吞咽困难，无呕血黑便，无消瘦。有无Barrett食管/食管腺癌家族史：____。今日来我院门诊就诊。","既往史":"既往体健，否认高血压、糖尿病、冠心病等慢性病史。否认肝炎、结核等传染病史。否认手术外伤史。否认食物药物过敏史。预防接种史随社会。","个人史及过敏史":"生于原籍，久居本地，无疫区疫水接触史，无特殊粉尘毒物放射性物质接触史。不吸烟，不饮酒。生活规律。否认食物药物过敏史。","体格检查":"T36.6℃，P80次/分，R18次/分，BP124/76mmHg，BMI25.6kg/m²。神志清楚，查体合作。腹部及胸部查体未见明显异常。","辅助检查":"【必做】胃镜+活检（确诊及评估：食管下段鳞柱交界上移、舌样/环周柱状上皮，按布拉格标准记录长度（C/M）；活检确认肠上皮化生及异型增生（低级别/高级别），定期（按风险每1~3年）内镜随访并活检）；【其他】腹部超声或CT（进展期，淋巴结及转移评估）。","初步诊断":"1. Barrett食管（长度：C4M6cm，伴无异型增生：无异型增生/低级别异型增生/高级别异型增生）\n（注：随访及干预：①控制反流（生活方式+足量PPI（埃索美拉唑20mg bid或奥美拉唑20mg bid），降低进展风险但非根治）；②内镜监测：无dysplasia每3~5年；低级别异型增生每6~12个月（或内镜消融，RFA射频消融）；高级别异型增生/早期腺癌内镜切除（EMR/ESD）+消融（首选）或手术（食管切除，病变广泛/浸润深者）；③进展风险因素（男性、白种、肥胖、腹型肥胖、吸烟，强化监测与干预）；戒烟、减重、控制反流；需长期随访（食管腺癌风险较普通人群高30~50倍但绝对风险仍低）。）","处理方案":"【药物治疗】\n1. 质子泵抑制剂（首选，抑酸核心治疗）：埃索美拉唑镁肠溶片 20mg bid，早、晚餐前30分钟口服，疗程8周，症状缓解后减量至20mg qd长期维持；亦可选用奥美拉唑肠溶胶囊 20mg bid，餐前30分钟口服，疗程8～12周。\n2. 促胃肠动力药（辅助治疗）：枸橼酸莫沙必利片 5mg tid，餐前15～30分钟口服，疗程4～8周，促进胃排空、减少反流。\n3. 胃黏膜保护剂（对症缓解）：铝碳酸镁咀嚼片 1.0g（2片）tid，餐后1小时嚼服，缓解烧心、反酸等不适。\n4. 对PPI不耐受或夜间反流明显者：法莫替丁片 20mg bid 口服，睡前加服1次。\n【一般治疗及生活指导】\n1. 饮食指导：低脂、易消化饮食，少食多餐、避免过饱；睡前3小时禁食禁水；戒烟戒酒，忌咖啡、浓茶、巧克力及辛辣刺激食物。\n2. 体位与活动：餐后保持立位或慢走30分钟，避免立即平卧；夜间睡眠时将床头抬高15～20cm；避免弯腰、提重物、屏气用力等增加腹压的动作；控制体重，腰带不宜过紧。\n3. 戒烟限酒：吸烟与饮酒均可加重反流及食管黏膜损伤，应严格戒除。\n【随诊要求】\n1. 门诊定期复诊：每3～6个月复诊1次，评估反流症状控制及用药依从性，必要时调整抑酸治疗方案。\n2. 胃镜随访监测：无异型增生的Barrett食管每3～5年复查胃镜，按Prague标准记录化生黏膜范围并取活检；出现低级别异型增生者每6～12个月复查胃镜并活检；高级别异型增生或可疑早癌者及时转诊行内镜下治疗或外科手术评估。\n3. 长期PPI维持治疗者每6～12个月评估长期用药风险（骨质疏松、低镁血症、肾功能等），必要时监测血镁及肾功能。\n4. 出现吞咽困难、进行性体重下降、呕血、黑便等报警症状时，立即就诊行胃镜复查。"},"icd10_diagnosis":"","icd10_secondary":[],"icd9cm3_procedure":[]}},"locator":{"file":"门诊住院病历模板/病历模板包_全部_20261111.json","arrayRow":412,"caseRow":1},"sourceHash":"10e4fdb435986b7b85f847c3951d0cb0eafdce0f372c5617949c05b337149194","contentHash":"af9de33e617a8b776299471ba633c10afc707c69f9d9638cdb57f38dc79c2067","pinyin":"Barrettshiguan","initials":"Bsg","setting":"out","caseName":"门诊病历277","templateNames":["主诉","现病史","既往史","个人史及过敏史","体格检查","辅助检查","初步诊断","处理方案"],"emptyTemplates":[],"escapedNewlines":[],"quickFields":[["病例名称","门诊病历277",60],["模板名称","主诉 现病史 既往史 个人史及过敏史 体格检查 辅助检查 初步诊断 处理方案",30],["主要诊断编码","",30]]},{"id":"templates-7d1936dc68ddab9496ec","key":"v1-c9ccc21dfe2a3058|templates-7d1936dc68ddab9496ec","module":"templates","moduleKey":"v1-c9ccc21dfe2a3058|templates","version":"v1-c9ccc21dfe2a3058","title":"萎缩性胃炎","category":"门诊病历模板","raw":{"name":"萎缩性胃炎","category":"门诊病历模板","case":{"case_name":"门诊病历278","templates":{"主诉":"上腹隐痛、饱胀伴食欲减退1年，加重2周","现病史":"患者于3年前开始反复上腹部隐痛/胀痛、餐后饱胀、早饱、嗳气、食欲减退，近2周加重，有无反酸烧心、恶心、消瘦、贫血乏力（恶性贫血（A型萎缩性胃炎：胃体萎缩伴内因子缺乏）、黑便），与进食及情绪关系：进食后加重，情绪紧张时明显。有无幽门螺杆菌（Hp）感染史及治疗情况、长期服用NSAIDs、胆汁反流、饮酒及胃癌家族史：无。今日来我院门诊就诊。","既往史":"既往体健，否认高血压、糖尿病、冠心病等慢性病史。否认肝炎、结核等传染病史。否认手术外伤史。否认食物药物过敏史。预防接种史随社会。","个人史及过敏史":"生于原籍，久居本地，无疫区疫水接触史，无特殊粉尘毒物放射性物质接触史。不吸烟，不饮酒。生活规律。否认食物药物过敏史。","体格检查":"T36.5℃，P76次/分，R18次/分，BP118/74mmHg。神志清楚，查体合作。上腹部轻压痛（+），无肌紧张反跳痛，肝脾未触及。贫血貌（-）（恶性贫血）。","辅助检查":"检查计划：患者反复上腹隐痛、餐后饱胀、早饱、嗳气、食欲减退3年，近2周加重，且有消瘦乏力，需完善胃镜加黏膜活检以明确黏膜萎缩（血管透见）、肠上皮化生及异型增生程度，并按OLGA/OLGIM系统进行病理分期以评估癌变风险并制定随访间隔；同时完善幽门螺杆菌检测（尿素呼气试验）明确有无Hp现症感染，阳性者行四联疗法根除以阻断萎缩进展；查血常规了解有无大细胞性贫血，提示维生素B12缺乏所致恶性贫血；查维生素B12及叶酸明确有无吸收障碍及缺乏程度，为补充甲钴胺提供依据；查抗壁细胞抗体及抗内因子抗体以明确有无A型萎缩性胃炎（自身免疫性胃炎）；完善血清胃泌素及胃蛋白酶原Ⅰ/Ⅱ比值检查评估萎缩部位与程度，作为无创筛查及随访指标；查肝肾功能及电解质为长期用药及内镜检查安全性提供依据。患者伴中-重度萎缩或肠上皮化生者需每1~3年定期复查胃镜，伴低级别异型增生者缩短至6~12个月复查。\n\n（检查清单）\n【必做】胃镜+活检（黏膜萎缩（血管透见）、肠化生、异型增生，病理分期（OLGA/OLGIM））、幽门螺杆菌检测（尿素呼气试验，Hp现症感染）；【血液】血常规（大细胞性贫血：维生素B12缺乏）、维生素B12及叶酸、抗壁细胞抗体/抗内因子抗体（A型萎缩性胃炎）；【其他】血清胃泌素、胃蛋白酶原（Ⅰ/Ⅱ比值，萎缩程度筛查指标）。","初步诊断":"1. 慢性萎缩性胃炎（B型（胃窦）：A型（胃体）/B型（胃窦），伴肠上皮化生/异型增生无）\n（注：治疗：①Hp阳性者根除（四联疗法：PPI+铋剂+两种抗生素（阿莫西林1g+克拉霉素0.5g，均bid×14天），可部分逆转萎缩、阻断进展）；②对症（促动力莫沙必利5mg tid、胃黏膜保护剂（瑞巴派特/替普瑞酮）、消化酶）；③随访：伴中-重度萎缩/肠化生者每1~3年胃镜复查（异型增生者缩短，低级别每6~12个月/高级别内镜切除），不伴者3年；④A型监测维生素B12（缺乏者补充甲钴胺）；戒烟酒、少盐少腌制、补充叶酸及维生素C（部分证据）；筛查胃癌高危人群（家族史者胃镜筛查）。）","处理方案":"【药物治疗】\n1. 根除幽门螺杆菌（Hp阳性者）：铋剂四联方案，如\"艾司奥美拉唑镁肠溶片20mg bid+枸橼酸铋钾胶囊220mg bid+阿莫西林胶囊1.0g bid+克拉霉素片0.5g bid\"，口服×14天；青霉素过敏者以甲硝唑片0.4g bid替代阿莫西林。停药4周后复查13C/14C-尿素呼气试验评估根除效果。\n2. 胃黏膜保护修复：瑞巴派特片0.1g tid，或替普瑞酮胶囊50mg tid，餐后口服，疗程4～8周，促进胃黏膜修复、减轻萎缩进展。\n3. 促动力及助消化：腹胀、纳差明显者予多潘立酮片10mg tid（餐前15～30分钟口服），或复方消化酶胶囊1粒 tid，餐中或餐后口服。\n4. 补充叶酸及维生素B12：血清叶酸或维生素B12缺乏者予叶酸片5mg tid、甲钴胺片0.5mg tid，口服，疗程1～3个月，防治贫血并可能延缓萎缩进展。\n【一般治疗及生活指导】\n1. 注意休息，避免熬夜、过度劳累及精神紧张，保持心情舒畅，保证充足睡眠。\n2. 饮食规律，少食多餐，细嚼慢咽；宜清淡、易消化、富含蛋白质及维生素；忌烟酒、浓茶、咖啡及辛辣、过烫、过硬、腌制及油炸食物；避免长期服用阿司匹林、布洛芬等非甾体抗炎药及激素。\n3. 适当运动（如散步、慢跑、太极拳），增强体质；讲究饮食卫生，实行分餐制、使用公筷，避免幽门螺杆菌交叉感染。\n4. 积极治疗伴发的胆汁反流、糖尿病等基础疾病，避免其加重胃黏膜萎缩。\n【随诊要求】\n1. 萎缩性胃炎伴肠上皮化生或异型增生者，建议6～12个月复查胃镜并多点活检；无肠化及异型增生者建议1～3年复查胃镜1次。\n2. 根除幽门螺杆菌者于停药4周后复查尿素呼气试验；根除失败者建议行幽门螺杆菌药敏试验后更换方案补救治疗。\n3. 定期复查血常规、血清铁、叶酸及维生素B12，及时发现并纠正缺铁性贫血及巨幼细胞性贫血。\n4. 中重度萎缩或伴中高级别异型增生者，转消化内科专科长期随访，必要时行内镜下黏膜切除或外科手术，并定期监测胃癌风险。"},"icd10_diagnosis":"","icd10_secondary":[],"icd9cm3_procedure":[]}},"locator":{"file":"门诊住院病历模板/病历模板包_全部_20261111.json","arrayRow":413,"caseRow":1},"sourceHash":"10e4fdb435986b7b85f847c3951d0cb0eafdce0f372c5617949c05b337149194","contentHash":"85b990ddf0bbb96576e18a4187b6b2438eae3161107b8f121a1290873fe9a221","pinyin":"weisuoxingweiyan","initials":"wsxwy","setting":"out","caseName":"门诊病历278","templateNames":["主诉","现病史","既往史","个人史及过敏史","体格检查","辅助检查","初步诊断","处理方案"],"emptyTemplates":[],"escapedNewlines":[],"quickFields":[["病例名称","门诊病历278",60],["模板名称","主诉 现病史 既往史 个人史及过敏史 体格检查 辅助检查 初步诊断 处理方案",30],["主要诊断编码","",30]]},{"id":"templates-ba6de67e63333e3f5217","key":"v1-c9ccc21dfe2a3058|templates-ba6de67e63333e3f5217","module":"templates","moduleKey":"v1-c9ccc21dfe2a3058|templates","version":"v1-c9ccc21dfe2a3058","title":"糜烂性胃炎","category":"门诊病历模板","raw":{"name":"糜烂性胃炎","category":"门诊病历模板","case":{"case_name":"门诊病历279","templates":{"主诉":"上腹灼痛、反酸伴恶心3天","现病史":"患者于3天前（进食刺激性食物/饮酒/服用NSAIDs（阿司匹林、布洛芬等）/应激后）出现上腹灼痛/隐痛、反酸、烧心、恶心、嗳气，无呕血、黑便（有无呕血、黑便，警惕糜烂出血，量及颜色），食欲减退。有无消化性溃疡史及Hp感染史：无。今日来我院门诊就诊。","既往史":"既往体健，否认高血压、糖尿病、冠心病等慢性病史。否认肝炎、结核等传染病史。否认手术外伤史。否认食物药物过敏史。预防接种史随社会。","个人史及过敏史":"生于原籍，久居本地，无疫区疫水接触史，无特殊粉尘毒物放射性物质接触史。不吸烟，不饮酒。生活规律。否认食物药物过敏史。","体格检查":"T36.8℃，P84次/分，R18次/分，BP122/76mmHg。神志清楚，查体合作。上腹轻压痛（+），无肌紧张反跳痛。肠鸣音正常。大便隐血（-）。","辅助检查":"检查计划：患者3天前有进食刺激性食物、饮酒或服用NSAIDs等诱因，出现上腹灼痛、反酸、烧心、恶心、嗳气，需完善胃镜检查以明确胃窦、胃体黏膜充血水肿及多发性糜烂灶（平坦型或隆起型）并观察有无出血点，此为确诊依据；完善幽门螺杆菌检测（尿素呼气试验）明确有无Hp感染，阳性者在炎症消退后行根除治疗以减少复发；查血常规了解血红蛋白及红细胞水平，排除糜烂出血所致贫血，尤其注意有无呕血黑便等出血征象；完善大便隐血检查明确有无消化道慢性失血；查凝血功能及血小板评估出血风险，为是否行内镜下止血及用药提供依据；查肝肾功能为质子泵抑制剂及胃黏膜保护剂的选用与剂量调整提供依据；查电解质了解有无因恶心、进食减少所致电解质紊乱；患者需长期服用NSAIDs时，完善心血管及肾脏风险评估相关检查（血压、肾功能）以指导是否换用选择性COX-2抑制剂并加用PPI预防；治疗4~6周后复查胃镜评估糜烂愈合情况。\n\n（检查清单）\n【必做】胃镜（胃窦/胃体黏膜充血水肿、多发性糜烂灶（平坦/隆起）、出血点，可确诊）、幽门螺杆菌检测（尿素呼气试验）；【其他】血常规（出血者查血红蛋白）、大便隐血。","初步诊断":"1. 急性糜烂性胃炎（出血性/非出血性）\n（注：治疗：①去除诱因（停用NSAIDs、戒酒、避免刺激饮食）；②抑酸：质子泵抑制剂（奥美拉唑20mg bid或埃索美拉唑20mg qd~bid，疗程4~6周，促糜烂愈合）；③胃黏膜保护剂（硫糖铝/铝碳酸镁）；④促动力/对症（恶心予莫沙必利）；⑤Hp阳性者炎症消退后根除；⑥出血者（呕血黑便、Hb下降）：急诊处理（禁食、静脉PPI（奥美拉唑40mg bid）、必要时内镜下止血）；长期需NSAIDs者评估（换用选择性COX-2抑制剂/PPI预防，根除Hp后）。）","处理方案":"【药物治疗】\n1. 抑酸治疗：奥美拉唑肠溶胶囊20mg qd，早餐前30分钟口服，疗程4周；亦可用雷贝拉唑肠溶片10mg qd或艾司奥美拉唑镁肠溶片20mg qd替代。\n2. 胃黏膜保护：铝碳酸镁咀嚼片1.0g（2片）tid，餐后1小时嚼服，疗程2-4周；可与抑酸药序贯或联合使用。\n3. 幽门螺杆菌阳性者行四联根除治疗：阿莫西林胶囊1.0g bid＋克拉霉素片0.5g bid＋奥美拉唑肠溶胶囊20mg bid＋枸橼酸铋钾片220mg bid，疗程14天（青霉素过敏者将阿莫西林改为左氧氟沙星片0.5g qd或甲硝唑片0.4g bid）。\n4. 伴腹胀、早饱、嗳气者：枸橼酸莫沙必利片5mg tid，餐前15-30分钟口服，疗程2周。\n\n【一般治疗及生活指导】\n1. 休息与情志：规律作息，保证充足睡眠，避免熬夜及长期精神紧张、焦虑，保持情绪平稳。\n2. 饮食：清淡、易消化饮食，少食多餐、细嚼慢咽；忌辛辣、过酸、过甜、过冷过热食物，戒烟限酒，避免浓茶、咖啡及油炸粗糙食物。\n3. 禁忌：尽量避免阿司匹林、布洛芬等非甾体抗炎药及糖皮质激素，确需使用者医师指导下联合PPI保护胃黏膜。\n4. 活动：适当进行散步等轻中度运动，避免饭后剧烈活动，保持大便通畅。\n\n【随诊要求】\n1. 用药2周后复诊评估症状缓解及药物耐受情况；疗程结束后（4周）复查胃镜，评估糜烂愈合情况。\n2. 行根除治疗者，停药（抗生素及铋剂≥4周、PPI≥2周）后复查13C/14C尿素呼气试验，明确幽门螺杆菌是否根除。\n3. 治疗期间若出现呕血、黑便、进行性消瘦、贫血或症状持续不缓解，应随时复诊，必要时完善上消化道钡餐或病理活检以排除恶变。"},"icd10_diagnosis":"","icd10_secondary":[],"icd9cm3_procedure":[]}},"locator":{"file":"门诊住院病历模板/病历模板包_全部_20261111.json","arrayRow":414,"caseRow":1},"sourceHash":"10e4fdb435986b7b85f847c3951d0cb0eafdce0f372c5617949c05b337149194","contentHash":"d538b83cd3cd15295556210d553d94e1423072f723292e6221bb6a8741980c24","pinyin":"milanxingweiyan","initials":"mlxwy","setting":"out","caseName":"门诊病历279","templateNames":["主诉","现病史","既往史","个人史及过敏史","体格检查","辅助检查","初步诊断","处理方案"],"emptyTemplates":[],"escapedNewlines":[],"quickFields":[["病例名称","门诊病历279",60],["模板名称","主诉 现病史 既往史 个人史及过敏史 体格检查 辅助检查 初步诊断 处理方案",30],["主要诊断编码","",30]]},{"id":"templates-5bd2f146c75f35d08b74","key":"v1-c9ccc21dfe2a3058|templates-5bd2f146c75f35d08b74","module":"templates","moduleKey":"v1-c9ccc21dfe2a3058|templates","version":"v1-c9ccc21dfe2a3058","title":"胃息肉","category":"门诊病历模板","raw":{"name":"胃息肉","category":"门诊病历模板","case":{"case_name":"门诊病历280","templates":{"主诉":"体检发现胃内隆起性病变1月","现病史":"患者于____（体检/因上腹不适行胃镜）发现胃息肉：部位____（胃底/胃体/胃窦），大小约____cm，数量____（单发/多发），形态____（带蒂/广基），活检病理：____（增生性息肉/胃底腺息肉/腺瘤性息肉，管状/绒毛状）。目前无上腹痛、无呕血黑便、无消瘦。有无长期PPI服用史（胃底腺息肉相关）、Hp感染及胃癌/肠癌家族史：____。今日来我院门诊就诊。","既往史":"既往体健，否认高血压、糖尿病、冠心病等慢性病史。否认肝炎、结核等传染病史。否认手术外伤史。否认食物药物过敏史。预防接种史随社会。","个人史及过敏史":"生于原籍，久居本地，无疫区疫水接触史，无特殊粉尘毒物放射性物质接触史。不吸烟，不饮酒。生活规律。否认食物药物过敏史。","体格检查":"T36.6℃，P78次/分，R18次/分，BP120/75mmHg。神志清楚，查体合作。腹部检查未见明显异常，无压痛及包块。","辅助检查":"【必做】胃镜+活检（息肉大小、形态、病理类型，处理决策核心）；【其他】若为腺瘤性息肉或伴胃癌家族史，同期结肠镜（排除结肠腺瘤，共同危险因素）；Hp检测。","初步诊断":"1. 胃息肉（____：部位，____：大小，病理：____性）\n（注：处理依据病理：增生性息肉（最常见，恶变率低）：<0.5cm可随访（1~2年），较大或出血者内镜下切除；胃底腺息肉（长期PPI相关）：停PPI后部分消退，大者切除；腺瘤性息肉（癌前病变：恶变率与其大小/绒毛成分/异型程度相关），均应内镜下切除（EMR/ESD），切除后每1年复查胃镜（3~6个月首次复查创面）；伴Hp感染者根除（可促增生性息肉消退）；多发息肉病（如黑斑息肉综合征、家族性腺瘤性息肉病），遗传咨询及全身筛查。）","处理方案":"【药物治疗】\n1. 根除幽门螺杆菌（适用于幽门螺杆菌阳性相关增生性息肉）：四联方案：奥美拉唑肠溶胶囊20mg bid + 阿莫西林胶囊1.0g bid + 克拉霉素片0.5g bid + 枸橼酸铋钾颗粒220mg bid，餐前30分钟口服，疗程14天；停药4周后复查13C/14C呼气试验。\n2. 抑酸治疗：雷贝拉唑钠肠溶片20mg qd，晨起空腹口服，疗程2-4周，用于息肉切除术后创面愈合及反酸、烧心症状控制。\n3. 胃黏膜保护：瑞巴派特片0.1g tid，餐后口服，疗程2-4周，促进创面修复。\n4. 创面较大或切除术后出血风险高者：加用硫糖铝混悬液5ml tid，餐前1小时及睡前口服，疗程1-2周。\n\n【一般治疗及生活指导】\n1. 饮食：切除术后当天进流质饮食，次日过渡至半流质、软食；忌粗糙、过硬、辛辣刺激及过烫食物，避免损伤创面引起出血。\n2. 生活：戒烟限酒（术后禁酒2周以上），规律作息，避免劳累及精神紧张。\n3. 活动：术后2周内避免剧烈运动及重体力劳动，防止创面脱落出血。\n4. 禁忌：术后1-2周内避免使用阿司匹林、布洛芬等非甾体抗炎药及抗凝/抗血小板药物（确需使用者需医师评估后决定），以防创面出血。\n\n【随诊要求】\n1. 根除幽门螺杆菌者停药4周后复查呼气试验，仍阳性者予补救方案再次根除。\n2. 内镜下切除后按病理复查胃镜：增生性息肉6-12个月后复查；腺瘤性息肉3-6个月后复查；胃底腺息肉1-2年复查。\n3. 术后2周内如出现黑便、呕血、持续性腹痛加剧等，及时复诊或急诊就医。"},"icd10_diagnosis":"","icd10_secondary":[],"icd9cm3_procedure":[]}},"locator":{"file":"门诊住院病历模板/病历模板包_全部_20261111.json","arrayRow":415,"caseRow":1},"sourceHash":"10e4fdb435986b7b85f847c3951d0cb0eafdce0f372c5617949c05b337149194","contentHash":"2e306031d4157e75154ac7488c3aeae02aa04d05d4bf3686d77cb4994fd49087","pinyin":"weixirou","initials":"wxr","setting":"out","caseName":"门诊病历280","templateNames":["主诉","现病史","既往史","个人史及过敏史","体格检查","辅助检查","初步诊断","处理方案"],"emptyTemplates":[],"escapedNewlines":[],"quickFields":[["病例名称","门诊病历280",60],["模板名称","主诉 现病史 既往史 个人史及过敏史 体格检查 辅助检查 初步诊断 处理方案",30],["主要诊断编码","",30]]},{"id":"templates-b2c63230a4e4c18245c4","key":"v1-c9ccc21dfe2a3058|templates-b2c63230a4e4c18245c4","module":"templates","moduleKey":"v1-c9ccc21dfe2a3058|templates","version":"v1-c9ccc21dfe2a3058","title":"肠息肉","category":"门诊病历模板","raw":{"name":"肠息肉","category":"门诊病历模板","case":{"case_name":"门诊病历281","templates":{"主诉":"反复便血、排便习惯改变1月","现病史":"患者于____（体检/因便血、腹泻便秘交替行结肠镜）发现结肠息肉：部位____（直肠/乙状结肠/降结肠/横结肠/升结肠），大小约____cm，数量____（单发/多发），形态____（带蒂/无蒂/扁平），病理：____（腺瘤性（管状/绒毛状/管状绒毛状）/增生性/炎性）。有无便血（鲜血附着/黑便）、排便习惯及性状改变、腹痛腹胀，有无大肠癌/腺瘤家族史及炎性肠病史：____。今日来我院门诊就诊。","既往史":"既往体健，否认高血压、糖尿病、冠心病等慢性病史。否认肝炎、结核等传染病史。否认手术外伤史。否认食物药物过敏史。预防接种史随社会。","个人史及过敏史":"生于原籍，久居本地，无疫区疫水接触史，无特殊粉尘毒物放射性物质接触史。不吸烟，不饮酒。生活规律。否认食物药物过敏史。","体格检查":"T36.7℃，P80次/分，R18次/分，BP124/78mmHg。神志清楚，查体合作。腹部未见异常，无压痛及包块。直肠指诊未触及异常（距肛缘8cm未触及异常/未触及异常），指套无染血。","辅助检查":"【必做】结肠镜+活检（息肉完整评估，建议全结肠检查排除同时性病变）、病理；【其他】如为锯齿状息肉/侧向发育型肿瘤，高清内镜（NBI/放大）精细评估；疑遗传性息肉病（幼年性息肉病/黑斑息肉综合征/家族性腺瘤性息肉病，多发/幼年起病/家族史）：基因检测。","初步诊断":"1. 结肠息肉（____：部位，病理：____性腺瘤/增生性等）\n（注：腺瘤性息肉为结直肠癌癌前病变，均应内镜下切除（息肉切除，圈套器EMR，大的/侧向发育型ESD），送完整病理；切除后随访：低危腺瘤（1~2个<1cm管状），5~10年复查；高危腺瘤（≥3个、≥1cm、绒毛状、伴高级别异型增生），3年复查（首年复查创面）；增生性息肉（直肠小、<5mm）可随访；一级亲属有大肠癌/腺瘤者，提早至40岁或比亲属发病年龄早10年筛查；便血者注意与痔鉴别（勿漏诊）。）","处理方案":"【药物治疗】\n1. 保持大便通畅、预防便秘：乳果糖口服溶液15ml po qd（早餐后服用），以每日排便1～2次成形软便为宜，疗程1～2周。\n2. 调节肠道菌群：双歧杆菌三联活菌胶囊420mg po tid，凉水或温牛奶送服，疗程2周。\n3. 息肉切除术后黏膜修复：复方谷氨酰胺肠溶胶囊2粒 po tid，饭前服用，疗程2周。\n\n【一般治疗及生活指导】\n1. 饮食：多食新鲜蔬菜、水果及全谷类等富含膳食纤维食物（每日膳食纤维25～30g），减少红肉及加工肉制品摄入，戒烟限酒，避免辛辣刺激及油腻饮食。\n2. 活动：适当运动（快走、慢跑、游泳等）每周不少于150分钟，控制体重（BMI 18.5～23.9kg/m²），避免久坐。\n3. 排便习惯：保持规律排便，避免长期便秘或腹泻，养成定时排便习惯。\n4. 禁忌：息肉切除术后1～2周内避免剧烈运动、重体力劳动及提举重物；禁饮酒；暂停服用阿司匹林、布洛芬等抗血小板及抗凝药物（遵医嘱调整）。\n\n【随诊要求】\n1. 息肉切除术后1年内复查肠镜；若为多发性腺瘤（≥3枚）、绒毛状腺瘤、锯齿状腺瘤或息肉直径≥1cm、病理提示高级别上皮内瘤变者，术后6个月复查肠镜；非腺瘤性小息肉（如增生性息肉）可1～3年复查。\n2. 复查肠镜前须规范行肠道准备，按处方服用复方聚乙二醇电解质散并控制饮食。\n3. 随访期间若出现便血、黑便、腹痛、排便习惯或大便性状改变，及时门诊就诊。"},"icd10_diagnosis":"","icd10_secondary":[],"icd9cm3_procedure":[]}},"locator":{"file":"门诊住院病历模板/病历模板包_全部_20261111.json","arrayRow":416,"caseRow":1},"sourceHash":"10e4fdb435986b7b85f847c3951d0cb0eafdce0f372c5617949c05b337149194","contentHash":"733319d2e0ef956854e1d961c03564aeedd922afa5f86772158d73b44ad41304","pinyin":"changxirou","initials":"cxr","setting":"out","caseName":"门诊病历281","templateNames":["主诉","现病史","既往史","个人史及过敏史","体格检查","辅助检查","初步诊断","处理方案"],"emptyTemplates":[],"escapedNewlines":[],"quickFields":[["病例名称","门诊病历281",60],["模板名称","主诉 现病史 既往史 个人史及过敏史 体格检查 辅助检查 初步诊断 处理方案",30],["主要诊断编码","",30]]},{"id":"templates-887dc2700aa565129aad","key":"v1-c9ccc21dfe2a3058|templates-887dc2700aa565129aad","module":"templates","moduleKey":"v1-c9ccc21dfe2a3058|templates","version":"v1-c9ccc21dfe2a3058","title":"憩室炎","category":"门诊病历模板","raw":{"name":"憩室炎","category":"门诊病历模板","case":{"case_name":"门诊病历282","templates":{"主诉":"左下腹疼痛伴发热3天","现病史":"患者于2天前出现左下腹（乙状结肠憩室炎最常见）持续性隐痛/胀痛，阵发性加重，进食后加重，伴发热（体温最高38.6℃）、恶心、食欲减退，无便秘/腹泻、里急后重，无便血（有无便秘/腹泻、里急后重、便血，警惕憩室出血），尿频尿急（结肠膀胱瘘，炎性包块压迫/瘘道形成时），无呕吐。既往有无憩室病史、长期便秘史：无。今日来我院门诊就诊。","既往史":"既往体健，否认高血压、糖尿病、冠心病等慢性病史。否认肝炎、结核等传染病史。否认手术外伤史。否认食物药物过敏史。预防接种史随社会。","个人史及过敏史":"生于原籍，久居本地，无疫区疫水接触史，无特殊粉尘毒物放射性物质接触史。不吸烟，不饮酒。生活规律。否认食物药物过敏史。","体格检查":"T38.2℃，P96次/分，R20次/分，BP126/78mmHg。神志清楚，急性病容。腹平软，左下腹压痛（+），可及包块（炎性包块，左下腹），反跳痛及肌紧张（-）（穿孔，腹膜炎时全腹压痛反跳痛），肠鸣音减弱（减弱/正常）。直肠指诊：左侧直肠壁压痛（左侧直肠壁压痛，盆位憩室炎）。","辅助检查":"【必做】血常规（白细胞升高）、CRP（显著升高）、腹部CT增强（结肠壁增厚、憩室周围脂肪间隙模糊、蜂窝织炎/脓肿，为诊断及分级首选，较钡灌肠/结肠镜安全（急性期禁行结肠镜，穿孔风险））；【其他】尿常规（膀胱受累）、老年/不典型者结肠镜（炎症消退6~8周后，排除结肠癌，重要！）。","初步诊断":"1. 急性憩室炎（轻度：轻度/中度/重度（Hinchey分级））\n（注：轻度（无并发症、可耐受口服）：门诊口服抗生素（环丙沙星0.5g bid+甲硝唑0.4g tid，或阿莫西林克拉维酸0.625g tid）×7~10天+流质/低渣饮食+对症；中重度（发热高、脓肿、腹膜炎、免疫低下）予住院静脉抗生素（哌拉西林他唑巴坦或头孢曲松+甲硝唑）+禁食补液；脓肿形成（>3~5cm）行CT引导穿刺引流；穿孔/弥漫性腹膜炎/瘘行急诊手术（切除病变肠段（Hartmann术或一期吻合））；炎症消退后复查结肠镜（排除肿瘤）；恢复后高纤维饮食减少复发（急性期低渣）。）","处理方案":"【药物治疗】\n1. 抗感染治疗（覆盖革兰阴性菌及厌氧菌，疗程7天）：首选阿莫西林克拉维酸钾片0.625g tid（餐后口服）×7天；或头孢呋辛酯片0.25g bid+甲硝唑片0.4g tid×7天；对青霉素及头孢菌素过敏者改用左氧氟沙星片0.5g qd+甲硝唑片0.4g tid×7天。\n2. 解痉止痛：匹维溴铵片50mg tid（餐时服用），缓解左下腹绞痛。\n3. 肠道微生态调节：双歧杆菌三联活菌胶囊0.42g bid（与抗菌药物间隔2小时以上服用），减少抗生素相关性腹泻。\n【一般治疗及生活指导】\n1. 休息：急性期适当卧床休息，避免剧烈活动及劳累。\n2. 饮食：急性期予流质或半流质清淡饮食（米汤、粥、烂面条），少食多餐，避免高纤维及产气食物（粗粮、豆类、韭菜等）；症状缓解后逐步过渡至低渣饮食，恢复期及平时建议高纤维饮食（每日膳食纤维25～35g），保证每日饮水2000ml以上，保持大便通畅。\n3. 禁忌：避免用力排便、提重物、屏气等增加腹压的动作；纠正便秘，必要时口服乳果糖口服溶液15ml qd（晨起），禁用刺激性泻药及灌肠。\n4. 活动：症状缓解后循序渐进恢复日常活动，规律运动，控制体重，戒烟限酒。\n【随诊要求】\n用药后48～72小时复诊评估症状缓解情况，复查血常规、C反应蛋白；若腹痛持续加重、高热不退或出现腹膜刺激征，需立即急诊就诊以排除穿孔、脓肿等并发症。疗程结束后1周门诊复诊；建议4～6周后行结肠镜检查，明确诊断并排除结直肠肿瘤等病变。憩室炎反复发作≥2次或曾并发脓肿、穿孔者，建议转普外科/胃肠外科评估择期手术治疗。"},"icd10_diagnosis":"","icd10_secondary":[],"icd9cm3_procedure":[]}},"locator":{"file":"门诊住院病历模板/病历模板包_全部_20261111.json","arrayRow":417,"caseRow":1},"sourceHash":"10e4fdb435986b7b85f847c3951d0cb0eafdce0f372c5617949c05b337149194","contentHash":"2687b6da5545426036796e4cb0719c453fd4878f8fd2521900b65485ab889a1c","pinyin":"qishiyan","initials":"qsy","setting":"out","caseName":"门诊病历282","templateNames":["主诉","现病史","既往史","个人史及过敏史","体格检查","辅助检查","初步诊断","处理方案"],"emptyTemplates":[],"escapedNewlines":[],"quickFields":[["病例名称","门诊病历282",60],["模板名称","主诉 现病史 既往史 个人史及过敏史 体格检查 辅助检查 初步诊断 处理方案",30],["主要诊断编码","",30]]},{"id":"templates-a8a0917e06b34f1bff8e","key":"v1-c9ccc21dfe2a3058|templates-a8a0917e06b34f1bff8e","module":"templates","moduleKey":"v1-c9ccc21dfe2a3058|templates","version":"v1-c9ccc21dfe2a3058","title":"缺血性肠病","category":"门诊病历模板","raw":{"name":"缺血性肠病","category":"门诊病历模板","case":{"case_name":"门诊病历283","templates":{"主诉":"突发左下腹剧痛伴便血1天","现病史":"患者（老年、动脉粥样硬化/房颤/低血压/心衰/腹部血管手术史）于2天前突发左下腹（左下腹/脐周/全腹）剧烈绞痛，呈持续性，阵发加剧，后出现便血（暗红色/鲜血，量约200ml）、腹泻，伴恶心呕吐、低热，无腹膜炎表现（有无恶心呕吐、发热、腹膜炎表现，警惕肠坏死时），进食后腹痛加重（肠系膜缺血特征，慢性型：餐后腹痛、体重下降、惧食）。有无房颤、动脉硬化、血压过低（休克/脱水）、近期心梗/心衰等诱因：无。今日来我院急诊就诊。","既往史":"既往体健，否认高血压、糖尿病、冠心病等慢性病史。否认肝炎、结核等传染病史。否认手术外伤史。否认食物药物过敏史。预防接种史随社会。","个人史及过敏史":"生于原籍，久居本地，无疫区疫水接触史，无特殊粉尘毒物放射性物质接触史。不吸烟，不饮酒。生活规律。否认食物药物过敏史。","体格检查":"T37.6℃，P98次/分（可增快），R20次/分，BP142/86mmHg。神志清楚，痛苦面容。腹部早期体征轻（腹痛剧烈与体征不符，缺血性肠病特征，需警惕肠坏死），渐出现压痛、反跳痛肌紧张（肠坏死，腹膜炎），肠鸣音减弱（早期亢进后减弱消失），移动性浊音（-）（腹水，坏死晚期），直肠指诊：指套染血。","辅助检查":"检查计划：患者老年、有动脉粥样硬化或房颤、低血压等基础，2天前突发左下腹剧烈绞痛呈持续性阵发加剧，随后出现暗红色便血约200ml伴恶心呕吐、低热，需急诊即刻完善血常规了解白细胞升高及血液浓缩情况，评估感染与脱水程度；急诊完善血气分析明确有无代谢性酸中毒，此为肠坏死的重要线索；查血乳酸了解有无升高并动态监测，乳酸持续升高提示肠缺血进展或肠坏死，是决定是否剖腹探查的重要指标；查D-二聚体了解血栓活动情况；查心肌肌钙蛋白排除急性心肌损伤及心源性栓塞；完善肝肾功能及血淀粉酶评估脏器功能并鉴别急性胰腺炎所致腹痛；急诊完成腹部CT增强血管成像（CTA）观察肠系膜上动脉、下动脉及静脉有无栓塞或血栓，肠壁有无增厚、积气及门静脉积气等坏死征象，此为诊断首选且不可延误；患者便血明显，病情稳定后完善结肠镜检查观察结肠黏膜有无淤血坏死及缺血后狭窄，急性期操作需谨慎以防穿孔；如CTA提示血管病变且需血管再通，行DSA检查兼作诊断金标准与介入取栓、溶栓治疗；治疗期间动态复查血气分析、血乳酸及腹部体征，出现持续腹膜炎或肠坏死征象时立即手术。\n\n（检查清单）\n【必做】血常规（白细胞升高、血液浓缩）、血气分析（代谢性酸中毒，肠坏死重要线索）、血乳酸（升高）、D-二聚体、心肌肌钙蛋白、肝肾功能、血淀粉酶；【影像学】腹部CT增强血管成像（CTA，观察肠系膜血管（上动脉/下动脉/静脉）栓塞或血栓、肠壁增厚/积气（肠壁气肿，坏死征象）、门静脉积气，为诊断首选）；【其他】结肠镜（结肠缺血，急性期谨慎、黏膜淤血坏死）、DSA（急性肠系膜缺血，诊断金标准兼介入治疗）。","初步诊断":"1. 缺血性肠病（急性肠系膜缺血（动脉栓塞/血栓、静脉血栓）：急性肠系膜缺血（动脉栓塞/血栓、静脉血栓）/结肠缺血/慢性肠系膜缺血）\n（注：急性肠系膜缺血为致死性急症（死亡率高），需立即急诊：①禁食、胃肠减压、积极液体复苏、广谱抗生素（覆盖肠道菌群，哌拉西林他唑巴坦/碳青霉烯）、纠正酸中毒；②尽早血管再通（6~12小时黄金时间窗）：肠系膜上动脉栓塞行急诊取栓/导管溶栓/血管成形；③持续腹膜炎/肠坏死征象（CT肠壁气肿、腹水、乳酸持续升高）行急诊剖腹探查切除坏死肠段（二期吻合）；慢性/结肠缺血（轻症）：保守（液体复苏、抗凝（房颤：华法林/NOAC）、避免低血压、广谱抗生素），随访结肠镜（缺血后狭窄）；明确病因（房颤抗凝治疗防再栓塞）。）","处理方案":"【药物治疗】\n1. 改善肠道微循环、扩血管：贝前列素钠片40μg tid po×2周（门诊首选）；症状较重者予前列地尔注射液10μg加入0.9%氯化钠注射液100ml ivdrip qd×7～10天。\n2. 抗血小板（动脉粥样硬化性缺血者）：阿司匹林肠溶片100mg qd po×长期，餐后服；不耐受者改氯吡格雷片75mg qd po×长期。\n3. 防治继发感染（肠黏膜屏障受损时短程使用）：左氧氟沙星片0.5g qd po×3～5天；或头孢克肟胶囊0.1g bid po×3～5天。\n4. 肠道黏膜保护及菌群调节：蒙脱石散3g tid po×1周；双歧杆菌三联活菌胶囊420mg tid po×2周，与抗生素间隔2小时以上服用。\n\n【一般治疗及生活指导】\n1. 发作期卧床或半卧位休息，避免剧烈活动与劳累；腹痛、便血明显时暂禁食或仅进流质，缓解后改低渣、少纤维、易消化饮食，少食多餐，避免暴饮暴食及生冷刺激食物。\n2. 严格戒烟戒酒；积极控制高血压、高血脂、糖尿病等基础病，避免低血压、脱水、心功能不全等诱发肠道缺血的因素。\n3. 避免使用收缩血管药物（如麦角类、拟交感神经药）及强利尿剂、过量洋地黄等可加重肠缺血的药物。\n4. 保持大便通畅，避免便秘及用力屏气排便；如厕勿久蹲。\n\n【随诊要求】\n1. 门诊治疗3～5天复诊，评估腹痛、便血及腹泻缓解情况；若腹痛持续加重、便血增多、出现发热或腹膜炎体征（压痛、反跳痛、肌紧张），须立即急诊就诊。\n2. 治疗2周后复查血常规、大便常规+隐血，行腹部增强CT或结肠镜检查评估肠黏膜血供及恢复情况，明确有无狭窄等后遗改变。\n3. 合并动脉粥样硬化及心脑血管疾病者，按心内科/血管外科专科随访，规范抗栓及危险因素管理；症状反复发作或提示慢性肠系膜缺血者，转诊血管外科评估介入或手术治疗。"},"icd10_diagnosis":"","icd10_secondary":[],"icd9cm3_procedure":[]}},"locator":{"file":"门诊住院病历模板/病历模板包_全部_20261111.json","arrayRow":418,"caseRow":1},"sourceHash":"10e4fdb435986b7b85f847c3951d0cb0eafdce0f372c5617949c05b337149194","contentHash":"fb304eab39d4f7b151f36f25728893c6bf4292ae0e810e068ada8c02dad50490","pinyin":"quexuexingchangbing","initials":"qxxcb","setting":"out","caseName":"门诊病历283","templateNames":["主诉","现病史","既往史","个人史及过敏史","体格检查","辅助检查","初步诊断","处理方案"],"emptyTemplates":[],"escapedNewlines":[],"quickFields":[["病例名称","门诊病历283",60],["模板名称","主诉 现病史 既往史 个人史及过敏史 体格检查 辅助检查 初步诊断 处理方案",30],["主要诊断编码","",30]]},{"id":"templates-62374cc2f092eace8865","key":"v1-c9ccc21dfe2a3058|templates-62374cc2f092eace8865","module":"templates","moduleKey":"v1-c9ccc21dfe2a3058|templates","version":"v1-c9ccc21dfe2a3058","title":"伪膜性肠炎","category":"门诊病历模板","raw":{"name":"伪膜性肠炎","category":"门诊病历模板","case":{"case_name":"门诊病历284","templates":{"主诉":"腹泻伴发热、腹痛3天","现病史":"患者于2周前使用广谱抗生素（克林霉素或头孢类或氟喹诺酮或阿莫西林克拉维酸等，最常见诱因），停药后1周出现腹泻（每日6次，水样便，重症可呈米汤样，可伴脱落的伪膜），伴发热（体温最高38.5℃）、腹痛、腹胀、恶心，有轻度脱水，无低血压，无中毒性巨结肠表现（腹胀加剧、停止排气），无近期住院、免疫低下及炎症性肠病史。今日来我院门诊就诊。","既往史":"既往体健，否认高血压、糖尿病、冠心病等慢性病史。否认肝炎、结核等传染病史。否认手术外伤史。否认食物药物过敏史。预防接种史随社会。","个人史及过敏史":"生于原籍，久居本地，无疫区疫水接触史，无特殊粉尘毒物放射性物质接触史。不吸烟，不饮酒。生活规律。否认食物药物过敏史。","体格检查":"T38.5℃，P96次/分，R20次/分，BP110/70mmHg。神志清楚，精神可，皮肤弹性稍差（脱水评估），腹部膨隆（+），全腹或脐周压痛（+），肠鸣音活跃（减弱或消失提示中毒性巨结肠），反跳痛、肌紧张（-）。","辅助检查":"检查计划：患者2周前使用克林霉素等广谱抗生素，停药1周后出现每日6次水样便，伴发热38.5℃、腹痛腹胀、恶心及轻度脱水，需完善粪便艰难梭菌毒素检测（A/B毒素酶免疫法或核酸扩增）以确诊，必要时采用谷氨酸脱氢酶（GDH）联合毒素的两步法提高检出率；查血常规了解白细胞有无显著升高（>15×10⁹/L提示重症）并评估脱水血液浓缩；查肝肾功能了解药物代谢及有无低白蛋白血症等重症指标；查电解质明确有无腹泻所致低钾低钠等紊乱并及时纠正；查血乳酸评估组织灌注，升高提示重症或暴发性感染；查白蛋白了解营养状态，降低提示重症及预后不良；完善腹部X线或CT检查观察有无结肠扩张（横结肠>6cm提示中毒性巨结肠）、结肠壁增厚及拇指印征；如诊断不明或需鉴别其他结肠炎，可考虑结肠镜检查观察黄白色隆起斑块样伪膜，但重症者慎行以防穿孔；治疗期间动态复查血常规、电解质、白蛋白及腹部影像，警惕中毒性巨结肠与肠穿孔。\n\n（检查清单）\n【必做】粪便艰难梭菌毒素检测（A/B毒素酶免疫法或核酸扩增，为确诊核心，比培养更特异）或谷氨酸脱氢酶（GDH）+毒素两步法、血常规（白细胞可显著升高，>15×10⁹/L提示重症）、肝肾功能、电解质、血乳酸、白蛋白（降低提示重症）；【影像学】腹部X线或CT（结肠扩张（横结肠>6cm提示中毒性巨结肠）、结肠壁增厚、拇指印征）；【内镜】结肠镜（伪膜，呈黄白色隆起斑块附着，为典型表现；重症慎行，有穿孔风险）。","初步诊断":"1. 艰难梭菌感染（抗生素相关性伪膜性肠炎，轻中度）\n（注：①立即停用诱发抗生素（最重要）；②轻中度：口服万古霉素125mg qid×10天或非达霉素200mg bid×10天（或甲硝唑500mg tid（轻症））；重症或暴发性：万古霉素125mg qid口服（或经鼻肠管）+静脉甲硝唑，必要时万古霉素灌肠；③暴发性（中毒性巨结肠、休克、穿孔）：外科手术（全结肠切除）评估；④复发（首次治疗后6~8周内再现，约20%）：万古霉素脉冲或递减方案或粪菌移植（FMT，复发难治者）；⑤感染控制（手卫生、隔离、消毒）；补液纠正脱水，避免使用止泻药（防毒素潴留）。）","处理方案":"【药物治疗】\n1. 口服万古霉素胶囊0.125g qid（重症0.25g qid）×10～14天，为轻、中、重度病例的首选方案，重症可与静脉甲硝唑联合；\n2. 甲硝唑片0.5g tid口服×10～14天，适用于轻中度病例（无万古霉素或不能耐受时）；\n3. 非达霉素片0.2g bid口服×10天，初发及复发均可选用，疗效与万古霉素相当且复发率更低；\n4. 布拉氏酵母菌散0.5g bid口服，于抗菌药物停用后服用，与万古霉素间隔2小时以上，辅助恢复肠道菌群平衡。\n【一般治疗及生活指导】\n1. 立即停用或调整诱发本病的抗菌药物（在临床允许前提下），禁用抑制肠蠕动的止泻药（如洛哌丁胺、阿托品等），以免毒素滞留肠腔加重病情；\n2. 注意卧床休息，多饮温水或口服补液盐以纠正水、电解质紊乱；进清淡、易消化的流质或半流质饮食（如米汤、藕粉、烂面条），少食多餐，避免生冷、油腻及高纤维食物，腹泻明显时暂免乳制品；\n3. 便后肥皂水洗手，餐具、衣物及卫生间做好隔离消毒，避免与家人交叉感染；不与免疫力低下者共用卫生间及餐具；\n4. 每日监测体温、大便次数、性状及腹部症状，警惕高热不退、腹胀明显、血便及脱水等重症迹象。\n【随诊要求】\n1. 治疗3天后症状无改善，或出现高热、剧烈腹泻、明显腹胀、血便、意识改变等，应立即复诊或住院治疗；\n2. 症状好转亦须完成足疗程，不可自行停药，疗程结束后1～2周门诊复查评估；\n3. 本病复发率约20%～30%，疗程结束后2个月内再次出现腹泻者应尽早复诊，必要时复查粪便艰难梭菌毒素，并考虑万古霉素递减/脉冲疗程、非达霉素或粪菌移植等复发性治疗方案。"},"icd10_diagnosis":"","icd10_secondary":[],"icd9cm3_procedure":[]}},"locator":{"file":"门诊住院病历模板/病历模板包_全部_20261111.json","arrayRow":419,"caseRow":1},"sourceHash":"10e4fdb435986b7b85f847c3951d0cb0eafdce0f372c5617949c05b337149194","contentHash":"fded1fe057a8923d21dbbc98bb71b63aff8a904289e04508aa4bc4892c53447c","pinyin":"weimoxingchangyan","initials":"wmxcy","setting":"out","caseName":"门诊病历284","templateNames":["主诉","现病史","既往史","个人史及过敏史","体格检查","辅助检查","初步诊断","处理方案"],"emptyTemplates":[],"escapedNewlines":[],"quickFields":[["病例名称","门诊病历284",60],["模板名称","主诉 现病史 既往史 个人史及过敏史 体格检查 辅助检查 初步诊断 处理方案",30],["主要诊断编码","",30]]},{"id":"templates-c6e61dc74df16ec4aa02","key":"v1-c9ccc21dfe2a3058|templates-c6e61dc74df16ec4aa02","module":"templates","moduleKey":"v1-c9ccc21dfe2a3058|templates","version":"v1-c9ccc21dfe2a3058","title":"放射性肠炎","category":"门诊病历模板","raw":{"name":"放射性肠炎","category":"门诊病历模板","case":{"case_name":"门诊病历285","templates":{"主诉":"反复腹泻、腹痛伴便血3月","现病史":"患者因宫颈癌接受放射治疗（总剂量50Gy），放疗结束后6个月出现腹泻（每日4次，黏液血便）、里急后重、腹痛（痉挛性），有便血（放射性直肠炎常见），伴肛门坠胀、食欲减退、体重下降，无肠梗阻表现（慢性纤维化狭窄），便后缓解。今日来我院门诊就诊。","既往史":"既往体健，否认高血压、糖尿病、冠心病等慢性病史。否认肝炎、结核等传染病史。否认手术外伤史。否认食物药物过敏史。预防接种史随社会。","个人史及过敏史":"生于原籍，久居本地，无疫区疫水接触史，无特殊粉尘毒物放射性物质接触史。不吸烟，不饮酒。生活规律。否认食物药物过敏史。","体格检查":"T36.8℃，P80次/分，R18次/分，BP110/70mmHg。神志清楚，查体合作，营养状况稍差。腹部压痛（+，左下腹），肠鸣音活跃，直肠指诊示直肠前壁黏膜粗糙、触血阳性。","辅助检查":"【必做】结肠镜（放射性肠炎：黏膜充血水肿、毛细血管扩张（血管扩张）、糜烂溃疡、狭窄，病变范围与原放疗野一致）；【影像学】腹部CT或小肠造影（小肠放射性损伤，可见狭窄、瘘）；【其他】血常规（贫血）、白蛋白（营养）、大便常规及培养（排除感染，放射性损伤基础上易继发）。","初步诊断":"1. 放射性肠炎（慢性，放疗后数月至数年，直肠部位）\n（注：治疗：急性期以对症为主（止泻：洛哌丁胺或蒙脱石散、黏膜保护剂（硫糖铝灌肠或口服）、益生菌），多数放疗结束后缓解；慢性：①腹泻或里急后重：5-氨基水杨酸制剂（美沙拉嗪）灌肠、糖皮质激素灌肠（布地奈德，局部抗炎）、硫糖铝灌肠、益生菌；②便血（毛细血管扩张）：内镜下氩离子凝固术（APC，疗效好）、福尔马林局部灌洗；③营养支持（要素饮食或肠外营养，营养不良者）、补充维生素B12（末端回肠损伤）；④狭窄、梗阻或瘘：内镜扩张或手术（造口）；⑤避免NSAIDs；治疗肿瘤随访（需与肿瘤复发或转移鉴别，行影像及内镜活检）。）","处理方案":"【药物治疗】\n1.黏膜保护及止泻：蒙脱石散3g tid，餐前口服，腹泻缓解后逐渐减量至停药；腹泻严重（每日≥6次）可临时加用洛哌丁胺胶囊2mg，腹泻后口服，24小时总量不超过8mg，感染性腹泻及高热时禁用。\n2.肠道微生态调节：双歧杆菌三联活菌胶囊（培菲康）420mg（2粒）tid，餐后凉开水送服，与抗菌药物间隔2小时以上，疗程2~4周。\n3.局部抗炎治疗（直肠及乙状结肠受累明显者）：美沙拉嗪灌肠液4g/100ml，每晚睡前排空大便后保留灌肠（至少保留30分钟），疗程2~4周；便血明显者可用地塞米松5mg+0.9%氯化钠注射液100ml保留灌肠，每晚1次，疗程1~2周。\n4.肠黏膜营养修复：谷氨酰胺颗粒5g bid，餐后温水冲服，疗程4周，促进受损肠黏膜修复。\n\n【一般治疗及生活指导】\n1.休息：急性期注意卧床休息、避免劳累，减少肠蠕动对受损黏膜的刺激；放疗后1年内避免剧烈运动及重体力劳动。\n2.饮食：进少渣、低纤维、高蛋白、高维生素易消化饮食，少量多餐；忌辛辣刺激、油腻、过冷过热食物，避免牛奶及乳制品（乳糖不耐受可加重腹泻），腹泻期暂停粗纤维蔬菜及坚果。\n3.活动及肛周护理：避免久坐，每日温水坐浴1~2次（直肠、肛门受累者），便后及时清洁并保持肛周皮肤干燥，预防肛周皮肤破损及感染。\n4.禁忌：避免使用非甾体抗炎药等损伤肠黏膜药物；放疗结束后3~6个月内避免无指征的灌肠、直肠指检等刺激性操作，确需肠镜等检查应由专科医师评估后进行。\n\n【随诊要求】\n1.治疗期间每周复诊1次，评估腹泻、便血、腹痛等症状变化；腹泻明显者每2~4周复查血常规、肝肾功能及电解质，监测并纠正脱水、电解质紊乱。\n2.放疗结束后6个月内为急性放射性肠炎高发期，出现持续或大量便血、剧烈腹痛、发热、腹胀呕吐等表现需立即就诊，警惕肠梗阻、肠穿孔、肠瘘等严重并发症，必要时行肠镜检查及营养支持治疗。\n3.转为慢性放射性肠炎者建议每6~12个月复查肠镜，动态评估肠管狭窄及黏膜病变，监测营养状况，防治肠狭窄、瘘管及放疗相关第二肿瘤风险。"},"icd10_diagnosis":"","icd10_secondary":[],"icd9cm3_procedure":[]}},"locator":{"file":"门诊住院病历模板/病历模板包_全部_20261111.json","arrayRow":420,"caseRow":1},"sourceHash":"10e4fdb435986b7b85f847c3951d0cb0eafdce0f372c5617949c05b337149194","contentHash":"5604cfa956c5075cf99430a21ab1070b69f19880dd86fa79d30999fc41984d40","pinyin":"fangshexingchangyan","initials":"fsxcy","setting":"out","caseName":"门诊病历285","templateNames":["主诉","现病史","既往史","个人史及过敏史","体格检查","辅助检查","初步诊断","处理方案"],"emptyTemplates":[],"escapedNewlines":[],"quickFields":[["病例名称","门诊病历285",60],["模板名称","主诉 现病史 既往史 个人史及过敏史 体格检查 辅助检查 初步诊断 处理方案",30],["主要诊断编码","",30]]},{"id":"templates-fb6db9b19fb727174580","key":"v1-c9ccc21dfe2a3058|templates-fb6db9b19fb727174580","module":"templates","moduleKey":"v1-c9ccc21dfe2a3058|templates","version":"v1-c9ccc21dfe2a3058","title":"吸收不良综合征","category":"门诊病历模板","raw":{"name":"吸收不良综合征","category":"门诊病历模板","case":{"case_name":"门诊病历286","templates":{"主诉":"慢性腹泻伴体重下降1年","现病史":"患者于____月/年前开始腹泻（每日____次，量大、恶臭、油腻漂浮（脂肪泻，陶土色/油滴）、腹胀、肠鸣亢进），体重下降约____kg，伴乏力、贫血、____（有无维生素及矿物质缺乏表现：口角炎舌炎（B族）、皮肤干燥出血倾向（脂溶性维生素ADEK）、手足麻木（B12）、骨痛病理性骨折（钙D）、夜盲（A）、低蛋白水肿），有无乳糜泻、慢性胰腺炎、小肠切除、Whipple病、寄生虫病等基础病及长期饮酒史：____。今日来我院门诊就诊。","既往史":"既往体健，否认高血压、糖尿病、冠心病等慢性病史。否认肝炎、结核等传染病史。否认手术外伤史。否认食物药物过敏史。预防接种史随社会。","个人史及过敏史":"生于原籍，久居本地，无疫区疫水接触史，无特殊粉尘毒物放射性物质接触史。不吸烟，不饮酒。生活规律。否认食物药物过敏史。","体格检查":"T36.5℃，P88次/分，R18次/分，BP100/65mmHg，BMI17.5kg/m²。神志清楚，慢性消耗貌，皮肤干燥、弹性差，口角炎、舌炎（+），下肢水肿（+）（低蛋白），腹部膨隆、肠鸣音亢进，杵状指（-）。","辅助检查":"【必做】粪脂肪定性（苏丹Ⅲ染色）及72小时粪脂肪定量（>7g/24h，可确诊脂肪泻）、血常规（贫血，呈大细胞性或小细胞性）、白蛋白（降低）、铁蛋白、叶酸、维生素B12、25-(OH)D、钙磷、凝血功能（PT延长，提示维生素K缺乏）；【病因学】乳糜泻血清学（抗组织转谷氨酰胺酶抗体tTG-IgA阳性，需行内镜十二指肠活检）、小肠镜+活检（绒毛萎缩，提示乳糜泻）、粪便虫卵（寄生虫）、胰腺功能（粪弹力蛋白酶，评估慢性胰腺炎）、呼气试验（乳糖不耐受或小肠细菌过度生长）；【影像学】腹部CT（胰腺钙化，提示慢性胰腺炎；并评估小肠疾病）、小肠钡餐或MRE。","初步诊断":"1. 吸收不良综合征（病因待查：乳糜泻、慢性胰腺炎或短肠等）\n（注：①病因治疗（核心）：乳糜泻予严格终身无麸质饮食（禁小麦大麦黑麦）、补充缺乏营养素；慢性胰腺炎予胰酶替代（胰酶肠溶胶囊，随餐服用）；小肠细菌过度生长予利福昔明550mg tid×14天；寄生虫予驱虫治疗；②对症及营养支持：低脂或中链甘油三酯饮食（MCT，可直接吸收）、补充脂溶性维生素（ADEK）、维生素B12、叶酸、铁、钙（B12缺乏者肌注甲钴胺）、肠内或肠外营养（严重者）；③监测体重、白蛋白、骨密度（代谢性骨病，酌情使用双膦酸盐）；找消化内科或营养科专科系统评估病因，明确诊断是治疗关键。）","处理方案":"【药物治疗】\n1. 胰酶替代治疗：胰酶肠溶胶囊（如得每通）0.3g tid，于进餐中随餐吞服，连用2-4周，症状改善后可长期维持，注意不可嚼碎。\n2. 补充消化酶及益生菌：复方消化酶胶囊1粒 tid餐后口服；双歧杆菌三联活菌胶囊420mg bid，连用2周，以改善消化吸收功能。\n3. 补充维生素及矿物质：维生素AD软胶囊1粒 qd；维生素E软胶囊100mg qd；碳酸钙D3片（含钙600mg）1片 qd；叶酸片5mg tid；维生素B12注射液500μg im qw，连用4周，后根据复查水平调整。\n4. 对症止泻：腹泻明显者予蒙脱石散3g tid餐前口服，水样便缓解后停药；伴明显腹胀、腹泻者注意口服补液（ORS）维持水电解质平衡。\n\n【一般治疗及生活指导】\n1. 饮食：低脂、高蛋白、高热量、易消化饮食，少量多餐（每日5-6餐），减少油腻、煎炸食物及乳制品摄入，避免辛辣刺激性食物。\n2. 病因性饮食管理：疑似乳糜泻者须严格无麸质饮食（禁小麦、大麦、黑麦及其制品）；乳糖不耐受者避免含乳糖奶制品。\n3. 休息与活动：急性期适当卧床休息、避免劳累，症状缓解后循序渐进恢复日常活动；戒烟限酒，避免暴饮暴食。\n4. 用药禁忌：避免长期滥用抗生素、非甾体抗炎药及泻药，以防肠道菌群紊乱加重吸收障碍。\n\n【随诊要求】\n1. 2周后门诊复诊，评估腹泻、腹胀、体重等改善情况，必要时调整胰酶及药物剂量。\n2. 定期复查血常规、电解质、肝功能、白蛋白、血脂、25-(OH)D3、叶酸、维生素B12水平及粪便脂肪定性/定量，动态监测营养状态。\n3. 体重持续下降或症状反复者，建议完善小肠镜/胶囊内镜、小肠细菌过度生长呼气试验等进一步明确病因，并遵医嘱长期随访。"},"icd10_diagnosis":"","icd10_secondary":[],"icd9cm3_procedure":[]}},"locator":{"file":"门诊住院病历模板/病历模板包_全部_20261111.json","arrayRow":421,"caseRow":1},"sourceHash":"10e4fdb435986b7b85f847c3951d0cb0eafdce0f372c5617949c05b337149194","contentHash":"540d0a4a63ce3af4dd751077f09f535e15e9a1367aa056dd46d62880fda5bed6","pinyin":"xishoubuliangzonghezheng","initials":"xsblzhz","setting":"out","caseName":"门诊病历286","templateNames":["主诉","现病史","既往史","个人史及过敏史","体格检查","辅助检查","初步诊断","处理方案"],"emptyTemplates":[],"escapedNewlines":[],"quickFields":[["病例名称","门诊病历286",60],["模板名称","主诉 现病史 既往史 个人史及过敏史 体格检查 辅助检查 初步诊断 处理方案",30],["主要诊断编码","",30]]},{"id":"templates-6e85105bc3c0dc90aef7","key":"v1-c9ccc21dfe2a3058|templates-6e85105bc3c0dc90aef7","module":"templates","moduleKey":"v1-c9ccc21dfe2a3058|templates","version":"v1-c9ccc21dfe2a3058","title":"短肠综合征","category":"门诊病历模板","raw":{"name":"短肠综合征","category":"门诊病历模板","case":{"case_name":"门诊病历287","templates":{"主诉":"小肠切除术后腹泻伴体重下降3月","现病史":"患者因肠系膜缺血坏死于7个月前行小肠广泛切除（切除长度约350cm，保留小肠约100cm，未保留回盲瓣），术后1个月开始出现腹泻（每日8次，大量水样泻）、体重下降约12kg、乏力、腹胀，有末端回肠造口（造口排出量约1500ml/d），有维生素B12缺乏（回肠切除致贫血、神经症状），无草酸盐肾结石（脂肪泻致肠源性高草酸尿）、胆结石、D-乳酸酸中毒（碳水化合物发酵致意识模糊），有脱水及电解质紊乱史。今日来我院门诊就诊。","既往史":"既往体健，否认高血压、糖尿病、冠心病等慢性病史。否认肝炎、结核等传染病史。否认手术外伤史。否认食物药物过敏史。预防接种史随社会。","个人史及过敏史":"生于原籍，久居本地，无疫区疫水接触史，无特殊粉尘毒物放射性物质接触史。不吸烟，不饮酒。生活规律。否认食物药物过敏史。","体格检查":"T36.5℃，P96次/分，R20次/分，BP95/60mmHg（血压偏低，提示脱水），BMI16.8kg/m²。神志清楚，消瘦，皮肤弹性差（脱水），下肢水肿（-）（低蛋白或维生素缺乏时可出现），腹部可见手术瘢痕及造口，腹软，肠鸣音活跃。","辅助检查":"【必做】血常规、肝肾功能、电解质（低钾低镁）、白蛋白、前白蛋白（营养）、维生素（B12、D、A、E）、微量元素（锌、硒）、铁蛋白、血气分析（代谢性酸中毒）、粪量及粪电解质（评估）；【其他】血清枸橼酸/尿草酸（肾结石监测）、骨密度（代谢性骨病）、D-乳酸（疑D-乳酸酸中毒时）。","初步诊断":"1. 短肠综合征（保留小肠100cm，不伴结肠，稳定期）\n（注：治疗（多学科：消化、营养、外科）：①肠内营养为主（少量多餐、要素或半要素制剂，促进肠适应），静脉营养（肠外营养，用于早期或严重者，目标过渡至肠内）；②药物：止泻（洛哌丁胺或可待因，餐前服用）、抑酸（PPI，用于高胃酸分泌期）、胰酶（脂肪泻时虽无胰病但可辅助）、生长抑素类似物（奥曲肽，减少分泌性腹泻）、重组人胰高血糖素样肽2（替度鲁肽，促肠适应，用于重度短肠）；③营养补充：维生素B12（回肠切除者每月肌注甲钴胺）、镁锌硒钙、脂溶性维生素、中链甘油三酯；④防治并发症（草酸盐结石：低草酸低脂饮食+口服钙、胆结石）；⑤外科：肠康复手术（肠延长术或小肠移植，肠衰竭依赖肠外营养者应评估）；定期监测肝功（肠外营养相关肝病，优化静脉营养方案）。）","处理方案":"【药物治疗】\n1. 止泻：洛哌丁胺胶囊（易蒙停）2mg，首剂4mg，此后每次稀便后加服2mg，每日总量不超过16mg，餐前30分钟服用，以减少肠蠕动、控制腹泻及减少肠液丢失。\n2. 抑酸：奥美拉唑肠溶胶囊20mg，每日1-2次（晨起空腹及睡前各1次），疗程4周起，视胃酸分泌过多及腹泻控制情况调整，以减少胃酸对残余肠黏膜的损伤并缓解高胃泌素血症相关腹泻。\n3. 胰酶替代：复方胰酶肠溶胶囊（得每通0.15g）每次1-2粒，随餐或餐后立即整粒吞服，根据脂肪泻程度调整剂量，改善脂肪吸收及脂溶性维生素缺乏。\n4. 营养补充：口服复合维生素制剂（含脂溶性维生素A、D、E、K）每日1片；葡萄糖酸钙片0.5g每日3次，镁、锌、铁等微量元素按化验结果个体化补充，纠正钙镁及微量营养素缺乏。\n\n【一般治疗及生活指导】\n1. 饮食：少食多餐，每日6-8餐、每餐少量；以高蛋白、高碳水化合物、低脂、低乳糖、低草酸盐为原则，主食选精细米面，适量进食可溶性膳食纤维（燕麦、香蕉、苹果泥）以延缓肠排空；忌油炸肥腻、酒精、辛辣刺激及高草酸食物（菠菜、甜菜、浓茶、巧克力），以防草酸钙肾结石。\n2. 口服补液：腹泻期间于两餐间少量多次口服补液盐（ORS），避免一次性大量饮水及高渗饮料（果汁、含糖碳酸饮料），每日记录出入量与体重变化，防止脱水和电解质紊乱。\n3. 活动与休息：保证充足睡眠、避免劳累及剧烈运动；注意手卫生与饮食卫生，避免生冷食物，预防肠道感染诱发腹泻加重。\n4. 用药注意：避免使用非甾体抗炎药及各类泻药，以免损伤残余肠黏膜；戒烟，减少肠黏膜刺激。\n\n【随诊要求】\n1. 初诊或出院后1-2周复诊，复查血电解质（钾、钠、氯、钙、镁）、肝肾功能、白蛋白及前白蛋白，评估水电解质与营养状况。\n2. 每月监测体重及营养状况；每1-3个月复查血清维生素B12、叶酸、铁蛋白、锌、铜、硒及脂溶性维生素水平，发现缺乏及时补充。\n3. 每6-12个月行双能X线骨密度（DXA）检查筛查骨质疏松，并复查腹部超声，警惕胆结石及肾结石形成。\n4. 出现发热、剧烈腹痛、腹胀、呕吐、腹泻加重或便血等应及时就诊；病情稳定后由营养科及胃肠外科评估肠康复治疗与长期营养支持方案，逐步调整经口饮食和静脉营养比例。"},"icd10_diagnosis":"","icd10_secondary":[],"icd9cm3_procedure":[]}},"locator":{"file":"门诊住院病历模板/病历模板包_全部_20261111.json","arrayRow":422,"caseRow":1},"sourceHash":"10e4fdb435986b7b85f847c3951d0cb0eafdce0f372c5617949c05b337149194","contentHash":"02c7046cd23f9b6b8015026be8fc390e412eab1990fd2b345719154e68472cfd","pinyin":"duanchangzonghezheng","initials":"dczhz","setting":"out","caseName":"门诊病历287","templateNames":["主诉","现病史","既往史","个人史及过敏史","体格检查","辅助检查","初步诊断","处理方案"],"emptyTemplates":[],"escapedNewlines":[],"quickFields":[["病例名称","门诊病历287",60],["模板名称","主诉 现病史 既往史 个人史及过敏史 体格检查 辅助检查 初步诊断 处理方案",30],["主要诊断编码","",30]]},{"id":"templates-79866aee703e571e61dd","key":"v1-c9ccc21dfe2a3058|templates-79866aee703e571e61dd","module":"templates","moduleKey":"v1-c9ccc21dfe2a3058|templates","version":"v1-c9ccc21dfe2a3058","title":"肝肾综合征","category":"门诊病历模板","raw":{"name":"肝肾综合征","category":"门诊病历模板","case":{"case_name":"门诊病历288","templates":{"主诉":"尿量进行性减少伴腹胀加重2周","现病史":"患者有肝硬化病史10年（病因：乙肝），反复腹水，有大量放腹水未补充白蛋白、使用利尿剂过量诱因，无食管静脉曲张出血、自发性腹膜炎，无NSAIDs或肾毒性药物使用史，近2周尿量明显减少（24小时约500ml）、腹胀加重、乏力、食欲减退，无发热、腹痛（合并感染），无呕血黑便，无意识改变（肝性脑病），大便颜色。今日来我院门诊就诊。","既往史":"既往体健，否认高血压、糖尿病、冠心病等慢性病史。否认肝炎、结核等传染病史。否认手术外伤史。否认食物药物过敏史。预防接种史随社会。","个人史及过敏史":"生于原籍，久居本地，无疫区疫水接触史，无特殊粉尘毒物放射性物质接触史。不吸烟，不饮酒。生活规律。否认食物药物过敏史。","体格检查":"T36.8℃，P88次/分，R18次/分，BP92/60mmHg（偏低）。神志清楚（嗜睡提示肝性脑病，需查扑翼样震颤），皮肤巩膜黄染（+），肝掌蜘蛛痣（+），腹膨隆、移动性浊音（+）（腹水）、腹壁静脉曲张，双下肢水肿（+），脐疝（-）。","辅助检查":"【必做】肾功能（血肌酐升高，>133μmol/L或符合急性肾损伤标准，为诊断核心）、尿常规及尿钠（尿钠<10mmol/L、尿渗透压高于血浆，呈肾前性特征，提示功能性肾衰）、血电解质、肝功能（Child-Pugh）、凝血功能、血常规（血小板减少，提示脾亢）、白蛋白；【鉴别】尿蛋白及沉渣（排除急性肾小管坏死，尿钠>40）、肾脏超声（排除梗阻及肾实质病）；【其他】腹水检查（排除自发性腹膜炎，SBP为本病常见诱因）、血培养。","初步诊断":"1. 肝肾综合征（肝硬化基础上功能性肾衰竭，1型：快速进展，2周内肌酐翻倍）\n（注：1型HRS预后极差，需积极处理：①去除诱因（停用利尿剂、NSAIDs及肾毒性药、治疗SBP（头孢噻肟2g q8h）及消化道出血（生长抑素+内镜套扎））；②血管活性药物+白蛋白（特利加压素0.5~1mg iv q4~6h（或去甲肾上腺素）+白蛋白20~40g/d，联合用药可逆转；用药期间监测血压尿量）；③TIPS（经颈静脉肝内门体分流，用于难治性腹水或等待移植者）；④肝移植（唯一根治手段，需评估移植时机）；⑤血液透析或人工肝（桥接）；预后差（1型不移植中位生存<1月），应尽早转肝病专科及移植中心；戒酒、利尿适度（体重下降<0.5kg/d）。）","处理方案":"【药物治疗】\n1. 血管活性药物联合白蛋白（HRS-AKI一线方案）：特利加压素注射液1mg静脉注射q6h（或0.5-2mg持续静脉泵入），联合人血白蛋白20-40g/d静脉滴注，疗程5-15天，直至血清肌酐较基线下降≥25%或恢复至133μmol/L（1.5mg/dl）以下；\n2. 米多君片7.5mg口服tid（可渐增至12.5mg tid），联合醋酸奥曲肽注射液100μg皮下注射tid，用于特利加压素不可及或不能耐受者，疗程同前（5-15天）；\n3. 乳果糖口服溶液10-15ml口服bid，保持每日1-2次软便，预防肝性脑病并减少内毒素血症诱因；合并感染证据时加用三代头孢（如头孢噻肟钠2g静脉滴注q8h）抗感染，疗程5-7天。\n【一般治疗及生活指导】\n1. 严格卧床休息，每日晨起空腹测体重、腹围，记录24小时出入量，避免劳累及剧烈活动；\n2. 低盐饮食（钠盐<2g/d），控制液体入量（约500-1000ml/d加前日尿量），优质蛋白饮食约1.0-1.2g/kg/d，禁酒；\n3. 绝对禁用非甾体抗炎药（布洛芬、双氯芬酸等）、氨基糖苷类及造影剂等肾毒性药物；慎用利尿剂，避免快速大量放腹水导致有效血容量骤降；\n4. 保持大便通畅，注意手卫生及皮肤、口腔护理，预防感染、消化道出血等HRS诱因。\n【随诊要求】\n1. 每周复诊，复查肝功能、肾功能（肌酐、尿素氮）、电解质（重点血钠、血钾）及尿量、体重变化；\n2. 每2周复查血常规、凝血功能（PT/INR）、血氨，评估出血及肝性脑病风险；\n3. 出现24小时尿量<400ml（少尿）或<100ml（无尿）、肌酐进行性升高、意识障碍、呕血黑便、血压下降时，立即急诊就诊，必要时住院治疗；\n4. 动态评估病情转归，符合条件者转肝移植中心评估移植时机。"},"icd10_diagnosis":"","icd10_secondary":[],"icd9cm3_procedure":[]}},"locator":{"file":"门诊住院病历模板/病历模板包_全部_20261111.json","arrayRow":423,"caseRow":1},"sourceHash":"10e4fdb435986b7b85f847c3951d0cb0eafdce0f372c5617949c05b337149194","contentHash":"a7f4e40acc295957e3bcb8c0325a7bfd88e9d0e03251965607a7b1cc4ee4c369","pinyin":"ganshenzonghezheng","initials":"gszhz","setting":"out","caseName":"门诊病历288","templateNames":["主诉","现病史","既往史","个人史及过敏史","体格检查","辅助检查","初步诊断","处理方案"],"emptyTemplates":[],"escapedNewlines":[],"quickFields":[["病例名称","门诊病历288",60],["模板名称","主诉 现病史 既往史 个人史及过敏史 体格检查 辅助检查 初步诊断 处理方案",30],["主要诊断编码","",30]]},{"id":"templates-0b2ee6d49b1780f02cb9","key":"v1-c9ccc21dfe2a3058|templates-0b2ee6d49b1780f02cb9","module":"templates","moduleKey":"v1-c9ccc21dfe2a3058|templates","version":"v1-c9ccc21dfe2a3058","title":"肝性脑病","category":"门诊病历模板","raw":{"name":"肝性脑病","category":"门诊病历模板","case":{"case_name":"门诊病历289","templates":{"主诉":"意识障碍伴行为异常3天","现病史":"患者有肝硬化病史8年，近3天出现性格改变（欣快）、行为异常（昼夜颠倒、随地大小便）、定向力障碍、言语不清、计算力下降及嗜睡，意识障碍分级（West Haven：Ⅰ~Ⅳ级），有明显诱因：高蛋白饮食及便秘，无上消化道出血、感染（SBP）、大量放腹水或利尿过度、低钾碱中毒、镇静药或酒精使用、TIPS术后，无呕血黑便、发热，有腹胀，大便3天未解。今日来我院急诊就诊。","既往史":"既往体健，否认高血压、糖尿病、冠心病等慢性病史。否认肝炎、结核等传染病史。否认手术外伤史。否认食物药物过敏史。预防接种史随社会。","个人史及过敏史":"生于原籍，久居本地，无疫区疫水接触史，无特殊粉尘毒物放射性物质接触史。不吸烟；饮酒25年，约2两/日。生活规律。否认食物药物过敏史。","体格检查":"T____℃，P____次/分，R____次/分，BP____/____mmHg。神志____（Ⅰ级：轻微性格改变，可引出扑翼样震颤；Ⅳ级：昏迷），计算力/定向力____（减退），扑翼样震颤（+/-），肝掌蜘蛛痣（+），黄疸（+），腹水征（+/-），腱反射____，病理征____（Ⅲ~Ⅳ级出现，需排除颅内病变）。","辅助检查":"【必做】血氨（升高，但程度与分级不完全平行）、肝功能（Child-Pugh）、凝血功能、血常规（用于感染或出血评估）、电解质（低钾）、血气分析（碱中毒可促氨入脑）、血糖（低血糖鉴别）；【诱因排查】腹水检查（SBP）、大便隐血（消化道出血为最常见诱因）、胸片或血培养（感染）、尿常规；【影像学】头颅CT（排除颅内出血或梗死，意识障碍伴神经系统体征时需查）。","初步诊断":"1. 肝性脑病（Ⅱ级，与肝硬化相关，诱因：高蛋白饮食及便秘）\n（注：处理：①去除诱因（止血（食管静脉曲张出血予内镜套扎+生长抑素）、抗感染（SBP予头孢噻肟）、纠正电解质酸碱紊乱（补钾）、停镇静药、解除便秘）；②降氨：乳果糖口服（15~30ml tid，调至每日2~3次软便，为一线用药）或乳果糖灌肠、利福昔明550mg bid（联合用药或不能耐受乳果糖者使用，可降低复发）；③营养支持（早期肠内营养、植物蛋白或支链氨基酸，避免严格限蛋白，目前不推荐低蛋白饮食，反而有害）；④急性意识障碍（Ⅲ~Ⅳ级）：ICU监护、气道保护、预防误吸；⑤肝移植评估（难治性或反复发作者）；⑥复发预防（长期乳果糖或利福昔明、避免诱因）；需与低血糖、颅内出血、Wernicke脑病等鉴别。）","处理方案":"【药物治疗】\n1. 降氨治疗：乳果糖口服溶液15~30ml，bid~tid，以每日排便2~3次软便为宜，维持至神志清醒后逐渐减量；门冬氨酸鸟氨酸颗粒5g，tid，餐后口服，连用2~4周。\n2. 抑制肠道产氨菌：利福昔明片400mg，tid，7~14天，必要时与乳果糖联用预防复发。\n3. 支链氨基酸：口服支链氨基酸制剂10~20g，bid~tid，纠正支链/芳香族氨基酸失衡；进食差者静脉输注复方氨基酸注射液(3AA) 250ml，qd。\n4. 纠正诱因用药：合并感染、出血、电解质紊乱者针对性治疗，禁用含氨药物（如氯化铵）及含芳香族氨基酸制剂。\n【一般治疗及生活指导】\n1. 休息：急性期卧床休息，避免劳累、熬夜及精神紧张，保证充足睡眠。\n2. 饮食：保证每日热量30~35kcal/kg，以碳水化合物为主；急性期蛋白质摄入<40g/d或0.8~1.0g/(kg·d)，以植物蛋白、乳制品蛋白为主；多吃富含纤维素食物，保持大便通畅。\n3. 禁忌：绝对戒酒；禁用镇静催眠药（地西泮、巴比妥类）、麻醉药及阿片类镇痛药；慎用利尿剂，避免低钾、碱中毒诱发肝性脑病。\n4. 监测：每日观察性格改变、行为异常、扑翼样震颤、嗜睡等先兆症状，出现上述表现立即就诊。\n【随诊要求】\n1. 服药期间每周复查血氨、肝功能及凝血功能；出现定向力障碍、嗜睡、昏迷或扑翼样震颤加重，立即急诊就诊。\n2. 每2~4周门诊复诊，评估神志状态、肝功能及血氨水平，据排便情况调整乳果糖剂量、据病情调整利福昔明疗程。\n3. 伴腹水、低钾者每月复查电解质、肾功能及血氨，纠正低钾性碱中毒等诱因，防止复发。"},"icd10_diagnosis":"","icd10_secondary":[],"icd9cm3_procedure":[]}},"locator":{"file":"门诊住院病历模板/病历模板包_全部_20261111.json","arrayRow":424,"caseRow":1},"sourceHash":"10e4fdb435986b7b85f847c3951d0cb0eafdce0f372c5617949c05b337149194","contentHash":"d9806eb81db235f0b0536173e7375bdd7f3d389465f7a08401c372a3815873c5","pinyin":"ganxingnaobing","initials":"gxnb","setting":"out","caseName":"门诊病历289","templateNames":["主诉","现病史","既往史","个人史及过敏史","体格检查","辅助检查","初步诊断","处理方案"],"emptyTemplates":[],"escapedNewlines":[],"quickFields":[["病例名称","门诊病历289",60],["模板名称","主诉 现病史 既往史 个人史及过敏史 体格检查 辅助检查 初步诊断 处理方案",30],["主要诊断编码","",30]]},{"id":"templates-5b2ad8f42f750f9e45a3","key":"v1-c9ccc21dfe2a3058|templates-5b2ad8f42f750f9e45a3","module":"templates","moduleKey":"v1-c9ccc21dfe2a3058|templates","version":"v1-c9ccc21dfe2a3058","title":"急性间质性肾炎","category":"门诊病历模板","raw":{"name":"急性间质性肾炎","category":"门诊病历模板","case":{"case_name":"门诊病历290","templates":{"主诉":"用药后发热、皮疹伴尿量减少3天","现病史":"患者于10天前开始服用别嘌醇（常见致敏药物，同类尚包括抗生素（β-内酰胺类或氟喹诺酮）、NSAIDs、质子泵抑制剂、中草药等），用药1周后出现发热（体温最高38.5℃）、乏力，有皮疹（药疹）、关节痛，无腰痛，尿量减少（24小时约500ml），尿色呈洗肉水样（血尿），无少尿及水肿（急性肾衰表现），无尿频尿急尿痛。既往否认药物过敏史及肾脏病史。今日来我院门诊就诊。","既往史":"既往体健，否认高血压、糖尿病、冠心病等慢性病史。否认肝炎、结核等传染病史。否认手术外伤史。否认食物药物过敏史。预防接种史随社会。","个人史及过敏史":"生于原籍，久居本地，无疫区疫水接触史，无特殊粉尘毒物放射性物质接触史。不吸烟，不饮酒。生活规律。否认食物药物过敏史。","体格检查":"T38.5℃，P96次/分，R20次/分，BP130/80mmHg。神志清楚。皮肤可见斑丘疹，双肾区叩击痛（+），腹平软，双下肢水肿（-）。","辅助检查":"【必做】尿常规（无菌性白细胞尿、白细胞管型、嗜酸性粒细胞尿（嗜酸细胞>1%，提示AIN）、蛋白尿（少量）、血尿）、肾功能（血肌酐急性升高）、血常规（嗜酸性粒细胞升高）、尿钠及尿渗透压、电解质；【影像学】肾脏超声（双肾增大、皮质回声增强，并排除梗阻）；【确诊】肾穿刺活检（间质炎性细胞浸润（淋巴细胞、嗜酸性粒细胞）、水肿，为确诊金标准，诊断不明确或肾功能持续恶化时进行）。","初步诊断":"1. 急性间质性肾炎（药物相关性可能性大，与别嘌醇有关）\n（注：①立即停用可疑致敏药物（最关键，多数停药后肾功能可恢复）；②对症及支持（补液维持尿量、纠正电解质酸碱紊乱、监测肾功能、必要时透析（严重急性肾衰））；③糖皮质激素（停致病药物后3~5天肾功能无改善者：泼尼松30~60mg/d或甲泼尼龙冲击，疗程4~8周渐减，有助于恢复；NSAIDs相关者疗效不确定）；④避免再接触致敏药物（病历永久记录）；⑤预后：及时停药多数可恢复，部分遗留慢性肾损害，需随访肾功能3~6个月。）","处理方案":"【药物治疗】\n1. 停用致病药物（NSAIDs、青霉素类及头孢类抗生素、PPI、别嘌醇、利尿剂等）：立即停用一切可疑致病药物，轻症患者停用后1～3周肾功能多可自行恢复，此为治疗首要环节。\n2. 糖皮质激素：泼尼松片0.5～1mg/kg·d（成人常规30～40mg/d），晨起顿服，疗程4～6周；适用于停药后1周肾功能无改善、肾功能持续恶化或肾活检证实重症/肉芽肿性间质性肾炎者，显效后每1～2周减量5mg，总疗程不超过8～12周。\n3. 对症及支持治疗：伴高钾血症者予聚苯乙烯磺酸钠15g po tid或呋塞米20mg iv/qd促排钾并严格限钾；伴代谢性酸中毒（血HCO3⁻<15mmol/L）者予碳酸氢钠片1g po tid，需监测血电解质及血气；少尿期严格限制液体入量（每日入量=前日尿量+500ml）。\n4. 肾功能严重受损（血肌酐进行性升高、尿毒症症状或高钾血症药物难控制）时，及时转肾内科行血液透析等肾脏替代治疗，并纠正贫血、维持血压稳定。\n【一般治疗及生活指导】\n1. 急性期卧床休息，避免劳累、熬夜及剧烈运动，保证充足睡眠，待肾功能恢复后逐渐增加活动量。\n2. 饮食：低盐低脂饮食，每日食盐<5g；肾功能不全者限制蛋白摄入（0.6～0.8g/kg·d，以优质蛋白为主），控制水分摄入，少尿期忌高钾食物（香蕉、柑橘、土豆等）。\n3. 严禁自行服用NSAIDs类止痛药、成分不明中药、保健品及偏方；就医时主动告知既往药物过敏史，避免再次接触致病药物。\n4. 每日记录尿量、自测血压及体重，观察尿色、尿量变化，如出现少尿、水肿加重或肉眼血尿立即就医。\n【随诊要求】\n1. 治疗期间每周复查尿常规、肾功能（血肌酐、尿素氮）、电解质及尿蛋白定量，直至肾功能稳定。\n2. 停用激素后第2周、4周、8周复查尿常规、肾功能，重点监测尿蛋白、尿糖（近端肾小管损伤指标）及血肌酐恢复情况。\n3. 长期随访：若3～6个月肾功能未完全恢复或持续蛋白尿，应3～6个月复查肾功能并转肾内科行肾活检评估慢性化程度；随访期间监测血压，防治慢性肾脏病进展。"},"icd10_diagnosis":"","icd10_secondary":[],"icd9cm3_procedure":[]}},"locator":{"file":"门诊住院病历模板/病历模板包_全部_20261111.json","arrayRow":425,"caseRow":1},"sourceHash":"10e4fdb435986b7b85f847c3951d0cb0eafdce0f372c5617949c05b337149194","contentHash":"33828044f5ca7334241a6defa1f3cbb75cc8686600923e6387c0cb4d4ca5ef46","pinyin":"jixingjianzhixingshenyan","initials":"jxjzxsy","setting":"out","caseName":"门诊病历290","templateNames":["主诉","现病史","既往史","个人史及过敏史","体格检查","辅助检查","初步诊断","处理方案"],"emptyTemplates":[],"escapedNewlines":[],"quickFields":[["病例名称","门诊病历290",60],["模板名称","主诉 现病史 既往史 个人史及过敏史 体格检查 辅助检查 初步诊断 处理方案",30],["主要诊断编码","",30]]},{"id":"templates-c2748710a4017ef01801","key":"v1-c9ccc21dfe2a3058|templates-c2748710a4017ef01801","module":"templates","moduleKey":"v1-c9ccc21dfe2a3058|templates","version":"v1-c9ccc21dfe2a3058","title":"慢性间质性肾炎","category":"门诊病历模板","raw":{"name":"慢性间质性肾炎","category":"门诊病历模板","case":{"case_name":"门诊病历291","templates":{"主诉":"夜尿增多、乏力伴骨痛1年","现病史":"患者于2年前开始夜尿增多（3次/夜，提示早期肾浓缩功能受损，为慢性间质性肾炎特征）、多尿、乏力，渐出现贫血（与肾衰程度不符，较早出现）、食欲减退、恶心、骨痛（肾小管酸中毒，有低钾、酸中毒表现）、皮肤瘙痒，有长期服用镇痛药（非那西丁或对乙酰氨基酚，致镇痛剂肾病）史，无服用NSAIDs、锂盐、马兜铃酸（中草药肾病）及铅镉等重金属史，无慢性尿路梗阻或反流（梗阻性肾病）、高尿酸血症或痛风等病因。无高血压（常较轻，晚期出现）。今日来我院门诊就诊。","既往史":"既往体健，否认高血压、糖尿病、冠心病等慢性病史。否认肝炎、结核等传染病史。否认手术外伤史。否认食物药物过敏史。预防接种史随社会。","个人史及过敏史":"生于原籍，久居本地，无疫区疫水接触史，无特殊粉尘毒物放射性物质接触史。不吸烟，不饮酒。生活规律。否认食物药物过敏史。","体格检查":"T36.6℃，P82次/分，R18次/分，BP120/75mmHg。神志清楚，贫血貌（+）。双肾区无叩击痛。腹平软，双下肢无水肿。神经系统（低钾可致肌无力、腱反射减弱）。","辅助检查":"【必做】尿常规（尿蛋白少量（<1g/24h，区别于肾小球疾病大量蛋白尿）、尿糖（血糖正常，因肾小管重吸收障碍）、尿pH偏碱）、尿NAG或β2-微球蛋白（肾小管损伤标志）、肾功能（血肌酐、eGFR，呈慢性下降）、电解质（低钾或高氯性酸中毒，提示肾小管酸中毒）、血尿酸、血气分析（代谢性酸中毒）、血常规（贫血）；【影像学】肾脏超声（双肾缩小、皮质变薄，提示慢性；有无梗阻或结石，以明确病因）；【其他】尿钙磷、维生素D及甲状旁腺激素（肾性骨病）。","初步诊断":"1. 慢性间质性肾炎（病因：镇痛剂、梗阻或尿酸等，肾小管功能不全）\n（注：①去除病因（最关键：停用致病药物、解除梗阻、控制血尿酸（别嘌醇或非布司他）、脱离重金属）；②对症治疗：纠酸（口服碳酸氢钠，维持血碳酸氢盐>22mmol/L）、补钾（低钾者予枸橼酸钾）、纠正贫血（促红素+铁）、活性维生素D（肾性骨病者予骨化三醇）、控制血压（ACEI或ARB）；③监测肾功能进展（eGFR）、电解质、血气；④避免肾毒性药物及脱水；⑤进展至ESRD者肾脏替代治疗评估；预后较肾小球疾病相对好（进展较慢），去除病因可稳定，随访肾内科。）","处理方案":"【药物治疗】\n1. 病因治疗：立即停用可疑致病药物（非甾体抗炎药、含马兜铃酸中草药、氨基糖苷类抗生素、质子泵抑制剂等）；伴高尿酸血症者予别嘌醇片100mg qd口服，据血尿酸水平每2周调整1次，目标血尿酸<360μmol/L。\n2. 控制血压、延缓肾功能进展：首选ACEI/ARB类，如贝那普利片10mg qd口服或缬沙坦胶囊80mg qd口服，血压目标<130/80mmHg；用药期间监测血肌酐及血钾，若血肌酐较基线升高>30%或血钾>5.5mmol/L应停药并复诊。\n3. 纠正代谢性酸中毒：碳酸氢钠片1.0g tid口服（伴低钾血症者改用枸橼酸钾颗粒3g tid），维持血二氧化碳结合力≥22mmol/L，并监测血钾。\n4. 纠正肾性贫血：血红蛋白<100g/L时予重组人促红素3000IU皮下注射每周2次，联合琥珀酸亚铁片0.1g tid口服补铁，目标血红蛋白110~130g/L，避免过高。\n\n【一般治疗及生活指导】\n1. 充分休息，避免劳累、熬夜及感染，注意保暖预防感冒，防止诱发肾功能急性加重。\n2. 清淡低盐饮食，每日食盐<5g；肾功能不全（eGFR<60ml/min·1.73m²）时予优质低蛋白饮食0.6~0.8g/kg·d，保证充足饮水（无水肿时每日1500~2000ml）。\n3. 严格避免肾毒性因素：禁用非甾体抗炎药（布洛芬、双氯芬酸等）及氨基糖苷类抗生素，慎用含马兜铃酸成分中草药（关木通、广防己等）；确需造影检查者应先评估肾功能并与医师沟通。\n4. 戒烟限酒，规律作息，每日自测血压并记录，维持理想体重。\n\n【随诊要求】\n1. 每月复查尿常规、血肌酐/尿素氮、eGFR、血电解质（血钾、二氧化碳结合力）及血尿酸；每3个月复查24小时尿蛋白定量或尿微量白蛋白/肌酐比值。\n2. 每日家庭自测血压并记录，若血压持续>140/90mmHg或出现夜尿增多、乏力、恶心呕吐、双下肢水肿、少尿（24小时尿量<400ml）等，及时复诊或急诊就诊。\n3. 长期服用ACEI/ARB、别嘌醇、碳酸氢钠等药物者须遵医嘱规律服药，不可自行停药或增减剂量；如出现皮疹、发热、关节痛、肉眼血尿等药物不良反应，立即复诊。"},"icd10_diagnosis":"","icd10_secondary":[],"icd9cm3_procedure":[]}},"locator":{"file":"门诊住院病历模板/病历模板包_全部_20261111.json","arrayRow":426,"caseRow":1},"sourceHash":"10e4fdb435986b7b85f847c3951d0cb0eafdce0f372c5617949c05b337149194","contentHash":"a6baff950b71aa8042686e4066fbf019cb4c5e3616b71bd96d3ed8b3c8472b4d","pinyin":"manxingjianzhixingshenyan","initials":"mxjzxsy","setting":"out","caseName":"门诊病历291","templateNames":["主诉","现病史","既往史","个人史及过敏史","体格检查","辅助检查","初步诊断","处理方案"],"emptyTemplates":[],"escapedNewlines":[],"quickFields":[["病例名称","门诊病历291",60],["模板名称","主诉 现病史 既往史 个人史及过敏史 体格检查 辅助检查 初步诊断 处理方案",30],["主要诊断编码","",30]]},{"id":"templates-0015b3556b351531b67e","key":"v1-c9ccc21dfe2a3058|templates-0015b3556b351531b67e","module":"templates","moduleKey":"v1-c9ccc21dfe2a3058|templates","version":"v1-c9ccc21dfe2a3058","title":"肾小管酸中毒","category":"门诊病历模板","raw":{"name":"肾小管酸中毒","category":"门诊病历模板","case":{"case_name":"门诊病历292","templates":{"主诉":"反复乏力、多饮多尿伴骨痛6月","现病史":"患者于____月前开始反复乏力、四肢无力（低钾，严重时软瘫）、多饮多尿、夜尿多，渐出现骨痛（骨软化）、病理性骨折（慢性酸中毒：骨骼缓冲）、肾结石（Ⅰ型：尿路结石/肾钙质沉着），生长发育迟缓（儿童），____（有无眼干口干（干燥综合征：继发RTA最常见）、自身免疫病、慢性腹泻、使用药物（两性霉素B、锂盐、利尿剂），病因线索），血电解质曾示____（低钾、高氯性代谢性酸中毒：阴离子间隙正常：RTA特征）。今日来我院门诊就诊。","既往史":"既往体健，否认高血压、糖尿病、冠心病等慢性病史。否认肝炎、结核等传染病史。否认手术外伤史。否认食物药物过敏史。预防接种史随社会。","个人史及过敏史":"生于原籍，久居本地，无疫区疫水接触史，无特殊粉尘毒物放射性物质接触史。不吸烟，不饮酒。生活规律。否认食物药物过敏史。","体格检查":"T36.5℃，P82次/分，R18次/分，BP100/65mmHg。神志清楚，查体合作。肌力Ⅳ级（减弱，低钾），腱反射减弱，骨骼压痛（骨软化），生长发育迟缓（儿童评估），脱水貌（-）。","辅助检查":"【必做】血气分析（高氯性正常阴离子间隙代谢性酸中毒，核心表现）、血电解质（低钾）、尿pH（Ⅰ型：>5.5，泌氢障碍；Ⅱ型：酸中毒时尿pH可<5.5）、尿阴离子间隙（正值，远端酸化障碍）、尿钾（低钾鉴别）、肾功能；【分型试验】氯化铵负荷试验（Ⅰ型：尿pH不能降至5.5以下）、碳酸氢钠负荷试验（Ⅱ型：尿HCO3-排泄分数>15%）；【病因筛查】自身抗体（干燥综合征：抗SSA/SSB）、尿糖氨基酸（Fanconi综合征，Ⅱ型近端）、影像（泌尿系超声：肾结石/钙化）。","初步诊断":"1. 肾小管酸中毒（Ⅰ型（远端），待明确）\n（注：治疗以碱剂替代为核心：Ⅰ型，枸橼酸钾钠（或碳酸氢钠1~3mmol/kg/d分次，使血碳酸氢盐正常、尿钙下降防结石）、补钾（低钾，枸橼酸钾，忌氯化钾，加重高氯）；Ⅱ型，大剂量碱剂（碳酸氢钠5~10mmol/kg/d，随尿丢失多）、补充磷钾及维生素D（佝偻病/骨软化）、氢氯噻嗪（减少尿HCO3-排泄，辅助）；Ⅳ型，纠酸+限钾、氟氢可的松/袢利尿剂（高钾处理）、治疗原发病（低醛固酮，糖尿病肾病）；积极治疗原发病（干燥综合征，激素/免疫抑制剂）；长期随访电解质、血气、尿钙、影像（结石）。）","处理方案":"【药物治疗】\n1. 碱剂纠酸（基础治疗）：碳酸氢钠片0.5～1.0g po tid，Ⅱ型（近端型）RTA用量需加大至1.0～1.5g po tid～qid，按血气分析及尿pH调整剂量，长期维持血HCO₃⁻于正常范围；不能耐受者改予枸橼酸合剂（Shohl液）10～20ml po tid。\n2. 补钾：Ⅰ型（远端型）RTA低钾突出，予10%枸橼酸钾口服液10～20ml po tid，或枸橼酸钾颗粒1.0～2.0g po tid，使血钾维持在正常范围；忌用氯化钾，以免加重高氯性酸中毒。\n3. 纠正骨代谢异常：合并低血钙、佝偻病/骨软化者予骨化三醇软胶囊0.25μg po qd，联合碳酸钙D3片（含元素钙600mg）1片 po qd，治疗期间动态监测血钙、尿钙，防止高钙尿症及肾钙质沉着加重。\n4. 高钾型（Ⅳ型）RTA：在限钾饮食基础上予呋塞米片20mg po qd～bid促进排钾，必要时加用氟氢可的松0.1mg po qd补充盐皮质激素，并避免使用保钾利尿剂。\n\n【一般治疗及生活指导】\n1. 饮食：Ⅰ、Ⅱ型RTA予高热量、富含钾钙饮食并限钠（每日食盐<5g），以减少尿钾丢失；Ⅳ型RTA须严格限制钾摄入，忌用低钠盐及含钾代盐。\n2. 保证每日饮水2000～2500ml并维持充足尿量，稀释尿液，降低肾结石及肾钙质沉着发生风险。\n3. 避免诱因：避免劳累、受凉、感染及脱水；禁用非甾体抗炎药、两性霉素B、保钾利尿剂（螺内酯、氨苯蝶啶等）及肾毒性药物，以免加重肾小管损伤和高钾血症。\n4. 活动：适度活动即可，合并骨软化、佝偻病者避免剧烈运动及负重，注意防跌倒，预防病理性骨折。\n\n【随诊要求】\n1. 治疗初期每1～2周复诊1次，复查血气分析、血电解质（钾、钠、氯、钙、磷）、尿pH及尿钙，据此调整碱剂与补钾剂量；病情稳定后每1～3个月复诊1次。\n2. 每3～6个月复查肾功能（血肌酐、eGFR）、尿常规、24h尿钙/尿枸橼酸及泌尿系超声，监测肾结石、肾钙质沉着及肾功能变化。\n3. 合并骨病者每6～12个月复查血钙磷、碱性磷酸酶、骨密度或骨骼X线；Ⅰ型RTA成人建议行听力检查（可伴感音神经性耳聋）。\n4. 出现乏力、心悸、四肢软瘫、手足抽搐、恶心呕吐或血钾异常波动时，随时复诊或急诊就医。"},"icd10_diagnosis":"","icd10_secondary":[],"icd9cm3_procedure":[]}},"locator":{"file":"门诊住院病历模板/病历模板包_全部_20261111.json","arrayRow":427,"caseRow":1},"sourceHash":"10e4fdb435986b7b85f847c3951d0cb0eafdce0f372c5617949c05b337149194","contentHash":"9110d623007a7e6ce69d2fa276ca3b342e66be8d423299d16c024e5721325323","pinyin":"shenxiaoguansuanzhongdu","initials":"sxgszd","setting":"out","caseName":"门诊病历292","templateNames":["主诉","现病史","既往史","个人史及过敏史","体格检查","辅助检查","初步诊断","处理方案"],"emptyTemplates":[],"escapedNewlines":[],"quickFields":[["病例名称","门诊病历292",60],["模板名称","主诉 现病史 既往史 个人史及过敏史 体格检查 辅助检查 初步诊断 处理方案",30],["主要诊断编码","",30]]},{"id":"templates-743b2def35306e6aeb6b","key":"v1-c9ccc21dfe2a3058|templates-743b2def35306e6aeb6b","module":"templates","moduleKey":"v1-c9ccc21dfe2a3058|templates","version":"v1-c9ccc21dfe2a3058","title":"肾动脉狭窄","category":"门诊病历模板","raw":{"name":"肾动脉狭窄","category":"门诊病历模板","case":{"case_name":"门诊病历293","templates":{"主诉":"血压持续升高2年，加重伴肾功能下降1月","现病史":"患者高血压病史5年，平素联合3种降压药（含ACEI/ARB/CCB/利尿剂等）仍控制不佳（血压170/105mmHg），有无上腹部血管杂音、低钾（醛固酮继发增多）、肾功能进行性下降（ACEI/ARB后肌酐明显升高，双侧重度狭窄特征）、肺水肿反复发作（双侧狭窄，心衰表现）、年轻人新发高血压（大动脉炎/纤维肌性发育不良）或老年人动脉粥样硬化，有无吸烟、糖尿病、动脉粥样硬化及血管疾病史：无吸烟、无糖尿病、无动脉粥样硬化及血管疾病史。今日来我院门诊就诊。","既往史":"既往体健，否认高血压、糖尿病、冠心病等慢性病史。否认肝炎、结核等传染病史。否认手术外伤史。否认食物药物过敏史。预防接种史随社会。","个人史及过敏史":"生于原籍，久居本地，无疫区疫水接触史，无特殊粉尘毒物放射性物质接触史。不吸烟，不饮酒。生活规律。否认食物药物过敏史。","体格检查":"T36.5℃，P78次/分，R18次/分，BP170/105mmHg（双上肢对比，锁骨下动脉狭窄时双上肢差>20mmHg）。神志清楚。上腹部或脐周可闻及收缩期血管杂音（肾动脉狭窄体征，重要线索），腹主动脉搏动正常，双下肢动脉搏动可及（周围动脉疾病并存评估）。","辅助检查":"【必做】肾功能（肌酐、eGFR）、电解质（低钾）、尿常规（蛋白尿，肾损害）、肾素-血管紧张素-醛固酮（RAAS，继发高醛固酮评估）；【影像学】肾动脉彩色多普勒超声（肾动脉流速增快（峰值>180cm/s）、肾内血流阻力指数，筛查首选）、肾动脉CTA/MRA（狭窄部位及程度，无创确诊）；【确诊】肾动脉造影（DSA，金标准兼介入治疗）。","初步诊断":"1. 肾动脉狭窄（病因：动脉粥样硬化性，侧别：单侧，狭窄70%）\n（注：治疗决策依据病因、狭窄程度及肾功能：①药物治疗（所有患者）：控制血压（CCB/β受体阻滞剂/利尿剂，双侧重度狭窄或单功能肾者慎用/禁用ACEI/ARB（可致急性肾衰，用药后1~2周复查肌酐）、他汀、抗血小板）；②血运重建（支架植入（PTRA），指征：难治性高血压、肾功能进行性下降、复发性肺水肿（双侧/单功能肾重度狭窄）、纤维肌性发育不良（球囊扩张疗效好）；动脉粥样硬化性，严格筛选（近期肾功能恶化/难控血压者获益），因ASTRAL/CORAL研究示多数药物控制即可）；③大动脉炎，激素/免疫抑制+血管成形时机选择；随访血压、肾功能、超声。）","处理方案":"【药物治疗】\n1. 抗血小板治疗：阿司匹林肠溶片100mg qd po，长期口服，用于动脉粥样硬化性肾动脉狭窄，降低血栓及心血管事件风险。\n2. 调脂治疗：阿托伐他汀钙片20mg qn po，长期口服，LDL-C目标<1.8mmol/L，延缓动脉粥样硬化进展。\n3. 降压治疗：首选钙通道阻滞剂，苯磺酸氨氯地平片5mg qd po，血压控制目标<140/90mmHg（耐受者<130/80mmHg）；单侧肾动脉狭窄且血肌酐正常者，可加用血管紧张素转换酶抑制剂培哚普利叔丁胺片4mg qd po，服药后1周复查血肌酐及血钾（升高>30%或高钾血症即停药）；双侧肾动脉严重狭窄或孤立肾肾动脉狭窄者禁用ACEI/ARB。\n4. 血糖、血脂及血尿酸异常者同步规范化管理，控制动脉粥样硬化危险因素。\n\n【一般治疗及生活指导】\n1. 低盐低脂饮食，每日食盐摄入<5g，戒烟限酒，控制体重（BMI<24kg/m²），规律有氧运动（如快走、太极拳，每周≥150分钟）。\n2. 保证每日饮水1500-2000ml，避免剧烈运动、大汗、腹泻等导致脱水及血容量不足，以防肾灌注骤降诱发急性肾损伤或肾梗死。\n3. 避免使用非甾体抗炎药（如布洛芬、双氯芬酸）及氨基糖苷类等肾毒性药物，慎用造影剂，必要时充分水化。\n4. 每日自测血压并记录，规律服药，避免血压剧烈波动，警惕血压骤升或骤降。\n\n【随诊要求】\n1. 每1-3个月门诊复查血压、血肌酐、eGFR、血钾及尿常规，评估肾功能变化及药物耐受性。\n2. 每6-12个月复查肾动脉彩色多普勒超声，评估狭窄程度及进展；狭窄加重或出现肾萎缩时缩短复查间隔。\n3. 如出现血压难以控制、进行性肾功能恶化、反复发作性肺水肿或难治性心衰，及时就诊，评估行肾动脉介入治疗（PTRA+支架）或外科血运重建指征。"},"icd10_diagnosis":"","icd10_secondary":[],"icd9cm3_procedure":[]}},"locator":{"file":"门诊住院病历模板/病历模板包_全部_20261111.json","arrayRow":428,"caseRow":1},"sourceHash":"10e4fdb435986b7b85f847c3951d0cb0eafdce0f372c5617949c05b337149194","contentHash":"b6cda3fb7acfd34354bb689956637c271847491d898ed637b375b5885f1dc2cf","pinyin":"shendongmaixiazhai","initials":"sdmxz","setting":"out","caseName":"门诊病历293","templateNames":["主诉","现病史","既往史","个人史及过敏史","体格检查","辅助检查","初步诊断","处理方案"],"emptyTemplates":[],"escapedNewlines":[],"quickFields":[["病例名称","门诊病历293",60],["模板名称","主诉 现病史 既往史 个人史及过敏史 体格检查 辅助检查 初步诊断 处理方案",30],["主要诊断编码","",30]]},{"id":"templates-8972b839cfbe292180f3","key":"v1-c9ccc21dfe2a3058|templates-8972b839cfbe292180f3","module":"templates","moduleKey":"v1-c9ccc21dfe2a3058|templates","version":"v1-c9ccc21dfe2a3058","title":"肾静脉血栓","category":"门诊病历模板","raw":{"name":"肾静脉血栓","category":"门诊病历模板","case":{"case_name":"门诊病历294","templates":{"主诉":"突发腰痛伴血尿3天","现病史":"患者有肾病综合征（大量蛋白尿、低白蛋白血症，高凝状态）或膜性肾病（膜性肾病最常见伴发）病史，近3天突发患侧腰部胀痛、肉眼血尿，蛋白尿较前增多，尿量减少（急性肾静脉血栓，肾功能急骤恶化）、发热，无肺栓塞表现：突发胸痛、咯血、呼吸困难（血栓脱落），慢性者，侧支循环形成可无症状或仅蛋白尿增多。今日来我院急诊就诊。","既往史":"既往体健，否认高血压、糖尿病、冠心病等慢性病史。否认肝炎、结核等传染病史。否认手术外伤史。否认食物药物过敏史。预防接种史随社会。","个人史及过敏史":"生于原籍，久居本地，无疫区疫水接触史，无特殊粉尘毒物放射性物质接触史。不吸烟，不饮酒。生活规律。否认食物药物过敏史。","体格检查":"T37.8℃，P96次/分，R20次/分，BP130/80mmHg。神志清楚，痛苦面容。患侧肾区叩击痛（+），腹部可及肿大肾脏，双下肢水肿（肾病综合征基础表现），心肺未闻及异常（肺栓塞征象，呼吸急促）。","辅助检查":"检查计划：患者有肾病综合征或膜性肾病所致高凝状态，近3天突发右侧腰部胀痛、肉眼血尿、蛋白尿增多及尿量减少，急诊完善D-二聚体检查了解血栓形成与纤溶活动情况；查肾功能明确有无急性升高，评估急性肾静脉血栓所致肾功能急骤恶化；查尿常规明确血尿、蛋白尿程度；查血白蛋白了解有无低白蛋白血症这一高凝基础并评估肾病综合征活动度；完善凝血功能检查为抗凝治疗提供安全基线；完善肾脏超声加彩色多普勒检查了解肾脏有无增大、血流是否减少，但需注意其对静脉血栓敏感性有限；完善CT血管成像或磁共振静脉成像（MRV）明确肾静脉有无充盈缺损，此为确诊依据；腹部CT含静脉期可发现肾静脉血栓，肾病随访CT亦常意外发现；患者血栓可能脱落，需排查肺栓塞，如出现突发胸痛、咯血、呼吸困难应急诊完成CTPA；完善血常规及血小板计数评估抗凝治疗安全性；抗凝治疗（低分子肝素桥接华法林或直接口服抗凝药，至少6个月）期间定期复查肾功能、凝血功能及影像学，随访血栓消退情况并监测肺栓塞等并发症。\n\n（检查清单）\n【必做】D-二聚体（升高）、肾功能（急性升高）、尿常规（血尿、蛋白尿）、血白蛋白（低，高凝基础）、凝血功能；【影像学】肾脏超声+彩色多普勒（肾脏增大、血流减少，但静脉血栓敏感性有限）、CT血管成像/磁共振静脉成像（MRV，肾静脉充盈缺损，确诊）、腹部CT（含静脉期，分期扫描时发现，肾病随访CT常见意外发现）；【其他】肺栓塞排查（疑脱落，CTPA）。","初步诊断":"1. 肾静脉血栓（右侧，病程：急性，基础病：肾病综合征/膜性肾病）\n（注：①抗凝治疗（核心）：低分子肝素（依诺肝素1mg/kg q12h）桥接华法林（INR 2~3）或直接口服抗凝药（利伐沙班/达比加群，近年患者增加，至少6个月，肾病综合征持续者长期）；②溶栓（导管定向溶栓/全身，急性双侧/肾功能急剧恶化/血栓巨大，权衡出血风险）；③治疗基础病（肾病综合征，激素/免疫抑制降低高凝）；④预防（肾病综合征蛋白<20g/L或白蛋白<20g/L高危者，预防性抗凝（低分子肝素/Warfarin），尤其膜性肾病）；⑤监测并发症（肺栓塞、肾功能）；肾内科+血管外科协作，随访影像复查血栓消退情况。）","处理方案":"【药物治疗】\n1. 抗凝治疗（核心）：低分子肝素钙（那屈肝素钙0.4ml/4100IU，皮下注射q12h），疗程7～14天，作为口服抗凝药起效前的桥接治疗。\n2. 口服抗凝药：华法林钠片2.5～3mg qd，与低分子肝素重叠≥5天，INR达标（2.0～3.0）后停用肝素，总疗程3～6个月；或利伐沙班片20mg qd（CrCl 15～49ml/min时减为15mg qd），疗程3～6个月，病因未消除者根据患者具体情况制定个体化方案延长。\n3. 病因及对症治疗：肾病综合征者予泼尼松0.8～1.0mg/(kg·d)口服（或按专科方案用免疫抑制剂），联合贝那普利10mg qd减少蛋白尿、呋塞米20mg qd利尿消肿。\n【一般治疗及生活指导】\n1. 急性期绝对卧床休息，待腰痛、血尿、发热等症状缓解后逐渐下床活动；避免按摩、热敷患侧腰腹部及下肢，防止血栓脱落。\n2. 低盐低脂优质蛋白饮食，每日食盐<5g，水肿明显时限制液体入量（约=前日尿量+500ml）；服用华法林者保持富含维生素K食物（菠菜、西兰花、动物肝脏等）摄入量稳定。\n3. 卧床期间进行踝泵运动及健侧肢体主动活动，恢复期避免久坐久站、跷二郎腿，戒烟限酒，避免使用雌激素类避孕药。\n4. 严格遵医嘱服药，不可自行停药、减量或更换抗凝药，注意观察皮肤黏膜有无出血点。\n【随诊要求】\n1. 华法林治疗期间首周每1～2天复查INR，稳定后每2～4周复查1次，维持INR 2.0～3.0；利伐沙班者每3～6个月复查肾功能（CrCl）调整剂量。\n2. 每2～4周复查尿常规、24h尿蛋白定量、血肌酐/eGFR及凝血功能，定期复查血常规监测出血风险。\n3. 抗凝治疗3～6个月后复查肾脏彩超或CTA评估血栓消退与再通情况；若肾病综合征等病因持续未缓解，应延长抗凝并定期随访。\n4. 出现咯血、黑便、牙龈及皮肤明显出血、肉眼血尿、突发剧烈腹痛或下肢肿胀加重等，立即来院就诊。"},"icd10_diagnosis":"","icd10_secondary":[],"icd9cm3_procedure":[]}},"locator":{"file":"门诊住院病历模板/病历模板包_全部_20261111.json","arrayRow":429,"caseRow":1},"sourceHash":"10e4fdb435986b7b85f847c3951d0cb0eafdce0f372c5617949c05b337149194","contentHash":"fe5aebbc2a9fdd6d8bc363302617c513fdb095b84a60ee52c4eff5d8547beb73","pinyin":"shenjingmaixueshuan","initials":"sjmxs","setting":"out","caseName":"门诊病历294","templateNames":["主诉","现病史","既往史","个人史及过敏史","体格检查","辅助检查","初步诊断","处理方案"],"emptyTemplates":[],"escapedNewlines":[],"quickFields":[["病例名称","门诊病历294",60],["模板名称","主诉 现病史 既往史 个人史及过敏史 体格检查 辅助检查 初步诊断 处理方案",30],["主要诊断编码","",30]]},{"id":"templates-7a2b5763001e02866502","key":"v1-c9ccc21dfe2a3058|templates-7a2b5763001e02866502","module":"templates","moduleKey":"v1-c9ccc21dfe2a3058|templates","version":"v1-c9ccc21dfe2a3058","title":"附睾睾丸炎","category":"门诊病历模板","raw":{"name":"附睾睾丸炎","category":"门诊病历模板","case":{"case_name":"门诊病历295","templates":{"主诉":"阴囊肿胀、疼痛伴发热3天","现病史":"患者于2天前出现右侧（单侧）阴囊肿胀、坠痛，可向腹股沟（腹股沟/下腹）放射，站立行走时加重、平卧托起阴囊减轻（Prehn征阳性，附睾炎特征，区别于睾丸扭转），伴发热（体温最高38.8℃）、寒战，伴尿频尿急尿痛、尿道分泌物（性传播感染（衣原体/淋球菌，35岁以下）），无排尿困难（前列腺炎/梗阻（老年，大肠杆菌）），无恶心呕吐。有无近期导尿/器械操作、剧烈运动（扭转诱因）：无近期导尿/器械操作、无剧烈运动。今日来我院门诊就诊。","既往史":"既往体健，否认高血压、糖尿病、冠心病等慢性病史。否认肝炎、结核等传染病史。否认手术外伤史。否认食物药物过敏史。预防接种史随社会。","个人史及过敏史":"生于原籍，久居本地，无疫区疫水接触史，无特殊粉尘毒物放射性物质接触史。不吸烟，不饮酒。生活规律。否认食物药物过敏史。","体格检查":"T38.8℃，P100次/分，R20次/分，BP120/75mmHg。神志清楚，痛苦面容。患侧阴囊皮肤红肿、皮温升高，附睾肿大、触痛明显（先于睾丸受累），睾丸相对完整，Prehn征阳性（托起减轻），精索增粗压痛，尿道口无分泌物，腹股沟淋巴结肿大。","辅助检查":"【必做】尿常规及尿培养（白细胞，尿路感染）、血常规（白细胞升高）、CRP；【性传播感染筛查】尿道/首段尿淋球菌及衣原体核酸检测（<35岁/高危，重要）；【影像学】阴囊彩色多普勒超声（附睾/睾丸增大血流增多，炎症；睾丸扭转，血流减少/消失，关键鉴别！）；【其他】睾丸扭转急诊鉴别（青少年突发，彩色多普勒血流减少需急诊手术探查）。","初步诊断":"1. 急性附睾睾丸炎（右侧，类型：细菌性（性传播/非性传播））\n（注：①抗菌治疗：<35岁疑性传播，头孢曲松250mg~1g肌注单剂（淋球菌）+多西环素100mg bid×10~14天（衣原体）；老年/尿路感染相关，氟喹诺酮（左氧氟沙星500mg qd×10~14天）或头孢类；根据培养调整；②对症：卧床休息、阴囊托起抬高、冰敷（48小时内）、NSAIDs（布洛芬）镇痛抗炎；③性伴侣同治（性传播者）；④鉴别睾丸扭转（青少年突发+无尿路症状+Prehn阴性+血流减少，急诊手术探查，黄金6小时）；⑤治疗1周复查；脓肿形成（波动感/超声），切开引流；随访睾丸萎缩风险（炎症后）。）","处理方案":"【药物治疗】\n1. 抗感染（首选覆盖肠杆菌科及淋球菌）：头孢克肟胶囊 0.2g bid×7天；若明确为性传播感染或合并尿道炎，加用多西环素片 0.1g bid×14天（覆盖沙眼衣原体）。\n2. 抗炎镇痛：布洛芬缓释胶囊 0.3g bid×5~7天（或塞来昔布胶囊 0.2g qd×5~7天），缓解阴囊疼痛及减轻炎性水肿。\n3. 消肿（促进淋巴回流、减轻阴囊肿胀）：地奥司明片 0.5g tid×7天。\n4. 对症退热：体温≥38.5℃时，对乙酰氨基酚片 0.5g 口服，必要时6小时重复1次，24小时不超过4次。\n【一般治疗及生活指导】\n1. 急性期卧床休息，用毛巾或丁字带托高阴囊，减少下坠牵拉痛；避免久坐久站及剧烈运动。\n2. 急性期（症状消退前）禁止性生活及手淫，避免局部摩擦刺激；忌烟酒、辛辣刺激饮食。\n3. 急性期48小时内阴囊局部冷敷（每次15~20分钟，每日3~4次），禁热敷，以免加重炎性水肿。\n4. 保持阴囊局部清洁干燥，穿宽松透气棉质内裤，多饮水，保证充足睡眠。\n【随诊要求】\n1. 用药3~5天复诊，评估阴囊疼痛、肿胀、发热改善情况；7天后复查血常规、尿常规评估疗效，必要时复查阴囊彩超。\n2. 若用药48~72小时症状无缓解，或出现高热不退、阴囊肿痛进行性加重，需立即复诊并行阴囊彩超，排除睾丸扭转、脓肿形成；儿童及青少年急性阴囊痛应先排除睾丸扭转。\n3. 性传播感染所致者，性伴侣应同时检查及治疗，疗程结束后复查病原学以确认治愈。\n4. 症状缓解后1~2周复查阴囊彩超，确认炎症完全吸收；反复发作或迁延不愈者，需进一步评估有无尿道梗阻、前列腺炎等基础病因。"},"icd10_diagnosis":"","icd10_secondary":[],"icd9cm3_procedure":[]}},"locator":{"file":"门诊住院病历模板/病历模板包_全部_20261111.json","arrayRow":430,"caseRow":1},"sourceHash":"10e4fdb435986b7b85f847c3951d0cb0eafdce0f372c5617949c05b337149194","contentHash":"041aaf46cceb61db3f43ccd7e9c3b3a20e64ec979c0a8e9c341c89dfe07893af","pinyin":"fugaogaowanyan","initials":"fggwy","setting":"out","caseName":"门诊病历295","templateNames":["主诉","现病史","既往史","个人史及过敏史","体格检查","辅助检查","初步诊断","处理方案"],"emptyTemplates":[],"escapedNewlines":[],"quickFields":[["病例名称","门诊病历295",60],["模板名称","主诉 现病史 既往史 个人史及过敏史 体格检查 辅助检查 初步诊断 处理方案",30],["主要诊断编码","",30]]},{"id":"templates-819c57cd4155639628e6","key":"v1-c9ccc21dfe2a3058|templates-819c57cd4155639628e6","module":"templates","moduleKey":"v1-c9ccc21dfe2a3058|templates","version":"v1-c9ccc21dfe2a3058","title":"鞘膜积液","category":"门诊病历模板","raw":{"name":"鞘膜积液","category":"门诊病历模板","case":{"case_name":"门诊病历296","templates":{"主诉":"阴囊逐渐增大伴坠胀感1年","现病史":"患者于6月前发现阴囊内肿块/阴囊逐渐增大，呈坠胀感，平卧后缩小（交通性，平卧缩小/非交通性，大小不变），站立及活动后增大，无疼痛，无发热，无外伤、附睾炎、睾丸肿瘤（继发性鞘膜积液，成人突发大量积液需警惕睾丸肿瘤）、无丝虫病疫区居住（鞘膜积液，丝虫病）、无腹股沟疝手术史。小儿：出生后有无阴囊肿胀（先天性鞘膜积液，多见自愈）。今日来我院门诊就诊。","既往史":"既往体健，否认高血压、糖尿病、冠心病等慢性病史。否认肝炎、结核等传染病史。否认手术外伤史。否认食物药物过敏史。预防接种史随社会。","个人史及过敏史":"生于原籍，久居本地，无疫区疫水接触史，无特殊粉尘毒物放射性物质接触史。不吸烟，不饮酒。生活规律。否认食物药物过敏史。","体格检查":"T36.5℃，P76次/分，R18次/分，BP120/75mmHg。神志清楚，查体合作。患侧阴囊内可及梨形囊性肿块，表面光滑，有囊性感，无压痛，睾丸触诊不清（肿块后方，透光试验阳性（鞘膜积液，透光；疝/肿瘤，不透光）），精索无增粗（有无增粗，精索鞘膜积液），交通性，按压后缩小。","辅助检查":"【必做】阴囊彩色多普勒超声（无回声积液区、睾丸形态正常，确诊并排除睾丸肿瘤、疝，首选检查）；【其他】血AFP/hCG（成人，睾丸肿瘤标志物，继发性积液需排除睾丸肿瘤时）。","初步诊断":"1. 鞘膜积液（类型：睾丸鞘膜，右侧）\n（注：①婴幼儿（<2岁）交通性鞘膜积液，多可自愈（鞘状突闭合），观察至2岁，不闭合者手术（鞘状突高位结扎）；②成人少量无症状，观察随访；症状明显（坠胀影响活动）或积液量大，手术治疗：睾丸鞘膜翻转术（或鞘膜切除）；③交通性，疝修补式处理（鞘状突高位结扎）；④继发性（成人突发），先明确病因（外伤血肿，保守/穿刺；附睾炎，抗感染；睾丸肿瘤，根治手术），禁忌仅穿刺抽液（复发且延误肿瘤诊断，抽液仅用于诊断或不能手术者）；⑤老年人，复查超声及AFP排除睾丸肿瘤。）","处理方案":"【药物治疗】\n1. 头孢呋辛酯片 0.25g bid×5天（用于合并感染、伴阴囊红肿热痛者；青霉素过敏者禁用，改选阿奇霉素片0.5g qd×3天）。\n2. 布洛芬缓释胶囊 0.3g bid×5天（缓解阴囊坠胀疼痛；饭后服，消化性溃疡活动期禁用）。\n3. 地奥司明片 0.9g bid×4周（改善淋巴回流、减轻鞘膜渗液及坠胀感）。\n4. 迈之灵片（马栗种子提取物）300mg bid×4周（辅助减轻局部水肿与渗出）。\n\n【一般治疗及生活指导】\n1. 注意休息，避免久站、久坐及剧烈运动，减少腹压骤增动作（如用力咳嗽、屏气排便、负重），以免加重积液。\n2. 建议穿宽松透气的棉质内裤或使用阴囊托带，抬高阴囊，减轻坠胀不适。\n3. 饮食宜清淡，多饮水，忌辛辣刺激、忌酒，保持大便通畅。\n4. 急性期局部可用冷敷缓解胀痛，禁止热敷及自行穿刺抽液（防感染、复发），注意局部清洁干燥。\n\n【随诊要求】\n1. 用药后2周门诊复查，行阴囊彩超评估积液量变化。\n2. 若积液持续增大、疼痛加重或出现发热、阴囊皮肤红肿，提示感染或病情进展，须立即复诊。\n3. 成人鞘膜积液以手术根治为主，药物保守无效或积液量大影响生活者，建议1个月内转泌尿外科门诊评估手术治疗（鞘膜翻转术/鞘膜切除术）。\n4. 已手术者术后2周复查切口愈合情况，1个月后复查彩超评估有无复发。"},"icd10_diagnosis":"","icd10_secondary":[],"icd9cm3_procedure":[]}},"locator":{"file":"门诊住院病历模板/病历模板包_全部_20261111.json","arrayRow":431,"caseRow":1},"sourceHash":"10e4fdb435986b7b85f847c3951d0cb0eafdce0f372c5617949c05b337149194","contentHash":"34b930670a7c78fe2d2a7986f3e9f2ecb2aa4e91811a6509a213e26e1c7a837a","pinyin":"qiaomojiye","initials":"qmjy","setting":"out","caseName":"门诊病历296","templateNames":["主诉","现病史","既往史","个人史及过敏史","体格检查","辅助检查","初步诊断","处理方案"],"emptyTemplates":[],"escapedNewlines":[],"quickFields":[["病例名称","门诊病历296",60],["模板名称","主诉 现病史 既往史 个人史及过敏史 体格检查 辅助检查 初步诊断 处理方案",30],["主要诊断编码","",30]]},{"id":"templates-0a7514f1c535a0a13f1b","key":"v1-c9ccc21dfe2a3058|templates-0a7514f1c535a0a13f1b","module":"templates","moduleKey":"v1-c9ccc21dfe2a3058|templates","version":"v1-c9ccc21dfe2a3058","title":"包皮龟头炎","category":"门诊病历模板","raw":{"name":"包皮龟头炎","category":"门诊病历模板","case":{"case_name":"门诊病历297","templates":{"主诉":"包皮红肿、疼痛伴分泌物3天","现病史":"患者于3天前出现包皮内板及龟头红肿、灼痛、瘙痒，包皮口红肿狭窄（狭窄，包茎，分泌物不易排出），可见白色奶酪样分泌物（分泌物：白色奶酪样（念珠菌，糖尿病/抗生素后）、脓性（细菌）、溃疡面），无尿频尿痛、无发热、无腹股沟淋巴结肿大，无不洁性生活（性传播感染，生殖器疱疹/梅毒/淋病，溃疡鉴别）、无糖尿病（反复念珠菌性龟头炎需筛查）、无长期使用抗生素/糖皮质激素及个人卫生/清洁剂刺激（接触性）：无以上诱因。今日来我院门诊就诊。","既往史":"既往体健，否认高血压、糖尿病、冠心病等慢性病史。否认肝炎、结核等传染病史。否认手术外伤史。否认食物药物过敏史。预防接种史随社会。","个人史及过敏史":"生于原籍，久居本地，无疫区疫水接触史，无特殊粉尘毒物放射性物质接触史。不吸烟，不饮酒。生活规律。否认食物药物过敏史。","体格检查":"T36.8℃，P80次/分，R18次/分，BP120/75mmHg。神志清楚，查体合作。包皮口红肿、狭窄（能否翻转：不能完全翻转），翻转后可见龟头及冠状沟红斑、糜烂、白色奶酪样分泌物，局部压痛，尿道口无分泌物，腹股沟淋巴结未肿大。","辅助检查":"检查计划：患者包皮内板及龟头红肿、灼痛、瘙痒3天，可见白色奶酪样分泌物，结合包皮口红肿狭窄、包茎致分泌物不易排出，临床考虑念珠菌性包皮龟头炎，但脓性分泌物提示细菌感染可能，故门诊即刻完善分泌物涂片检查，镜下查找真菌菌丝与孢子、细菌及滴虫，明确致病微生物类型，指导抗真菌或抗细菌用药方向；同时完善尿常规检查，排除尿道炎、膀胱炎等泌尿系感染，并了解有无尿糖及白细胞增多，为是否合并糖尿病及下尿路感染提供线索；因包皮口狭窄、分泌物引流不畅易致感染迁延，完善分泌物细菌培养及真菌培养，明确病原菌种类并据药敏结果调整抗生素，避免经验性用药无效；患者本次为念珠菌性龟头炎，反复发作的念珠菌感染常以糖尿病为基础病因，故完善血糖检查筛查糖尿病，明确有无糖代谢异常这一根本诱因，血糖控制后方可减少复发；患者虽否认不洁性生活史，但白色奶酪样分泌物需与溃疡性、脓性性传播感染相鉴别，故完善性传播感染检测，包括梅毒血清学、HSV（单纯疱疹病毒）抗体及淋球菌、衣原体核酸检测，排除梅毒、生殖器疱疹、淋病及沙眼衣原体感染，防止漏诊与伴侣间传播。此外，对上述检查结果仍不能解释者，可行高危型HPV分型检测评估有无HPV感染，因其与阴茎癌、宫颈病变相关；并复查尿常规、分泌物涂片，评估抗真菌治疗1~2周后的疗效，必要时行包皮环切术前相关检查（血常规、凝血功能），为炎症消退后手术防复发做准备。\n\n（检查清单）\n【必做】分泌物涂片（真菌菌丝/细菌/滴虫）、尿常规；【其他】分泌物细菌/真菌培养、血糖（反复念珠菌性，糖尿病筛查）、性传播感染检测（梅毒血清学、HSV、淋球菌衣原体，有溃疡或不洁性生活史时）。","初步诊断":"1. 包皮龟头炎（类型：念珠菌性）\n（注：①局部清洁（生理盐水/稀释高锰酸钾清洗，保持干燥）；②念珠菌性，抗真菌软膏（克霉唑乳膏bid×1~2周）或口服氟康唑150mg单剂（重症/反复），治疗糖尿病（根本，反复者必查血糖）；③细菌性，抗生素软膏（莫匹罗星/夫西地酸），重症口服抗生素（头孢类）；④接触性，停用刺激物、弱效激素软膏短期（丁酸氢化可的松，炎症明显时）；⑤包茎/反复发作（包皮口狭窄影响清洁），炎症消退后包皮环切术（防复发、降低阴茎癌/HPV感染风险）；⑥伴侣同治（念珠菌/性传播者）；若溃疡，梅毒/疱疹鉴别（血清学随访）。）","处理方案":"【药物治疗】\n1. 局部清洗消毒：1:5000～1:8000高锰酸钾溶液（或3%硼酸溶液）清洗患处，每日2次，每次浸泡10～15分钟，连用5～7天，保持局部清洁干燥。\n2. 抗真菌外用（念珠菌性龟头炎首选）：1%克霉唑乳膏（或2%咪康唑乳膏）外涂患处，每日2次，连用7～14天，症状消退后继续用药3～5天以防复发。\n3. 抗菌外用（合并细菌感染或糜烂渗液明显者）：莫匹罗星软膏外涂患处，每日2～3次，连用5～7天；渗液多者先用3%硼酸溶液湿敷，待干燥后再涂药。\n4. 口服抗菌药物（炎症较重、反复感染或伴全身症状者）：头孢克肟胶囊0.1g bid×7天，或左氧氟沙星片0.5g qd×5～7天；确诊真菌感染者可加用氟康唑胶囊150mg单剂顿服。\n\n【一般治疗及生活指导】\n1. 保持局部清洁干燥：每日用温水清洗包皮及龟头，清洗后彻底擦干，避免使用刺激性肥皂、沐浴液及各类\"洗液\"过度清洗。\n2. 急性期禁性生活及手淫，避免摩擦刺激；包皮过长或包茎者症状消退后建议行包皮环切术，以根治并预防复发。\n3. 勤换宽松透气的棉质内裤，内衣裤与家人分开清洗并在阳光下晾晒；糖尿病患者应积极控制血糖（血糖不达标者本病易反复）。\n4. 清淡饮食，忌辛辣刺激食物，忌酒，多饮水，规律作息，避免劳累。\n\n【随诊要求】\n1. 用药3～5天后症状无缓解或加重者，及时复诊调整方案。\n2. 疗程结束后复查局部皮损消退情况，确认治愈；反复发作或迁延不愈者，建议转泌尿外科评估择期包皮环切术。\n3. 若出现发热、寒战、排尿困难、包皮嵌顿或腹股沟淋巴结肿大等表现，应立即复诊或急诊处理。"},"icd10_diagnosis":"","icd10_secondary":[],"icd9cm3_procedure":[]}},"locator":{"file":"门诊住院病历模板/病历模板包_全部_20261111.json","arrayRow":432,"caseRow":1},"sourceHash":"10e4fdb435986b7b85f847c3951d0cb0eafdce0f372c5617949c05b337149194","contentHash":"704bb3f9ae89b2e1b5294767134ed31fa63e0689a181d548dc207a43a3884aac","pinyin":"baopiguitouyan","initials":"bpgty","setting":"out","caseName":"门诊病历297","templateNames":["主诉","现病史","既往史","个人史及过敏史","体格检查","辅助检查","初步诊断","处理方案"],"emptyTemplates":[],"escapedNewlines":[],"quickFields":[["病例名称","门诊病历297",60],["模板名称","主诉 现病史 既往史 个人史及过敏史 体格检查 辅助检查 初步诊断 处理方案",30],["主要诊断编码","",30]]},{"id":"templates-93d1ffdca4554ccf33a0","key":"v1-c9ccc21dfe2a3058|templates-93d1ffdca4554ccf33a0","module":"templates","moduleKey":"v1-c9ccc21dfe2a3058|templates","version":"v1-c9ccc21dfe2a3058","title":"尿崩症","category":"门诊病历模板","raw":{"name":"尿崩症","category":"门诊病历模板","case":{"case_name":"门诊病历298","templates":{"主诉":"多饮、多尿伴烦渴6月","现病史":"患者于3月前开始多尿（24小时尿量达6L，低比重，尿崩症特征）、烦渴多饮（喜饮冷饮，每日6L），夜尿增多（3次/夜），无脱水表现，不能饮水时（昏迷/手术禁水）迅速脱水高钠、无头痛视野缺损（中枢性，下丘脑垂体病变：颅咽管瘤/垂体肿瘤/外伤手术/朗格汉斯细胞组织细胞增生症）、无肾功能不全/低钾/高钙（肾性尿崩症，对加压素无反应），有无头颅外伤/手术/放疗史及家族史（遗传性，婴幼儿发病）：无头颅外伤/手术/放疗史，无家族史。有无糖尿病（多尿鉴别，尿糖）：无糖尿病。今日来我院门诊就诊。","既往史":"既往体健，否认高血压、糖尿病、冠心病等慢性病史。否认肝炎、结核等传染病史。否认手术外伤史。否认食物药物过敏史。预防接种史随社会。","个人史及过敏史":"生于原籍，久居本地，无疫区疫水接触史，无特殊粉尘毒物放射性物质接触史。不吸烟，不饮酒。生活规律。否认食物药物过敏史。","体格检查":"T36.5℃，P88次/分，R18次/分，BP110/70mmHg（脱水时低血压）。神志清楚，皮肤黏膜干燥（脱水评估），神经系统检查（视野、颅神经，中枢病变，视交叉受压，双颞侧偏盲）未见异常。","辅助检查":"【必做】尿常规（低比重<1.005、低渗透压，尿渗透压<300mOsm/kg）、血电解质（血钠可正常或升高）、血渗透压、尿量测定（24小时）；【确诊】禁水-加压素试验（禁水后尿渗透压不升，中枢性：注射加压素后尿渗透压显著升高>50%；肾性：无反应）、血浆精氨酸加压素（AVP）水平（中枢性低/肾性高）；【病因影像】鞍区MRI（垂体柄增粗、下丘脑/垂体占位，中枢性病因）；【其他】血糖（排除糖尿病）、肾功能、血钙血钾（肾性病因）。","初步诊断":"1. 尿崩症（类型：中枢性，程度：完全性）\n（注：中枢性，去氨加压素（DDAVP）替代（口服0.1~0.2mg tid或鼻喷，从小剂量起始，监测血钠防水中毒，出现低钠停用）、治疗原发病（鞍区占位，手术/放疗，转神经外科/内分泌科）；肾性，去氨加压素无效：纠正病因（停锂盐、纠正低钾高钙、治疗肾疾病）、低盐低蛋白饮食+噻嗪类利尿剂（氢氯噻嗪25~50mg qd，减少尿量，机制：轻度容量不足促近端重吸收）+吲哚美辛（难治性）、阿米洛利（锂盐相关）；保证充分饮水（防脱水，尿崩症治疗前提，随意饮水时一般不发生脱水）；监测尿量、尿比重、血钠、体重，内分泌科长期随访。）","处理方案":"【药物治疗】1.去氨加压素片（弥凝）：为中枢性尿崩症首选，成人常规剂量0.1mg/次，口服或舌下含服，每日3次，根据尿量及口渴程度个体化调整（0.05～0.2mg/次），疗程为长期维持用药。2.氢氯噻嗪片：25mg/次，每日2～3次口服，适用于肾性尿崩症及部分中枢性尿崩症，服药期间限钠（每日<3g）并注意补钾，可联合氨苯蝶啶50mg每日2次以减少低钾风险，疗程为长期维持。3.卡马西平片：0.1～0.2g/次，每日2～3次口服，用于对去氨加压素疗效欠佳的部分中枢性尿崩症，疗程为长期维持。4.氯磺丙脲片：0.1～0.25g，每日1次晨服，可增强抗利尿激素作用，注意监测血糖防治低血糖，疗程为长期维持。\n【一般治疗及生活指导】1.保证充分饮水：每日饮水量按需供给（成人常需2～4L/d），随身携带水壶、口渴即饮，避免脱水，同时记录每日饮水量及尿量以便调整药量。2.饮食：低盐（每日钠<3g）、低蛋白饮食，忌浓茶、咖啡、酒精等利尿饮品及高渗饮食，以免加重尿量。3.休息与活动：规律作息，避免劳累、熬夜、精神应激及感染等诱因，日常活动量力而行，避免脱水时剧烈运动。4.监测：每日晨起测体重并记录，定期测血压、尿比重；警惕用药过量致水中毒（头痛、恶心、乏力、意识改变），出现时及时就诊。\n【随诊要求】1.用药期间每1～3个月门诊复诊，复查血电解质（钠、钾）、血/尿渗透压、尿比重及24小时尿量，评估疗效并调整去氨加压素剂量。2.长期服用氢氯噻嗪者定期复查电解质并防低钾；服用卡马西平、氯磺丙脲者定期监测肝肾功能及血糖。3.若出现严重口渴、尿量骤增、明显脱水，或水中毒表现（头痛、呕吐、抽搐、意识障碍）应立即就诊；儿童、妊娠及老年患者需专科随访并个体化调整方案。"},"icd10_diagnosis":"","icd10_secondary":[],"icd9cm3_procedure":[]}},"locator":{"file":"门诊住院病历模板/病历模板包_全部_20261111.json","arrayRow":433,"caseRow":1},"sourceHash":"10e4fdb435986b7b85f847c3951d0cb0eafdce0f372c5617949c05b337149194","contentHash":"27785651419cc8c058afea97e8162c687de940870772cb61a78bd873c1795886","pinyin":"niaobengzheng","initials":"nbz","setting":"out","caseName":"门诊病历298","templateNames":["主诉","现病史","既往史","个人史及过敏史","体格检查","辅助检查","初步诊断","处理方案"],"emptyTemplates":[],"escapedNewlines":[],"quickFields":[["病例名称","门诊病历298",60],["模板名称","主诉 现病史 既往史 个人史及过敏史 体格检查 辅助检查 初步诊断 处理方案",30],["主要诊断编码","",30]]},{"id":"templates-6ba6033eb68707ca916f","key":"v1-c9ccc21dfe2a3058|templates-6ba6033eb68707ca916f","module":"templates","moduleKey":"v1-c9ccc21dfe2a3058|templates","version":"v1-c9ccc21dfe2a3058","title":"抗利尿激素分泌异常综合征","category":"门诊病历模板","raw":{"name":"抗利尿激素分泌异常综合征","category":"门诊病历模板","case":{"case_name":"门诊病历299","templates":{"主诉":"乏力、恶心伴食欲减退2周","现病史":"患者（存在基础病：小细胞肺癌（SIADH最常见肿瘤病因）、中枢神经系统疾病（颅脑外伤/感染/卒中）、肺部疾病（肺炎/结核）、药物（SSRI类抗抑郁药、卡马西平、环磷酰胺、长春新碱、噻嗪类等）等病因线索）于2周前出现乏力、食欲减退、恶心、头痛，血钠118mmol/L（低钠），无神志改变：嗜睡、抽搐、昏迷（重度低钠<120mmol/L，脑水肿表现），尿量不少（不少，尿渗透压不适当升高（>100mOsm/kg）而血渗透压降低，SIADH特征，区别于容量不足）。今日来我院门诊就诊。","既往史":"既往体健，否认高血压、糖尿病、冠心病等慢性病史。否认肝炎、结核等传染病史。否认手术外伤史。否认食物药物过敏史。预防接种史随社会。","个人史及过敏史":"生于原籍，久居本地，无疫区疫水接触史，无特殊粉尘毒物放射性物质接触史。不吸烟，不饮酒。生活规律。否认食物药物过敏史。","体格检查":"T____℃，P____次/分，R____次/分，BP____/____mmHg（正常，无低血容量表现，重要鉴别）。神志____（清楚/嗜睡/昏迷），皮肤弹性正常（无脱水征，区别于真性低容量），神经系统检查（低钠脑病：抽搐、病理征）。","辅助检查":"【必做】血电解质（低钠<135mmol/L）、血渗透压（低<275mOsm/kg）、尿渗透压（不适当升高>100mOsm/kg，诊断核心）、尿钠（>40mmol/L，SIADH；<20，低容量性低钠）、肾功能、血糖、甲状腺功能（甲减，低钠病因）、肝功能、皮质醇（肾上腺皮质功能减退，低钠鉴别）；【病因筛查】胸部CT（肿瘤，肺癌排查，SIADH最常见病因，吸烟者必须）、头颅MRI（中枢病因）、肿瘤标志物。","初步诊断":"1. 抗利尿激素分泌异常综合征（SIADH，病因：肿瘤/中枢/肺部/药物待明确）\n（注：①病因治疗（核心，肿瘤治疗/停致病药物/治感染）；②限水（轻中度：液体限制<800~1000ml/日，一线，监测血钠渐升）；③中重度/有症状低钠：高渗盐水（3%NaCl，缓慢纠正：每小时血钠上升<0.5~1mmol/L，24小时<8~10mmol/L，防渗透性脱髓鞘（纠正过快，尤其慢性低钠）；必要时呋塞米+高渗盐水，紧急情况）；④药物治疗（限水无效）：地美环素300mg bid~qid（抑制AVP作用，肾性，注意肾毒性光敏）或托伐普坦（加压素V2受体拮抗剂，7.5~15mg qd，纠正低钠，监测血钠防过度纠正、肝功能）；⑤监测血钠（最初每4~6小时）、体重、出入量；纠正后明确并治疗病因（肿瘤排查为重中之重，避免漏诊肺癌）。）","处理方案":"【药物治疗】\n1. 托伐普坦片（选择性V2受体拮抗剂）15mg po qd，清晨服用，服药期间可不必严格限水；根据血钠回升情况可增至30mg qd，血钠正常后渐减量，疗程一般2-4周，用药期间每3-7天复查血钠及肝功能。\n2. 呋塞米片20mg po qd-bid，用于合并容量负荷需促进排水者，与补钠同用，注意监测血钾，必要时联合口服补钾（如氯化钾缓释片0.5g bid）。\n3. 病因治疗：排查并处理基础病因（恶性肿瘤、肺部感染、中枢神经系统疾病等），停用或更换可能诱发SIADH的药物（如卡马西平、SSRI类抗抑郁药、噻嗪类利尿剂、环磷酰胺等）；血钠<120mmol/L或伴明显神经系统症状者不适宜门诊处理，应收住院静脉输注3%高渗氯化钠。\n【一般治疗及生活指导】\n1. 严格限制液体入量：每日总液体入量控制在800-1000ml（含饮水、汤、粥、饮料及水果等所有含水量），记录每日出入量；每日晨起称体重，体重每日下降约0.5kg提示限液有效。\n2. 饮食：限水基础上适当增加食盐摄入（每日约6-9g，合并高血压、心衰、肾病者遵医嘱调整），保证优质蛋白及热量，忌一次性大量饮水、忌浓茶咖啡及含糖饮料。\n3. 避免诱因：避免剧烈运动后大量饮水，避免情绪激动及精神紧张，戒烟戒酒；避免自行服用可能影响水钠平衡的药物。\n【随诊要求】\n1. 每周复诊复查血电解质（血钠、血钾、血氯）、血渗透压、尿渗透压及尿钠，血钠回升速度应≤8-10mmol/L/24h，防止渗透性脱髓鞘综合征。\n2. 使用托伐普坦者用药1、2周及疗程结束时复查血钠与肝功能，疗程>30天者每2周复查肝功能；长期限液者每月复查血钠评估达标情况。\n3. 出现恶心呕吐、头痛、烦躁不安、意识模糊、嗜睡或抽搐等低钠症状加重表现时，立即急诊就医，不可拖延。"},"icd10_diagnosis":"","icd10_secondary":[],"icd9cm3_procedure":[]}},"locator":{"file":"门诊住院病历模板/病历模板包_全部_20261111.json","arrayRow":434,"caseRow":1},"sourceHash":"10e4fdb435986b7b85f847c3951d0cb0eafdce0f372c5617949c05b337149194","contentHash":"98ed8f6392ce8a8236030df12f3036c2155eff623b8caf30073c494957db6379","pinyin":"kangliniaojisufenmiyichangzonghezheng","initials":"klnjsfmyczhz","setting":"out","caseName":"门诊病历299","templateNames":["主诉","现病史","既往史","个人史及过敏史","体格检查","辅助检查","初步诊断","处理方案"],"emptyTemplates":[],"escapedNewlines":[],"quickFields":[["病例名称","门诊病历299",60],["模板名称","主诉 现病史 既往史 个人史及过敏史 体格检查 辅助检查 初步诊断 处理方案",30],["主要诊断编码","",30]]},{"id":"templates-88b958d7aad19b53bd0e","key":"v1-c9ccc21dfe2a3058|templates-88b958d7aad19b53bd0e","module":"templates","moduleKey":"v1-c9ccc21dfe2a3058|templates","version":"v1-c9ccc21dfe2a3058","title":"嗜铬细胞瘤","category":"门诊病历模板","raw":{"name":"嗜铬细胞瘤","category":"门诊病历模板","case":{"case_name":"门诊病历300","templates":{"主诉":"阵发性头痛、心悸、大汗1年","现病史":"患者于6月前开始反复出现阵发性发作：剧烈头痛、心悸、大汗（三联征，为嗜铬细胞瘤特征性表现）、面色苍白、恶心、焦虑、血压骤升（发作时血压可达220/130mmHg，平时可正常或持续升高），发作持续数分钟至1小时，自行缓解，发作频率每周2~3次，诱因（体位改变、情绪激动、体力活动、按压腹部、排便、饮酒、服用拟交感药或β受体阻滞剂后（可反常升压））：情绪激动及按压腹部。有无高血压（发病年龄轻、波动大）、糖尿病、甲状腺髓样癌或嗜铬细胞瘤家族史（MEN2、神经纤维瘤病、VHL等遗传综合征筛查）：无。今日来我院门诊就诊。","既往史":"既往体健，否认高血压、糖尿病、冠心病等慢性病史。否认肝炎、结核等传染病史。否认手术外伤史。否认食物药物过敏史。预防接种史随社会。","个人史及过敏史":"生于原籍，久居本地，无疫区疫水接触史，无特殊粉尘毒物放射性物质接触史。不吸烟，不饮酒。生活规律。否认食物药物过敏史。","体格检查":"T36.5℃，P96次/分（可增快），R20次/分，BP150/95mmHg（间歇期可正常或持续升高，注意发作时测量对比）。神志清楚，面色苍白（苍白或潮红），出汗（+），心率96次/分，心律齐，皮肤无咖啡牛奶斑（神经纤维瘤相关咖啡牛奶斑，NF1筛查）。","辅助检查":"检查计划：患者近半年反复阵发性剧烈头痛、心悸、大汗三联征，发作时血压骤升至220/130mmHg，情绪激动及按压腹部可诱发，血压波动大且发病年龄轻，高度提示儿茶酚胺分泌性肿瘤，故急诊或入院即刻完善血浆游离甲氧基肾上腺素类物质（MN/NMN）检测，其为敏感性与特异性最高的生化筛查，明确儿茶酚胺是否过量分泌；同时完善24小时尿儿茶酚胺及VMA/HVA测定，作为经典生化依据互相印证，排除假阴性并评估肿瘤分泌总量；生化提示阳性的基础上，完善肾上腺CT/MRI检查，明确肾上腺占位的大小、坏死囊变及强化特征，属于嗜铬细胞瘤典型表现，并明确定位，同时了解有无腹主动脉旁Zuckerkandl器；对怀疑转移或多发、异位病灶者，完善间碘苄胍显像（MIBG）或生长抑素受体显像，明确肿瘤分布范围及有无远处转移；追问患者无高血压、甲状腺髓样癌及嗜铬细胞瘤家族史，但本病年轻、双侧、多发者常属遗传综合征，故完善RET/VHL/NF1基因检测，明确有无MEN2、VHL病、神经纤维瘤病等遗传背景，指导家系筛查与长期随访。因α受体阻滞剂术前准备需评估心脏耐受性，完善心电图与心脏彩超了解有无儿茶酚胺心肌病、心律失常及心功能状态；完善血常规、肝肾功能、电解质及血糖检查，评估血容量与代谢状态，排除低钾、高血糖等儿茶酚胺效应所致异常，为术前扩容及用药安全提供保障。\n\n（检查清单）\n【必做】血浆游离甲氧基肾上腺素类物质（MN/NMN，为敏感性和特异性最高的生化筛查，首选用游离血浆或24小时尿分馏甲氧基肾上腺素）、24小时尿儿茶酚胺（VMA/HVA，经典但敏感性较低）；【影像学】肾上腺CT/MRI（肾上腺占位（>3cm、坏死囊变、增强明显，为嗜铬细胞瘤特征）、异位（腹主动脉旁Zuckerkandl器），用于定位）；【功能影像】间碘苄胍（MIBG）显像/生长抑素受体显像（转移/异位）；【遗传筛查】RET/VHL/NF1基因检测（年轻、家族史、双侧、多发者）。","初步诊断":"1. 嗜铬细胞瘤（部位：肾上腺（肾上腺外为副神经节瘤），来源：散发（遗传性者少见））\n（注：①术前准备（关键，防术中/操作中儿茶酚胺危象）：α受体阻滞剂（酚苄明10mg bid起始渐增或哌唑嗪，术前10~14天，目标血压<130/80、体位性低血压可接受），心率快时加β受体阻滞剂（普萘洛尔，必在α阻滞后使用，否则可致血压骤升，发生α危象）；②扩容（术前充分补液，α阻滞后血管扩张）；③手术切除（腹腔镜肾上腺切除，定位明确后）；④术中监测血压（硝普钠/酚妥拉明备用）；⑤急诊情况，高血压危象发作：酚妥拉明1~5mg静注；⑥术后随访（血压、儿茶酚胺，复发/转移，恶性约10%）；避免刺激（挤压肿瘤、麻醉诱导、造影剂）。）","处理方案":"【药物治疗】\n1. α受体阻滞剂（首选，解除儿茶酚胺收缩血管效应）：盐酸酚苄明片10mg bid起始，每2～3日递增10～20mg，直至血压平稳、阵发性发作消失，维持量一般为20～40mg/d分2～3次口服；或盐酸多沙唑嗪控释片4mg qd，必要时渐增至8mg qd。术前准备疗程至少2～4周。\n2. β受体阻滞剂（控制心率，必患者α受体阻滞剂充分患者、血压平稳后加用）：盐酸普萘洛尔片10mg tid，根据心率调整剂量，目标静息心率60～80次/分，疗程与α受体阻滞剂同步，禁止单独使用。\n3. 钙通道阻滞剂（辅助降压）：硝苯地平控释片30mg qd或苯磺酸氨氯地平片5mg qd，可与α受体阻滞剂联用增强降压、预防血管痉挛。\n\n【一般治疗及生活指导】\n1. 避免诱因：避免情绪激动、剧烈运动、用力排便、体位骤变、饱餐、腹部挤压及按压肿瘤部位等诱发儿茶酚胺大量释放的因素。\n2. 饮食：低盐饮食，忌咖啡、浓茶、酒精；少食奶酪、巧克力、香蕉、红葡萄酒、腌制及发酵食品等富含酪胺食物。\n3. 禁忌：禁止单独使用β受体阻滞剂；避免使用拟交感胺类药物（如麻黄碱）、糖皮质激素、三环类抗抑郁药及含麻黄成分的感冒药等可诱发高血压危象的药物。\n4. 自我监测：每日定时测量并记录血压、心率；出现阵发性头痛、心悸、出汗、面色苍白等发作时立即测血压并记录发作时间及诱因，供复诊调整用药参考。\n\n【随诊要求】\n1. 服药期间每1～2周复诊，根据血压、心率及直立性低血压情况调整α受体阻滞剂剂量；出现明显鼻塞、直立性低血压、心悸等不良反应及时就诊调整。\n2. 阵发性发作频繁或血压难以控制，或发作时血压显著升高（≥180/110mmHg）伴心悸、大汗者，应尽快就诊，必要时急诊处理，并完善血浆或24小时尿甲氧基肾上腺素类物质（MNs）、儿茶酚胺及VMA检测评估病情。\n3. 生化确诊后应尽早行定位检查：肾上腺区及腹部CT/MRI，必要时123I-MIBG或PET-CT显像，明确肿瘤部位、数目及有无转移，评估手术时机，转泌尿外科/普外科限期手术切除。\n4. 术后长期随访：术后1、6、12个月复查血压及血/尿儿茶酚胺代谢物，此后每年复查1次，监测复发与转移；确诊恶性嗜铬细胞瘤者转专科行131I-MIBG治疗或化疗，并按专科方案随访。"},"icd10_diagnosis":"","icd10_secondary":[],"icd9cm3_procedure":[]}},"locator":{"file":"门诊住院病历模板/病历模板包_全部_20261111.json","arrayRow":435,"caseRow":1},"sourceHash":"10e4fdb435986b7b85f847c3951d0cb0eafdce0f372c5617949c05b337149194","contentHash":"735b714d9e5e9da0f56a11b395cc73168edd555cb2e114be06ec36945fb02cf3","pinyin":"shigexibaoliu","initials":"sgxbl","setting":"out","caseName":"门诊病历300","templateNames":["主诉","现病史","既往史","个人史及过敏史","体格检查","辅助检查","初步诊断","处理方案"],"emptyTemplates":[],"escapedNewlines":[],"quickFields":[["病例名称","门诊病历300",60],["模板名称","主诉 现病史 既往史 个人史及过敏史 体格检查 辅助检查 初步诊断 处理方案",30],["主要诊断编码","",30]]},{"id":"templates-618fa016e2fef35bf5c7","key":"v1-c9ccc21dfe2a3058|templates-618fa016e2fef35bf5c7","module":"templates","moduleKey":"v1-c9ccc21dfe2a3058|templates","version":"v1-c9ccc21dfe2a3058","title":"原发性醛固酮增多症","category":"门诊病历模板","raw":{"name":"原发性醛固酮增多症","category":"门诊病历模板","case":{"case_name":"门诊病历301","templates":{"主诉":"血压升高伴乏力、多尿1年","现病史":"患者高血压病史8年，需3种降压药控制不佳/顽固性高血压（对常规降压药抵抗，使用>3种仍不达标，为醛固酮增多症筛查指征），血钾曾示2.9mmol/L（低钾，但约半数血钾正常，不能以低钾作为筛查前提），伴乏力、肌无力、多尿夜尿多、心悸、四肢麻木（低钾表现），有阵发性肌无力（有无阵发性肌无力/软瘫，严重低钾；心悸为低钾心电图表现），发病年龄较轻（<50岁）。有无肾上腺腺瘤/增生、高血压及醛固酮增多症家族史：无。今日来我院门诊就诊。","既往史":"既往体健，否认高血压、糖尿病、冠心病等慢性病史。否认肝炎、结核等传染病史。否认手术外伤史。否认食物药物过敏史。预防接种史随社会。","个人史及过敏史":"生于原籍，久居本地，无疫区疫水接触史，无特殊粉尘毒物放射性物质接触史。不吸烟，不饮酒。生活规律。否认食物药物过敏史。","体格检查":"T36.5℃，P86次/分，R18次/分，BP165/100mmHg（可显著升高）。神志清楚，查体合作。心率86次/分，心律齐（低钾时可出现期前收缩/房颤），肌力Ⅴ级（低钾时减弱），腱反射正常。","辅助检查":"【必做】血电解质（低钾，但正常不排除）、血醛固酮/肾素活性比值（ARR，为筛查核心：醛固酮（ng/dl）/肾素活性（ng/ml/h）>30且醛固酮>15ng/dl，阳性者需确诊试验）、肾功能（排除肾性失钾）；【确诊】生理盐水输注试验/卡托普利试验/口服高钠试验（ARR阳性者，醛固酮不被抑制，可确诊）；【分型影像】肾上腺CT（腺瘤（<2cm低密度）/双侧增生，但CT不能可靠分型，<1cm腺瘤易漏）；【分型确诊】肾上腺静脉采血（AVS，为单侧腺瘤与双侧增生的鉴别金标准，决定手术（单侧切除）或药物（双侧，用螺内酯），是关键检查）；【其他】血皮质醇（排除库欣）、基因（年轻/家族性，如糖皮质激素可抑制性醛固酮增多症）。","初步诊断":"1. 原发性醛固酮增多症（分型：特发性双侧增生（醛固酮腺瘤者需AVS分型））\n（注：①药物治疗（所有患者，尤其双侧增生）：螺内酯25~100mg qd起始（盐皮质激素受体拮抗剂，为一线用药，监测血钾血肌酐、男性乳房发育，可换依普利酮或阿米洛利）、补钾（低钾者）；②单侧腺瘤（AVS证实）行腹腔镜肾上腺切除术（术前螺内酯准备4周）；③降压目标（<130/80）联合常规降压药；④随访：术后1~2周复查血钾醛固酮，评估治愈/改善，每年随访血压电解质，监测复发（对侧/增生）；⑤筛查心血管并发症（低钾致心律失常、高血压靶器官损害），早诊早治（原醛占高血压5%~10%，难治性高血压者应筛查）。）","处理方案":"【药物治疗】\n1. 盐皮质激素受体拮抗剂（首选）：螺内酯片（安体舒通）20mg bid口服起始，根据血压及血钾每1～2周调整剂量，常规维持量40～80mg/d，分2～3次口服，长期维持；若出现男性乳房发育、性功能障碍等不良反应，可换用依普利酮片25mg bid口服。\n2. 补钾治疗：氯化钾缓释片0.5g tid口服，用于血钾<3.5mmol/L者，每1～2周复查血钾，达标（≥4.0mmol/L）后逐渐减量至停用，避免高钾血症。\n3. 联合降压（血压控制不佳时）：氨氯地平片5mg qd口服，或硝苯地平控释片30mg qd口服；仍不达标可加用缬沙坦胶囊80mg qd或依那普利片10mg qd，目标血压<140/90mmHg（合并糖尿病、慢性肾病者<130/80mmHg）。\n【一般治疗及生活指导】\n1. 低钠饮食：每日食盐摄入<5g，避免咸菜、腌制品、腊肉、酱油等高盐食物及加工食品。\n2. 适当补充富含钾食物（香蕉、橙子、土豆、菠菜、豆类等）；合并肾功能不全者补钾需在医师指导下进行，切勿自行大量补钾。\n3. 每日晨起及下午各测血压1次并记录，注意休息，避免劳累、熬夜及情绪激动，适度活动，戒烟限酒。\n4. 禁忌：避免服用含甘草制剂（如复方甘草片）、排钾利尿剂（氢氯噻嗪、呋塞米等）及长期使用非甾体抗炎药，以防电解质紊乱加重。\n【随诊要求】\n1. 用药调整期间每1～2周门诊复诊，复查血钾、血钠、肾功能及血压，据结果调整螺内酯及补钾方案；稳定后每2～4周复诊1次。\n2. 行肾上腺CT平扫+增强明确有无腺瘤，完善血浆醛固酮/肾素比值、盐水负荷试验或卡托普利抑制试验等确诊及分型检查。\n3. 确诊单侧肾上腺腺瘤者，转泌尿外科/内分泌科评估腹腔镜肾上腺切除术指征，术前按上述方案控制血压、纠正低钾；双侧增生者长期药物维持治疗。\n4. 术后或药物控制良好者每3～6个月复查血压、血钾及血浆醛固酮水平，长期随访。"},"icd10_diagnosis":"","icd10_secondary":[],"icd9cm3_procedure":[]}},"locator":{"file":"门诊住院病历模板/病历模板包_全部_20261111.json","arrayRow":436,"caseRow":1},"sourceHash":"10e4fdb435986b7b85f847c3951d0cb0eafdce0f372c5617949c05b337149194","contentHash":"0182fc7662becfb0f2db9b92006501280ad30fcbbdb491952755a04478e644ce","pinyin":"yuanfaxingquangutongzengduozheng","initials":"yfxqgtzdz","setting":"out","caseName":"门诊病历301","templateNames":["主诉","现病史","既往史","个人史及过敏史","体格检查","辅助检查","初步诊断","处理方案"],"emptyTemplates":[],"escapedNewlines":[],"quickFields":[["病例名称","门诊病历301",60],["模板名称","主诉 现病史 既往史 个人史及过敏史 体格检查 辅助检查 初步诊断 处理方案",30],["主要诊断编码","",30]]},{"id":"templates-3d33253cc06d47e7fb52","key":"v1-c9ccc21dfe2a3058|templates-3d33253cc06d47e7fb52","module":"templates","moduleKey":"v1-c9ccc21dfe2a3058|templates","version":"v1-c9ccc21dfe2a3058","title":"库欣综合征","category":"门诊病历模板","raw":{"name":"库欣综合征","category":"门诊病历模板","case":{"case_name":"门诊病历302","templates":{"主诉":"向心性肥胖、满月脸伴乏力1年","现病史":"患者于6月前渐出现向心性肥胖（躯干肥、四肢细）、满月脸、水牛背、皮肤紫纹（腹部大腿）、皮肤薄易瘀斑、痤疮多毛（女性）、月经紊乱，伴乏力、高血压、血糖升高、骨痛（骨质疏松）、情绪异常，有无近期长期使用糖皮质激素（药源性）、有无视力视野障碍（垂体大腺瘤）：无。今日来我院门诊就诊。","既往史":"既往体健，否认高血压、糖尿病、冠心病等慢性病史。否认肝炎、结核等传染病史。否认手术外伤史。否认食物药物过敏史。预防接种史随社会。","个人史及过敏史":"生于原籍，久居本地，无疫区疫水接触史，无特殊粉尘毒物放射性物质接触史。不吸烟，不饮酒。生活规律。否认食物药物过敏史。","体格检查":"T36.7℃，P88次/分，R18次/分，BP160/100mmHg。向心性肥胖、满月脸、水牛背，皮肤薄、腹部及大腿紫纹、瘀斑，多毛，锁骨上及颈背部脂肪垫，近端肌无力（下蹲起立困难），双下肢轻度水肿。","辅助检查":"【必做】午夜血/唾液皮质醇（昼夜节律消失）、24小时尿游离皮质醇、小剂量地塞米松抑制试验（1mg过夜不被抑制，可确诊）、血ACTH（鉴别垂体/肾上腺/异位）、血糖、血钾；【分型】大剂量地塞米松抑制试验、鞍区MRI、肾上腺CT；【并发症】骨密度、眼底。","初步诊断":"1. 库欣综合征（待分型：库欣病/肾上腺/异位ACTH）\n（注：病因治疗为核心，库欣病经蝶窦垂体瘤切除、肾上腺腺瘤手术切除（围术期激素替代防肾上腺危象）、异位ACTH切除原发肿瘤；药源性者缓慢减停激素；不能手术者药物治疗（酮康唑0.2g bid~tid，监测肝功能）；并发症处理（降压降糖补钾、钙剂维生素D及双膦酸盐抗骨质疏松）；术后随访激素及复发，内分泌科长期管理。）","处理方案":"【药物治疗】\n1. 奥西卓司他片：起始2mg bid（早晚随餐口服），每1-2周评估血皮质醇水平，按需每次加量2mg，维持量2-7mg bid，目标使24小时尿游离皮质醇及午夜血皮质醇降至正常范围，疗程需长期维持并个体化调整；用药期间监测血皮质醇，避免过度抑制出现肾上腺皮质功能不全。\n2. 酮康唑片：200mg bid 餐后口服，若耐受且血皮质醇未达标，每1-2周加量200mg，最大剂量400mg bid，疗程视血皮质醇控制情况而定；用药期间每2-4周监测肝功能（ALT/AST）及血钾，肝功能异常或出现黄疸立即停药并就诊。\n3. 美替拉酮胶囊（甲吡酮）：250mg tid 口服，必要时渐增至500mg tid-qid，疗程视血皮质醇水平调整；用药期间监测血压（部分患者可出现低血压）、血钾及血皮质醇，警惕肾上腺皮质功能不全（乏力、恶心、低血压）。\n4. 库欣病术后未缓解或复发者：可加用帕瑞肽（pasireotide）0.6mg bid 皮下注射，或卡麦角林0.5mg qod-qd 口服，疗程及剂量需在专科随访中根据血皮质醇与ACTH动态调整。\n\n【一般治疗及生活指导】\n1. 饮食：低盐、低糖、低脂饮食，控制总热量摄入，适当增加优质蛋白、含钾（香蕉、橙子、土豆）及含钙（牛奶、豆制品）食物摄入，限制腌制、加工食品，避免因高盐加重高血压及水肿。\n2. 休息与活动：规律作息，保证充足睡眠；可进行散步、太极拳等温和运动，避免剧烈运动、负重及跳跃，因长期皮质醇过多致骨质疏松，易发生骨折；注意防滑防跌倒。\n3. 预防感染：皮质醇过多及治疗期间免疫力下降，注意保暖、勤洗手，避免去人群密集场所，出现发热、咳嗽、尿路刺激症状及时就医；避免使用含糖皮质激素的药物、药膏及成分不明的保健品。\n4. 自我监测：每日监测血压、血糖（尤其空腹及餐后），记录体重及腹围变化；出现明显乏力、恶心、头晕、低血压、食欲减退等皮质醇过低表现时立即停药并急诊就诊。\n\n【随诊要求】\n1. 每1-3个月专科门诊复诊，复查24小时尿游离皮质醇、午夜唾液或血清皮质醇、血ACTH及促肾上腺皮质激素释放激素试验等，评估疗效并调整药物剂量。\n2. 定期监测血常规、血钾、肝功能（尤其服用酮康唑者）、血脂、血压及血糖，必要时行骨密度检查评估骨质疏松并予钙剂、维生素D治疗。\n3. 库欣病术后患者建议术后6-12周评估内分泌功能，长期随访有无复发；异位ACTH综合征或肾上腺皮质癌患者按病因制定相应随访计划。\n4. 治疗期间若出现感染、心衰加重、消化道溃疡出血、精神症状加重或皮质醇过低综合征（Addison危象前兆：乏力、低血压、低血糖、恶心呕吐），需及时就诊或急诊处理，不可自行停药或减量。"},"icd10_diagnosis":"","icd10_secondary":[],"icd9cm3_procedure":[]}},"locator":{"file":"门诊住院病历模板/病历模板包_全部_20261111.json","arrayRow":437,"caseRow":1},"sourceHash":"10e4fdb435986b7b85f847c3951d0cb0eafdce0f372c5617949c05b337149194","contentHash":"239e63b17412175af8382c5d05d5c7759492a7ff4bd39f6aa42b2c074d70767f","pinyin":"kuxinzonghezheng","initials":"kxzhz","setting":"out","caseName":"门诊病历302","templateNames":["主诉","现病史","既往史","个人史及过敏史","体格检查","辅助检查","初步诊断","处理方案"],"emptyTemplates":[],"escapedNewlines":[],"quickFields":[["病例名称","门诊病历302",60],["模板名称","主诉 现病史 既往史 个人史及过敏史 体格检查 辅助检查 初步诊断 处理方案",30],["主要诊断编码","",30]]},{"id":"templates-d62f3551ffcb098c28e5","key":"v1-c9ccc21dfe2a3058|templates-d62f3551ffcb098c28e5","module":"templates","moduleKey":"v1-c9ccc21dfe2a3058|templates","version":"v1-c9ccc21dfe2a3058","title":"肾上腺皮质功能减退","category":"门诊病历模板","raw":{"name":"肾上腺皮质功能减退","category":"门诊病历模板","case":{"case_name":"门诊病历303","templates":{"主诉":"乏力、食欲减退伴体重下降6月","现病史":"患者于8月前渐出现进行性乏力（休息不缓解）、食欲减退、恶心、体重下降、低血压头晕、空腹心慌出汗（低血糖），有无皮肤黏膜色素沉着（原发，表现为皮肤皱褶掌纹牙龈瘢痕变黑）、阴毛腋毛脱落（继发，提示垂体病变）、结核史、长期激素后骤停史、抗磷脂综合征及自身免疫病：无。今日来我院门诊就诊。","既往史":"既往体健，否认高血压、糖尿病、冠心病等慢性病史。否认肝炎、结核等传染病史。否认手术外伤史。否认食物药物过敏史。预防接种史随社会。","个人史及过敏史":"生于原籍，久居本地，无疫区疫水接触史，无特殊粉尘毒物放射性物质接触史。不吸烟，不饮酒。生活规律。否认食物药物过敏史。","体格检查":"T36.2℃，P92次/分，R18次/分，BP88/56mmHg（偏低，体位性低血压）。消瘦，皮肤色素沉着（原发，见于乳头乳晕、掌纹、口腔黏膜）、腋毛稀疏，心音低钝。","辅助检查":"检查计划：患者近8个月进行性乏力、食欲减退、恶心、体重下降，伴低血压头晕及空腹心慌出汗，提示肾上腺皮质功能减退可能，故首要完善血电解质检查，了解有无低钠高钾这一原发性肾上腺皮质功能减退的特征性改变；完善血糖检查，明确有无空腹低血糖，评估糖异生受损程度；完善血皮质醇（基础值）及血ACTH测定，原发性者皮质醇降低而ACTH升高，继发性者两者均降低，借此明确病变位于肾上腺还是垂体；进而完善ACTH兴奋试验，观察皮质醇能否正常升高，为确诊本病及鉴别原发与继发提供金标准依据。病因方面，患者否认结核史、长期激素骤停史及自身免疫病史，但需完善肾上腺CT检查，明确有无结核性钙化、肾上腺萎缩或出血等病变；完善抗21-羟化酶抗体检测，明确有无自身免疫性肾上腺炎；对考虑继发者完善鞍区MRI检查，明确有无垂体腺瘤、空蝶鞍等垂体病变。因患者乏力怕冷、体重下降，需完善甲状腺功能检查，了解有无合并甲状腺功能减退或其他自身免疫性内分泌腺病；同时完善血常规、肝肾功能、心电图检查，评估贫血、电解质紊乱对心脏的影响及激素替代治疗的用药安全，必要时监测血钠、血钾与血压以调整氟氢可的松剂量。\n\n（检查清单）\n【必做】血电解质（低钠高钾，见于原发）、血糖（可低）、血皮质醇（基础降低）、血ACTH（原发升高/继发降低）、ACTH兴奋试验（确诊，皮质醇不升）；【病因】肾上腺CT（结核钙化/萎缩/出血）、抗21-羟化酶抗体、鞍区MRI（继发）；【其他】甲状腺功能。","初步诊断":"1. 肾上腺皮质功能减退（原发/继发）\n（注：激素替代终身，氢化可的松（早15~20mg、午后5~10mg）或泼尼松晨顿服；原发者加氟氢可的松（监测血压血钾）；应激（感染手术外伤）时激素加倍，预防肾上腺危象（呕吐腹泻、低血压休克、低钠高钾、低血糖意识障碍，急症处理：静脉氢化可的松100mg q6~8h+补糖盐水）；随身应急卡及注射剂；治疗原发病（结核抗结核）；内分泌科长期随访。）","处理方案":"【药物治疗】\n1. 糖皮质激素替代治疗（首选）：氢化可的松片20mg/日，分次口服（晨8时服10-15mg，下午4时服5mg，模拟皮质醇昼夜节律）；或泼尼松片5-7.5mg/日，分早晚两次口服（晨服全量2/3，午后服1/3）。维持量个体化，以乏力、低血压、食欲等临床症状缓解为目标，长期维持。\n2. 盐皮质激素替代：氟氢可的松片0.05-0.1mg，每日1次晨服，适用于原发性肾上腺皮质功能减退伴醛固酮缺乏者，联合糖皮质激素使用。\n3. 应激状态糖皮质激素加量：发热、感染、外伤、手术等应激时，氢化可的松剂量临时增至平时2-3倍（如每日40-60mg），应激解除后逐渐减回维持量；若出现呕吐、腹泻不能口服时，需立即静脉给药（氢化可的松琥珀酸钠100mg静脉滴注，q8h）并急诊就诊。\n\n【一般治疗及生活指导】\n1. 高钠饮食：鼓励适当多食盐（每日10-15g），避免高钾食物（香蕉、柑橘、橙汁、土豆等），防止低钠血症及高钾血症。\n2. 注意休息，避免劳累、熬夜、剧烈运动、情绪激动及精神紧张，保证充足睡眠，生活规律。\n3. 注意保暖，避免受凉感冒及感染，勤洗手、避免去人群密集场所；外出随身携带疾病识别卡，标明诊断及用药。\n4. 糖皮质激素须遵医嘱规律服用，不可自行增减、漏服或停药；避免使用可加重病情的药物（如利福平、苯妥英钠、酮康唑等），如确需使用应复诊调整激素剂量。\n\n【随诊要求】\n1. 每1-3个月门诊复诊1次，监测血压、体重、电解质（血钠、血钾）、血糖，评估激素替代剂量是否恰当，据此调整药物剂量。\n2. 每年复查1次肾上腺CT或垂体MRI及肾上腺功能相关检查，评估原发病变化；定期监测骨密度。\n3. 若出现发热、恶心呕吐、腹泻、腹痛、乏力进行性加重、血压下降、意识淡漠等，提示可能发生肾上腺危象，须立即就近急诊就医，切勿延误。"},"icd10_diagnosis":"","icd10_secondary":[],"icd9cm3_procedure":[]}},"locator":{"file":"门诊住院病历模板/病历模板包_全部_20261111.json","arrayRow":438,"caseRow":1},"sourceHash":"10e4fdb435986b7b85f847c3951d0cb0eafdce0f372c5617949c05b337149194","contentHash":"0699a0f433380f9c1d61ddc7784303ceed8a33986653b151e180759765985fff","pinyin":"shenshangxianpizhigongnengjiantui","initials":"ssxpzgnjt","setting":"out","caseName":"门诊病历303","templateNames":["主诉","现病史","既往史","个人史及过敏史","体格检查","辅助检查","初步诊断","处理方案"],"emptyTemplates":[],"escapedNewlines":[],"quickFields":[["病例名称","门诊病历303",60],["模板名称","主诉 现病史 既往史 个人史及过敏史 体格检查 辅助检查 初步诊断 处理方案",30],["主要诊断编码","",30]]},{"id":"templates-9ec913ff7859697bfac6","key":"v1-c9ccc21dfe2a3058|templates-9ec913ff7859697bfac6","module":"templates","moduleKey":"v1-c9ccc21dfe2a3058|templates","version":"v1-c9ccc21dfe2a3058","title":"甲状旁腺功能亢进","category":"门诊病历模板","raw":{"name":"甲状旁腺功能亢进","category":"门诊病历模板","case":{"case_name":"门诊病历304","templates":{"主诉":"骨痛、乏力伴多饮多尿6月","现病史":"患者于____月前渐出现全身骨痛、乏力、食欲减退、便秘、多饮多尿、情绪抑郁，有无反复肾结石（血尿肾绞痛）、病理性骨折、胰腺炎、消化性溃疡（MEN1）、颈部放疗史、肾衰竭透析史（三发性）及家族史：____。血钙曾示____（升高）。今日来我院门诊就诊。","既往史":"既往体健，否认高血压、糖尿病、冠心病等慢性病史。否认肝炎、结核等传染病史。否认手术外伤史。否认食物药物过敏史。预防接种史随社会。","个人史及过敏史":"生于原籍，久居本地，无疫区疫水接触史，无特殊粉尘毒物放射性物质接触史。不吸烟，不饮酒。生活规律。否认食物药物过敏史。","体格检查":"T36.5℃，P80次/分，R18次/分，BP145/90mmHg。骨骼压痛，角膜带状变性（裂隙灯，见于长期高钙），脱水貌，颈部无明显包块。","辅助检查":"【必做】血钙（白蛋白校正后升高）、血磷（低）、甲状旁腺激素（PTH升高，为确诊核心，即高钙+PTH高）、25-(OH)D、肾功能、24小时尿钙（鉴别家族性低尿钙性高钙血症）；【定位】颈部超声、99mTc-MIBI甲状旁腺显像；【并发症】骨密度、泌尿系超声。","初步诊断":"1. 原发性甲状旁腺功能亢进症\n（注：手术切除为根治手段，有症状、血钙高于正常上限0.25mmol/L以上、尿钙高、骨密度T值<-2.5、年龄<50岁均应手术（微创甲状旁腺切除，术前超声+MIBI定位）；无症状轻度高钙可随访（每6~12个月复查）；术后警惕低钙血症（骨饥饿，予口服钙+骨化三醇）；高钙危象（>3.5mmol/L意识障碍，急诊：生理盐水补液+呋塞米+降钙素/唑来膦酸）；遗传性（MEN1）家族筛查。）","处理方案":"【药物治疗】\n1. 拟钙剂：西那卡塞片25mg po qd，晚餐后服用，每2~4周根据血钙及PTH水平滴定剂量（可增至50~75mg qd，最大90mg bid），适用于有手术禁忌、手术失败的原发性甲旁亢及药物难治性继发性甲旁亢，长期维持治疗，用药期间每1~2周监测血钙、血PTH，警惕低钙血症。\n2. 双膦酸盐（合并骨质疏松时）：阿仑膦酸钠片70mg po qw，晨起空腹以200ml清水送服，服后保持直立位至少30分钟且禁食禁卧，疗程6~12个月后复查骨密度评估疗效；亦可用唑来膦酸5mg静脉滴注，每12个月1次。\n3. 活性维生素D（仅限继发性甲旁亢伴低钙或肾功能不全者）：骨化三醇胶丸0.25μg po bid，根据血钙、血磷、PTH调整，疗程中每周至每月监测血钙、血磷、尿钙，防止高钙血症。\n4. 高钙血症明显者：呋塞米片20~40mg po qd（充分补液后短期使用），促进尿钙排泄；必要时住院行静脉补液及降钙素治疗。\n\n【一般治疗及生活指导】\n1. 多饮水，每日2000~3000ml，促进尿钙排出，减少肾结石及泌尿系钙盐沉积风险；避免脱水及大量出汗。\n2. 低钙饮食：限制奶制品、豆制品、虾皮、芝麻酱等高钙食物，避免额外补充钙剂和维生素D；忌用噻嗪类利尿剂（氢氯噻嗪）、锂盐等可升高血钙的药物。\n3. 适当进行负重运动（步行、慢跑、抗阻训练）以维持骨量，合并骨质疏松者注意防跌倒，避免剧烈运动及重物提举以防病理性骨折。\n4. 戒烟限酒，规律作息，避免长期卧床制动；每半年至一年口腔科检查（警惕颌骨棕色瘤及牙龈病变）。\n\n【随诊要求】\n1. 治疗初期及剂量调整期每1~3个月复查血钙、血磷、血PTH、肾功能、碱性磷酸酶及24h尿钙，病情稳定后每3~6个月复查1次。\n2. 每6~12个月复查骨密度（双能X线吸收法）评估骨量变化及抗骨质疏松疗效。\n3. 每6~12个月行泌尿系超声，筛查肾结石、肾钙质沉着，必要时查泌尿系CT。\n4. 拟行或已行甲状旁腺切除者，术前评估颈部超声及甲状旁腺核素显像定位，术后第1周每日监测血钙（警惕骨饥饿综合征致低钙血症），并随访血PTH评估是否治愈或复发。"},"icd10_diagnosis":"","icd10_secondary":[],"icd9cm3_procedure":[]}},"locator":{"file":"门诊住院病历模板/病历模板包_全部_20261111.json","arrayRow":439,"caseRow":1},"sourceHash":"10e4fdb435986b7b85f847c3951d0cb0eafdce0f372c5617949c05b337149194","contentHash":"b5461fb76100fc0b300465f741f6f399b2a12f8a519abe783a29366ef6a5a98a","pinyin":"jiazhuangpangxiangongnengkangjin","initials":"jzpxgnkj","setting":"out","caseName":"门诊病历304","templateNames":["主诉","现病史","既往史","个人史及过敏史","体格检查","辅助检查","初步诊断","处理方案"],"emptyTemplates":[],"escapedNewlines":[],"quickFields":[["病例名称","门诊病历304",60],["模板名称","主诉 现病史 既往史 个人史及过敏史 体格检查 辅助检查 初步诊断 处理方案",30],["主要诊断编码","",30]]},{"id":"templates-fb6f2d9564ee5f3df21f","key":"v1-c9ccc21dfe2a3058|templates-fb6f2d9564ee5f3df21f","module":"templates","moduleKey":"v1-c9ccc21dfe2a3058|templates","version":"v1-c9ccc21dfe2a3058","title":"甲状旁腺功能减退","category":"门诊病历模板","raw":{"name":"甲状旁腺功能减退","category":"门诊病历模板","case":{"case_name":"门诊病历305","templates":{"主诉":"反复手足搐搦、四肢麻木6月","现病史":"患者于甲状腺/甲状旁腺手术后（甲状腺/甲状旁腺手术后、颈部放疗后、自身免疫性）出现反复手足搐搦（手足痉挛呈助产士手）、四肢远端麻木刺痛、肌肉痉挛，有无喉痉挛（喘鸣）、癫痫样发作、性格改变、白内障、皮肤干燥脱屑、毛发稀疏：无。血钙曾示1.75mmol/L（低）。有无Addison病及念珠菌病（APS）史及家族史：无。今日来我院门诊就诊。","既往史":"既往体健，否认高血压、糖尿病、冠心病等慢性病史。否认肝炎、结核等传染病史。否认手术外伤史。否认食物药物过敏史。预防接种史随社会。","个人史及过敏史":"生于原籍，久居本地，无疫区疫水接触史，无特殊粉尘毒物放射性物质接触史。不吸烟，不饮酒。生活规律。否认食物药物过敏史。","体格检查":"T36.5℃，P78次/分，R18次/分，BP112/72mmHg。Chvostek征（叩面神经口角抽动）、Trousseau征（束臂试验手痉挛），皮肤干燥、毛发稀疏，白内障（裂隙灯）。","辅助检查":"【必做】血钙（低）、血磷（高）、PTH（低，见于原发甲旁减；高，见于假性甲旁减，即PTH抵抗）、血镁、25-(OH)D、肾功能；【影像】头颅CT（基底节钙化，见于长期低钙）、心电图（QT延长）；【其他】甲状旁腺术后动态监测。","初步诊断":"1. 甲状旁腺功能减退症\n（注：急性低钙（搐搦喉痉挛癫痫，属急症）：10%葡萄糖酸钙10~20ml缓慢静注（监测心电）后继滴注；慢性治疗：口服钙剂（元素钙1~1.5g/d）+活性维生素D（骨化三醇0.25~1μg/d，为核心用药），目标血钙维持正常低值（2.0~2.2mmol/L，防高尿钙结石），定期监测血钙尿钙（防过量高钙及肾结石）；低镁者补镁；避免加重因素；内分泌科长期管理。）","处理方案":"【药物治疗】\n1. 钙剂：碳酸钙D3片（钙尔奇D，每片含元素钙600mg）1片 口服 qd，餐中或餐后嚼服；若血钙未达目标值可增至1片 bid，依据复查血钙调整。\n2. 活性维生素D：骨化三醇胶囊（罗盖全）0.25μg 口服 bid，维持量0.25～0.5μg/d；或阿法骨化醇软胶囊（阿法迪三）0.25μg 口服 qd，可渐增至0.5～1μg/d，与钙剂联用，目标血钙维持在正常低值（2.0～2.25mmol/L）。\n3. 低镁血症纠正：若血镁<0.65mmol/L，予25%硫酸镁10ml加入5%葡萄糖液500ml中静脉滴注 qd，纠正后改口服补镁，因低镁可导致PTH分泌与作用障碍。\n4. 低钙血症急性发作（手足搐搦、喉痉挛）：10%葡萄糖酸钙注射液10ml 加25%葡萄糖20ml缓慢静注（≥10分钟），继以10%葡萄糖酸钙30ml加入5%葡萄糖500ml静脉滴注维持，症状缓解后尽早转口服钙剂序贯治疗。\n\n【一般治疗及生活指导】\n1. 饮食：高钙低磷饮食，增加奶制品、豆制品、芝麻酱等含钙丰富食物；限制蛋黄、动物内脏、坚果、全谷类及含磷饮料（可乐等）等高磷食物摄入。\n2. 休息与活动：低钙症状明显或调整用药期间注意休息，避免剧烈运动与过度劳累；病情稳定者可正常活动，注意预防跌倒，避免外伤致骨折。\n3. 禁忌与诱因规避：避免过度换气、情绪激动、腹泻、呕吐、发热等诱发低钙的因素；妊娠期、哺乳期需在医师指导下增加钙剂及维生素D剂量；钙剂避免与铁剂、四环素类、左甲状腺素同时服用（间隔至少2小时），以免影响吸收。\n4. 用药安全：避免长期使用袢利尿剂（呋塞米）及糖皮质激素等可加重低钙的药物；如同时使用噻嗪类利尿剂、锂剂等需监测血钙及尿钙变化。\n\n【随诊要求】\n1. 调整药物期间每1～2周复诊复查血清钙、磷、镁及24小时尿钙，目标血钙2.0～2.25mmol/L、24小时尿钙<7.5mmol（300mg），避免高钙尿症及肾结石形成。\n2. 病情稳定后每1～3个月复诊，复查血钙、血磷、血镁及肾功能；每6～12个月行泌尿系超声检查，筛查肾钙质沉着及肾结石；长期病程者每年评估骨密度及眼科检查（白内障筛查）。\n3. 若出现手足麻木、抽搐、喉痉挛、心悸或精神行为异常，提示低钙血症急性加重，应立即急诊就诊，不可等待常规复诊。"},"icd10_diagnosis":"","icd10_secondary":[],"icd9cm3_procedure":[]}},"locator":{"file":"门诊住院病历模板/病历模板包_全部_20261111.json","arrayRow":440,"caseRow":1},"sourceHash":"10e4fdb435986b7b85f847c3951d0cb0eafdce0f372c5617949c05b337149194","contentHash":"ccd34532c389a895c1f2979e985ec27f9fc766315161e7fa76a4479bbae76869","pinyin":"jiazhuangpangxiangongnengjiantui","initials":"jzpxgnjt","setting":"out","caseName":"门诊病历305","templateNames":["主诉","现病史","既往史","个人史及过敏史","体格检查","辅助检查","初步诊断","处理方案"],"emptyTemplates":[],"escapedNewlines":[],"quickFields":[["病例名称","门诊病历305",60],["模板名称","主诉 现病史 既往史 个人史及过敏史 体格检查 辅助检查 初步诊断 处理方案",30],["主要诊断编码","",30]]},{"id":"templates-95cde531bc9d4fe97225","key":"v1-c9ccc21dfe2a3058|templates-95cde531bc9d4fe97225","module":"templates","moduleKey":"v1-c9ccc21dfe2a3058|templates","version":"v1-c9ccc21dfe2a3058","title":"垂体功能减退","category":"门诊病历模板","raw":{"name":"垂体功能减退","category":"门诊病历模板","case":{"case_name":"门诊病历306","templates":{"主诉":"乏力、怕冷伴性功能减退1年","现病史":"患者（病因：垂体腺瘤压迫、产后大出血（Sheehan）、垂体卒中、颅脑外伤手术放疗、浸润病、淋巴细胞性垂体炎）于产后大出血后渐出现乏力怕冷（继发甲减）、性欲减退/阳痿/闭经（性腺轴）、低血糖低血压（ACTH轴，即继发肾上腺皮质功能不全）、产后无乳闭经，有无头痛、视力视野障碍（视交叉受压，表现为双颞侧偏盲）、多饮多尿（尿崩症）：无。今日来我院门诊就诊。","既往史":"既往体健，否认高血压、糖尿病、冠心病等慢性病史。否认肝炎、结核等传染病史。否认手术外伤史。否认食物药物过敏史。预防接种史随社会。","个人史及过敏史":"生于原籍，久居本地，无疫区疫水接触史，无特殊粉尘毒物放射性物质接触史。不吸烟，不饮酒。生活规律。否认食物药物过敏史。","体格检查":"T36.3℃，P62次/分（可慢），R16次/分，BP96/62mmHg（可低）。皮肤苍白细腻、腋毛阴毛稀疏、眉毛外1/3脱落，乳房外生殖器萎缩，视野（双颞侧偏盲）。","辅助检查":"检查计划：患者产后大出血后渐出现乏力、怕冷、性欲减退、产后无乳及闭经，临床考虑Sheehan综合征致垂体功能减退，故完善垂体前叶激素全套检查，逐项评估各内分泌轴功能；查TSH及FT4，明确有无继发性甲状腺功能减退，解释患者怕冷、乏力症状；查ACTH及皮质醇，评估肾上腺轴功能，明确有无继发性肾上腺皮质功能不全，为激素替代顺序（先补皮质醇后补甲状腺素）提供依据；查FSH、LH及雌二醇或睾酮，了解性腺轴受损程度，明确闭经与性功能减退的病因；查泌乳素，明确有无垂体柄受压所致升高或垂体坏死所致降低；查GH及IGF-1，评估生长激素轴储备，指导是否需生长激素替代。因肾上腺轴与甲状腺轴功能低下易致低钠、低血糖，完善电解质及血糖检查，排除低钠、低钾等电解质紊乱所致乏力与心律失常，并了解有无低血糖，评估垂体功能减退对糖代谢的影响，保障替代治疗安全；患者有产后大出血病史，完善鞍区MRI增强扫描，明确有无垂体腺瘤、空蝶鞍或垂体柄增粗等病因，并了解视交叉有无受压；对多饮多尿或怀疑生长激素缺乏者，必要时完善GH激发试验，明确生长激素储备功能；此外完善血常规、肝肾功能及心电图检查，评估贫血、电解质异常及心脏耐受性；替代治疗期间定期复查各轴激素水平与电解质，评估疗效并调整剂量。\n\n（检查清单）\n【必做】垂体前叶激素全套，包括TSH及FT4（继发甲减）、ACTH及皮质醇、FSH/LH及雌二醇/睾酮、泌乳素（可高，因垂体柄受压）、GH/IGF-1、电解质血糖；【影像】鞍区MRI增强（腺瘤/空蝶鞍/柄增粗）；【动态】必要时GH激发试验。","初步诊断":"1. 垂体功能减退症（受累轴：性腺轴、甲状腺轴、肾上腺轴）\n（注：激素替代治疗，先补皮质醇（氢化可的松，必须先于甲状腺素，否则诱发肾上腺危象）再补甲状腺素（左甲状腺素50~100μg qd），之后补性激素，GH由专科评估；病因治疗（泌乳素瘤，卡麦角林/溴隐亭首选；大腺瘤压迫，手术）；垂体卒中为急症（突发头痛视力障碍，予大剂量激素+急诊减压）；应激时激素加量；Sheehan产后及早诊断；内分泌科长期随访。）","处理方案":"【药物治疗】\n1. 糖皮质激素替代（首选，须最先启动）：醋酸泼尼松片 2.5～5mg，每日晨起（7～8时）顿服，模拟生理性皮质醇分泌节律；如遇感染、手术、外伤等应激情况，剂量暂增至原剂量的2～3倍，应激消除后渐减回维持量。\n2. 甲状腺激素替代（患者糖皮质激素替代充分后或同时启动，勿先于糖皮质激素）：左甲状腺素钠片（优甲乐）25μg 每日晨起空腹顿服，每1～2周递增25μg，直至甲状腺功能恢复正常水平，维持量一般为50～100μg/日。\n3. 性激素替代（男性）：十一酸睾酮胶丸 40mg 每日2次，餐后服用（或80mg每日1次），连用2～3个月后复查睾酮水平调整剂量。\n4. 性激素替代（女性，视年龄及生育需求）：雌二醇片 1～2mg/日，后半周期加用孕激素（如地屈孕酮10mg bid×10天）行周期序贯治疗，绝经后或有禁忌者暂不启用。\n\n【一般治疗及生活指导】\n1. 规律作息，避免劳累、熬夜及情绪波动；避免剧烈运动和突然改变体位，防止低血压、低血糖发生。\n2. 均衡饮食，保证足量蛋白质及含碘食物摄入；嘱按时进食，随身携带糖果、饼干，出现心慌、出冷汗等低血糖征兆时立即进食。\n3. 注意保暖，预防感冒及各种感染；避免外伤、手术等应激诱因，需行有创操作或手术前务必告知医师正在接受激素替代治疗。\n4. 激素替代药物须长期坚持、规律服用，严禁自行停药、减量或随意更换，随身携带注明诊断及用药的急救卡片。\n\n【随诊要求】\n1. 用药初期每2～4周复诊1次，评估症状改善及血压、血糖、电解质（尤其血钠）等指标；病情稳定后每3～6个月复诊1次。\n2. 每3～6个月复查血皮质醇、促肾上腺皮质激素（ACTH）、促甲状腺激素（TSH）、游离T4、泌乳素、性激素及睾酮水平，据此调整替代剂量；每年复查一次垂体MRI及视野检查。\n3. 告知患者若出现发热、恶心呕吐、腹痛、血压骤降、意识模糊等表现，提示肾上腺危象可能，须立即急诊就诊并告知激素用药史。"},"icd10_diagnosis":"","icd10_secondary":[],"icd9cm3_procedure":[]}},"locator":{"file":"门诊住院病历模板/病历模板包_全部_20261111.json","arrayRow":441,"caseRow":1},"sourceHash":"10e4fdb435986b7b85f847c3951d0cb0eafdce0f372c5617949c05b337149194","contentHash":"846e37bfc15270b7812cca5bb13b07ae665a5584e123a78808b5680a64841517","pinyin":"chuitigongnengjiantui","initials":"ctgnjt","setting":"out","caseName":"门诊病历306","templateNames":["主诉","现病史","既往史","个人史及过敏史","体格检查","辅助检查","初步诊断","处理方案"],"emptyTemplates":[],"escapedNewlines":[],"quickFields":[["病例名称","门诊病历306",60],["模板名称","主诉 现病史 既往史 个人史及过敏史 体格检查 辅助检查 初步诊断 处理方案",30],["主要诊断编码","",30]]},{"id":"templates-9f9a36aa5071561654c6","key":"v1-c9ccc21dfe2a3058|templates-9f9a36aa5071561654c6","module":"templates","moduleKey":"v1-c9ccc21dfe2a3058|templates","version":"v1-c9ccc21dfe2a3058","title":"巨人症","category":"门诊病历模板","raw":{"name":"巨人症","category":"门诊病历模板","case":{"case_name":"门诊病历307","templates":{"主诉":"面容粗陋、手足增大伴头痛5年","现病史":"患者（青少年骨垢未闭，表现为身高猛长（巨人症）；成人骨垢已闭，表现为肢端肥大，即面容粗陋、手足增大，鞋号/戒指增大、皮肤粗厚油腻多汗、声音低沉）于6年前渐出现上述改变，伴头痛、乏力、睡眠呼吸暂停（舌大）、关节痛、腕管综合征、视力视野障碍（垂体大腺瘤）、高血压、血糖升高：无。今日来我院门诊就诊。","既往史":"既往体健，否认高血压、糖尿病、冠心病等慢性病史。否认肝炎、结核等传染病史。否认手术外伤史。否认食物药物过敏史。预防接种史随社会。","个人史及过敏史":"生于原籍，久居本地，无疫区疫水接触史，无特殊粉尘毒物放射性物质接触史。不吸烟，不饮酒。生活规律。否认食物药物过敏史。","体格检查":"T36.6℃，P82次/分，R18次/分，BP148/92mmHg。身材高大或面容粗陋（眉弓突出、鼻唇厚、下颌前突、舌大）、手足增大、皮肤粗厚多毛、面部皱纹深，心界扩大，视野（双颞侧偏盲）。","辅助检查":"检查计划：患者6年来面容粗陋、手足增大，鞋号与戒指增大、皮肤粗厚油腻，伴头痛与睡眠呼吸暂停，符合生长激素分泌过多表现，故门诊完善血清IGF-1测定，其为筛查肢端肥大症最敏感的指标，明确有无生长激素轴过度活跃；进而完善口服葡萄糖抑制试验（75g葡萄糖负荷后测GH），观察GH能否被抑制至1μg/L以下，明确疾病是否处于活动期，作为确诊依据；同时完善垂体前叶激素全套，了解甲状腺轴、肾上腺轴、性腺轴及泌乳素有无受累，评估垂体功能储备，为激素替代与手术风险做准备。因生长激素过多常合并糖代谢异常与心肌病变，完善血糖HbA1c检查，明确有无糖尿病或糖耐量减低；完善心脏超声检查，了解有无心肌肥厚、心脏扩大及瓣膜反流等肢端肥大症心肌病表现；完善肝肾功能检查，评估代谢状态及生长抑素类似物、培维索孟等药物使用的安全性。影像方面，完善鞍区MRI增强扫描，明确垂体腺瘤大小、位置及有无视交叉受压，为经蝶窦手术定位；因患者GH腺瘤病程长，结直肠腺瘤及癌风险升高，完善结肠镜检查筛查结直肠病变，明确有无腺瘤并予切除随访。此外完善血常规、电解质、睡眠呼吸监测，评估有无贫血、电解质紊乱及睡眠呼吸暂停低通气综合征，指导围手术期管理与并发症治疗。\n\n（检查清单）\n【必做】血清IGF-1（升高，用于筛查）、口服葡萄糖抑制试验（75g糖后GH不被抑制<1μg/L，可确诊活动）、垂体前叶激素全套、血糖HbA1c、心脏超声、肝肾功能；【影像】鞍区MRI增强（腺瘤，用于定位）、结肠镜（GH腺瘤患者结直肠腺瘤/癌风险高，应筛查）。","初步诊断":"1. 垂体生长激素腺瘤（巨人症/肢端肥大症）\n（注：手术首选，行经蝶窦垂体瘤切除；术后残留/不能手术者用生长抑素类似物（奥曲肽长效肌注每4周）或GH受体拮抗剂（培维索孟，降IGF-1）或多巴胺激动剂；放疗（残留/抵抗）；并发症管理（降压降糖、CPAP治呼吸暂停）；治疗目标随机GH<1μg/L、IGF-1正常；术后定期监测激素、影像、垂体功能；多学科协作（内分泌/神经外科）。）","处理方案":"【药物治疗】\n1. 生长抑素类似物（一线首选）：醋酸奥曲肽注射液0.1mg皮下注射，每日3次，两餐之间或睡前给药；或奥曲肽微球（长效剂型）20~30mg深部肌肉注射，每4周1次，根据GH/IGF-1水平调整剂量。\n2. 多巴胺受体激动剂（单用或与生长抑素类似物联用）：溴隐亭片1.25mg口服每日2次起始，餐中服用，渐增至2.5mg每日2~3次；或卡麦角林片0.5mg口服每周2次，根据耐受性及IGF-1调整。\n3. GH受体拮抗剂（对前两者疗效不佳者）：培维索孟注射液10mg皮下注射每日1次，每月按IGF-1水平调整剂量（每次增减5mg，单日最大剂量30mg）。\n\n【一般治疗及生活指导】\n1. 饮食：低盐、低脂、均衡营养，合并糖尿病者按低盐低脂饮食管理，控制总热量、限制精制糖和油脂，保证钙及维生素D摄入。\n2. 活动：以散步等温和活动为主，避免剧烈运动、负重及对抗性运动，防止关节损伤和跌倒；合并心功能受累者活动量以不引起心悸、气促为度。\n3. 监测：每日监测并记录血压、血糖；留意面部、手足、鞋帽尺寸是否继续增大，定期测量并记录身高、体重变化。\n4. 禁忌：戒烟限酒；合并睡眠呼吸暂停者避免仰卧位睡眠及睡前饮酒，必要时行睡眠呼吸监测；慎用含雌激素类药物。\n\n【随诊要求】\n每月复诊1次，复查血清GH、IGF-1、空腹及餐后血糖、糖化血红蛋白、肝肾功能；每3~6个月复查垂体MRI评估肿瘤大小；每6~12个月行视野及眼底检查、心电图、超声心动图，每年复查骨密度及骨关节X线。根据GH/IGF-1水平及不良反应调整药物剂量；若出现剧烈头痛、视力视野下降、肢端生长加速或月经紊乱等异常，及时就诊。"},"icd10_diagnosis":"","icd10_secondary":[],"icd9cm3_procedure":[]}},"locator":{"file":"门诊住院病历模板/病历模板包_全部_20261111.json","arrayRow":442,"caseRow":1},"sourceHash":"10e4fdb435986b7b85f847c3951d0cb0eafdce0f372c5617949c05b337149194","contentHash":"52bc6642c25568364d3d9300d7906c711cc2bc301a819fa06e4ec645cbff299d","pinyin":"jurenzheng","initials":"jrz","setting":"out","caseName":"门诊病历307","templateNames":["主诉","现病史","既往史","个人史及过敏史","体格检查","辅助检查","初步诊断","处理方案"],"emptyTemplates":[],"escapedNewlines":[],"quickFields":[["病例名称","门诊病历307",60],["模板名称","主诉 现病史 既往史 个人史及过敏史 体格检查 辅助检查 初步诊断 处理方案",30],["主要诊断编码","",30]]},{"id":"templates-38495c64cf2fe4d66ab4","key":"v1-c9ccc21dfe2a3058|templates-38495c64cf2fe4d66ab4","module":"templates","moduleKey":"v1-c9ccc21dfe2a3058|templates","version":"v1-c9ccc21dfe2a3058","title":"面肌痉挛","category":"门诊病历模板","raw":{"name":"面肌痉挛","category":"门诊病历模板","case":{"case_name":"门诊病历308","templates":{"主诉":"一侧眼睑及面部肌肉阵发性抽搐1年","现病史":"患者于6月前开始出现右侧眼睑（眼轮匝肌）不自主抽动，渐扩展至同侧面肌（口角面颊），精神紧张疲劳时加重、睡眠时消失，有无耳内杂音、听力下降（面神经受压，即Mime征）、面部麻木、口角歪斜（面瘫后联动，见于Bell麻痹后），有无颅内病变史：无。今日来我院门诊就诊。","既往史":"既往体健，否认高血压、糖尿病、冠心病等慢性病史。否认肝炎、结核等传染病史。否认手术外伤史。否认食物药物过敏史。预防接种史随社会。","个人史及过敏史":"生于原籍，久居本地，无疫区疫水接触史，无特殊粉尘毒物放射性物质接触史。不吸烟，不饮酒。生活规律。否认食物药物过敏史。","体格检查":"T36.5℃，P76次/分，R16次/分，BP122/78mmHg。患侧面肌阵挛性抽动（范围频率），示齿鼓腮时可见联动运动，面部感觉正常、闭眼有力、角膜反射存在，余神经系统无阳性体征。","辅助检查":"【影像】头颅MRI薄层高分辨（评估面神经出脑干区血管压迫，联合MRA），排除桥小脑角肿瘤、血管畸形（继发性面肌痉挛）；【其他】肌电图（面肌痉挛放电）。","初步诊断":"1. 面肌痉挛（原发（血管压迫）/继发）\n（注：药物治疗用于轻症（卡马西平200~400mg tid或奥卡西平、加巴喷丁，注意头晕嗜睡低钠）；A型肉毒毒素局部注射为一线（疗效维持3~6个月，重复注射，注意眼睑下垂复视）；微血管减压术（MVD，可根治，适用于血管压迫明确者，有面瘫听力减退风险，适合年轻或药物肉毒无效者）；继发性（桥小脑角肿瘤）手术切除原发病；治疗前MRI排除继发因素。）","处理方案":"【药物治疗】\n1. A型肉毒毒素局部注射（首选一线治疗）：保妥适或国产衡力，根据眼轮匝肌、口轮匝肌等痉挛肌群行多点局部注射，每次总量25~50U，注射后2~7天起效，疗效维持3~6个月，症状复发后可重复注射，两次注射间隔不少于3个月。\n2. 奥卡西平（症状轻微或不愿接受注射者）：起始150mg bid口服，3~5天后加量至300mg bid维持，疗程4~8周后评估疗效调整剂量，注意低钠血症及皮疹等不良反应。\n3. 卡马西平：起始0.1g bid口服，每3~5天递增至0.2g tid，每日总量不超过0.6g，用药期间监测血常规、肝肾功能，出现皮疹、眩晕、共济失调立即停药就诊。\n4. 甲钴胺0.5mg tid口服，疗程2~4周，作为神经营养辅助治疗。\n【一般治疗及生活指导】\n1. 保证充足睡眠，避免熬夜、精神紧张及过度疲劳，情绪波动可诱发或加重痉挛。\n2. 清淡饮食，忌辛辣刺激食物，避免浓茶、咖啡、酒精等兴奋性饮品。\n3. 避免强光刺激、冷风直吹面部及长时间注视屏幕；洗脸、刷牙动作轻柔，避免用力搓揉、按摩面部。\n4. 眼睑闭合不全者外出佩戴墨镜，注意保护角膜，必要时滴用人工泪液。\n【随诊要求】\n1. 接受肉毒毒素注射者：注射后2周复诊评估疗效，症状复发（约3~6个月）时复诊再次注射。\n2. 口服药物者：2周后复诊评估疗效及不良反应，定期复查血常规、肝肾功能、电解质。\n3. 建议完善头颅MRI排除桥小脑角区占位、血管压迫等继发性面肌痉挛；若出现面部肌肉无力、言语含糊、听力下降或痉挛范围扩大，立即就诊；内科治疗无效者转神经外科评估微血管减压术。"},"icd10_diagnosis":"","icd10_secondary":[],"icd9cm3_procedure":[]}},"locator":{"file":"门诊住院病历模板/病历模板包_全部_20261111.json","arrayRow":443,"caseRow":1},"sourceHash":"10e4fdb435986b7b85f847c3951d0cb0eafdce0f372c5617949c05b337149194","contentHash":"8b6edf2e68e267d33439313abc3eab704173483ce2b9647239b36f55df5a1d3b","pinyin":"mianjijingluan","initials":"mjjl","setting":"out","caseName":"门诊病历308","templateNames":["主诉","现病史","既往史","个人史及过敏史","体格检查","辅助检查","初步诊断","处理方案"],"emptyTemplates":[],"escapedNewlines":[],"quickFields":[["病例名称","门诊病历308",60],["模板名称","主诉 现病史 既往史 个人史及过敏史 体格检查 辅助检查 初步诊断 处理方案",30],["主要诊断编码","",30]]},{"id":"templates-b3b3d670093fd3fd7b18","key":"v1-c9ccc21dfe2a3058|templates-b3b3d670093fd3fd7b18","module":"templates","moduleKey":"v1-c9ccc21dfe2a3058|templates","version":"v1-c9ccc21dfe2a3058","title":"眼睑痉挛","category":"门诊病历模板","raw":{"name":"眼睑痉挛","category":"门诊病历模板","case":{"case_name":"门诊病历309","templates":{"主诉":"双眼频繁眨眼、痉挛性紧闭6月","现病史":"患者于6月前开始双眼频繁眨眼，渐发展为眼睑痉挛性紧闭（睁眼困难，视觉正常），晨轻午后及紧患者光时加重，注意力分散时减轻、睡眠消失，有无口下颌不自主运动（Meige综合征：张口闭口舌动）、眼干（干眼，继发刺激加重）、畏光：有眼干、畏光。有无抗精神病药史（迟发性运动障碍）：无。今日来我院门诊就诊。","既往史":"既往体健，否认高血压、糖尿病、冠心病等慢性病史。否认肝炎、结核等传染病史。否认手术外伤史。否认食物药物过敏史。预防接种史随社会。","个人史及过敏史":"生于原籍，久居本地，无疫区疫水接触史，无特殊粉尘毒物放射性物质接触史。不吸烟，不饮酒。生活规律。否认食物药物过敏史。","体格检查":"T36.7℃，P76次/分，R18次/分，BP120/78mmHg。观察安静及交谈时眼睑痉挛（能否自主睁开，注意分散时变化），口下颌不自主运动，结膜充血（干眼），面部感觉及闭眼肌力正常，无面瘫体征。","辅助检查":"【影像】头颅MRI（排除基底节/脑干病变）；【其他】眼科检查（干眼评估，泪液分泌试验）。","初步诊断":"1. 眼睑痉挛（伴口下颌肌张力障碍，考虑Meige综合征）\n（注：A型肉毒毒素眼轮匝肌注射为一线（缓解率高、维持3~4个月、重复注射）；口服药疗效有限（氯硝西泮、苯海索）；治疗干眼（人工泪液，减少刺激，重要辅助）；佩戴感光过滤镜（畏光）；难治性严重者脑深部电刺激（DBS）评估；排除并停用诱发药物（抗精神病药，迟发性）；神经科随访。）","处理方案":"【药物治疗】\n1. 首选A型肉毒毒素局部注射：注射用A型肉毒毒素（保妥适或衡力）2.5~5U/点，于眼轮匝肌睑部及眶部选4~6个注射点（如上睑中外1/3、下睑中外1/3、外眦部等），单眼总量10~30U，每次注射间隔3~6个月，疗效可维持3~6个月。\n2. 口服抗胆碱能药：盐酸苯海索片（安坦）1mg po tid起始，疗效不佳可渐增至2mg po tid，疗程4~8周评估疗效，注意口干、视物模糊等不良反应。\n3. 苯二氮䓬类：氯硝西泮片0.5mg po qn，睡眠差或痉挛明显者可用0.5~1mg po bid，减轻肌痉挛并改善睡眠，注意嗜睡、头晕，服药期间勿驾车。\n4. 备选：卡马西平片0.1g po bid起始，可渐增至0.2g po tid，用于对肉毒毒素反应不佳者，需监测血常规及肝功能。\n\n【一般治疗及生活指导】\n1. 避免精神紧张、焦虑及过度劳累，保证充足睡眠（每日7~8小时），可配合放松训练及心理疏导缓解痉挛诱因。\n2. 减少长时间用眼，避免强光、风沙及烟尘刺激，外出佩戴太阳镜遮光，减少不必要的频繁眨眼。\n3. 每日温水毛巾热敷眼周10~15分钟、每日2次，并轻柔按摩眼睑，促进眼轮匝肌放松。\n4. 忌饮浓茶、咖啡、酒精等刺激性饮品，避免接触二手烟，减少痉挛诱发因素。\n\n【随诊要求】\n1. 肉毒毒素注射后2周复诊，评估痉挛改善程度及有无眼睑下垂、复视、局部瘀斑等不良反应。\n2. 疗效维持约3~6个月，症状明显复发时可再次注射，两次注射间隔不应短于3个月。\n3. 口服药物治疗者每4~8周复诊1次，评估疗效及嗜睡、口干、共济失调等不良反应，定期复查血常规、肝肾功能；若出现视物模糊、眼睑下垂、吞咽困难等异常，及时就诊。"},"icd10_diagnosis":"","icd10_secondary":[],"icd9cm3_procedure":[]}},"locator":{"file":"门诊住院病历模板/病历模板包_全部_20261111.json","arrayRow":444,"caseRow":1},"sourceHash":"10e4fdb435986b7b85f847c3951d0cb0eafdce0f372c5617949c05b337149194","contentHash":"3addc2efb0e00e541f3035080184f7cb04324e822479bc5b8c0ae86ac57ec19a","pinyin":"yanjianjingluan","initials":"yjjl","setting":"out","caseName":"门诊病历309","templateNames":["主诉","现病史","既往史","个人史及过敏史","体格检查","辅助检查","初步诊断","处理方案"],"emptyTemplates":[],"escapedNewlines":[],"quickFields":[["病例名称","门诊病历309",60],["模板名称","主诉 现病史 既往史 个人史及过敏史 体格检查 辅助检查 初步诊断 处理方案",30],["主要诊断编码","",30]]},{"id":"templates-458742d4780c9dd2c977","key":"v1-c9ccc21dfe2a3058|templates-458742d4780c9dd2c977","module":"templates","moduleKey":"v1-c9ccc21dfe2a3058|templates","version":"v1-c9ccc21dfe2a3058","title":"痉挛性斜颈","category":"门诊病历模板","raw":{"name":"痉挛性斜颈","category":"门诊病历模板","case":{"case_name":"门诊病历310","templates":{"主诉":"颈部肌肉不自主收缩致头颈扭转1年","现病史":"患者于1年前开始颈部肌肉不自主痉挛，头颈向左侧扭转、倾斜，晨轻、紧张疲劳加重、轻触面部可暂时矫正（感觉诡计）、睡眠平卧减轻，伴颈肩酸痛，有无吞咽困难、手部震颤、构音障碍，有无抗精神病药史（迟发性）、围产期缺氧史及家族史：均无。今日来我院门诊就诊。","既往史":"既往体健，否认高血压、糖尿病、冠心病等慢性病史。否认肝炎、结核等传染病史。否认手术外伤史。否认食物药物过敏史。预防接种史随社会。","个人史及过敏史":"生于原籍，久居本地，无疫区疫水接触史，无特殊粉尘毒物放射性物质接触史。不吸烟，不饮酒。生活规律。否认食物药物过敏史。","体格检查":"T____℃，P____次/分，R____次/分，BP____/____mmHg。头颈姿势异常（扭转方向及代偿：耸肩脊柱侧弯），受累肌（胸锁乳突肌/斜方肌等）痉挛肥大，感觉诡计试验阳性，四肢肌力腱反射正常、无病理征。","辅助检查":"【影像】头颅及颈髓MRI（排除基底节脑干病变、Arnold-Chiari畸形、颈髓病变）、颈椎X线（骨性斜颈/代偿改变）；【其他】Wilson病筛查（年轻患者，角膜K-F环、铜蓝蛋白）。","初步诊断":"1. 痉挛性斜颈\n（注：A型肉毒毒素肌电/超声引导注射痉挛肌群为一线（维持3~4个月，注意吞咽困难，避免双侧胸锁乳突肌同时大量注射）；口服药疗效有限（苯海索、氯硝西泮、巴氯芬）；难治严重者脑深部电刺激（DBS，GPi）评估；排除继发因素（药物、Wilson病、脑干病变）；运动障碍专科随访管理。）","处理方案":"【药物治疗】\n1.A型肉毒毒素局部注射（首选治疗方案）：注射用A型肉毒毒素（保妥适或衡力）100~300U，根据受累肌群（胸锁乳突肌、头夹肌、斜方肌、肩胛提肌等）行多点肌内注射，单次总量≤300U，每3~4个月重复注射1次；注射后2~3周起效，疗效维持3~4个月。\n2.盐酸苯海索片（安坦）1~2mg，口服，每日3次；出现口干、视物模糊、便秘等抗胆碱能副作用时减量或停用。\n3.氯硝西泮片0.5~1mg，口服，每晚1次（或每日2次），从小剂量开始，注意嗜睡、头晕等副作用，服药期间避免驾车及高空作业。\n4.巴氯芬片5mg，口服，每日3次起始，每3~5天递增5mg，逐步加至有效量（最大不超过60mg/日），停药须缓慢减量以防戒断反应。\n\n【一般治疗及生活指导】\n1.注意颈部保暖，避免空调、风扇直吹及受凉；避免长时间低头伏案及不良头颈姿势，工作间隙做颈肩部放松活动。\n2.症状明显时可佩戴软颈托限制异常头位，避免颈部剧烈扭转、甩头等动作，防止继发颈肌劳损及颈椎损伤。\n3.保持情绪稳定，避免精神紧张、焦虑及过度劳累，保证充足睡眠；可配合局部温热敷、手法放松及生物反馈等物理康复治疗。\n4.因头颈偏斜可影响视野和平衡，驾车、骑行及过马路时注意安全，避免从事高处作业等危险操作。\n\n【随诊要求】\n1.口服药物调整剂量者2周内复诊，评估疗效及不良反应；肉毒毒素注射后2~4周复诊评估起效情况及副作用。\n2.每3~4个月定期复诊1次，评估症状控制与复发情况，决定是否重复注射肉毒毒素。\n3.出现吞咽困难、饮水呛咳、声音嘶哑、呼吸困难等不良反应时立即就诊；颈痛加重或出现上肢麻木、无力时及时复诊。"},"icd10_diagnosis":"","icd10_secondary":[],"icd9cm3_procedure":[]}},"locator":{"file":"门诊住院病历模板/病历模板包_全部_20261111.json","arrayRow":445,"caseRow":1},"sourceHash":"10e4fdb435986b7b85f847c3951d0cb0eafdce0f372c5617949c05b337149194","contentHash":"fd5d34bcfbdd6835f3ccdc7b03328b5f8cb208d05db6db3203a8243001fc360a","pinyin":"jingluanxingxiejing","initials":"jlxxj","setting":"out","caseName":"门诊病历310","templateNames":["主诉","现病史","既往史","个人史及过敏史","体格检查","辅助检查","初步诊断","处理方案"],"emptyTemplates":[],"escapedNewlines":[],"quickFields":[["病例名称","门诊病历310",60],["模板名称","主诉 现病史 既往史 个人史及过敏史 体格检查 辅助检查 初步诊断 处理方案",30],["主要诊断编码","",30]]},{"id":"templates-d51bc2b2851975a4e4a9","key":"v1-c9ccc21dfe2a3058|templates-d51bc2b2851975a4e4a9","module":"templates","moduleKey":"v1-c9ccc21dfe2a3058|templates","version":"v1-c9ccc21dfe2a3058","title":"不安腿综合征","category":"门诊病历模板","raw":{"name":"不安腿综合征","category":"门诊病历模板","case":{"case_name":"门诊病历311","templates":{"主诉":"静息及夜间双下肢不适、活动后缓解6月","现病史":"患者于6月前出现静息时（尤其夜间卧床）双下肢难以忍受不适（蚁走感、酸胀、牵拉），需活动下肢或行走缓解，夜间加重致入睡困难、睡眠中断，白天嗜睡，有无睡眠中周期性踢腿（同床者观察）、日间打盹亦出现，有无缺铁性贫血、妊娠、尿毒症透析、糖尿病周围神经病、帕金森病、使用抗抑郁药或抗组胺药、咖啡因摄入及家族史：均无。今日来我院门诊就诊。","既往史":"既往体健，否认高血压、糖尿病、冠心病等慢性病史。否认肝炎、结核等传染病史。否认手术外伤史。否认食物药物过敏史。预防接种史随社会。","个人史及过敏史":"生于原籍，久居本地，无疫区疫水接触史，无特殊粉尘毒物放射性物质接触史。不吸烟，不饮酒。生活规律。否认食物药物过敏史。","体格检查":"T36.6℃，P78次/分，R18次/分，BP118/76mmHg。神经系统查体（双下肢感觉肌力腱反射正常，排除周围神经病），足背动脉搏动正常。","辅助检查":"【必做】血清铁蛋白（<50~75μg/L为补铁指征，核心筛查）、血常规、肾功能、血糖、维生素B12、叶酸、甲状腺功能；【睡眠】多导睡眠监测（PLMS周期性肢动指数评估，睡眠障碍明显时）。","初步诊断":"1. 不安腿综合征（继发，缺铁/尿毒症/妊娠/药物）\n（注：非药物（轻症）：规律作息、睡前适度活动温水浴按摩、避免咖啡因酒精、停用诱发药（SSRI换安非他酮）；铁蛋白<50μg/L者补铁（硫酸亚铁口服，复查铁蛋白）；中重度药物治疗：α2δ配体（加巴喷丁恩那卡比或普瑞巴林睡前，一线，无加重现象）或多巴胺能（普拉克索0.125~0.25mg睡前，起效快但长期可致症状加重，谨慎）；避免甲氧氯普胺等多巴胺拮抗剂；治疗原发病（尿毒症优化透析、纠正贫血）；随访症状量表（IRLS）评估，睡眠/神经专科管理。）","处理方案":"【药物治疗】\n1. 首选α2δ钙通道配体：普瑞巴林胶囊75mg qn（睡前1小时口服），症状控制欠佳者可每3～5天加量至150mg qn，最大剂量300mg/d；或加巴喷丁胶囊300mg qn，可渐增至900mg/d，分2～3次（下午及睡前各1次），疗程4～8周后评估疗效（该类药物为首选，因多巴胺能药物易引起症状加重现象）\n2. 备选多巴胺受体激动剂（一线药物不耐受或效果不佳时选用）：普拉克索片0.125mg qn（睡前2小时口服），每3～5天递增0.125mg，一般不超过0.5mg/d，小剂量起始，疗程4周评估；注意监测是否出现\"症状加重现象\"（症状提前出现、范围扩大、加重）\n3. 若血清铁蛋白<75μg/L或转铁蛋白饱和度<20%：琥珀酸亚铁片0.1g bid，餐后口服，疗程3个月后复查铁代谢指标，达标后停用\n\n【一般治疗及生活指导】\n1. 睡前温水泡脚、小腿按摩或适度牵伸活动，避免久坐久站及睡前剧烈运动；保持规律作息与良好睡眠卫生（固定就寝时间、卧室安静避光）\n2. 午后及晚间避免咖啡、浓茶、可乐等含咖啡因饮品，戒烟、限酒；避免受凉刺激下肢\n3. 排查并停用可诱发或加重症状的药物：抗组胺药（如苯海拉明、氯苯那敏）、选择性5-羟色胺再摄取抑制剂（SSRI）/5-羟色胺去甲肾上腺素再摄取抑制剂（SNRI）、甲氧氯普胺、抗精神病药等\n4. 排查继发因素并予以纠正：缺铁性贫血、糖尿病周围神经病、慢性肾衰竭（注意透析期症状）、妊娠、甲状腺功能异常、帕金森病等，合并者应同步治疗原发病\n\n【随诊要求】\n用药后2～4周复诊，评估症状改善程度（可采用国际不安腿综合征评定量表IRLS评分）及药物不良反应（头晕、嗜睡、水肿等）；每3～6个月复查血常规、血清铁蛋白、肾功能及电解质；如出现症状较用药前提前出现、范围扩大或药物需不断加量，提示可能发生\"症状加重现象\"，应及时就诊调整方案；症状稳定控制后遵医嘱缓慢减量，不可擅自停药或骤停。"},"icd10_diagnosis":"","icd10_secondary":[],"icd9cm3_procedure":[]}},"locator":{"file":"门诊住院病历模板/病历模板包_全部_20261111.json","arrayRow":446,"caseRow":1},"sourceHash":"10e4fdb435986b7b85f847c3951d0cb0eafdce0f372c5617949c05b337149194","contentHash":"0d32070c104d5c9e2134cd1dbfd665b5aa5f896e078d58b8a3763ae758261b58","pinyin":"buantuizonghezheng","initials":"batzhz","setting":"out","caseName":"门诊病历311","templateNames":["主诉","现病史","既往史","个人史及过敏史","体格检查","辅助检查","初步诊断","处理方案"],"emptyTemplates":[],"escapedNewlines":[],"quickFields":[["病例名称","门诊病历311",60],["模板名称","主诉 现病史 既往史 个人史及过敏史 体格检查 辅助检查 初步诊断 处理方案",30],["主要诊断编码","",30]]},{"id":"templates-6e6b2cab7c8f46684aff","key":"v1-c9ccc21dfe2a3058|templates-6e6b2cab7c8f46684aff","module":"templates","moduleKey":"v1-c9ccc21dfe2a3058|templates","version":"v1-c9ccc21dfe2a3058","title":"发作性睡病","category":"门诊病历模板","raw":{"name":"发作性睡病","category":"门诊病历模板","case":{"case_name":"门诊病历312","templates":{"主诉":"白天嗜睡伴猝倒、睡前幻觉1年","现病史":"患者于1年前开始白天不可抗拒的困倦嗜睡（上课/开会/驾车/进食时突入眠，睡眠发作），睡眠后短暂精神恢复，有无猝倒（大笑/激动时突发肌张力丧失，垂头、膝软、跌倒，意识清楚）、入睡前幻觉（将入睡时生动梦境样幻觉，视/听/触）、睡眠瘫痪（醒后短暂不能动不能说，数秒至数分钟）、夜间睡眠紊乱（多醒多梦）：有猝倒、入睡前幻觉。有无家族史：无。今日来我院门诊就诊。","既往史":"既往体健，否认高血压、糖尿病、冠心病等慢性病史。否认肝炎、结核等传染病史。否认手术外伤史。否认食物药物过敏史。预防接种史随社会。","个人史及过敏史":"生于原籍，久居本地，无疫区疫水接触史，无特殊粉尘毒物放射性物质接触史。不吸烟，不饮酒。生活规律。否认食物药物过敏史。","体格检查":"T36.5℃，P72次/分，R18次/分，BP116/74mmHg。神志清楚，查体合作（就诊时可现困倦）。神经系统检查无阳性体征（排除发作性睡病以外的嗜睡病因，癫痫、颅内占位等）。","辅助检查":"【必做】多导睡眠监测（PSG，排除阻塞性睡眠呼吸暂停等其他嗜睡病因）及多次小睡潜伏期试验（MSLT，平均入睡潜伏期<8分钟且出现≥2次快速眼动期起始睡眠，诊断依据）；【其他】脑脊液下丘脑泌素（orexin）测定（1型发作性睡病降低，确诊）、HLA-DQB1*06:02检测（辅助）、Epworth嗜睡量表。","初步诊断":"1. 发作性睡病（1型：伴猝倒/orexin降低）\n（注：非药物：规律睡眠（定时小睡每日2~3次每次15~20分钟）、避免驾驶及危险作业（嗜睡发作时）、心理支持；药物治疗：白天嗜睡，莫达非尼200~400mg qd（一线）或哌甲酯（二线）、新型药物（索利氨酯，orexin受体激动剂）；猝倒，文拉法辛/氯米帕明（REM抑制）或羟丁酸钠（γ-羟丁酸，夜间给药，改善夜间睡眠及猝倒）；注意药物不良反应及依赖；睡眠专科随访，评估驾驶安全（法律要求，嗜睡发作控制前限制驾驶）。）","处理方案":"【药物治疗】\n1. 中枢兴奋剂（日间过度嗜睡）：莫达非尼片200mg qd（晨起空腹或餐后服），效果欠佳时午后12时前可加服100mg，长期维持；亦可选用哌甲酯缓释片18mg qd晨服，最大可增至54mg/d，分次服用。\n2. 猝倒控制（REM睡眠抑制，抗抑郁药）：文拉法辛缓释胶囊75mg qd（晨服），效果不理想可增至150mg qd；或氟西汀胶囊20mg qd晨服，疗程长期维持，停药需缓慢减量以防猝倒反跳。\n3. 难治性病例（专科处方）：羟丁酸钠口服液首夜2.25g，睡前及醒后2.5-4小时各服一半，此后每2周递增1.5g/d至9g/d（最大单次4.5g），需在睡眠专科医师指导下按麻醉药品管理规定开具并登记；或替洛利生片（若可及）17.8mg qd晨服，最大34.6mg/d。\n\n【一般治疗及生活指导】\n1. 规律作息：固定就寝与起床时间，保证夜间睡眠7-8小时；午后安排1-2次定时短睡（每次15-20分钟），可显著缓解日间嗜睡并减少意外。\n2. 安全防护：日间嗜睡及猝倒发作未完全控制期间，禁止驾驶、高空及危险机械作业、涉水游泳；必要时乘坐公共交通工具或由他人陪同出行。\n3. 饮食禁忌：避免高糖高碳水餐（加重餐后嗜睡）、酒精及含咖啡因饮料（尤其晚间），忌用苯二氮䓬类等镇静催眠药；清淡均衡饮食，适当日间活动。\n4. 情绪与心理：避免大笑、情绪激动、愤怒等诱发猝倒的强烈情绪刺激；正确认识疾病，必要时心理疏导，避免自暴自弃及抑郁焦虑加重病情。\n\n【随诊要求】\n1. 每1-3个月专科复诊，评估Epworth嗜睡量表（ESS）评分及猝倒发作频率，据此调整莫达非尼或文拉法辛剂量。\n2. 用药期间定期监测血压、心率；服用文拉法辛者监测情绪及睡眠质量变化，出现抑郁加重、自杀观念或5-羟色胺综合征表现（烦躁、震颤、出汗、腹泻）立即复诊。\n3. 长期服药者每3-6个月复查血常规、肝肾功能；育龄期女性需咨询药物妊娠安全性，服药期间避免计划外妊娠。\n4. 出现夜间睡眠瘫痪、入睡前幻觉明显加重，或猝倒频繁致跌倒受伤、日间嗜睡影响正常工作生活时，及时提前复诊；不得自行停药或增减剂量。"},"icd10_diagnosis":"","icd10_secondary":[],"icd9cm3_procedure":[]}},"locator":{"file":"门诊住院病历模板/病历模板包_全部_20261111.json","arrayRow":447,"caseRow":1},"sourceHash":"10e4fdb435986b7b85f847c3951d0cb0eafdce0f372c5617949c05b337149194","contentHash":"21af9f11d7f0dbd198e964386ca70500e17ab5fc72617ca0047c5f24140e0b05","pinyin":"fazuoxingshuibing","initials":"fzxsb","setting":"out","caseName":"门诊病历312","templateNames":["主诉","现病史","既往史","个人史及过敏史","体格检查","辅助检查","初步诊断","处理方案"],"emptyTemplates":[],"escapedNewlines":[],"quickFields":[["病例名称","门诊病历312",60],["模板名称","主诉 现病史 既往史 个人史及过敏史 体格检查 辅助检查 初步诊断 处理方案",30],["主要诊断编码","",30]]},{"id":"templates-874b08d73708f644f3b0","key":"v1-c9ccc21dfe2a3058|templates-874b08d73708f644f3b0","module":"templates","moduleKey":"v1-c9ccc21dfe2a3058|templates","version":"v1-c9ccc21dfe2a3058","title":"睡眠呼吸暂停综合征","category":"门诊病历模板","raw":{"name":"睡眠呼吸暂停综合征","category":"门诊病历模板","case":{"case_name":"门诊病历313","templates":{"主诉":"夜间打鼾伴呼吸暂停、白天嗜睡1年","现病史":"患者（多为中年肥胖男性）于3年前开始夜间响亮打鼾（家人述鼾声如雷、间歇性暂停，呼吸暂停后呛醒），晨起口干头痛、白天嗜睡（开车/开会犯困）、乏力、注意力记忆力减退、易怒，有无夜尿增多、性功能减退、晨起血压升高（难治性高血压，OSA重要表现）、心慌胸闷（心律失常）、反酸：有夜尿增多、晨起血压升高。有无肥胖（BMI）、颈围增粗、扁桃体肥大/下颌后缩、饮酒（睡前加重）及高血压糖尿病史：有肥胖、颈围增粗、高血压史。今日来我院门诊就诊。","既往史":"既往体健，否认高血压、糖尿病、冠心病等慢性病史。否认肝炎、结核等传染病史。否认手术外伤史。否认食物药物过敏史。预防接种史随社会。","个人史及过敏史":"生于原籍，久居本地，无疫区疫水接触史，无特殊粉尘毒物放射性物质接触史。不吸烟，不饮酒。生活规律。否认食物药物过敏史。","体格检查":"T36.5℃，P80次/分，R18次/分，BP145/90mmHg（可高），BMI30kg/m²，颈围42cm。神志清楚，嗜睡面容。鼻腔通畅（通畅/狭窄），咽腔狭窄（扁桃体肥大、软腭低垂、舌体肥大），下颌后缩（后缩），心肺听诊未闻及明显异常。","辅助检查":"【必做】多导睡眠监测（PSG，呼吸暂停低通气指数AHI≥5次/小时且伴症状或≥15，诊断及分级（轻5~15/中15~30/重>30），金标准）、夜间血氧监测（氧减饱和度指数）；【评估】Epworth嗜睡量表、血压血糖血脂（代谢综合征共病，OSA相关心血管风险）、心电图（心律失常）、超声心动图（肺动脉高压右心改变，重症长期）；【耳鼻喉/口腔】上气道评估（内镜，阻塞平面）。","初步诊断":"1. 阻塞性睡眠呼吸暂停低通气综合征（重度，AHI34）\n（注：①生活方式（基础，所有患者）：减重（最重要，显著改善）、侧卧睡眠、戒烟酒（尤其睡前）、避免镇静药；②持续气道正压通气（CPAP，中重度首选治疗，每晚使用，显著改善嗜睡及心血管预后，依从性是关键，随访调压）；③口腔矫治器（轻中度、下颌后缩者，舌托/下颌前移器）；④耳鼻喉手术（明确上气道阻塞部位，扁桃体切除/腭咽成形，选择病例）；⑤治疗共病（高血压糖尿病，CPAP改善后药物可减量）；⑥重度伴日间低氧或心肺并发症，评估无创通气/氧疗；睡眠专科及多学科随访，评估驾驶安全。）","处理方案":"【药物治疗】\n1. 莫达非尼片（促醒药）：100mg qd晨起口服，可增至200mg qd，用于无创通气（CPAP）治疗纠正呼吸事件后仍存在残留日间过度嗜睡者，疗程2~4周后评估疗效调整。\n2. 布地奈德鼻喷雾剂（鼻用糖皮质激素）：64μg/喷，每侧鼻孔各1~2喷，bid，疗程2~4周，用于合并慢性鼻炎、鼻甲肥大所致鼻塞者，改善上气道通畅度。\n3. 司美格鲁肽注射液（GLP-1受体激动剂，减重适应证）：0.25mg ih qw起始，4周后增至0.5mg qw维持（可渐增至1.0mg qw），用于BMI≥27kg/m²合并肥胖的OSAHS患者辅助减重，治疗期间监测血糖、胃肠反应及胰腺炎相关症状。\n【一般治疗及生活指导】\n1. 体位训练：坚持侧卧位睡眠，避免仰卧位，可用睡衣背后缝置网球等方法强制保持侧卧。\n2. 减重管理：控制总热量、低脂低糖饮食，规律有氧运动（快走、游泳等，每周≥150分钟），目标减轻体重≥10%（可降低AHI约30%~50%）。\n3. 戒烟限酒：睡前4~6小时避免饮酒，禁用镇静催眠药（如苯二氮䓬类）、肌松药及阿片类镇痛药，以免加重呼吸抑制。\n4. 作息与安全：保持规律作息、保证充足睡眠，避免熬夜及日间过度疲劳；日间嗜睡明显者在充分有效治疗前避免驾驶、高空作业及精密操作。\n【随诊要求】\n1. 开始治疗（CPAP、口腔矫治器或药物）后2周~1个月复诊，评估依从性、症状改善及不良反应。\n2. 治疗稳定后每3~6个月门诊复诊，复查多导睡眠监测（PSG）或家庭睡眠呼吸暂停监测，评估AHI及最低血氧饱和度变化。\n3. 每年至少复查1次PSG评估病情进展；减重者每3个月监测体重、BMI及血压、血糖、血脂。\n4. 合并高血压、冠心病、心律失常者需同步监测血压、心率并调整相关用药；出现夜间窒息憋醒加重、胸痛、心悸、白天嗜睡明显影响工作驾驶时，随时就诊或急诊处理。"},"icd10_diagnosis":"","icd10_secondary":[],"icd9cm3_procedure":[]}},"locator":{"file":"门诊住院病历模板/病历模板包_全部_20261111.json","arrayRow":448,"caseRow":1},"sourceHash":"10e4fdb435986b7b85f847c3951d0cb0eafdce0f372c5617949c05b337149194","contentHash":"0f9f9ee1b7400120e0fd472e98672cf940e392517b596f0ab2cc10bd07416256","pinyin":"shuimianhuxizantingzonghezheng","initials":"smhxztzhz","setting":"out","caseName":"门诊病历313","templateNames":["主诉","现病史","既往史","个人史及过敏史","体格检查","辅助检查","初步诊断","处理方案"],"emptyTemplates":[],"escapedNewlines":[],"quickFields":[["病例名称","门诊病历313",60],["模板名称","主诉 现病史 既往史 个人史及过敏史 体格检查 辅助检查 初步诊断 处理方案",30],["主要诊断编码","",30]]},{"id":"templates-c3978528ebeec37105d7","key":"v1-c9ccc21dfe2a3058|templates-c3978528ebeec37105d7","module":"templates","moduleKey":"v1-c9ccc21dfe2a3058|templates","version":"v1-c9ccc21dfe2a3058","title":"丛集性头痛","category":"门诊病历模板","raw":{"name":"丛集性头痛","category":"门诊病历模板","case":{"case_name":"门诊病历314","templates":{"主诉":"单侧眼眶剧烈疼痛反复发作2周","现病史":"患者于2周前开始出现丛集期发作（每年固定季节，春秋多见，持续数周至数月，每日定时发作1~8次，多在夜间固定时间痛醒），每次发作单侧眼眶周围（单侧眼眶周围/颞部）剧烈疼痛（刀割样/烧灼样/钻痛，程度极重，坐立不安、来回踱步），持续60分钟（15~180分钟），伴同侧流泪（流泪、结膜充血、鼻塞流涕、眼睑水肿、面部出汗、瞳孔缩小/眼睑下垂，自主神经症状，特征性），发作间期完全缓解，丛集期内饮酒/硝酸甘油可诱发。有无丛集性头痛/偏头痛家族史及吸烟饮酒史：无家族史，有吸烟史。今日来我院门诊就诊。","既往史":"既往体健，否认高血压、糖尿病、冠心病等慢性病史。否认肝炎、结核等传染病史。否认手术外伤史。否认食物药物过敏史。预防接种史随社会。","个人史及过敏史":"生于原籍，久居本地，无疫区疫水接触史，无特殊粉尘毒物放射性物质接触史。不吸烟，不饮酒。生活规律。否认食物药物过敏史。","体格检查":"T36.6℃，P78次/分，R18次/分，BP125/80mmHg。发作期间可见同侧流泪（同侧流泪、结膜充血、Horner征（轻），眼睑下垂瞳孔缩小），发作间期神经系统检查无阳性体征。","辅助检查":"【影像】头颅MRI或MRA（排除继发性丛集样头痛，垂体病变、颈内动脉瘤/夹层、动静脉畸形，首次发作/症状不典型/持续不缓解者必查）；【其他】一般无需特殊化验。","初步诊断":"1. 丛集性头痛（发作性）\n（注：急性发作治疗（快速终止）：高流量纯氧吸入（100%O2 7~15L/min×15分钟，有效且安全）、皮下/鼻喷舒马普坦（6mg皮下或20mg鼻喷，丛集性头痛最有效药物，禁忌冠心病）；过渡期（丛集期预防，泼尼松40~60mg/d×2~3周渐减，快速起效桥接）、维拉帕米240~480mg/d（丛集期预防一线，需心电图监测房室传导）或锂盐（慢性型）；避免丛集期饮酒及硝酸甘油；手术（难治性慢性，蝶腭神经节刺激/深部脑刺激，专科评估）；发作时安全（避免驾驶，剧痛影响）；神经科头痛专科管理。）","处理方案":"【药物治疗】\n1. 急性发作期：舒马普坦注射液6mg皮下注射（首选），单次最大剂量6mg，24小时内不超过12mg（分次使用，间隔≥1小时）；或佐米曲普坦鼻喷剂5mg喷鼻1次，24小时内不超过10mg。发作时可同时予面罩纯氧吸入10-15L/min×15分钟（无禁忌症者氧疗为一线非药物措施）。\n2. 过渡期预防（丛集期短期桥接）：醋酸泼尼松片60mg qd口服，连用3-5天后每3天减10mg，2周内减停（须排除高血压、糖尿病、消化性溃疡等禁忌）。\n3. 长期预防性治疗（首选）：盐酸维拉帕米缓释片80mg tid口服起始，每1-2周加量80mg/日，维持240-480mg/日，丛集期结束2周后逐渐减停；用药期间监测心电图及血压，警惕房室传导阻滞、低血压及便秘。\n\n【一般治疗及生活指导】\n1. 丛集期保证规律作息、避免熬夜与过度劳累，保持情绪平稳，避免精神紧张诱发发作。\n2. 丛集期内严格戒烟、戒酒，避免接触硝酸甘油类扩血管药物（酒精、硝酸甘油均可明确诱发发作）。\n3. 发作时于安静、避光房间休息，可冷敷或热敷前额、颞部辅助止痛，避免剧烈运动及长时间低头伏案。\n4. 记录头痛日记（发作时间、频率、持续时间、诱因），供复诊评估预防方案疗效。\n\n【随诊要求】\n1. 急性发作控制不佳或每日发作≥2次者，3-5日内复诊调整急性期及预防方案。\n2. 服用维拉帕米期间每2-4周复诊，复查心电图、血压及肝肾功能，评估疗效与不良反应，根据发作缓解情况调整减停时机。\n3. 头痛性质改变、出现新发神经系统症状（如复视、肢体无力）、或疑为继发性头痛者，立即就诊。"},"icd10_diagnosis":"","icd10_secondary":[],"icd9cm3_procedure":[]}},"locator":{"file":"门诊住院病历模板/病历模板包_全部_20261111.json","arrayRow":449,"caseRow":1},"sourceHash":"10e4fdb435986b7b85f847c3951d0cb0eafdce0f372c5617949c05b337149194","contentHash":"245c0ad4c50a963975c4b59a680729d4efe6886bcc182de106df361ac82c60d3","pinyin":"congjixingtoutong","initials":"cjxtt","setting":"out","caseName":"门诊病历314","templateNames":["主诉","现病史","既往史","个人史及过敏史","体格检查","辅助检查","初步诊断","处理方案"],"emptyTemplates":[],"escapedNewlines":[],"quickFields":[["病例名称","门诊病历314",60],["模板名称","主诉 现病史 既往史 个人史及过敏史 体格检查 辅助检查 初步诊断 处理方案",30],["主要诊断编码","",30]]},{"id":"templates-7e87260591bd0c8fd11f","key":"v1-c9ccc21dfe2a3058|templates-7e87260591bd0c8fd11f","module":"templates","moduleKey":"v1-c9ccc21dfe2a3058|templates","version":"v1-c9ccc21dfe2a3058","title":"低颅压头痛","category":"门诊病历模板","raw":{"name":"低颅压头痛","category":"门诊病历模板","case":{"case_name":"门诊病历315","templates":{"主诉":"站立加重、平卧缓解的头痛1周","现病史":"患者于10天前出现头痛，特征为站立或坐起后15分钟内出现并加重（枕部/全头钝痛或胀痛），平卧后缓解或消失，伴恶心呕吐（恶心呕吐、颈部僵硬、耳鸣听力下降、视物模糊/复视（外展神经麻痹）、畏光），有无腰椎穿刺/硬膜外麻醉/脊髓手术史（继发脑脊液漏）、头部外伤及剧烈运动、慢性咳嗽用力（自发脑脊液漏）：无。有无体位性头痛发作史：无。今日来我院门诊就诊。","既往史":"既往体健，否认高血压、糖尿病、冠心病等慢性病史。否认肝炎、结核等传染病史。否认手术外伤史。否认食物药物过敏史。预防接种史随社会。","个人史及过敏史":"生于原籍，久居本地，无疫区疫水接触史，无特殊粉尘毒物放射性物质接触史。不吸烟，不饮酒。生活规律。否认食物药物过敏史。","体格检查":"T36.6℃，P76次/分，R18次/分，BP115/75mmHg。神志清楚，查体合作。卧位与立位对比，立位诱发头痛，颈抵抗（+），神经系统检查（复视，外展神经受累，颅神经检查），眼底正常（正常/视乳头水肿（少见，静脉淤血））。","辅助检查":"【影像】头颅MRI增强（弥漫性硬脑膜强化，特征性改变，最重要影像发现）、头颅MRI（脑下垂（小脑扁桃体下移）、硬膜下积液/出血）、脊髓MRI（自发脑脊液漏，寻找漏口，必要时脊髓造影/放射性核素脑池造影定位）；【腰穿】测压（开放压<60mmH2O，低颅压确诊，谨慎，加重漏）；【其他】常规化验排除感染等。","初步诊断":"1. 低颅压性头痛（继发性（腰穿后等））\n（注：①保守治疗（轻症，自限，尤其腰穿后）：绝对卧床平卧（去枕）、充分补液（每天2000~3000ml）、咖啡因（口服300mg bid或静注，收缩脑血管，缓解症状）、避免用力咳嗽排便；②硬膜外自体血补片（EBP，保守1~2周无效或症状重，注射自体血15~20ml封堵漏口，疗效好，可重复）；③自发性脑脊液漏，寻找并修补漏口（手术/介入）；④预防：腰穿用细针、术后平卧；⑤随访头痛缓解情况，持续不缓解复查影像，排除其他颅内病变（占位/静脉窦血栓，体位性头痛亦可见）。）","处理方案":"【药物治疗】\n1. 苯甲酸钠咖啡因注射液0.5g加入5%葡萄糖注射液500ml中静脉滴注，每日1次，连续3～5天；不能静脉用药者改口服咖啡因片0.2g，每日2次。\n2. 对乙酰氨基酚片0.5g，头痛时口服，必要时6小时1次，每日不超过4次（日总量≤2g）；或布洛芬缓释胶囊0.3g，每日2次，餐后服用，按需使用不超过5天。\n3. 茶碱缓释片0.1g，每日2次，连用7天（通过收缩脑血管、升高颅内压缓解症状，心功能不全及心律失常者慎用）。\n\n【一般治疗及生活指导】\n1. 绝对卧床休息：去枕平卧或头低足高位，尽量减少坐立与行走，卧床至少1～2周，待直立位头痛明显缓解后再缓慢、分次逐步起床，避免突然坐起。\n2. 充分补液：每日饮水量2000～3000ml，可配合口服补液盐，保持尿量≥1500ml/日，以促进脑脊液生成与循环恢复。\n3. 避免一切诱发颅内压波动、加重脑脊液漏的动作：用力咳嗽、打喷嚏、屏气、用力排便、弯腰、提重物及剧烈运动；保持大便通畅，可预防性服用乳果糖口服液15ml，每日1次。\n4. 饮食宜高蛋白、高维生素、易消化，少量多餐，保证营养支持，忌烟酒及浓茶过量饮用。\n\n【随诊要求】\n1. 治疗3～5天后复诊评估头痛缓解情况；症状缓解可逐步下床活动，若直立位头痛复发，应继续卧床并及时复诊。\n2. 2周内复查头颅MRI（含增强扫描）及脊髓MRI，明确有无脑脊液漏及漏口位置。\n3. 经卧床、补液及药物治疗2周无效或症状反复加重者，建议转神经内科住院行硬膜外自体血补片（EBP）修补治疗；若出现头痛骤然加重、喷射性呕吐、意识障碍或耳鼻流液等，立即急诊就诊。"},"icd10_diagnosis":"","icd10_secondary":[],"icd9cm3_procedure":[]}},"locator":{"file":"门诊住院病历模板/病历模板包_全部_20261111.json","arrayRow":450,"caseRow":1},"sourceHash":"10e4fdb435986b7b85f847c3951d0cb0eafdce0f372c5617949c05b337149194","contentHash":"84cb845a072b8c63a532581ef75bdc2d71a8f0bb31a6f4c708de3ee3cea1af02","pinyin":"diluyatoutong","initials":"dlytt","setting":"out","caseName":"门诊病历315","templateNames":["主诉","现病史","既往史","个人史及过敏史","体格检查","辅助检查","初步诊断","处理方案"],"emptyTemplates":[],"escapedNewlines":[],"quickFields":[["病例名称","门诊病历315",60],["模板名称","主诉 现病史 既往史 个人史及过敏史 体格检查 辅助检查 初步诊断 处理方案",30],["主要诊断编码","",30]]},{"id":"templates-ed9aabcd2f69e79a4a6e","key":"v1-c9ccc21dfe2a3058|templates-ed9aabcd2f69e79a4a6e","module":"templates","moduleKey":"v1-c9ccc21dfe2a3058|templates","version":"v1-c9ccc21dfe2a3058","title":"颅内高压","category":"门诊病历模板","raw":{"name":"颅内高压","category":"门诊病历模板","case":{"case_name":"门诊病历316","templates":{"主诉":"进行性头痛伴恶心呕吐2周","现病史":"患者于4周前开始头痛（全头胀痛，晨起及咳嗽用力时加重，颅内高压特征，可伴喷射性呕吐，与进食无关），进行性加重，伴视物模糊（视乳头水肿，可一过性黑矇）、复视（外展神经麻痹），有无意识改变、抽搐、肢体无力（占位/脑疝，晚期）、耳鸣、头晕，病因线索（颅内占位（肿瘤/脓肿/血肿）、脑积水、静脉窦血栓、特发性颅内高压（肥胖年轻女性）、感染（脑膜炎）、中毒代谢）：均无。今日来我院门诊就诊。","既往史":"既往体健，否认高血压、糖尿病、冠心病等慢性病史。否认肝炎、结核等传染病史。否认手术外伤史。否认食物药物过敏史。预防接种史随社会。","个人史及过敏史":"生于原籍，久居本地，无疫区疫水接触史，无特殊粉尘毒物放射性物质接触史。不吸烟，不饮酒。生活规律。否认食物药物过敏史。","体格检查":"T____℃，P____次/分（可减慢，Cushing反应），R____次/分，BP____/____mmHg（可升高）。神志____（清楚/嗜睡/昏迷），眼底检查（视乳头水肿，核心体征，充血边界模糊隆起、静脉迂曲、出血），瞳孔及对光反射（脑疝：一侧散大），外展受限（复视），肢体肌力（偏瘫：占位定位）、病理征，颈抵抗（+/-，脑膜刺激）。","辅助检查":"【必做】头颅CT（急诊首选，颅内占位、出血、脑积水、中线移位，排除肿瘤血肿，占位性颅内高压）；【影像】头颅MRI增强+MRV（静脉窦血栓，年轻女性/产褥，重要病因，增强）；【腰穿】测压（>200mmH2O（卧位），确诊颅内压增高，但占位性病变/脑疝风险时禁忌，先影像再考虑）、脑脊液化验（感染/出血）；【其他】眼底（视乳头水肿程度，眼科会诊）、视野（视神经受压）。","初步诊断":"1. 颅内压增高（病因：占位，脑积水，静脉窦血栓，特发性，等待明确）\n（注：①急诊处理（颅内高压危象，意识障碍/脑疝征象）：床头抬高30°、过度通气（PaCO2 30~35mmHg，临时）、甘露醇0.5~1g/kg快速静滴（20%甘露醇250ml q6~8h，渗透性利尿降颅压，监测电解质肾功能）、糖皮质激素（地塞米松，瘤周水肿，注意禁忌）、必要时脑室穿刺引流（脑积水）；②病因治疗（核心）：占位，手术切除；脑积水，分流；静脉窦血栓，抗凝（低分子肝素→华法林）；感染，抗感染；特发性颅内高压，减重+乙酰唑胺（抑制脑脊液分泌）±反复腰穿放液，视神经鞘减压/分流（视力威胁时急诊手术指征）；③监测意识瞳孔生命体征（GCS）、眼底及视力；神经科/神经外科急诊多学科处理。）","处理方案":"【药物治疗】\n1.脱水降颅压（首选）：20%甘露醇注射液125ml静脉滴注（20~30分钟内滴完）q8h，疗程3~5天，滴注后30分钟起效、2~3小时达高峰，用药期间监测血压、血电解质、肾功能及24小时出入量，防止脱水过度及电解质紊乱。\n2.利尿剂辅助：呋塞米片20mg口服qd×3~5天，与甘露醇交替或联合使用以增强降颅压效果并延长作用时间，需同时补钾（如氯化钾缓释片0.5g口服bid）并监测血钾。\n3.糖皮质激素：地塞米松磷酸钠注射液5~10mg静脉注射qd×3~5天（适用于颅内占位、炎症或放射性脑水肿所致颅内高压），配合质子泵抑制剂（如奥美拉唑肠溶胶囊20mg口服qd）预防应激性溃疡；注意监测血糖。\n4.对症处理：甲氧氯普胺片10mg口服tid止吐；头痛明显时可临时予对乙酰氨基酚缓释片0.5g口服prn（间隔≥6小时，每日总量不超过2g），忌用强阿片类镇痛药以防呼吸抑制加重颅内高压。\n【一般治疗及生活指导】\n1.休息体位：绝对卧床休息，床头抬高15~30°，保持环境安静、避免声光刺激及情绪激动，尽量减少探视。\n2.饮食护理：低盐饮食（每日食盐<5g），控制液体入量每日1500~2000ml，少量多次饮温开水，避免一次大量饮水；进清淡易消化饮食，呕吐严重者暂禁食并静脉补液。\n3.活动禁忌：避免用力咳嗽、用力排便、剧烈活动、长时间低头及屏气动作，防止腹压、胸压骤增诱发颅压骤升；保持大便通畅，便秘时可予乳果糖口服溶液15ml口服qd。\n4.病情监测：每日监测神志、瞳孔、血压、心率及呼吸节律，记录24小时出入量；起床、站立体位变换时动作宜缓慢，防止体位性低血压。\n【随诊要求】\n1.用药期间3~5天复诊1次，评估头痛、呕吐、视物模糊等症状缓解情况及血电解质、肾功能；症状明显改善者可逐步延长复诊间隔至每周1次。\n2.疗程结束后1~2周复查头颅CT或MRI，根据影像学变化调整降颅压药物及疗程。\n3.若出现剧烈头痛进行性加重、喷射性呕吐、视乳头水肿或视力下降、意识障碍、肢体抽搐或无力等表现，须立即急诊就医。\n4.明确病因者（如颅内占位、静脉窦血栓、脑膜炎等）转神经外科、神经内科或感染科进一步病因治疗，专科随访。"},"icd10_diagnosis":"","icd10_secondary":[],"icd9cm3_procedure":[]}},"locator":{"file":"门诊住院病历模板/病历模板包_全部_20261111.json","arrayRow":451,"caseRow":1},"sourceHash":"10e4fdb435986b7b85f847c3951d0cb0eafdce0f372c5617949c05b337149194","contentHash":"aea10ff2f0dac45a250aed2e0b4d98dd6030d01f8e3bfed25ef8f9e6f6b8e716","pinyin":"luneigaoya","initials":"lngy","setting":"out","caseName":"门诊病历316","templateNames":["主诉","现病史","既往史","个人史及过敏史","体格检查","辅助检查","初步诊断","处理方案"],"emptyTemplates":[],"escapedNewlines":[],"quickFields":[["病例名称","门诊病历316",60],["模板名称","主诉 现病史 既往史 个人史及过敏史 体格检查 辅助检查 初步诊断 处理方案",30],["主要诊断编码","",30]]},{"id":"templates-f3008a2980f795e3084b","key":"v1-c9ccc21dfe2a3058|templates-f3008a2980f795e3084b","module":"templates","moduleKey":"v1-c9ccc21dfe2a3058|templates","version":"v1-c9ccc21dfe2a3058","title":"脑积水","category":"门诊病历模板","raw":{"name":"脑积水","category":"门诊病历模板","case":{"case_name":"门诊病历317","templates":{"主诉":"头痛、呕吐伴视物模糊1月","现病史":"患者（成人，继发于颅脑外伤出血后、脑膜炎后或肿瘤阻塞，或为正常压力脑积水，表现为步态障碍、认知障碍及尿失禁三联征，多见于老年人；婴幼儿为先天性，表现为头围增大、前囟饱满、落日眼）于颅脑外伤后出现头痛、呕吐、视乳头水肿等颅内压增高表现，或步态不稳（小碎步、宽基底，足黏地板感，为正常压力脑积水特征）、记忆力减退、反应迟钝、尿失禁（晚期表现），有无意识障碍、抽搐、发热（感染后脑膜炎所致脑积水）。婴幼儿需了解出生史及头围增长情况：头围增长较同龄儿明显增快。今日来我院门诊就诊。","既往史":"既往体健，否认高血压、糖尿病、冠心病等慢性病史。否认肝炎、结核等传染病史。否认手术外伤史。否认食物药物过敏史。预防接种史随社会。","个人史及过敏史":"生于原籍，久居本地，无疫区疫水接触史，无特殊粉尘毒物放射性物质接触史。不吸烟，不饮酒。生活规律。否认食物药物过敏史。","体格检查":"T36.5℃，P72次/分，R18次/分，BP120/80mmHg。神志清楚，表情淡漠。眼底见视乳头水肿，提示颅内压增高。步态宽基底、小碎步，起步困难，符合正常压力脑积水表现。认知功能减退，MMSE评分下降。尿失禁阳性。婴幼儿头围增大，超过同年龄百分位（需测量并绘制生长曲线）、前囟饱满紧张、落日眼（双眼下视、巩膜显露，为中脑顶盖受压）、头皮静脉怒张、叩诊破罐音。","辅助检查":"【必做】头颅CT或MRI：脑室扩张（侧脑室额角圆钝、第三脑室扩大）、脑室周围白质水肿（经室管膜渗出），并明确病因（占位、出血后、先天畸形如导水管狭窄、Dandy-Walker畸形）；【正常压力脑积水评估】腰椎穿刺放液试验（放30~50ml脑脊液后步态、认知改善，支持诊断并预测分流疗效）、颅内压监测；【婴幼儿】头颅超声（前囟未闭时可行，无创）；【其他】腰椎穿刺（感染后脑积水可行脑脊液化验）。","初步诊断":"1. 脑积水（梗阻性还是交通性，先天性、继发性还是正常压力性脑积水，待明确）\n（注：①治疗以手术为主（核心，药物疗效有限）：脑室-腹腔分流术（VP分流，最常用，适用于正常压力脑积水及多数脑积水，术前需评估）、第三脑室底造瘘术（ETV，适用于导水管狭窄及梗阻性脑积水，无分流依赖）；②正常压力脑积水腰穿放液试验阳性者分流效果好，步态最先改善；③对症：乙酰唑胺（仅用于部分婴幼儿，抑制脑脊液分泌，疗效有限）；④病因治疗（肿瘤切除、抗感染后复查）；⑤并发症：分流管感染、梗阻、过度分流（裂隙脑室综合征，表现为体位性头痛，需调压）；⑥婴幼儿早期手术可改善预后，迟治可致智力发育障碍；术后定期随访影像（脑室大小）及神经功能，由神经外科管理。）","处理方案":"【药物治疗】\n1. 乙酰唑胺片0.25g bid（早晚各1次），抑制脉络丛脑脊液分泌、减缓脑室扩张，连用4周后复查头颅CT/MRI评估疗效；用药期间每周监测血钾、血氯及二氧化碳结合力并常规补钾，警惕低钾血症及代谢性酸中毒。\n2. 呋塞米片20mg qd（晨服），与乙酰唑胺联用增强减少脑脊液生成、降低颅内压作用；每1-2周监测电解质、肾功能及血压，注意防治低钾、低钠血症及脱水。\n3. 合并脑室炎/颅内感染所致脑积水者：门诊可予左氧氟沙星片0.5g qd po×7天或头孢呋辛酯片0.5g bid po×7天，感染控制后复查脑脊液及头颅CT；感染重者转住院静脉抗感染（如头孢曲松2.0g ivgtt q12h×10-14天）后再评估分流时机。\n\n【一般治疗及生活指导】\n1. 休息与体位：保证充足睡眠，避免劳累与剧烈活动；休息时床头抬高15°-30°，利于颅内静脉回流、减轻颅压增高症状。\n2. 饮食：低盐清淡饮食，每日食盐<6g，减少水钠潴留；适量优质蛋白（鱼、蛋、瘦肉），多食富含钾食物（香蕉、橘子、土豆等）以补充利尿排钾；避免辛辣刺激及暴饮暴食。\n3. 活动与禁忌：避免用力咳嗽、用力排便、提重物、弯腰憋气等升高颅内压的动作，保持大便通畅，必要时予乳果糖通便；避免猛然起立及久蹲久坐；出现剧烈头痛、恶心呕吐、视物模糊时立即静卧休息并尽快就诊，警惕颅高压危象。\n4. 情志调护：保持情绪平稳，避免紧张、激动及过度用脑，防血压波动诱发颅压骤升。\n\n【随诊要求】\n1. 服药期间每1-2周门诊复诊一次，复查电解质（血钾、钠、氯）、肾功能、二氧化碳结合力及血压，调整利尿剂量。\n2. 每4周复查头颅CT或MRI，评估脑室大小及脑积水进展；如头痛加重、频繁呕吐、视物模糊、嗜睡、意识改变或肢体无力，立即急诊就诊。\n3. 药物保守治疗无效或症状进行性加重者，评估脑室-腹腔分流术（VP分流）或三脑室底造瘘术手术指征，及时转神经外科会诊。\n4. 分流术后或病情稳定者每3-6个月门诊随访，复查头颅CT动态观察脑室变化，注意有无分流管堵塞、感染、过度分流等并发症。"},"icd10_diagnosis":"","icd10_secondary":[],"icd9cm3_procedure":[]}},"locator":{"file":"门诊住院病历模板/病历模板包_全部_20261111.json","arrayRow":452,"caseRow":1},"sourceHash":"10e4fdb435986b7b85f847c3951d0cb0eafdce0f372c5617949c05b337149194","contentHash":"2f97ca07cb11acf498864c5f76f01bfc432792ec31c1f71f3ee1ca99357194b7","pinyin":"naojishui","initials":"njs","setting":"out","caseName":"门诊病历317","templateNames":["主诉","现病史","既往史","个人史及过敏史","体格检查","辅助检查","初步诊断","处理方案"],"emptyTemplates":[],"escapedNewlines":[],"quickFields":[["病例名称","门诊病历317",60],["模板名称","主诉 现病史 既往史 个人史及过敏史 体格检查 辅助检查 初步诊断 处理方案",30],["主要诊断编码","",30]]},{"id":"templates-0b0394ed42d5711e9e09","key":"v1-c9ccc21dfe2a3058|templates-0b0394ed42d5711e9e09","module":"templates","moduleKey":"v1-c9ccc21dfe2a3058|templates","version":"v1-c9ccc21dfe2a3058","title":"巨幼细胞性贫血","category":"门诊病历模板","raw":{"name":"巨幼细胞性贫血","category":"门诊病历模板","case":{"case_name":"门诊病历318","templates":{"主诉":"乏力、面色苍白伴舌痛、手足麻木6月","现病史":"患者于3个月前渐出现乏力、头晕、面色苍白（贫血）、活动后心慌气短，伴舌面光滑疼痛（Hunter舌炎、舌乳头萎缩）、食欲减退、恶心，有无手足对称性麻木及针刺感（维生素B12缺乏致脊髓后索及周围神经病变）、行走不稳（深感觉障碍，Romberg征）、记忆力减退、抑郁，有无长期素食（维生素B12缺乏，动物性食物来源不足）、胃切除或萎缩性胃炎（内因子缺乏致B12吸收障碍）、小肠疾病（回肠切除，B12吸收部位缺失）、长期服用质子泵抑制剂或二甲双胍（B12吸收减少）、酗酒或营养不良（叶酸缺乏）、妊娠（叶酸需求增加）及溶血（叶酸消耗）等诱因：无特殊诱因。今日来我院门诊就诊。","既往史":"既往体健，否认高血压、糖尿病、冠心病等慢性病史。否认肝炎、结核等传染病史。否认手术外伤史。否认食物药物过敏史。预防接种史随社会。","个人史及过敏史":"生于原籍，久居本地，无疫区疫水接触史，无特殊粉尘毒物放射性物质接触史。不吸烟，不饮酒。生活规律。否认食物药物过敏史。","体格检查":"T36.5℃，P72次/分，R18次/分，BP120/80mmHg。神志清楚，贫血貌，睑结膜苍白，舌面光滑、舌乳头萎缩（Hunter舌炎），皮肤轻度黄染（无效造血致间接胆红素升高）。神经系统：四肢远端触痛觉减退（周围神经受累）、振动觉及位置觉减退（后索受累）、Romberg征阳性、腱反射减弱（B12缺乏）。","辅助检查":"【必做】血常规（大细胞性贫血，MCV>100fl，红细胞大小不均，中性粒细胞分叶过多即核右移，为特征性改变）、网织红细胞（降低或正常）、血清维生素B12（降低<200pg/ml）、血清及红细胞叶酸（降低<4ng/ml）、血LDH及间接胆红素（升高，提示无效造血）、铁蛋白；【病因】内因子抗体、壁细胞抗体（恶性贫血）、胃镜（萎缩性胃炎）、抗组织转谷氨酰胺酶抗体（乳糜泻致叶酸吸收障碍）、甲状腺功能；【治疗监测】治疗后网织红细胞反应（3~5天上升，7~10天达高峰）、血钾（治疗中可降低，需补钾）。","初步诊断":"1. 巨幼细胞性贫血（维生素B12缺乏或叶酸缺乏待明确）\n（注：①维生素B12缺乏：肌注甲钴胺或维生素B12（1000μg每日1次×1周→每周1次×4周→每月1次维持，恶性贫血及胃切除者需终身），吸收障碍轻或依从性差者可口服大剂量（1000~2000μg/d）；②叶酸缺乏：口服叶酸5~10mg每日3次，同时纠正病因；③补充铁剂（合并缺铁者，治疗后铁耗竭，需监测铁蛋白）；④饮食指导（均衡饮食，摄入含B12的动物性食物）；⑤重要警示：疑B12缺乏时勿单独用叶酸，以免改善血液学而掩盖并加重神经损害，应先补B12或联合使用；⑥补钾（治疗初期大量红细胞生成耗钾，尤其老年及心脏病患者）；⑦随访血常规及网织红细胞直至正常，维持期定期复查。）","处理方案":"【药物治疗】\n1. 叶酸片 5mg po tid，口服至血红蛋白及红细胞形态恢复正常后停用，常规疗程4～6周（仅用于叶酸缺乏所致巨幼细胞性贫血；维生素B12缺乏者禁用大剂量叶酸，以免掩盖神经系统损害）。\n2. 甲钴胺注射液 0.5mg im qod，或维生素B12注射液（氰钴胺）0.5mg im qod，血象恢复后改为维持量（每月1次0.5mg）；也可口服甲钴胺片0.5mg tid，疗程4～8周，B12缺乏者（恶性贫血/胃切除后）需终身维持治疗。\n3. 同时口服10%氯化钾溶液10ml tid（红细胞再生时钾需求增加，注意补钾），并补充铁剂（琥珀酸亚铁片0.1g tid），疗程2～4周，防止造血恢复期缺铁。\n【一般治疗及生活指导】\n1. 适当休息：血红蛋白明显降低、头晕乏力明显者应减少活动、保证充足睡眠，避免剧烈运动及重体力劳动，防止晕厥跌倒。\n2. 调整饮食：多食富含叶酸的食物（绿叶蔬菜、动物肝脏、豆类、柑橘类水果）及富含维生素B12的食物（动物肝脏、瘦肉、鱼、蛋、奶），纠正偏食、长期素食习惯，荤素搭配；注意蔬菜烹调时间不宜过长，避免叶酸破坏。\n3. 严格戒酒，避免长期饮酒及饮用浓茶、咖啡影响叶酸吸收；慎用干扰叶酸代谢的药物（苯妥英钠、甲氨蝶呤、柳氮磺吡啶等），必须使用者应加强监测。\n4. 注意口腔及皮肤护理，进食细软易消化食物，防止舌炎、口腔溃疡及感染；忌自行盲目补充大剂量叶酸，以免延误B12缺乏的诊治。\n【随诊要求】\n1. 治疗后1周复查血常规，观察网织红细胞计数及血红蛋白回升情况；每2～4周复查血常规及血细胞形态，评估疗效至血象恢复正常。\n2. 4周后复查血清叶酸、维生素B12水平，评价补充是否达标；B12缺乏者维持治疗期间每3～6个月复查血常规及血清B12水平。\n3. 症状改善不明显或血象无回升者，及时复诊进一步行骨髓穿刺、内因子抗体、胃镜等检查明确病因；B12缺乏者注意随访神经系统症状（四肢麻木、行走不稳），出现异常及时就诊神经内科。"},"icd10_diagnosis":"","icd10_secondary":[],"icd9cm3_procedure":[]}},"locator":{"file":"门诊住院病历模板/病历模板包_全部_20261111.json","arrayRow":453,"caseRow":1},"sourceHash":"10e4fdb435986b7b85f847c3951d0cb0eafdce0f372c5617949c05b337149194","contentHash":"5888d60ff40411231e052f7c9e9649265406e37c05a6133793a7e8f16363eab9","pinyin":"juyouxibaoxingpinxue","initials":"jyxbxpx","setting":"out","caseName":"门诊病历318","templateNames":["主诉","现病史","既往史","个人史及过敏史","体格检查","辅助检查","初步诊断","处理方案"],"emptyTemplates":[],"escapedNewlines":[],"quickFields":[["病例名称","门诊病历318",60],["模板名称","主诉 现病史 既往史 个人史及过敏史 体格检查 辅助检查 初步诊断 处理方案",30],["主要诊断编码","",30]]},{"id":"templates-eae9d42c69722b5bafa9","key":"v1-c9ccc21dfe2a3058|templates-eae9d42c69722b5bafa9","module":"templates","moduleKey":"v1-c9ccc21dfe2a3058|templates","version":"v1-c9ccc21dfe2a3058","title":"再生障碍性贫血","category":"门诊病历模板","raw":{"name":"再生障碍性贫血","category":"门诊病历模板","case":{"case_name":"门诊病历319","templates":{"主诉":"进行性乏力、面色苍白伴出血点3月","现病史":"患者于3周前渐出现进行性乏力、面色苍白（贫血，红细胞减少）、皮肤瘀点瘀斑、牙龈出血、鼻出血（血小板减少致出血倾向）、反复发热感染（粒细胞减少、白细胞减少，可表现为肺炎、口腔感染、败血症，需注意有无发热寒战、咳嗽、咽痛、尿路感染症状），无肝脾淋巴结肿大（区别于白血病，再障无浸润体征），有无药物（氯霉素、磺胺、抗癫痫药、金制剂）、化学毒物（苯）、放射线、病毒感染（肝炎后再障，多见于病毒性肝炎后2~3月）接触史：无特殊接触史。今日来我院门诊就诊。","既往史":"既往体健，否认高血压、糖尿病、冠心病等慢性病史。否认肝炎、结核等传染病史。否认手术外伤史。否认食物药物过敏史。预防接种史随社会。","个人史及过敏史":"生于原籍，久居本地，无疫区疫水接触史，无特殊粉尘毒物放射性物质接触史。不吸烟，不饮酒。生活规律。否认食物药物过敏史。","体格检查":"T36.5℃，P72次/分，R18次/分，BP120/80mmHg。神志清楚，贫血貌，皮肤可见瘀点瘀斑，口腔黏膜血疱及溃疡（感染灶）、牙龈出血，浅表淋巴结不肿大（重要鉴别点），胸骨无压痛，心肺听诊未闻及异常，肝脾肋下未触及（不肿大，重要鉴别点，区别于白血病及脾功能亢进），肛周无红肿及感染灶。","辅助检查":"【必做】血常规（全血细胞减少，贫血+白细胞减少+血小板减少，网织红细胞降低）、外周血涂片（无幼稚细胞）、骨髓穿刺+活检（骨髓增生低下、造血细胞减少、脂肪细胞增多，为确诊金标准，需多部位穿刺以除外局灶性造血）、肝肾功能、病毒学（肝炎病毒、EBV、CMV）、自身抗体（鉴别风湿病相关全血细胞减少）；【鉴别】阵发性睡眠性血红蛋白尿筛查（流式细胞术检测CD55、CD59，再障-PNH综合征）、骨髓细胞遗传学（除外骨髓增生异常综合征，注意有无病态造血）。","初步诊断":"1. 再生障碍性贫血（重型或非重型，病因：特发性、药物性或化学物等）\n（注：①重型再障（血细胞三系严重减少，中性粒细胞<0.5×10⁹/L、血小板<20×10⁹/L、网织红细胞降低）需紧急转血液科住院：异基因造血干细胞移植（年轻且有供者，首选，可治愈）或免疫抑制治疗（抗胸腺细胞球蛋白ATG+环孢素，适用于40岁以上或无供者者）；②非重型：环孢素±雄激素（司坦唑醇，刺激造血），随访观察；③支持治疗（关键）：输血（红细胞<60g/L、血小板<20×10⁹/L或有出血时）、抗感染（粒细胞缺乏伴发热立即予经验性广谱抗生素）、粒细胞集落刺激因子（G-CSF，严重粒细胞缺乏）、祛铁（反复输血致铁过载）；④避免一切可能加重因素（骨髓抑制药物、苯、感染）；⑤严重出血（颅内）按急症处理；由血液科专科管理，长期随访，监测向白血病及骨髓增生异常综合征转化风险。）","处理方案":"【药物治疗】\n1.免疫抑制治疗：环孢素A软胶囊3～5mg/(kg·d)，分2次口服（体重60kg者每次约90～150mg，bid），餐后服用，维持全血谷浓度150～250ng/mL，疗程至少6个月，期间监测肝肾功能、血压及牙龈增生等不良反应。\n2.雄激素刺激造血：司坦唑醇片2mg tid口服；或十一酸睾酮胶丸40mg bid，疗程3～6个月，定期复查肝功能、血脂，注意男性化及水钠潴留等副作用。\n3.促血小板生成：艾曲泊帕乙醇胺片25～50mg qd口服（空腹服用，餐前1小时或餐后2小时），根据血小板计数调整剂量，疗程3～6个月，注意监测肝功能及血栓风险。\n\n【一般治疗及生活指导】\n1.休息与活动：血红蛋白<60g/L或血小板<30×10^9/L时以卧床休息为主，避免劳累、熬夜，保证充足睡眠；血小板明显减少期间避免剧烈运动、重体力劳动及磕碰外伤。\n2.饮食：给予高蛋白、高维生素、易消化饮食（瘦肉、蛋、鱼类、动物肝脏、新鲜蔬菜水果），注意食品卫生，避免生冷、过硬、带刺及辛辣刺激性食物，防止损伤口腔及消化道黏膜引起出血；严格戒烟、戒酒。\n3.出血防护：使用软毛牙刷，动作轻柔，避免用力擤鼻、剔牙及抠挖耳鼻；保持大便通畅，避免用力排便；女性患者注意经期经量，必要时记录并告知医师。\n4.用药禁忌：禁用氯霉素、磺胺类、保泰松等可能抑制骨髓的药物，避免使用阿司匹林等抗血小板药物；避免接触苯、油漆、农药及放射线等有害物质。\n\n【随诊要求】\n1.每1～2周复查血常规；用药初期每2～4周监测肝肾功能、环孢素血药浓度，稳定后每1～3个月复查1次。\n2.每3～6个月复查骨髓穿刺及骨髓活检评估造血功能恢复情况；长期随访监测有无疾病复发及向PNH、骨髓增生异常综合征、白血病等克隆演变。\n3.出现发热、咽痛、咳嗽等感染征象，或牙龈出血、皮肤瘀点瘀斑、鼻衄、黑便、月经量过多等出血征象时应随时就诊；血红蛋白明显下降需输注红细胞、血小板明显减少有出血风险需输注血小板时，及时复诊调整治疗方案。"},"icd10_diagnosis":"","icd10_secondary":[],"icd9cm3_procedure":[]}},"locator":{"file":"门诊住院病历模板/病历模板包_全部_20261111.json","arrayRow":454,"caseRow":1},"sourceHash":"10e4fdb435986b7b85f847c3951d0cb0eafdce0f372c5617949c05b337149194","contentHash":"c2b003bd8c897758e1be3b5852e7488c795892124bb86af7997d703b400f9dcf","pinyin":"zaishengzhangaixingpinxue","initials":"zszaxpx","setting":"out","caseName":"门诊病历319","templateNames":["主诉","现病史","既往史","个人史及过敏史","体格检查","辅助检查","初步诊断","处理方案"],"emptyTemplates":[],"escapedNewlines":[],"quickFields":[["病例名称","门诊病历319",60],["模板名称","主诉 现病史 既往史 个人史及过敏史 体格检查 辅助检查 初步诊断 处理方案",30],["主要诊断编码","",30]]},{"id":"templates-97ce4a1f0864b21f64bb","key":"v1-c9ccc21dfe2a3058|templates-97ce4a1f0864b21f64bb","module":"templates","moduleKey":"v1-c9ccc21dfe2a3058|templates","version":"v1-c9ccc21dfe2a3058","title":"溶血性贫血","category":"门诊病历模板","raw":{"name":"溶血性贫血","category":"门诊病历模板","case":{"case_name":"门诊病历320","templates":{"主诉":"乏力、面色苍白伴黄疸1月","现病史":"患者于2个月前渐出现乏力、面色苍白（贫血）、皮肤巩膜黄染（溶血性黄疸，黄疸与贫血并存为溶血特征，区别于肝病）、尿色加深（呈酱油色或浓茶色，为血红蛋白尿，提示血管内溶血；含铁血黄素尿见于慢性血管内溶血）、脾大（血管外溶血，脾脏破坏红细胞），有无发热、腰背酸痛（急性血管内溶血）、寒战、急性肾衰（血红蛋白尿阻塞肾小管），诱因及病因包括红细胞膜缺陷（遗传性球形红细胞增多症，注意家族史）、酶缺陷（G6PD缺乏，见于进食蚕豆或氧化性药物如磺胺、阿司匹林、伯氨喹后）、血红蛋白病（地中海贫血、镰状细胞病）、自身免疫性（AIHA，温抗体型，可继发于SLE、淋巴瘤、药物或为原发）、阵发性睡眠性血红蛋白尿（晨起酱油色尿）、机械性（人工瓣膜、微血管病如TTP、HUS，可见碎片红细胞）：无明确诱因。今日来我院门诊就诊。","既往史":"既往体健，否认高血压、糖尿病、冠心病等慢性病史。否认肝炎、结核等传染病史。否认手术外伤史。否认食物药物过敏史。预防接种史随社会。","个人史及过敏史":"生于原籍，久居本地，无疫区疫水接触史，无特殊粉尘毒物放射性物质接触史。不吸烟，不饮酒。生活规律。否认食物药物过敏史。","体格检查":"T36.5℃，P72次/分，R18次/分，BP120/80mmHg。神志清楚，贫血貌，皮肤巩膜黄染，脾肋下2cm可触及（肿大，提示血管外溶血）、肝肋下未触及，心脏听诊心尖部可闻及收缩期杂音（贫血致高排），下肢无水肿。","辅助检查":"检查计划：患者近2个月乏力、面色苍白伴皮肤巩膜黄染、尿色加深呈酱油色，脾脏增大，黄疸与贫血并存提示溶血性贫血，故完善血常规检查明确贫血程度及有无白细胞、血小板改变；完善网织红细胞计数，其为骨髓代偿性造血的核心指标，显著升高支持溶血；完善外周血涂片，观察有无球形红细胞（遗传性球形红细胞增多症）、碎片红细胞（TTP、HUS等微血管病性溶血）及有核红细胞；完善血清胆红素检查，了解间接胆红素是否升高，明确溶血性黄疸；完善LDH检查了解红细胞破坏程度；完善结合珠蛋白检查，其降低为血管内溶血的重要依据；完善尿常规检查，明确有无血红蛋白尿及尿胆原升高。病因方面，完善直接抗人球蛋白试验（Coombs试验），明确有无自身免疫性溶血性贫血；完善G6PD活性测定，排除进食蚕豆或氧化性药物后急性溶血；完善血红蛋白电泳，排除地中海贫血及异常血红蛋白病；完善酸化血清试验及流式CD55/CD59检测，排除阵发性睡眠性血红蛋白尿；必要时完善红细胞渗透脆性试验，明确遗传性球形红细胞增多症。因血管内溶血可致血红蛋白管型阻塞肾小管并引发凝血异常，完善肾功能及凝血功能检查，评估有无急性肾损伤及凝血障碍；治疗期间定期复查血常规、网织红细胞及胆红素，评估激素或脾切除疗效，并完善叶酸水平检查指导补充。\n\n（检查清单）\n【必做】血常规（贫血）、网织红细胞（显著升高，骨髓代偿，为溶血核心指标）、外周血涂片（球形红细胞见于遗传性球形红细胞增多症、碎片红细胞见于微血管病性TTP及HUS、可见有核红细胞）、血清胆红素（间接胆红素升高）、LDH（升高）、结合珠蛋白（降低，为溶血指标）、尿常规（血红蛋白尿、尿胆原升高）；【病因】直接抗人球蛋白试验（Coombs试验，阳性提示自身免疫性溶血）、G6PD活性、血红蛋白电泳（地中海贫血及异常血红蛋白）、酸化血清试验及流式CD55/CD59（PNH）、渗透脆性试验（球形红细胞增多症）；【其他】肾功能（急性肾衰，见于血管内溶血）、凝血功能。","初步诊断":"1. 溶血性贫血（血管内或血管外，病因：遗传性（膜、酶、血红蛋白病）或获得性（免疫性、PNH、机械性））\n（注：①病因治疗（核心）：免疫性（AIHA）予糖皮质激素（泼尼松1~1.5mg/kg/d，一线），无效或复发者行脾切除、利妥昔单抗或免疫抑制剂（硫唑嘌呤）；G6PD缺乏者立即停用诱因（蚕豆、氧化性药物），避用磺胺及伯氨喹，急性发作予对症（补液碱化以防肾衰）；遗传性球形红细胞增多症溶血重者行脾切除（术后防感染，接种疫苗+青霉素预防）；PNH予依库珠单抗（补体C5抑制剂，抗溶血及抗血栓）加叶酸；②对症支持：补充叶酸（溶血消耗，常规）、输血（重度贫血输注洗涤红细胞，AIHA交叉配血困难）；③急性溶血急症处理（大量血红蛋白尿、急性肾衰、休克）：补液碱化（碳酸氢钠防血红蛋白管型）、利尿、血液净化（严重肾衰）、监护；④监测胆红素及肾功能；由血液科专科明确病因及长期管理。）","处理方案":"【药物治疗】\n1. 泼尼松片 40-60mg（1mg/kg/d）晨起顿服，连用4-6周，待血红蛋白及网织红细胞回升稳定后每1-2周减量5-10mg，减至每日5-10mg小剂量维持3-6个月（适用于自身免疫性溶血性贫血，用药期间监测血糖、血压及血钾）。\n2. 叶酸片 5mg 每日3次口服，贯穿整个溶血期（红细胞代偿性增生消耗叶酸，预防巨幼样变）。\n3. 铁剂仅在有明确缺铁证据（血清铁、铁蛋白降低）时补充，如硫酸亚铁片 0.3g 每日3次；慢性溶血多有铁过载风险，禁止常规补铁。\n4. 遗传性球形红细胞增多症等红细胞膜缺陷者评估脾切除指征（Hb≤80g/L、网织红细胞显著升高或溶血反复发作）；阵发性睡眠性血红蛋白尿（PNH）者考虑依库珠单抗治疗，建议专科会诊。\n\n【一般治疗及生活指导】\n1. 休息：急性溶血期卧床休息，Hb<60g/L时绝对卧床，避免劳累及剧烈活动；病情缓解后循序渐进恢复日常活动。\n2. 饮食：给予高蛋白、高维生素、富含叶酸饮食（瘦肉、蛋类、动物肝脏、绿叶蔬菜）；G6PD缺乏（蚕豆病）者绝对禁食蚕豆及蚕豆制品，避免接触樟脑丸、萘类化合物。\n3. 预防感染：避免受凉感冒及呼吸道感染，感染可诱发或加重溶血；注意个人卫生，避免去人群密集场所。\n4. 禁忌：禁用氧化性药物（磺胺类、呋喃类、伯氨喹、阿司匹林等）；冷抗体型自身免疫性溶血性贫血者注意保暖，避免寒冷刺激；含铁药物避免与茶、咖啡同服。\n\n【随诊要求】\n1. 激素治疗期间每1-2周复查血常规、网织红细胞计数，评估疗效；每2-4周监测肝功能、空腹血糖、血压、血钾，警惕激素不良反应。\n2. 病情稳定后每月复诊1次，激素减量必医师指导下进行，严禁自行停药或增减剂量，防止溶血复发。\n3. 出现酱油色尿、黄疸加深、发热、腹痛或突然面色苍白加重，应立即急诊就诊。\n4. 定期复查Coomb's试验、血清胆红素、乳酸脱氢酶、结合珠蛋白及尿含铁血黄素，动态评估溶血活动度；长期反复溶血者每年评估胆石症及脾切除适应证。"},"icd10_diagnosis":"","icd10_secondary":[],"icd9cm3_procedure":[]}},"locator":{"file":"门诊住院病历模板/病历模板包_全部_20261111.json","arrayRow":455,"caseRow":1},"sourceHash":"10e4fdb435986b7b85f847c3951d0cb0eafdce0f372c5617949c05b337149194","contentHash":"75f178bd2e83d242eaed02924ac94e14a633c53f42465a8d073007a41a9cd856","pinyin":"rongxuexingpinxue","initials":"rxxpx","setting":"out","caseName":"门诊病历320","templateNames":["主诉","现病史","既往史","个人史及过敏史","体格检查","辅助检查","初步诊断","处理方案"],"emptyTemplates":[],"escapedNewlines":[],"quickFields":[["病例名称","门诊病历320",60],["模板名称","主诉 现病史 既往史 个人史及过敏史 体格检查 辅助检查 初步诊断 处理方案",30],["主要诊断编码","",30]]},{"id":"templates-637c7dab9dc6bfa12c3b","key":"v1-c9ccc21dfe2a3058|templates-637c7dab9dc6bfa12c3b","module":"templates","moduleKey":"v1-c9ccc21dfe2a3058|templates","version":"v1-c9ccc21dfe2a3058","title":"真性红细胞增多症","category":"门诊病历模板","raw":{"name":"真性红细胞增多症","category":"门诊病历模板","case":{"case_name":"门诊病历321","templates":{"主诉":"头痛、头晕伴皮肤瘙痒6月","现病史":"患者于6个月前渐出现头痛、头晕、乏力、皮肤瘙痒（热水浴后加重，为特征性表现，与组胺释放有关）、面色潮红（醉酒貌）、结膜充血、视物模糊，有无耳鸣、肢体麻木及烧灼感（红斑性肢痛，指趾灼痛、遇热加重）、血栓史（深静脉血栓、肺栓塞、脑梗、心梗，血黏度增高，血栓为最主要死因及并发症）、出血倾向（黏膜出血，血小板功能异常）、高血压、脾大（腹部饱胀）。有无高原居住、慢性肺病、发绀型先心病（继发性红细胞增多，血氧低致代偿）及吸烟（继发，碳氧血红蛋白高）等继发因素：无上述继发因素。今日来我院门诊就诊。","既往史":"既往体健，否认高血压、糖尿病、冠心病等慢性病史。否认肝炎、结核等传染病史。否认手术外伤史。否认食物药物过敏史。预防接种史随社会。","个人史及过敏史":"生于原籍，久居本地，无疫区疫水接触史，无特殊粉尘毒物放射性物质接触史。不吸烟，不饮酒。生活规律。否认食物药物过敏史。","体格检查":"T36.5℃，P72次/分，R18次/分，BP120/80mmHg。神志清楚，面色潮红、结膜充血、唇舌暗红（多血貌），眼底见视网膜静脉扩张迂曲，脾肋下2cm可触及（肿大，髓外造血，常见）、肝肋下未触及，皮肤可见瘀斑及瘙痒抓痕，神经系统未见血栓后遗症（无偏瘫等）。","辅助检查":"【必做】血常规（血红蛋白>165g/L（男）或>160g/L（女），或红细胞压积>49%（男）、>48%（女），红细胞增多，白细胞及血小板可升高，提示全髓增殖）、血氧饱和度（正常，可排除继发性低氧性红细胞增多）、JAK2V617F突变（>95%阳性，为克隆性标志及确诊核心，真性红细胞增多症分子诊断）、促红细胞生成素（EPO，降低提示原发）、肝肾功能、尿酸（升高，细胞更新增快）；【影像】脾脏超声（脾大）、疑血栓时行相应影像检查；【鉴别】骨髓活检（三系增生，支持真性红细胞增多症）、血清维生素B12（可升高）。","初步诊断":"1. 真性红细胞增多症（JAK2阳性或阴性）\n（注：①治疗目标为降低血栓风险，控制红细胞压积<45%：放血治疗（静脉放血，初始每周250~500ml至压积<45%，维持期每1~3个月1次，同时小剂量补铁，因放血可致铁缺乏）；②骨髓抑制药（放血控制不佳、血小板>1000×10⁹/L、有血栓史、老年或脾大症状重者）：羟基脲0.5~1g每日1次（一线，需监测血常规）、干扰素α（适用于年轻及妊娠者，无白血病转化风险）或芦可替尼（JAK抑制剂，用于羟基脲耐药或不耐受的JAK2阳性者）；③抗血小板：阿司匹林100mg每日1次（无出血禁忌者，降低血栓风险）；④对症：瘙痒予抗组胺药或帕罗西汀，严重者用干扰素；⑤血栓及出血事件转相应专科处理；⑥监测向骨髓纤维化及急性白血病转化（血常规变化、脾进行性增大、全身症状，需骨穿评估）；由血液科长期随访。）","处理方案":"【药物治疗】\n1. 阿司匹林肠溶片100mg qd口服：低剂量抗血小板治疗，为低危组（无血栓史）患者一线用药，可显著降低血栓及心血管事件风险，长期服用，注意监测出血倾向；有消化道溃疡或出血史者慎用。\n2. 羟基脲片500mg bid口服（起始剂量15~20mg/kg/d，分2次）：一线骨髓抑制性细胞减容药物，适用于高危组（年龄>60岁或有血栓病史）或血细胞比容难以控制者，根据血常规调整剂量，维持白细胞>3.0×10⁹/L、血小板>100×10⁹/L，疗程为长期维持。\n3. 重组人干扰素α-2b注射液300万U皮下注射，每周3次（或聚乙二醇干扰素α-2a 135μg皮下注射，每周1次）：适用于<60岁及育龄期患者的细胞减容一线选择，可降低血细胞比容并抑制克隆增殖，根据血常规及耐受性调整，疗程为长期维持。\n4. 别嘌醇片100mg tid口服：防治细胞增殖及放血后所致高尿酸血症（目标血尿酸<420μmol/L），服药期间多饮水、碱化尿液，避免与硫唑嘌呤合用。\n【一般治疗及生活指导】\n1. 多饮水，每日饮水2000~2500ml，保持尿量充足，避免脱水（呕吐、腹泻、大汗后及时补液），以稀释血液、降低血液黏滞度，预防血栓。\n2. 低盐、低脂、清淡饮食，避免高嘌呤食物（动物内脏、浓肉汤、海鲜）及酒精，防治高尿酸血症和血栓形成。\n3. 适度活动（散步、太极拳等有氧运动），避免剧烈运动、长时间久坐或长时间静卧；避免进入高海拔缺氧环境，注意保持情绪平稳，避免过度劳累。\n4. 禁忌吸烟（吸烟加重缺氧及血液浓缩），禁止使用促红细胞生成素、铁剂及输血等升高红细胞或血红蛋白的措施；静脉放血后当日避免剧烈活动，注意休息并适当进食。\n【随诊要求】\n1. 每1~3个月门诊复查血常规及血细胞比容（治疗目标：男性HCT<0.45、女性HCT<0.42），同时监测血压、血尿酸、血清铁蛋白（放血者易缺铁）。\n2. 服用羟基脲或干扰素者每3个月复查肝肾功能、血常规，注意药物不良反应（骨髓抑制、肝功能损害、甲状腺功能异常等）。\n3. 长期随访观察疾病转化风险，若出现头痛、眩晕、视力模糊、耳鸣、胸痛、单侧肢体麻木无力、言语不清等血栓或缺血表现，应立即急诊就诊。\n4. 定期（每6~12个月）复查JAK2/V617F突变、腹部超声（脾脏大小），必要时行骨髓穿刺检查，监测向骨髓纤维化或白血病转化。"},"icd10_diagnosis":"","icd10_secondary":[],"icd9cm3_procedure":[]}},"locator":{"file":"门诊住院病历模板/病历模板包_全部_20261111.json","arrayRow":456,"caseRow":1},"sourceHash":"10e4fdb435986b7b85f847c3951d0cb0eafdce0f372c5617949c05b337149194","contentHash":"aa2c0583f34ca0c438cadbf78cfda28e45b845e682b11c4f856dc2c24f9ef8b5","pinyin":"zhenxinghongxibaozengduozheng","initials":"zxhxbzdz","setting":"out","caseName":"门诊病历321","templateNames":["主诉","现病史","既往史","个人史及过敏史","体格检查","辅助检查","初步诊断","处理方案"],"emptyTemplates":[],"escapedNewlines":[],"quickFields":[["病例名称","门诊病历321",60],["模板名称","主诉 现病史 既往史 个人史及过敏史 体格检查 辅助检查 初步诊断 处理方案",30],["主要诊断编码","",30]]},{"id":"templates-a8a135159ce910f015b9","key":"v1-c9ccc21dfe2a3058|templates-a8a135159ce910f015b9","module":"templates","moduleKey":"v1-c9ccc21dfe2a3058|templates","version":"v1-c9ccc21dfe2a3058","title":"原发性血小板增多症","category":"门诊病历模板","raw":{"name":"原发性血小板增多症","category":"门诊病历模板","case":{"case_name":"门诊病历322","templates":{"主诉":"头晕、乏力伴血小板增多6月","现病史":"患者于3个月前体检发现血小板升高（达650×10⁹/L，持续>450×10⁹/L），有无头痛头晕、视物模糊、肢端麻木及烧灼感（红斑性肢痛）、皮肤黏膜出血（瘀点瘀斑、牙龈及鼻出血，血小板功能异常）、血栓事件（脑梗、心梗、深静脉血栓、门静脉血栓，为重要并发症）：偶有头晕。有无脾大（腹胀）、瘙痒、体重下降。有无骨髓增殖性疾病家族史、缺铁性贫血及炎症肿瘤（继发性或反应性血小板增多，常见，需鉴别）：无上述病史。今日来我院门诊就诊。","既往史":"既往体健，否认高血压、糖尿病、冠心病等慢性病史。否认肝炎、结核等传染病史。否认手术外伤史。否认食物药物过敏史。预防接种史随社会。","个人史及过敏史":"生于原籍，久居本地，无疫区疫水接触史，无特殊粉尘毒物放射性物质接触史。不吸烟，不饮酒。生活规律。否认食物药物过敏史。","体格检查":"T36.5℃，P72次/分，R18次/分，BP120/80mmHg。神志清楚，多血貌阴性，皮肤瘀点瘀斑阴性，眼底见视网膜静脉扩张，脾肋下1cm可触及（轻度肿大）、肝肋下未触及。","辅助检查":"【必做】血常规（血小板持续>450×10⁹/L，需多次复查确认）、外周血涂片（观察血小板形态，可见大血小板及成堆分布）、JAK2V617F、CALR、MPL突变（克隆性标志，为诊断核心，JAK2约50%阳性）、促红细胞生成素（鉴别真性红细胞增多症）、血清铁蛋白（缺铁为继发性血小板增多常见原因）、CRP及血沉（炎症致反应性增高）、肿瘤标志物（老年人隐匿肿瘤致反应性增多）；【影像】腹部超声（脾大）；【其他】骨髓穿刺活检（巨核细胞增殖，必要鉴别，观察血细胞形态）。","初步诊断":"1. 原发性血小板增多症（JAK2、CALR、MPL突变状态待查）\n（注：血栓风险评估（年龄>60岁、血小板>1500×10⁹/L、血栓史、心血管危险因素）并据此分层治疗：低危予阿司匹林100mg每日1次（一级预防，注意出血，血小板极高时谨慎）；高危予降血小板药物（羟基脲0.5~1g每日1次，一线，监测血常规）或干扰素α（年轻及妊娠者，无致白血病风险）、阿那格雷（二线，降血小板快速）、芦可替尼（JAK2阳性难治者）；出血或血小板>2000×10⁹/L（获得性血管性血友病）时立即降血小板；对症：红斑性肢痛予阿司匹林，疗效显著；避免增加血栓因素（吸烟、口服避孕药）；监测向骨髓纤维化及白血病转化；由血液科长期随访。）","处理方案":"【药物治疗】\n1. 阿司匹林肠溶片 100mg qd 口服（餐后），用于降低血栓风险，适用于无出血倾向及无禁忌证的所有患者；\n2. 羟基脲片 0.5g bid 口服（起始剂量），每1-2周依据血小板计数调整剂量，目标使血小板降至<600×10^9/L，达标后以最小有效量（通常0.5-1.0g/d）维持，适用于年龄≥60岁、既往有血栓史等高危患者或血小板>1500×10^9/L者；\n3. 重组人干扰素α-2b注射液 300万U 皮下注射，隔日一次，适用于年轻患者（<40岁）、妊娠期或对羟基脲不耐受者，疗程根据血小板控制情况调整；\n4. 阿那格雷胶囊 0.5mg qid 口服（起始），每5-7天递增0.5mg/d直至血小板达标（每日最大剂量不超过10mg），作为羟基脲疗效不佳或不能耐受时的二线选择。\n\n【一般治疗及生活指导】\n1. 休息与活动：血小板显著增高或伴脾肿大者以静养为主，避免剧烈运动、长时间久坐及腹部受压碰撞，以防血栓形成及脾破裂；\n2. 饮食：低脂、清淡、均衡营养，保证每日饮水1500-2000ml以稀释血液，戒烟限酒，避免高脂、高糖饮食；\n3. 症状监测：如出现头痛、头晕、视物模糊、肢体麻木疼痛、胸痛、言语不清等血栓征象，或皮肤瘀斑、牙龈出血、鼻出血、黑便等出血征象，应立即就医；\n4. 就医注意事项：拔牙、手术、分娩等有创操作前患者血小板增多症病史并评估出血风险，避免自行加用其他药物。\n\n【随诊要求】\n1. 血常规：用药调整期每1-2周复查1次，血小板达标稳定后每1-3个月复查1次，监测血小板、白细胞及血红蛋白变化；\n2. 每3-6个月复查肝肾功能、凝血功能及腹部超声（观察脾脏大小变化），患者羟基脲者注意监测肝功能及有无血细胞减少；\n3. 若出现新发血栓、出血、皮肤黏膜溃疡或不明原因发热等异常，及时复诊调整用药方案。"},"icd10_diagnosis":"","icd10_secondary":[],"icd9cm3_procedure":[]}},"locator":{"file":"门诊住院病历模板/病历模板包_全部_20261111.json","arrayRow":457,"caseRow":1},"sourceHash":"10e4fdb435986b7b85f847c3951d0cb0eafdce0f372c5617949c05b337149194","contentHash":"46f1b0d857991b803f99aef634cab7758afa537a2921659758b726d191252399","pinyin":"yuanfaxingxuexiaobanzengduozheng","initials":"yfxxxbzdz","setting":"out","caseName":"门诊病历322","templateNames":["主诉","现病史","既往史","个人史及过敏史","体格检查","辅助检查","初步诊断","处理方案"],"emptyTemplates":[],"escapedNewlines":[],"quickFields":[["病例名称","门诊病历322",60],["模板名称","主诉 现病史 既往史 个人史及过敏史 体格检查 辅助检查 初步诊断 处理方案",30],["主要诊断编码","",30]]},{"id":"templates-ea16dbdc84955c8694a3","key":"v1-c9ccc21dfe2a3058|templates-ea16dbdc84955c8694a3","module":"templates","moduleKey":"v1-c9ccc21dfe2a3058|templates","version":"v1-c9ccc21dfe2a3058","title":"骨髓纤维化","category":"门诊病历模板","raw":{"name":"骨髓纤维化","category":"门诊病历模板","case":{"case_name":"门诊病历323","templates":{"主诉":"乏力、消瘦伴腹胀6月","现病史":"患者于6个月前渐出现乏力、食欲减退、体重下降、低热盗汗（全身症状，细胞因子释放）、腹胀（巨脾致左上腹包块及压迫饱胀感）、骨痛、皮肤瘙痒，有无贫血（面色苍白）、出血倾向、门静脉高压表现（腹水、食管静脉曲张出血，髓外造血致肝脾门脉血流增加）及血栓：无出血及血栓。既往有无真性红细胞增多症或原发性血小板增多症病史（PV或ET后骨髓纤维化，疾病演进）及家族史：无相关病史。今日来我院门诊就诊。","既往史":"既往体健，否认高血压、糖尿病、冠心病等慢性病史。否认肝炎、结核等传染病史。否认手术外伤史。否认食物药物过敏史。预防接种史随社会。","个人史及过敏史":"生于原籍，久居本地，无疫区疫水接触史，无特殊粉尘毒物放射性物质接触史。不吸烟，不饮酒。生活规律。否认食物药物过敏史。","体格检查":"T36.5℃，P72次/分，R18次/分，BP120/80mmHg。神志清楚，消瘦，贫血貌，皮肤可见瘀斑及瘙痒抓痕。脾肋下8cm可触及（巨脾，质硬，为核心体征）、肝肋下2cm可触及，心肺听诊未闻及异常，双下肢无水肿。","辅助检查":"检查计划：患者近6个月乏力、消瘦、食欲减退伴腹胀，查体考虑巨脾所致左上腹饱胀，伴低热盗汗等全身症状，临床怀疑原发性骨髓纤维化，故完善血常规及外周血涂片检查，了解贫血程度、白细胞与血小板增多或减少情况，并观察有无泪滴状红细胞及幼粒幼红细胞这一特征性改变，同时查白细胞碱性磷酸酶以助鉴别；完善JAK2、CALR、MPL突变检测，明确有无克隆性标志，为诊断与危险分层提供分子学依据；完善肝肾功能、LDH及尿酸检查，评估肿瘤负荷、组织破坏程度及芦可替尼等用药安全。确诊方面，完善骨髓穿刺及活检，行网状纤维与胶原纤维染色，观察纤维组织增生及巨核细胞异型聚集，此为诊断核心依据。影像方面，完善腹部超声或CT检查，明确脾脏增大程度、有无门静脉高压及肝脾淋巴结髓外造血灶。预后评估方面，依据年龄、血红蛋白、白细胞、原始细胞、染色体及全身症状等指标完善DIPSS及DIPSS-plus评分，指导危险分层与治疗选择。此外，完善凝血功能、心电图，评估出血与血栓风险及心脏耐受性；治疗期间定期复查血常规、肝肾功能与脾脏大小，并监测原始细胞比例，警惕向急性白血病转化，必要时复查骨髓穿刺。\n\n（检查清单）\n【必做】血常规（贫血、白细胞及血小板增多或减少，外周血涂片可见泪滴状红细胞及幼粒幼红细胞，为特征性改变，白细胞碱性磷酸酶升高）、JAK2、CALR、MPL突变（克隆性标志）、肝肾功能、LDH、尿酸；【确诊】骨髓穿刺+活检（纤维组织增生、巨核细胞异型聚集，网状纤维及胶原纤维染色，为核心诊断依据）；【影像】腹部超声或CT（巨脾、门静脉高压、髓外造血灶如肝脾淋巴结）；【预后】DIPSS及DIPSS-plus评分（年龄、血红蛋白、白细胞、原始细胞、染色体、全身症状）。","初步诊断":"1. 原发性骨髓纤维化（原发性还是真红或血小板增多后骨髓纤维化，中危或高危）\n（注：按危险分层治疗：低危无症状者观察或对症（贫血予雄激素、促红素或输血；脾大不适予羟基脲减脾，脾区放疗用于姑息）；中高危伴全身症状及脾大者予JAK2抑制剂芦可替尼15~20mg每日2次（缩脾、改善症状、延长生存，为核心药物，需监测血常规及感染如带状疱疹）；低剂量泼尼松+雄激素（贫血）；异基因造血干细胞移植（唯一根治手段，适用于年轻中高危者，需评估移植风险）；脾切除（巨脾症状重、药物无效、难治性贫血输血依赖者，需权衡术后血栓、出血、感染并发症）；门脉高压并发症处理（静脉曲张套扎、TIPS）；监测向急性白血病转化（原始细胞增多，需骨穿）；由血液科专科管理。）","处理方案":"【药物治疗】\n1. 芦可替尼（JAK1/JAK2抑制剂，一线首选）：起始剂量按血小板计数分层：PLT＞200×10⁹/L者20mg bid，PLT 100~200×10⁹/L者15mg bid，PLT 50~100×10⁹/L者5mg bid；空腹或随餐口服，每2~4周根据血常规（血小板、血红蛋白）及脾脏缩小情况调整剂量，长期维持治疗，不可骤然停药。\n2. 输血支持：血红蛋白＜80g/L或伴明显贫血症状（心悸、气促、乏力进行性加重）时输注去白细胞悬浮红细胞2U，必要时每1~2周重复；有活动性出血或血小板＜20×10⁹/L时输注单采血小板1个治疗量。\n3. 羟基脲：不能耐受芦可替尼或脾大症状（左上腹饱胀、疼痛、压迫感）明显者，0.5g qd~bid口服，据白细胞及血小板计数调整（维持WBC＞3×10⁹/L、PLT＞80×10⁹/L），每周复查血常规。\n4. 沙利度胺：合并中重度贫血者，沙利度胺50mg qn口服（可联合泼尼松0.5mg/kg qd），用药期间监测周围神经病变、便秘及血栓风险，育龄期女性禁用。\n【一般治疗及生活指导】\n1. 休息与活动：脾脏明显肿大者避免剧烈运动、弯腰提重物及腹部挤压碰撞，防止脾破裂；适度活动、避免长期卧床，降低血栓风险。\n2. 饮食：高蛋白、富含维生素、易消化饮食；血小板低下时避免坚硬、粗糙、过热食物（坚果、骨头、油炸食品），防止消化道出血。\n3. 出血与感染防护：血小板低时用软毛牙刷、避免用力擤鼻及剔牙；注意手卫生，避免去人群密集场所，预防感染。\n4. 禁忌：未经医师指导避免使用阿司匹林、氯吡格雷等抗血小板及抗凝药物；戒烟酒。\n【随诊要求】\n1. 服药期间每1~2周复查血常规，每3~6个月复查肝肾功能、电解质及腹部超声评估脾脏大小。\n2. 芦可替尼减量或停药须遵医嘱逐步进行，避免突然停药引起疾病反跳（停药综合征）；出现发热、脾区剧痛、新发出血或血栓、体重明显下降时立即就诊。\n3. 每6~12个月评估疾病进展（复查骨髓穿刺涂片及活检、JAK2/CALR/MPL基因突变状态），符合条件者转血液科专科评估异基因造血干细胞移植指征。"},"icd10_diagnosis":"","icd10_secondary":[],"icd9cm3_procedure":[]}},"locator":{"file":"门诊住院病历模板/病历模板包_全部_20261111.json","arrayRow":458,"caseRow":1},"sourceHash":"10e4fdb435986b7b85f847c3951d0cb0eafdce0f372c5617949c05b337149194","contentHash":"ec96aac9dd065e3a617d71c5e74299d4153a8a013573478a020a580d5a2abec4","pinyin":"gusuixianweihua","initials":"gsxwh","setting":"out","caseName":"门诊病历323","templateNames":["主诉","现病史","既往史","个人史及过敏史","体格检查","辅助检查","初步诊断","处理方案"],"emptyTemplates":[],"escapedNewlines":[],"quickFields":[["病例名称","门诊病历323",60],["模板名称","主诉 现病史 既往史 个人史及过敏史 体格检查 辅助检查 初步诊断 处理方案",30],["主要诊断编码","",30]]},{"id":"templates-7c0aab2240b5c172606b","key":"v1-c9ccc21dfe2a3058|templates-7c0aab2240b5c172606b","module":"templates","moduleKey":"v1-c9ccc21dfe2a3058|templates","version":"v1-c9ccc21dfe2a3058","title":"脾功能亢进","category":"门诊病历模板","raw":{"name":"脾功能亢进","category":"门诊病历模板","case":{"case_name":"门诊病历324","templates":{"主诉":"脾大伴乏力、腹胀1年","现病史":"患者有肝硬化门静脉高压（最常见病因）、慢性感染（疟疾、血吸虫、结核、黑热病）、血液病（淋巴瘤、白血病、骨髓增殖性疾病）、自身免疫病（SLE）、脾静脉血栓、Gaucher病等基础病史，于6个月前发现脾大及血细胞减少（白细胞、血小板、红细胞可一系或多系减少，甚至全血细胞减少）、乏力（贫血）、出血倾向（血小板减少）、易感染（白细胞减少）、腹部饱胀（巨脾压迫），有无发热、盗汗、体重下降（提示基础病活动）：无发热、盗汗及体重下降。今日来我院门诊就诊。","既往史":"既往体健，否认高血压、糖尿病、冠心病等慢性病史。否认肝炎、结核等传染病史。否认手术外伤史。否认食物药物过敏史。预防接种史随社会。","个人史及过敏史":"生于原籍，久居本地，无疫区疫水接触史，无特殊粉尘毒物放射性物质接触史。不吸烟，不饮酒。生活规律。否认食物药物过敏史。","体格检查":"T36.5℃，P72次/分，R18次/分，BP120/80mmHg。神志清楚，贫血貌。脾肋下5cm可触及（肿大，按肿大程度分度，达巨脾）、肝肋下未触及，腹水征阴性（无门静脉高压腹水），皮肤瘀点瘀斑阴性，浅表淋巴结未触及肿大。","辅助检查":"【必做】血常规（全血细胞或一系减少）、网织红细胞、外周血涂片、骨髓穿刺+活检（增生正常或活跃，排除原发血液病，与再障及白血病鉴别）、肝肾功能、病毒及寄生虫血清学（明确感染病因）、腹部超声或CT（脾脏大小、门静脉高压征象，观察门静脉及脾静脉内径）；【鉴别】脾功能亢进诊断需排除骨髓造血障碍（骨髓检查正常或代偿性增生）并证实脾脏破坏（放射性核素标记红细胞，脾与肝比值升高）。","初步诊断":"1. 脾功能亢进（病因：肝硬化门静脉高压或血液病等，血细胞减少情况待明确）\n（注：①治疗原发病（核心）：门静脉高压予TIPS或内镜处理静脉曲张以改善脾亢；感染予抗病原治疗；淋巴瘤予化疗；②对症：白细胞减少易感染，感染时积极抗感染（不预防性常规用G-CSF）；血小板减少出血时输注血小板（有出血或术前）；贫血予输血或纠正原发病；③脾切除指征（严格掌握，术前需评估）：巨脾压迫症状重、脾亢致严重血细胞减少影响生活（反复出血、感染或依赖输血）、遗传性球形红细胞增多症（切脾有效，但已少首选）、原发脾淋巴瘤或脾脓肿；切脾后需防感染（接种肺炎球菌疫苗+青霉素预防，重要）；部分性脾栓塞（介入治疗，可替代切脾，门脉高压者可选）；④脾切除后注意血栓风险（门静脉血栓，需评估抗凝）及暴发性感染风险宣教；由血液科、消化科及外科多学科评估。）","处理方案":"【药物治疗】\n1. 针对原发病治疗：慢性肝病/门静脉高压所致脾功能亢进者，乙肝相关者予恩替卡韦胶囊0.5mg qd口服（长期服用，不可随意停药）；丙肝相关者按抗病毒方案规范治疗；肝硬化门脉高压者予普萘洛尔片10mg tid起始口服，根据心率调整剂量（目标静息心率55~60次/分），以降低门静脉压力、减轻脾淤血。\n2. 白细胞减少者：予重组人粒细胞集落刺激因子（G-CSF，如瑞白）75~150μg/d皮下注射，连用3~5天，每周复查血常规评估，中性粒细胞恢复正常或伴发热感染控制后停药。\n3. 贫血明显者：予重组人促红细胞生成素（EPO）3000IU皮下注射，每周3次，疗程4周后复查血常规评估疗效，血红蛋白>90g/L可减量或停药。\n4. 免疫性病因（如免疫性血小板减少症）者：予泼尼松片1mg/(kg·d)晨起顿服，起效后2~4周开始逐渐减量，总疗程3~6个月，注意监测血糖、血压及补钙、护胃。\n【一般治疗及生活指导】\n1. 休息与活动：脾脏明显肿大者避免剧烈运动及腹部撞击（如对抗性体育运动、骑跨伤），避免突然用力、弯腰提重物，防止脾破裂；以休息为主，避免劳累。\n2. 饮食：进食高蛋白、高维生素、易消化饮食；肝硬化门脉高压者予软食、少渣饮食，忌粗糙坚硬及带骨刺食物（如坚果、油炸食品、鱼刺等），禁酒，防食管胃底静脉曲张破裂出血。\n3. 预防感染：白细胞减少者注意个人卫生，勤洗手，避免去人群密集场所及接触感染患者，出现发热、咽痛等感染征象及时就医。\n4. 用药禁忌：血小板明显减少者避免使用阿司匹林、布洛芬等非甾体抗炎药及抗血小板、抗凝药物，避免肌内注射及外伤磕碰；慎用可能抑制骨髓的药物。\n【随诊要求】\n1. 每1~2周复查血常规（白细胞、血小板、血红蛋白），动态评估血细胞减少程度及治疗反应。\n2. 原发病规律随诊：肝病者每1~3个月复查肝功能、病毒学指标、AFP及腹部超声，每6个月复查胃镜评估食管胃底静脉曲张；需行脾切除术者，至血液科、普外科（或肝胆外科）评估手术指征与风险。\n3. 出现以下情况立即就诊：发热、寒战等感染表现；皮肤瘀斑、牙龈出血、鼻衄、黑便等出血倾向；突发的左上腹剧痛、腹胀，警惕脾破裂可能。"},"icd10_diagnosis":"","icd10_secondary":[],"icd9cm3_procedure":[]}},"locator":{"file":"门诊住院病历模板/病历模板包_全部_20261111.json","arrayRow":459,"caseRow":1},"sourceHash":"10e4fdb435986b7b85f847c3951d0cb0eafdce0f372c5617949c05b337149194","contentHash":"02b30d88b461c6f33d190662854f8e94872da97da1eeee6acfb9fe08f9edb799","pinyin":"pigongnengkangjin","initials":"pgnkj","setting":"out","caseName":"门诊病历324","templateNames":["主诉","现病史","既往史","个人史及过敏史","体格检查","辅助检查","初步诊断","处理方案"],"emptyTemplates":[],"escapedNewlines":[],"quickFields":[["病例名称","门诊病历324",60],["模板名称","主诉 现病史 既往史 个人史及过敏史 体格检查 辅助检查 初步诊断 处理方案",30],["主要诊断编码","",30]]},{"id":"templates-88c1d25417696e3709b4","key":"v1-c9ccc21dfe2a3058|templates-88c1d25417696e3709b4","module":"templates","moduleKey":"v1-c9ccc21dfe2a3058|templates","version":"v1-c9ccc21dfe2a3058","title":"粒细胞缺乏症","category":"门诊病历模板","raw":{"name":"粒细胞缺乏症","category":"门诊病历模板","case":{"case_name":"门诊病历325","templates":{"主诉":"发热伴咽痛、口腔溃疡3天","现病史":"患者（病因包括药物：抗甲状腺药如甲巯咪唑及丙硫氧嘧啶最常见、抗肿瘤化疗、氯氮平、磺胺、解热镇痛药；血液病：再障、白血病、MDS；病毒感染；自身免疫）于化疗后出现发热（体温最高39.2℃，粒细胞缺乏伴发热为急症）、咽痛、口腔黏膜溃疡及坏死、牙龈肿痛，有无咳嗽咳痰、腹痛腹泻、尿路刺激症状、皮肤感染（蜂窝织炎、疖，肛周感染尤其需注意，粒细胞缺乏者常见隐匿感染灶）、乏力，有无寒战（提示菌血症）。近期用药史及化疗时间：化疗后第7天。今日来我院急诊就诊。","既往史":"既往体健，否认高血压、糖尿病、冠心病等慢性病史。否认肝炎、结核等传染病史。否认手术外伤史。否认食物药物过敏史。预防接种史随社会。","个人史及过敏史":"生于原籍，久居本地，无疫区疫水接触史，无特殊粉尘毒物放射性物质接触史。不吸烟，不饮酒。生活规律。否认食物药物过敏史。","体格检查":"T36.5℃，P72次/分，R18次/分，BP120/80mmHg。神志清楚。口腔黏膜可见溃疡及白斑、坏死，咽部充血，扁桃体无肿大及脓栓（粒细胞缺乏时可不典型），肺部听诊未闻及啰音（炎症反应弱，啰音可缺如）、腹部无压痛，皮肤未见疖肿、蜂窝织炎及肛患者肿（需仔细检查隐匿灶），浅表淋巴结未触及肿大。","辅助检查":"【必做】血常规（中性粒细胞<0.5×10⁹/L可确诊粒细胞缺乏；<0.1×10⁹/L为极重度）、外周血涂片（观察有无幼稚细胞，鉴别白血病）、血培养（发热者用抗生素前采集，需2~3套）、CRP、降钙素原、肝肾功能、电解质；【感染灶评估】胸片或CT（肺炎，早期可无阴影）、尿常规、大便常规、咽拭子培养、G试验及GM试验（化疗后免疫抑制者，发热持续时排查真菌）；【病因】骨髓穿刺（鉴别血液病，粒细胞缺乏原因不明或恢复不佳时）。","初步诊断":"1. 粒细胞缺乏症（中性粒细胞<0.5×10⁹/L）伴发热（粒缺性发热）\n（注：粒缺伴发热为肿瘤及药物相关急症，需立即住院：①经验性广谱抗生素（发热或明确感染时即刻使用，无需等待培养，首选抗假单胞菌β内酰胺类：哌拉西林他唑巴坦4.5g每6小时1次，或头孢吡肟、美罗培南，覆盖革兰阴性菌（铜绿假单胞菌）及革兰阳性菌；48~72小时无退热加用万古霉素（覆盖MRSA）±抗真菌药（卡泊芬净、伏立康唑，中性粒细胞减少>7天持续发热时经验性抗真菌）；②G-CSF（粒细胞集落刺激因子，化疗后使用，缩短粒缺期）；③停用或调整致病药物（药源性粒缺立即停用）；④隔离保护（单间、口腔护理、无菌饮食）、口腔及肛周护理；⑤积极寻找并处理感染灶；⑥监测血常规（粒细胞回升，通常停致病药后1~3周恢复）及体温；由血液科及肿瘤科管理，向患者宣教发热时立即就诊，勿自行服退热药掩盖病情。）","处理方案":"【药物治疗】\n1. 粒细胞集落刺激因子：重组人粒细胞集落刺激因子（rhG-CSF，如瑞白、吉粒芬）150～300μg 皮下注射 qd，连用3～7天，直至中性粒细胞绝对值回升至≥2.0×10⁹/L或血象稳定后停药，期间按血常规结果调整剂量。\n2. 经验性抗感染：粒细胞缺乏者感染风险极高，首选覆盖革兰阴性菌（尤其铜绿假单胞菌）的广谱方案。门诊口服可选左氧氟沙星片0.5g qd×7天，或阿莫西林克拉维酸钾片0.625g tid×7天；若伴发热或感染征象，建议改静脉给药：哌拉西林他唑巴坦4.5g ivgtt q8h，至体温正常且中性粒细胞回升后降阶梯。\n3. 抗真菌治疗：经验性抗菌治疗3～5天后仍持续发热，或出现口腔白斑、黏膜溃烂者，加用氟康唑胶囊0.4g（首剂）后0.15g qd，疗程至感染控制。\n4. 口腔黏膜炎对症：复方氯己定含漱液10ml含漱 tid，联合重组人粒细胞集落刺激因子含漱或局部外用表皮生长因子，减轻溃疡、预防继发感染。\n【一般治疗及生活指导】\n1. 充分卧床休息，避免劳累；中性粒细胞<0.5×10⁹/L时建议居家隔离或住院治疗，谢绝探视，外出全程佩戴口罩，避免前往人群密集、通风不良场所，不与感染患者接触。\n2. 高蛋白、高维生素、易消化软食，所有食物及水果、牛奶须充分加热煮熟后食用，禁生冷、隔夜、不洁及辛辣刺激性食物，多饮水，保证营养支持。\n3. 加强个人卫生：勤洗手，使用软毛牙刷、餐后及睡前含漱，保持口腔、皮肤及会阴部清洁；避免抠鼻、剔牙、搔抓皮肤，暂停拔牙、注射等不必要的侵入性操作。\n4. 立即停用可疑致病药物（如氯氮平、甲巯咪唑、丙硫氧嘧啶、磺胺类、抗甲状腺药物等），就诊时主动告知近期用药史，避免再次接触骨髓抑制药物及理化因素。\n【随诊要求】\n1. 治疗期间每2～3天复查血常规，动态监测中性粒细胞绝对值回升情况，直至连续两次稳定在≥1.5×10⁹/L后方可延长复查间隔。\n2. 每日监测体温≥4次；一旦出现发热（体温≥38.0℃持续1小时或≥38.3℃单次）、寒战、咽痛、咳嗽或任何感染征象，立即急诊就诊并留取血培养，不得等待常规门诊复诊。\n3. 每1～2周门诊复诊评估病情；粒细胞恢复后复查血常规确认，并进一步筛查有无血液系统原发病（必要时行骨髓穿刺检查），明确病因后制定长期随访方案。"},"icd10_diagnosis":"","icd10_secondary":[],"icd9cm3_procedure":[]}},"locator":{"file":"门诊住院病历模板/病历模板包_全部_20261111.json","arrayRow":460,"caseRow":1},"sourceHash":"10e4fdb435986b7b85f847c3951d0cb0eafdce0f372c5617949c05b337149194","contentHash":"efab43f38afd228e296e6b0a90725f9d4be9e960dc03569c9e267e5c3e54a2ec","pinyin":"lixibaoquefazheng","initials":"lxbqfz","setting":"out","caseName":"门诊病历325","templateNames":["主诉","现病史","既往史","个人史及过敏史","体格检查","辅助检查","初步诊断","处理方案"],"emptyTemplates":[],"escapedNewlines":[],"quickFields":[["病例名称","门诊病历325",60],["模板名称","主诉 现病史 既往史 个人史及过敏史 体格检查 辅助检查 初步诊断 处理方案",30],["主要诊断编码","",30]]},{"id":"templates-ba09f9b1b1498297942a","key":"v1-c9ccc21dfe2a3058|templates-ba09f9b1b1498297942a","module":"templates","moduleKey":"v1-c9ccc21dfe2a3058|templates","version":"v1-c9ccc21dfe2a3058","title":"假性痛风","category":"门诊病历模板","raw":{"name":"假性痛风","category":"门诊病历模板","case":{"case_name":"门诊病历326","templates":{"主诉":"关节急性红肿热痛伴发热3天","现病史":"患者于3天前突发膝关节（大关节中最常见，亦可见于腕、肩、髋关节）红肿热痛、活动受限（急性焦磷酸钙沉积病，CPPD），程度可与痛风相当，伴低热，有无代谢病（甲状旁腺功能亢进（原发甲旁亢，高钙促焦磷酸钙沉积）、血色病（铁过载）、低镁血症、甲状腺功能减退，均为CPPD易患因素）及家族史（遗传性）：无相关病史。血尿酸可正常（区别于痛风）。有无类似发作史及关节创伤、手术史：无类似发作史。今日来我院门诊就诊。","既往史":"既往体健，否认高血压、糖尿病、冠心病等慢性病史。否认肝炎、结核等传染病史。否认手术外伤史。否认食物药物过敏史。预防接种史随社会。","个人史及过敏史":"生于原籍，久居本地，无疫区疫水接触史，无特殊粉尘毒物放射性物质接触史。不吸烟；饮酒10年，约3两/日。生活规律。否认食物药物过敏史。","体格检查":"T36.5℃，P72次/分，R18次/分，BP120/80mmHg。神志清楚，痛苦面容。右膝关节明显红肿、皮温升高、关节积液（浮髌试验阳性）、压痛、活动受限，其他关节无受累，未见Heberden结节（CPPD相关骨关节炎及退行性变可并见，即假性骨关节炎），皮肤无痛风石。","辅助检查":"【必做】血常规（白细胞可升高）、血沉、CRP（升高）、血尿酸（可正常，用于鉴别）、血钙、血磷、血镁、铁蛋白及铁饱和度（筛查甲旁亢、血色病、低镁）、甲状腺功能、肝肾功能；【确诊】关节液偏振光镜检（见弱阳性双折光、短而粗的菱形焦磷酸钙结晶，区别于痛风的针状负双折光尿酸结晶，为确诊金标准）、关节液常规（炎性，白细胞升高）；【影像】X线（关节软骨钙化，纤维软骨及透明软骨线样钙化，见于膝半月板及腕三角纤维软骨，为特征性改变）、超声（软骨表面线样强回声，呈双轨征）。","初步诊断":"1. 假性痛风（焦磷酸钙沉积病，急性关节炎）\n（注：急性发作治疗与痛风相似：关节抽液减压（大量积液时兼具诊断与治疗作用）、NSAIDs（塞来昔布200mg每日2次或双氯芬酸，无禁忌者首选）或秋水仙碱（0.5mg每日2次，疗效较好，腹泻时停药）或关节内糖皮质激素注射（单关节，高效，为首选之一）、口服泼尼松（多关节或不能口服NSAIDs者，短期30mg/d渐减）；同时治疗基础病（原发甲旁亢予手术；血色病予放血以减少沉积）；慢性反复发作或慢性炎症性关节炎予秋水仙碱0.5mg每日1次预防或羟氯喹；避免关节过度使用；注意与痛风鉴别（两者可并存）；由风湿科随访。）","处理方案":"【药物治疗】1.非甾体抗炎药（首选）：塞来昔布胶囊0.2g bid 或双氯芬酸钠缓释片75mg qd，疗程5～7天，肿痛缓解后停药；胃溃疡病史者加用质子泵抑制剂护胃。2.秋水仙碱：急性发作72小时内尽早使用，首剂1.0mg，1小时后加服0.5mg，此后0.5mg bid，疗程3～5天；肾功能不全者减量为0.5mg qd。3.糖皮质激素（NSAIDs/秋水仙碱禁忌或疗效不佳时）：泼尼松片20～30mg qd，疗程3～7天，症状缓解后每2～3天减量5mg至停药；单关节大关节明显积液者可先行关节腔穿刺抽液，再注入曲安奈德10～20mg（排除感染后）。4.反复发作（≥2次/年）伴慢性炎症或关节破坏者：羟氯喹片0.2g bid，长期维持，需专科随访评估。\n【一般治疗及生活指导】1.急性期受累关节制动、抬高患肢，避免负重及剧烈活动，局部冰敷每次15～20分钟、每日3～4次以消肿止痛；症状缓解后循序渐进行关节功能锻炼。2.控制体重，均衡饮食，避免过量饮酒及高糖饮料，足量饮水；注意筛查并治疗相关代谢异常（甲状旁腺功能亢进、低镁血症、血色病、低磷血症等），必要时补充镁剂。3.避免诱发因素：防止关节外伤、过度劳累及脱水，避免关节过度使用；发作间期维持适度活动，防止关节僵硬。\n【随诊要求】1.用药后1～2周复诊，评估关节肿痛缓解情况并复查血沉、CRP等炎症指标。2.若反复发作或症状持续不缓解，建议转风湿免疫科进一步评估，完善受累关节X线/超声（寻找软骨钙化征）及病因筛查（血钙、血镁、血磷、甲状旁腺激素、铁蛋白等）。3.长期使用NSAIDs或糖皮质激素者，定期监测肝肾功能、血压、血糖及有无消化道症状，必要时胃镜检查。"},"icd10_diagnosis":"","icd10_secondary":[],"icd9cm3_procedure":[]}},"locator":{"file":"门诊住院病历模板/病历模板包_全部_20261111.json","arrayRow":461,"caseRow":1},"sourceHash":"10e4fdb435986b7b85f847c3951d0cb0eafdce0f372c5617949c05b337149194","contentHash":"611edbd2f8340f3fd6b874083304a274fcd45192bf4f8dd9bbcf35023500a842","pinyin":"jiaxingtongfeng","initials":"jxtf","setting":"out","caseName":"门诊病历326","templateNames":["主诉","现病史","既往史","个人史及过敏史","体格检查","辅助检查","初步诊断","处理方案"],"emptyTemplates":[],"escapedNewlines":[],"quickFields":[["病例名称","门诊病历326",60],["模板名称","主诉 现病史 既往史 个人史及过敏史 体格检查 辅助检查 初步诊断 处理方案",30],["主要诊断编码","",30]]},{"id":"templates-19e67cfc4a7d975e859d","key":"v1-c9ccc21dfe2a3058|templates-19e67cfc4a7d975e859d","module":"templates","moduleKey":"v1-c9ccc21dfe2a3058|templates","version":"v1-c9ccc21dfe2a3058","title":"银屑病关节炎","category":"门诊病历模板","raw":{"name":"银屑病关节炎","category":"门诊病历模板","case":{"case_name":"门诊病历327","templates":{"主诉":"关节肿痛、晨僵伴指趾肿胀1年","现病史":"患者有银屑病（皮肤鳞屑性斑块）病史5年，于皮损出现后出现关节症状：外周不对称性少关节炎（累及指趾）、远端指间关节受累（与指甲病变相关，可见顶针样甲）、脊柱及骶髂关节炎（炎性腰背痛，晨僵>30分钟、活动后改善）、附着点炎（跟腱、足底筋膜）、腊肠指趾（整个指趾弥漫肿胀，为特征性表现），伴晨僵、关节肿痛，有无指甲凹陷顶针样变及甲剥离、眼炎（结膜炎、虹膜炎）、乏力：无眼炎。皮肤及关节活动度评估见下文。有无家族史（银屑病、银屑病关节炎、脊柱关节炎）及HLA-B27相关：无明确家族史。今日来我院门诊就诊。","既往史":"既往体健，否认高血压、糖尿病、冠心病等慢性病史。否认肝炎、结核等传染病史。否认手术外伤史。否认食物药物过敏史。预防接种史随社会。","个人史及过敏史":"生于原籍，久居本地，无疫区疫水接触史，无特殊粉尘毒物放射性物质接触史。不吸烟，不饮酒。生活规律。否认食物药物过敏史。","体格检查":"T36.5℃，P72次/分，R18次/分，BP120/80mmHg。神志清楚。皮肤可见银屑病斑块（分布于肘膝伸侧、头皮及躯干），指甲可见顶针样凹陷、甲剥离及油滴征，双手远端指间关节及双足趾肿胀压痛（呈腊肠指趾，记录受累关节数）、晨僵、活动受限，跟腱止点压痛，脊柱活动度：Schober试验减小，骶髂关节压痛。","辅助检查":"【必做】血常规、血沉、CRP（升高）、类风湿因子（阴性，用于鉴别类风湿关节炎）、抗CCP抗体（多为阴性）、HLA-B27（脊柱受累者阳性率高）、肝肾功能、尿酸（排除痛风）；【影像】手及足X线（远端指间关节破坏，可见笔帽征及铅笔征、骨溶解、关节强直、骶髂关节炎，为X线特征）、超声或MRI（附着点炎、滑膜炎，用于早期诊断）；【评估】关节计数（肿胀及压痛）、皮肤受累面积（PASI）、功能评估（HAQ）。","初步诊断":"1. 银屑病关节炎（外周关节炎型伴指趾炎及附着点炎）\n（注：治疗目标为控制关节及皮肤炎症、防止关节破坏（达标治疗）：①NSAIDs（塞来昔布，对症缓解关节痛）；②改善病情抗风湿药（DMARDs，用于外周关节炎：甲氨蝶呤10~15mg每周1次（核心药物，对皮肤亦有效）+叶酸，或柳氮磺吡啶、来氟米特）；③生物制剂（中重度或传统DMARD无效者：肿瘤坏死因子抑制剂（依那西普50mg每周1次或阿达木单抗40mg每2周1次，对关节、皮肤及附着点均有效，首选）或IL-17抑制剂（司库奇尤单抗，皮肤疗效卓越）、IL-23抑制剂、JAK抑制剂（托法替布）；④脊柱受累予NSAIDs+生物制剂（TNFi或IL-17i）联合物理治疗；⑤小关节腔内激素注射（单关节）；⑥治疗前需筛查结核（生物制剂，行TST或IGRA+胸片）；⑦皮肤护理（外用药及光疗，与皮肤科协作）；由风湿免疫科长期管理，定期评估关节影像以防畸形。）","处理方案":"【药物治疗】\n1. 非甾体抗炎药（NSAIDs）：塞来昔布胶囊 0.2g bid×2周，关节肿痛缓解后减为0.2g qd或按需服用（有消化道溃疡、心血管疾病史者慎用，必要时联用质子泵抑制剂护胃）。\n2. 改善病情抗风湿药（DMARDs）：甲氨蝶呤片 7.5mg qw（每周固定1天顿服，4周后根据疗效与耐受性可渐增至15mg qw），同时叶酸片 5mg 每周1次（甲氨蝶呤服药后次日服用）以减轻不良反应；如疗效欠佳或不耐受，可换用或联用来氟米特片 10-20mg qd。\n3. 若上述治疗3个月疗效不佳或关节侵蚀进展，建议加用肿瘤坏死因子-α抑制剂（如阿达木单抗 40mg 皮下注射，每2周1次）或IL-17抑制剂（如司库奇尤单抗 150mg 皮下注射，每4周1次，首5周每周1次负荷量）。\n4. 皮损明显者：外用卡泊三醇软膏 适量涂患处 bid，或维生素D3衍生物联合糖皮质激素软膏外用；泛发顽固皮损可在皮肤科指导下加用阿维A胶囊 10mg bid。\n\n【一般治疗及生活指导】\n1. 急性期关节肿痛明显时应适当休息，减少负重关节活动；缓解期坚持规律关节功能锻炼，如游泳、伸展操，维持关节活动度、防止关节畸形。\n2. 戒烟戒酒，清淡均衡饮食，避免高脂高糖饮食，控制体重以减轻关节负荷；适当补充钙剂与维生素D，预防骨质疏松。\n3. 保护皮肤，避免搔抓、摩擦及外伤（注意同形反应可诱发或加重皮损），洗澡水温不宜过高，洗后及时涂抹保湿剂；避免使用可诱发或加重银屑病的药物（如β受体阻滞剂、锂剂、氯喹、干扰素等）。\n4. 保持情绪平稳，规律作息，避免劳累与感染（上呼吸道感染、咽部链球菌感染可诱发本病活动）。\n\n【随诊要求】\n1. 每2-4周门诊复诊1次，评估关节肿痛、晨僵、皮疹变化及药物疗效与不良反应，及时调整治疗方案。\n2. 使用甲氨蝶呤、来氟米特期间每2-4周复查血常规、肝肾功能；长期用药者每3-6个月复查1次并监测血脂、血糖。\n3. 每年复查受累关节X线或超声，评估骨侵蚀与关节破坏进展；长期使用糖皮质激素或活动受限者定期行骨密度检查。\n4. 注意监测心血管、代谢等共病情况，出现发热、咳嗽或感染征象及时就诊，使用生物制剂者用药期间避免接种活疫苗。"},"icd10_diagnosis":"","icd10_secondary":[],"icd9cm3_procedure":[]}},"locator":{"file":"门诊住院病历模板/病历模板包_全部_20261111.json","arrayRow":462,"caseRow":1},"sourceHash":"10e4fdb435986b7b85f847c3951d0cb0eafdce0f372c5617949c05b337149194","contentHash":"832d09a469cefa147074a1a53382dedd696e4a9d95644b9711cddb7864593a1e","pinyin":"yinxiebingguanjieyan","initials":"yxbgjy","setting":"out","caseName":"门诊病历327","templateNames":["主诉","现病史","既往史","个人史及过敏史","体格检查","辅助检查","初步诊断","处理方案"],"emptyTemplates":[],"escapedNewlines":[],"quickFields":[["病例名称","门诊病历327",60],["模板名称","主诉 现病史 既往史 个人史及过敏史 体格检查 辅助检查 初步诊断 处理方案",30],["主要诊断编码","",30]]},{"id":"templates-ea66d8d54b98e7f0c852","key":"v1-c9ccc21dfe2a3058|templates-ea66d8d54b98e7f0c852","module":"templates","moduleKey":"v1-c9ccc21dfe2a3058|templates","version":"v1-c9ccc21dfe2a3058","title":"肠病性关节炎","category":"门诊病历模板","raw":{"name":"肠病性关节炎","category":"门诊病历模板","case":{"case_name":"门诊病历328","templates":{"主诉":"关节肿痛伴炎性腰背痛6月","现病史":"患者有炎症性肠病（IBD，克罗恩病或溃疡性结肠炎）病史3年，肠道症状为腹痛、腹泻、黏液血便，于肠道活动期出现外周关节炎（Ⅰ型：少关节、大关节、与肠道活动相关、随肠道缓解而缓解）或中轴受累（强直性脊柱炎样炎性腰背痛，晨僵>30分钟、活动后改善，与肠道活动无关，病程独立），附着点炎（跟腱）、腊肠趾，有无结节性红斑、坏疽性脓皮病（IBD肠外皮肤表现，常并存）、葡萄膜炎及乏力：无明显皮肤及眼部表现。今日来我院门诊就诊。","既往史":"既往体健，否认高血压、糖尿病、冠心病等慢性病史。否认肝炎、结核等传染病史。否认手术外伤史。否认食物药物过敏史。预防接种史随社会。","个人史及过敏史":"生于原籍，久居本地，无疫区疫水接触史，无特殊粉尘毒物放射性物质接触史。不吸烟，不饮酒。生活规律。否认食物药物过敏史。","体格检查":"T36.5℃，P72次/分，R18次/分，BP120/80mmHg。神志清楚。腹部下腹压痛（提示肠道活动），双膝关节肿胀压痛（外周关节，记录分布）、脊柱活动度：Schober试验减小，跟腱及足底附着点压痛，皮肤未见结节性红斑及坏疽性脓皮病，眼部无充血（未见葡萄膜炎）。","辅助检查":"【必做】血常规（贫血，肠道失血或慢性病所致）、血沉、CRP（活动指标，与肠道活动相关但非特异）、肝肾功能、粪便钙卫蛋白（肠道活动评估）；【影像】受累关节X线、骶髂关节MRI（中轴受累，早期骶髂关节炎较X线敏感）、腹部影像及结肠镜（肠道评估）；【其他】HLA-B27（中轴受累者阳性率高，与预后相关）。","初步诊断":"1. 肠病性关节炎（与炎症性肠病相关，外周型）\n（注：治疗原则为控制肠道炎症是基础，IBD缓解后Ⅰ型外周关节炎随之缓解：①外周关节炎予NSAIDs（注意可加重肠道炎症及出血，IBD患者需谨慎权衡）、柳氮磺吡啶（对IBD及外周关节均有效，常用于结肠炎）、关节内激素注射；②肠道治疗（美沙拉嗪、激素、免疫抑制剂如硫唑嘌呤）以控制系统性活动性IBD；③生物制剂（肿瘤坏死因子抑制剂如英夫利昔单抗及阿达木单抗，对IBD及关节炎均有效，为中轴受累及难治性外周关节炎的核心药物；维多珠单抗为肠道选择性整合素抑制剂，IBD活动但关节症状者需联合评估）；④中轴受累予生物制剂（TNFi），IL-17抑制剂禁用（可加重IBD，重要）；⑤物理治疗（中轴受累予姿势训练）；⑥IBD活动期避免长期使用NSAIDs；由风湿免疫科与消化内科联合管理，生物制剂选择需兼顾肠道与关节。）","处理方案":"【药物治疗】\n1. 柳氮磺吡啶肠溶片：0.5g tid起始，1周后加量至1g tid，最大3g/d，疗程至少4周，可同时控制肠道与关节炎症，为肠病性关节炎首选；\n2. 美沙拉嗪缓释颗粒：1g tid口服，疗程8-12周，用于溃疡性结肠炎相关肠病性关节炎，抑制肠道黏膜活动性病变以缓解外周关节症状；\n3. 塞来昔布胶囊：0.2g qd，短期（≤2周）用于关节肿痛明显者，尽量选用选择性COX-2抑制剂，避免传统NSAIDs以免诱发或加重肠道病变；\n4. 甲氨蝶呤片：7.5-15mg qw（每周1次顿服），次日口服叶酸5mg，用于柳氮磺吡啶疗效不佳或慢性多关节受累者，每3个月评估疗效调整剂量。\n\n【一般治疗及生活指导】\n1. 关节急性肿痛期减少负重及剧烈活动，受累关节休息、局部保暖，避免长时间行走、爬楼梯及深蹲；\n2. 肠道活动期采用低渣、少纤维素、易消化饮食，忌辛辣刺激、生冷油腻食物，严格戒酒，补充优质蛋白、维生素及铁剂，保证营养支持；\n3. 缓解期坚持规律适度关节功能锻炼（如游泳、散步、太极拳），避免久坐久站、关节受凉受潮，控制体重减轻关节负荷；\n4. 规范治疗基础肠道病（溃疡性结肠炎/克罗恩病），戒烟，避免自行使用非甾体抗炎药、泻药及广谱抗生素以防肠道病变活动诱发关节炎复发。\n\n【随诊要求】\n1. 每月复诊1次，评估关节肿痛、晨僵时间及排便次数、便血等肠道症状变化，复查ESR、CRP、粪便钙卫蛋白，病情稳定后延长至每2-3个月1次；\n2. 服用柳氮磺吡啶或甲氨蝶呤期间每2-4周复查血常规、肝肾功能，监测皮疹、发热、口腔溃疡、骨髓抑制等不良反应；\n3. 每年复查肠镜评估肠道黏膜愈合情况；溃疡性结肠炎病程≥8年或克罗恩病累及结肠者，按IBD指南行结肠镜随访筛查；\n4. 出现持续腹泻便血、发热、新发虹膜炎、皮肤结节红斑或关节症状加重时及时复诊，必要时转消化科、眼科联合诊治。"},"icd10_diagnosis":"","icd10_secondary":[],"icd9cm3_procedure":[]}},"locator":{"file":"门诊住院病历模板/病历模板包_全部_20261111.json","arrayRow":463,"caseRow":1},"sourceHash":"10e4fdb435986b7b85f847c3951d0cb0eafdce0f372c5617949c05b337149194","contentHash":"663a6eeb814fafdf82796430c131b5e9b11f0401e076bc5b1e1b34962ed6548e","pinyin":"changbingxingguanjieyan","initials":"cbxgjy","setting":"out","caseName":"门诊病历328","templateNames":["主诉","现病史","既往史","个人史及过敏史","体格检查","辅助检查","初步诊断","处理方案"],"emptyTemplates":[],"escapedNewlines":[],"quickFields":[["病例名称","门诊病历328",60],["模板名称","主诉 现病史 既往史 个人史及过敏史 体格检查 辅助检查 初步诊断 处理方案",30],["主要诊断编码","",30]]},{"id":"templates-5791ba08d43417d0a2d0","key":"v1-c9ccc21dfe2a3058|templates-5791ba08d43417d0a2d0","module":"templates","moduleKey":"v1-c9ccc21dfe2a3058|templates","version":"v1-c9ccc21dfe2a3058","title":"感染性关节炎","category":"门诊病历模板","raw":{"name":"感染性关节炎","category":"门诊病历模板","case":{"case_name":"门诊病历329","templates":{"主诉":"单关节红肿热痛伴发热3天","现病史":"患者于3天前出现膝关节（最常见，亦可见于髋、肩、肘关节，以单关节炎为主，占80%以上）红肿热痛、活动严重受限（任何方向活动均剧痛，区别于炎症性关节炎）、不能负重，伴发热（体温最高38.9℃，约半数患者有）、寒战，有无基础病（类风湿关节炎、糖尿病、免疫抑制、吸毒静脉用药（淋球菌、金黄色葡萄球菌感染）、人工关节、近期关节注射或外伤、皮肤感染、泌尿道感染，为血行播散来源），其他关节有无游走性疼痛（淋球菌性关节炎，可伴腱鞘炎、皮疹、多关节受累）：无其他关节受累。今日来我院急诊就诊。","既往史":"既往体健，否认高血压、糖尿病、冠心病等慢性病史。否认肝炎、结核等传染病史。否认手术外伤史。否认食物药物过敏史。预防接种史随社会。","个人史及过敏史":"生于原籍，久居本地，无疫区疫水接触史，无特殊粉尘毒物放射性物质接触史。不吸烟，不饮酒。生活规律。否认食物药物过敏史。","体格检查":"T36.5℃，P72次/分，R18次/分，BP120/80mmHg。神志清楚，急性痛苦面容。右膝关节明显肿胀、皮温升高、关节积液（浮髌试验阳性）、皮肤红斑、被动活动及主动活动均明显受限（因疼痛，为核心体征）、关节周围压痛，其他关节无受累，皮肤未见皮疹（淋球菌感染可见脓疱及瘀点）、无腱鞘炎。","辅助检查":"【必做】关节液分析（最重要，需穿刺：外观浑浊脓性、白细胞>50000/mm³（中性>90%）、糖降低，为感染性特征）、关节液革兰染色及细菌培养（确诊金标准，用抗生素前穿刺）、血常规（白细胞升高）、血培养（约50%阳性，发热者）、CRP、血沉、降钙素原、血糖、尿酸（鉴别痛风，但痛风可合并感染，需警惕）；【影像】关节X线（早期可正常，用于排除骨髓炎及骨折，可见软组织肿胀）、超声或MRI（关节积液、滑膜增厚、软骨破坏早期评估，对诊断帮助大）；【特殊】淋球菌培养（尿道、宫颈、咽部，疑淋球菌性关节炎时）、结核及真菌检测（慢性单关节炎，特殊人群）。","初步诊断":"1. 感染性关节炎（右膝关节，化脓性即细菌性）\n（注：化脓性关节炎为骨科急症，延误可致软骨不可逆破坏及关节功能丧失，需立即住院：①经验性静脉抗生素（覆盖金黄色葡萄球菌，最常见；社区感染予头孢唑林或苯唑西林2g每6小时1次；MRSA高危予万古霉素；淋球菌予头孢曲松1g每日1次；革兰阴性菌或免疫低下者予哌拉西林他唑巴坦），根据培养药敏调整，疗程2~4患者脉加口服；②关节引流（关键，每日关节穿刺抽液或关节镜灌洗引流，必要时切开引流，髋关节需切开）；③患肢制动、抬高；④镇痛、退热；⑤寻找并处理感染源（皮肤、泌尿道、血管通路）；⑥治疗基础病（控制糖尿病）；⑦疗效评估（症状、CRP、关节液细胞数下降，白细胞<10000后可停静脉用药）；⑧后期功能康复锻炼（防关节僵硬，感染控制后进行）；由骨科与感染科协作。）","处理方案":"【药物治疗】\n1. 经验性抗感染治疗（门诊成人常规剂量）：首选头孢呋辛酯片0.25g bid po×14天，覆盖金黄色葡萄球菌及链球菌等常见病原；对β-内酰胺类过敏者改用莫西沙星片0.4g qd po×14天。\n2. 病原针对性治疗：关节腔穿刺液/血培养阳性者按药敏调整，金黄色葡萄球菌（MSSA）选用苯唑西林钠2g ivdrip q6h或头孢唑林钠2g ivdrip q8h；怀疑MRSA或社区重症、持续高热者应收住院静脉使用万古霉素1g ivdrip q12h（监测血药浓度及肾功能），不宜门诊口服治疗。\n3. 对症治疗：布洛芬缓释胶囊0.3g bid po（或塞来昔布胶囊0.2g qd po）退热镇痛，疗程3~7天，餐后服用，注意消化道出血及肾功能风险，合用抗凝药者慎用。\n4. 关节腔处理：急性期在无菌操作下行关节腔穿刺抽液减压并送检（常规、涂片革兰染色、培养+药敏），可依据积液情况行关节腔冲洗；避免反复无指征穿刺，疑似淋球菌性关节炎可经验性加用头孢曲松钠1g im qd。\n\n【一般治疗及生活指导】\n1. 休息与制动：急性期患肢绝对休息、抬高制动，避免负重及关节活动，必要时夹板或支具固定；疼痛、肿胀缓解后（通常3~5天后）开始被动活动，逐步过渡至主动功能锻炼，防止关节粘连、僵硬及肌肉萎缩。\n2. 饮食：高蛋白、高维生素、易消化饮食，保证充足热量，多饮水，维持水电解质平衡；糖尿病患者严格控制血糖，利于感染控制。\n3. 禁忌与防护：急性期禁忌热敷、按摩及过度活动患肢，禁忌饮酒；避免自行挤压关节部位；不得同时使用糖皮质激素或免疫抑制剂，以免掩盖症状、加重感染。\n4. 病情监测：每日监测体温及患关节红肿、灼热、疼痛、活动受限变化，观察穿刺部位有无渗液、脓性分泌物及全身中毒症状。\n\n【随诊要求】\n1. 用药3~5天复诊评估热退及关节症状改善情况；抗生素疗程一般为10~14天，停药前复查血常规、血沉（ESR）及C反应蛋白（CRP）至恢复正常。\n2. 关节腔引流者每周复诊，复查关节液培养至连续转阴后方可拔除引流；疗程结束后2~4周复查炎症指标及关节功能评估。\n3. 治疗期间出现持续高热不退、关节剧痛加重、红肿范围扩大、穿刺部位脓性分泌物或出现寒战、血压下降等全身感染征象者，应立即急诊就诊并考虑住院治疗。"},"icd10_diagnosis":"","icd10_secondary":[],"icd9cm3_procedure":[]}},"locator":{"file":"门诊住院病历模板/病历模板包_全部_20261111.json","arrayRow":464,"caseRow":1},"sourceHash":"10e4fdb435986b7b85f847c3951d0cb0eafdce0f372c5617949c05b337149194","contentHash":"b7e4571b2064a1521c799d9b7ea90caa102a0cba5d454a3d66a07a015a74b2f7","pinyin":"ganranxingguanjieyan","initials":"grxgjy","setting":"out","caseName":"门诊病历329","templateNames":["主诉","现病史","既往史","个人史及过敏史","体格检查","辅助检查","初步诊断","处理方案"],"emptyTemplates":[],"escapedNewlines":[],"quickFields":[["病例名称","门诊病历329",60],["模板名称","主诉 现病史 既往史 个人史及过敏史 体格检查 辅助检查 初步诊断 处理方案",30],["主要诊断编码","",30]]},{"id":"templates-5cdc456f1ee8adc74788","key":"v1-c9ccc21dfe2a3058|templates-5cdc456f1ee8adc74788","module":"templates","moduleKey":"v1-c9ccc21dfe2a3058|templates","version":"v1-c9ccc21dfe2a3058","title":"骨软化症","category":"门诊病历模板","raw":{"name":"骨软化症","category":"门诊病历模板","case":{"case_name":"门诊病历330","templates":{"主诉":"全身骨痛、肌无力伴行走困难1年","现病史":"患者（成人）于____月/年前渐出现全身弥漫性骨痛（负重骨/肋骨/骨盆，按压痛明显）、近端肌无力（下蹲起立困难、鸭步）、行走困难，骨骼变形（驼背/脊柱侧弯/胸廓畸形/骨盆狭窄，假性骨折处骨痛，Looser带），病理性骨折，____（有无维生素D缺乏病因：日照不足、饮食缺乏、胃肠吸收不良（乳糜泻/胃切除）、肝肾疾病（活性维生素D生成障碍）、肾小管疾病（Fanconi综合征：磷丢失）、药物（抗癫痫药：苯妥英诱导维生素D代谢）），低钙低磷血碱性磷酸酶升高史：____。儿童：佝偻病（骨骺改变）。今日来我院门诊就诊。","既往史":"既往体健，否认高血压、糖尿病、冠心病等慢性病史。否认肝炎、结核等传染病史。否认手术外伤史。否认食物药物过敏史。预防接种史随社会。","个人史及过敏史":"生于原籍，久居本地，无疫区疫水接触史，无特殊粉尘毒物放射性物质接触史。不吸烟，不饮酒。生活规律。否认食物药物过敏史。","体格检查":"T36.5℃，P72次/分，R18次/分，BP120/80mmHg。神志清楚。肋骨及胫骨前压痛（按压痛）、下肢近端肌力减退（起立试验阳性）、步态呈鸭步、骨骼畸形（胸廓、脊柱及下肢，可见膝内翻或外翻）、牙齿发育不良。","辅助检查":"【必做】血钙、血磷（低钙、低磷）、碱性磷酸酶（显著升高，骨转换增加，为骨软化核心生化指标）、25-(OH)D（降低，为维生素D缺乏依据）、甲状旁腺激素（继发升高）、肾功能、血镁、血气及尿pH（排查肾小管酸中毒）、尿磷（肾磷漏，Fanconi综合征）、肝肾功能；【影像】X线（弥漫骨密度降低、假性骨折即Looser线，见于耻骨支、股骨颈及肋骨，为特征性横贯骨皮质的透亮线、骨皮质变薄）、骨密度（降低）；【其他】骨活检（四环素标记，示骨矿化障碍，必要时可确诊）、病因相关检查（乳糜泻抗体、抗癫痫药评估）。","初步诊断":"1. 骨软化症（维生素D缺乏、磷代谢障碍或肾小管病等，病因待明确）\n（注：①维生素D补充（核心，用于缺乏者）：口服维生素D2或D3（骨质疏松常规剂量800~1200IU/d，治疗量需更大，2000~4000IU/d×数周至数月，复查25-(OH)D达30ng/ml以上）或活性维生素D（骨化三醇0.25~0.5μg每日2次，用于肝肾功能障碍者）；②钙剂补充（元素钙500~1000mg/d，与维生素D同用，纠正低钙）；③磷代谢障碍（低磷性骨软化予中性磷口服+骨化三醇，用于肾磷漏者）；④病因治疗（乳糜泻予无麸质饮食；停用或调整抗癫痫药；纠正酸中毒（肾小管酸中毒予碳酸氢钠或枸橼酸））；⑤监测：血钙、血磷、ALP（治疗有效后下降，骨矿化恢复，2~3个月复查）、25-(OH)D、PTH、尿钙（防过量致高钙尿及肾结石）；⑥对症：镇痛（骨痛）、防跌倒骨折、康复（肌力训练）；骨骼畸形严重者待骨矿化正常后评估矫形；随访骨密度。）","处理方案":"【药物治疗】\n1. 活性维生素D：骨化三醇胶囊（罗盖全）0.25μg bid po，疗程3个月；或阿法骨化醇软胶囊0.5μg qd po，用药2周后复查血钙、血磷及24h尿钙，据结果调整剂量。\n2. 钙剂：碳酸钙D3片（钙尔奇D）600mg qd po，餐中或餐后服用，与维生素D同服以促进钙吸收；或枸橼酸钙片500mg bid po。\n3. 维生素D2注射液：适用于血25-(OH)D3严重缺乏（<10ng/ml）者，维生素D2注射液60万IU im，每月1次，连用2~3个月，同时监测血钙避免高钙血症。\n4. 病因针对性用药：若为低磷性骨软化症（肿瘤性/遗传性），改用中性磷口服液（磷酸盐合剂）10ml tid po，并监测血磷及尿钙，忌与含钙制剂同服。\n\n【一般治疗及生活指导】\n1. 饮食指导：均衡营养，增加富含钙及维生素D食物摄入（牛奶、酸奶、豆制品、蛋黄、深海鱼、动物肝脏），每日保证钙摄入约1000mg；戒烟限酒，避免过量饮用浓茶、咖啡及碳酸饮料影响钙吸收。\n2. 日照与活动：每日于非暴晒时段（上午10时前或下午4时后）户外日晒至少30分钟，促进皮肤合成维生素D；骨痛缓解期适当进行慢走、游泳等温和负重运动，增强肌力，避免剧烈运动及负重爬楼。\n3. 休息与防跌倒：骨痛明显或行走困难者注意休息，必要时使用拐杖等助行器；家中卫生间安装扶手、地面防滑，减少跌倒致骨折风险。\n4. 禁忌：避免长期或大剂量使用糖皮质激素、抗癫痫药物等影响钙磷代谢的药物，如必须使用应定期监测骨代谢指标。\n\n【随诊要求】\n1. 治疗2周后复诊，复查血钙、血磷、碱性磷酸酶、血25-(OH)D3及24h尿钙，评估疗效并调整维生素D及钙剂剂量。\n2. 此后每1~3个月复诊一次，监测血清钙、磷及碱性磷酸酶变化，警惕高钙血症（多饮、多尿、便秘、恶心等症状时随时复诊）。\n3. 每6~12个月复查骨密度及X线平片，评估骨矿化改善及有无假性骨折（Looser线）愈合情况。\n4. 治疗3~6个月后骨痛无缓解、加重或出现新发骨痛、病理性骨折，或原发疾病（肾病、肠道吸收不良等）控制不佳时，应及时复诊，必要时转诊内分泌科或骨科进一步评估。"},"icd10_diagnosis":"","icd10_secondary":[],"icd9cm3_procedure":[]}},"locator":{"file":"门诊住院病历模板/病历模板包_全部_20261111.json","arrayRow":465,"caseRow":1},"sourceHash":"10e4fdb435986b7b85f847c3951d0cb0eafdce0f372c5617949c05b337149194","contentHash":"bc00823b4fe732381bad6079815e2a3ffecacdbac2894cc8b60240c882934906","pinyin":"guruanhuazheng","initials":"grhz","setting":"out","caseName":"门诊病历330","templateNames":["主诉","现病史","既往史","个人史及过敏史","体格检查","辅助检查","初步诊断","处理方案"],"emptyTemplates":[],"escapedNewlines":[],"quickFields":[["病例名称","门诊病历330",60],["模板名称","主诉 现病史 既往史 个人史及过敏史 体格检查 辅助检查 初步诊断 处理方案",30],["主要诊断编码","",30]]}]);